            if (damage > 0) applyCombatDamage(npc, damage, plan.part, { damageType: "blunt", crit: false, bleed: false, heavy: false, noCombo: true, superficial: true, aggressor: "player" });
            result.damage = Math.max(0, hpBeforeEffect - npc.hp);
