function parseTextTrainingCommand(raw) {
    if (textModeInCombat()) return null;
    let match = /^(?:drill|practise|practice)(?:\s+(?:on|at|with))?(?:\s+(.+))?$/i.exec(raw);
    if (match) return { verb: "train", args: { action: "drill", target: match[1] || "" } };
    match = /^(?:cast|use)\s+(.+?)\s+(?:at|on)\s+(.+?dumm(?:y|ies).*|dumm(?:y|ies))$/i.exec(raw);
    if (match) return { verb: "train", args: { action: "cast", target: match[1] + " at " + match[2] } };
    match = /^(?:train|training|lessons?)(?:\s+(.+))?$/i.exec(raw);
    if (match) return { verb: "train", args: { action: "menu", target: (match[1] || "").replace(/^(?:on|at)\s+/i, "") } };
    match = /^forget(?:\s+technique)?(?:\s+(.+))?$/i.exec(raw);
    if (match) return { verb: "train", args: { action: "forget", target: match[1] || "" } };
    match = /^learn\s+(?:technique\s+(.+)|(.+)\s+from\s+(?:the\s+)?trainer)$/i.exec(raw);
    if (match) return { verb: "train", args: { action: "learn", target: match[1] || match[2] } };
    if (sharedChoiceState.menu && /^training-/.test(sharedChoiceState.menu.kind) && !/\sfrom\s/i.test(raw)) {
        match = /^learn\s+(.+)$/i.exec(raw);
        if (match) return { verb: "train", args: { action: "learn", target: match[1] } };
    }
    return null;
}
