async function textTrainingMenuInput(menu, action, input) {
    if ((splitTextCommands(input || "").parts || []).length > 1) return textModeResult("needs_input", "Answer one training menu step per reply. Leave the menu before starting another batch.");
    if (action.verb === "leave") {
        if (!menu.valid()) return textModeResult("blocked", "That training scene changed. Type options.");
        const back = menu.options.find(function (choice) { return choice.meta.action === "back"; });
        return back ? textRunSharedChoice(menu, back) : textModeResult("blocked", "Use back to leave this menu.");
    }
    textModeState.busy = true; textModeState.paused = true; textModeState.capture = [];
    try {
        let result;
        if (menu.kind === "training-dummy") {
            const args = action.args || {}, cast = /^(.*?)\s+(?:at|on|with)\s+(.+)$/i.exec(args.target || "");
            if (!cast && args.target && /^(menu|drill)$/.test(args.action || "")) {
                if (!textLootMatch(args.target, [{ label: getEntityName(menu.fixture) }], function (entry) { return entry.label; }).length) return textModeResult("blocked", "Finish this dummy before choosing another one.");
                if (args.action === "menu") return showSharedChoiceMenu(menu);
            }
            if (args.action === "cast" || cast) {
                const target = cast ? /\bdumm(?:y|ies)\b/i.test(cast[1]) ? cast[2] : cast[1] : args.target;
                const namedDummy = cast ? /\bdumm(?:y|ies)\b/i.test(cast[1]) ? cast[1] : cast[2] : "";
                if (namedDummy && !textLootMatch(namedDummy, [{ label: getEntityName(menu.fixture) }], function (entry) { return entry.label; }).length) return textModeResult("blocked", "Finish this dummy before choosing another one.");
                result = await selectTextTraining(menu, { verb: "train", args: { action: "cast", target: target } });
            } else result = await selectTextTraining(menu, { verb: "train", args: { action: args.action, target: args.action === "drill" ? "" : args.target } });
        } else result = await selectTextTraining(menu, action);
        for (let i = 0; i < textModeState.capture.length; i++) await textModeState.capture[i];
        return result;
    } finally { textModeState.capture = null; textModeState.busy = false; renderTextModeStatus(); focusTextModeInput(); }
}

