        if (!reason && chosen === "key" && (!lock || lock.keyId === "room-token" || !findKeyForLock(lock))) reason = "You have no matching reusable key.";
        if (!reason && chosen === "pick" && !findPlayerItemById("lockpick")) reason = "You need a lockpick.";
