// Version identifier for debugging cached files
if (typeof window !== "undefined") {
    window.CORE_ENGINE_VERSION = window.__ENGINE_CORE_VERSION;   // alias: never edit separately
    console.log("[Core Engine] Loaded v" + window.__ENGINE_CORE_VERSION);

    // Expose Perchance's `ai` function to window so that intimacy-system.js
    // (loaded as a separate <script src> tag) can access it. The engine code
    // is appended by Perchance into a scope where `ai` is available as a
    // bare global, but data scripts loaded via <script src> don't have it.
    // This must run early in the engine so it's ready before any intimacy
    // actions are triggered.
    if (typeof ai === 'function' && typeof window.ai === 'undefined') {
        window.ai = ai;
        console.log("[Core Engine] Exposed ai() to window.ai for intimacy-system.js access");
    }

    // Fallback for when the engine itself is loaded via <script src> (too big
    // for the Perchance editor): bare `ai`/`image` are not in scope there, so
    // pull the imported plugins off Perchance's root object. The HTML shell's
    // inline "PERCHANCE PLUGIN BRIDGE" normally sets these first.
    (function () {
        var r = null;
        try { r = window.root ? (window.root.___proxyTarget ? window.root.___proxyTarget.obj : window.root) : null; } catch (e) { r = null; }
        if (!r) return;
        try { if (typeof window.ai !== "function" && typeof r.ai === "function") window.ai = r.ai; } catch (e) {}
        try { if (typeof window.image !== "function" && typeof r.image === "function") window.image = r.image; } catch (e) {}
    })();
    if (typeof window.ai !== "function") {
        console.warn("[Core Engine] ai() not found - add the inline plugin bridge <script> before the engine <script src> in the HTML panel.");
    }
}

// ── USE AI SWITCH ────────────────────────────────────────────────
// Sidebar "Use AI" checkbox (next to Portraits). Per-session only: it resets
// to On on every page load. Off = no text-AI call leaves the game; every
// caller already has a fallback (canned/RNG text), so a gated call just
// resolves to null. Portraits use image(), not ai(), and keep their own toggle.
// window.ai is wrapped so scripts loaded via <script src> (which only see
// window.ai) are gated too; window.useAIEnabled() is there for them to read.
window.__useAI = true;
function useAIEnabled() { return window.__useAI !== false; }
window.useAIEnabled = useAIEnabled;
// True when an AI call would actually go out (switch on and ai() exists).
function aiAvailable() {
    return useAIEnabled() && (typeof ai === "function" || (typeof window !== "undefined" && typeof window.ai === "function"));
}
window.aiAvailable = aiAvailable;
// Engine-side entry point for every ai() call: null when switched off.
function callAI(options) {
    if (!useAIEnabled()) return Promise.resolve(null);
    if (typeof ai === "function") return ai(options);
    if (typeof window !== "undefined" && typeof window.ai === "function") return window.ai(options);
    return Promise.resolve(null);
}
window.callAI = callAI;
(function () {
    if (typeof window === "undefined" || typeof window.ai !== "function" || window.ai.__useAIGate) return;
    const realAI = window.ai;
    const gatedAI = function () {
        if (!useAIEnabled()) return Promise.resolve(null);
        return realAI.apply(this, arguments);
    };
    gatedAI.__useAIGate = true;
    gatedAI.__realAI = realAI;
    window.ai = gatedAI;
})();

