function createTavernDrinkItem(template) {
    return assignLootUID({
        id: `${template.id}-${Math.random().toString(36).slice(2, 7)}`,
        name: template.name,
        type: ["consumable", "alcohol"],
        value: template.value,
        alcoholPotency: template.alcoholPotency || 1,
        description: template.description || `A serving of ${String(template.name || "drink").toLowerCase()}.`
    });
}

// Roles treated as "sells weapons" for the skill-potion vendor bonus
// (see seedNPCPotionStock). Currently just Blacksmith - the only role in
// ROLE_TRADE_GOODS themed around weapons/smithing - but kept as a list so
// a future weaponsmith/armorer-style role can be added here.
const WEAPON_VENDOR_ROLES = ["Blacksmith"];

function createPotionItem(template) {
    return assignLootUID({
        id: `${template.id}-${Math.random().toString(36).slice(2, 7)}`,
        name: template.name,
        type: ["potion", "consumable"],
        value: template.value,
        statusKey: template.statusKey,
        unitSize: 1,
        infinite: !!template.infinite,
        description: template.description || `A small vial of ${String(template.name || "potion").toLowerCase()}.`
    });
}

// Rolls `count` potions from `pool` (with repeats - two picks of the same
// type just show up as two separate buyable entries, not a stacked
// quantity, since NPC trade stock is bought one entry at a time - see
// buyTradeItem/renderTradeOptions, which don't do partial-stack purchases).
function rollPotionItems(pool, count) {
    const items = [];
    for (let i = 0; i < count; i++) {
        items.push(createPotionItem(rand(pool)));
    }
    return items;
}

// Spell scrolls and (blank) spellbooks for NPC stock and loot - see
// WIZARD SPELLS. Merchant-type roles sell them; scholarly and dangerous roles
// may simply carry a scroll. Appended after the flavour-loot cap like potions.
// ── CLASS GEAR ───────────────────────────────────────────────────
// Anyone can wear or wield any item; class gear carries an `affinity` block
// whose bonuses only apply while the wearer is one of the item's
// `classAffinity` classes. Everyone else just gets the base stats (armour,
// weapon die) - so the price is the real gate, not a class lock. Sold at
// premium prices by the Arcanist (arcane) and Reliquarian (divine) vendors,
// and rarely found in chests, on zone bosses and on a few NPCs.
//
// Affinity keys (all numbers, summed over every equipped matching item):
//   manaCostReduction  spells cost this much less (never below 2, or the base cost if lower)
//   spellDamage        flat damage on every spell
//   elementDamage      { fire|frost|shock: n } extra damage for that element
//   burnRounds         extra rounds of burn on Firebolt
//   freezeHits         Frost Shard freezes after this many fewer hits (min 2)
//   drainStamina       extra stamina drained by Frost Shard
//   stunChance         extra stun chance (0.15 = +15%) for Lightning Arc
//   manaRegen          extra mana per story turn
//   restMana           extra mana per rest turn
//   restHeal           extra HP per rest turn
//   copyDCBonus        lowers the willpower DC to copy a scroll
