const CLASS_GEAR_AFFINITY_LABELS = {
    manaCostReduction: (v) => `spells cost ${v} less mana`,
    spellDamage: (v) => `+${v} spell damage`,
    burnRounds: (v) => `Firebolt burns ${v} more round${v === 1 ? "" : "s"}`,
    freezeHits: (v) => `Frost Shard freezes ${v} hit${v === 1 ? "" : "s"} sooner`,
    drainStamina: (v) => `Frost Shard drains ${v} more stamina`,
    stunChance: (v) => `+${Math.round(v * 100)}% Lightning Arc stun chance`,
    manaRegen: (v) => `+${v} mana per turn`,
    restMana: (v) => `+${v} mana per rest turn`,
    restHeal: (v) => `+${v} HP per rest turn`,
    copyDCBonus: (v) => `easier scroll copying (-${v} DC)`,
    shrineMana: (v) => `+${Math.round(v * 100)}% mana from shrine prayer`,
    holyDamage: (v) => `+${v} damage against undead`
};

const CLASS_GEAR_PRICE_NOTE = true;
const CLASS_GEAR_CONTAINER_CHANCE = 0.03;
const CLASS_GEAR_CONTAINER_CHANCE_DEEP = 0.06;
const CLASS_GEAR_CHEST_MULT = 1.5;
const RARE_CLASS_GEAR_CHANCE = 0.3;     // zone boss carries one piece of class gear

// Who carries class gear. `each` vendors roll every piece of their theme
// (with `min` guaranteed); the rest roll `chance` for a single piece.
const CLASS_GEAR_STOCK = {
    "Arcanist": { theme: "arcane", each: 0.6, min: 2 },
    "Reliquarian": { theme: "divine", each: 0.6, min: 2 },
    "Enchanter": { theme: "arcane", chance: 0.15 },
    "Archivist": { theme: "arcane", chance: 0.08 },
    "Priest": { theme: "divine", chance: 0.1 },
    "Cultist": { theme: "divine", chance: 0.05 },
    "Wandering Merchant": { theme: "any", chance: 0.05 },
    "Adventurer": { theme: "any", chance: 0.03 },
    "Delver": { theme: "any", chance: 0.04 }
};

function getPlayerClassKey(player) {
    const p = player || (window.G ? window.G.player : null);
    return p && p.class ? String(p.class).toLowerCase() : "";
}

function isClassGearItem(item) {
    return !!(item && item.affinity && typeof item.affinity === "object");
}

function describeItemAffinity(item) {
    if (!isClassGearItem(item)) return "";
    const bits = [];
    Object.keys(item.affinity).forEach(function (key) {
        const v = item.affinity[key];
        if (key === "elementDamage") {
            Object.keys(v || {}).forEach(function (el) { bits.push(`+${v[el]} ${el} spell damage`); });
        } else if (CLASS_GEAR_AFFINITY_LABELS[key]) {
            bits.push(CLASS_GEAR_AFFINITY_LABELS[key](v));
        }
    });
    const who = Array.isArray(item.classAffinity) && item.classAffinity.length
        ? item.classAffinity.map(function (c) { return c.charAt(0).toUpperCase() + c.slice(1); }).join("/")
        : "Any class";
    return `${who} gear: ${bits.join(", ")}`;
}

function createClassGearItem(gearKey) {
    const def = CLASS_GEAR[gearKey];
    if (!def) return null;
    const item = cloneLootTemplate(def);
    item.affinity = JSON.parse(JSON.stringify(def.affinity));
    item.classAffinity = def.classAffinity.slice();
    item.description = `${def.description} (${describeItemAffinity(item)}; other classes gain nothing from the enchantment.)`;
    return item;
}

function getClassGearKeysForTheme(theme) {
    return Object.keys(CLASS_GEAR).filter(function (k) { return theme === "any" || CLASS_GEAR[k].theme === theme; });
}

function itemAffinityActive(item, player) {
    if (!isClassGearItem(item)) return false;
    if (!Array.isArray(item.classAffinity) || !item.classAffinity.length) return true;
    return item.classAffinity.some(function (c) { return getClassSkillRank(player, c) >= CLASS_GEAR_MIN_RANK; });
}

function getEquippedAffinityTotal(player, key) {
    const p = player || (window.G ? window.G.player : null);
    if (!p || !p.equipped) return 0;
    let total = 0;
    Object.keys(p.equipped).forEach(function (slot) {
        const item = p.equipped[slot];
        if (!item || Array.isArray(item) || !itemAffinityActive(item, p)) return;
        if (typeof item.affinity[key] === "number") total += item.affinity[key];
    });
    return total;
}

function getEquippedAffinityElement(player, element) {
    const p = player || (window.G ? window.G.player : null);
    if (!p || !p.equipped) return 0;
    let total = 0;
    Object.keys(p.equipped).forEach(function (slot) {
        const item = p.equipped[slot];
        if (!item || Array.isArray(item) || !itemAffinityActive(item, p)) return;
        const el = item.affinity.elementDamage;
        if (el && typeof el[element] === "number") total += el[element];
    });
    return total;
}

function getEffectiveSpellManaCost(player, spell) {
    if (!spell) return 0;
    const reduction = getEquippedAffinityTotal(player, "manaCostReduction");
    const floor = Math.min(spell.manaCost, 2);
    return Math.max(floor, spell.manaCost - reduction);
}

function isUndeadNPC(npc) {
    if (!npc) return false;
    const species = typeof normalizeSpeciesName === "function" ? normalizeSpeciesName(npc.species) : String(npc.species || "").toLowerCase();
    return ["skeleton", "ghost", "zombie", "wraith", "ghoul", "specter", "spectre", "revenant"].indexOf(species) >= 0;
}

// Class gear for an NPC's stock. Returns an array of items to append to the
// inventory (not subject to the 5-slot flavour cap).
function seedNPCClassGearStock(npc) {
    const items = [];
    if (!npc || !npc.role || npc.isHumanoid === false) return items;
    const cfg = CLASS_GEAR_STOCK[npc.role];
    if (!cfg) return items;
    const keys = getClassGearKeysForTheme(cfg.theme);
    if (typeof cfg.each === "number") {
        const picked = keys.filter(function () { return Math.random() < cfg.each; });
        const rest = keys.filter(function (k) { return picked.indexOf(k) < 0; });
        while (picked.length < (cfg.min || 0) && rest.length) {
            picked.push(rest.splice(randInt(0, rest.length - 1), 1)[0]);
        }
        picked.forEach(function (k) { items.push(createClassGearItem(k)); });
    } else if (Math.random() < (cfg.chance || 0)) {
        items.push(createClassGearItem(rand(keys)));
    }
    return items.filter(Boolean);
}

const SPELL_STOCK_ODDS = {
    "Archivist": { book: 0.8, scroll: 0.7, scrollMax: 2 },
    "Enchanter": { book: 0.5, scroll: 0.6, scrollMax: 2 },
    "Arcanist": { book: 0.9, scroll: 0.9, scrollMax: 3 },
    "Vendor": { book: 0.12, scroll: 0.2, scrollMax: 1 },
    "Shopkeeper": { book: 0.12, scroll: 0.2, scrollMax: 1 },
    "Wandering Merchant": { book: 0.2, scroll: 0.3, scrollMax: 1 },
    "Trader": { book: 0.15, scroll: 0.25, scrollMax: 1 },
    "Priest": { book: 0, scroll: 0.1, scrollMax: 1 },
    "Cultist": { book: 0, scroll: 0.25, scrollMax: 1 },
    "Delver": { book: 0, scroll: 0.15, scrollMax: 1 },
    "Adventurer": { book: 0, scroll: 0.1, scrollMax: 1 }
};

function seedNPCSpellStock(npc) {
    const items = [];
    if (!npc || !npc.role || npc.isHumanoid === false) return items;
    const odds = SPELL_STOCK_ODDS[npc.role] || { book: 0, scroll: 0.03, scrollMax: 1 };
    const spellIds = Object.keys(WIZARD_SPELLS);
    if (odds.book > 0 && Math.random() < odds.book) items.push(createSpellbookItem([]));
    if (odds.scroll > 0 && Math.random() < odds.scroll) {
        const count = randInt(1, odds.scrollMax || 1);
        for (let i = 0; i < count; i++) items.push(createSpellScrollItem(rand(spellIds)));
    }
    return items;
}

// Called from seedNPCStartingLoot, kept separate from the general trade-good
// rolling above (and appended after that array's slice(0, 5) cap) so a
// healer's guaranteed potions - or a blacksmith's skill-potion bonus - can
// never get crowded out by unrelated flavor loot.
function seedNPCPotionStock(npc) {
    const potions = [];
    if (!npc || !npc.role) return potions;

    if (npc.role === "Healer") {
        potions.push(...rollPotionItems(POTION_STAT_TEMPLATES, randInt(2, 5)));
        potions.push(createPotionItem(POTION_OF_HEALTH_TEMPLATE));
        if (Math.random() < 0.5) potions.push(createPotionItem(POTION_OF_STAMINA_TEMPLATE));
        if (Math.random() < 0.5) potions.push(createPotionItem(POTION_OF_MANA_TEMPLATE));
    } else if (npc.role === "Innkeeper" || npc.role === "Bartender") {
        if (Math.random() < 0.05) {
            potions.push(...rollPotionItems(POTION_STAT_TEMPLATES, 1));
        }
        if (Math.random() < 0.20) {
            potions.push(...rollPotionItems([POTION_OF_STAMINA_TEMPLATE], randInt(1, 2)));
        }
    } else if (isMerchantRole(npc.role)) {
        if (Math.random() < 0.10) {
            potions.push(...rollPotionItems(POTION_STAT_TEMPLATES, randInt(1, 3)));
        }
        if (Math.random() < 0.10) {
            potions.push(createPotionItem(POTION_OF_STAMINA_TEMPLATE));
        }
        if (Math.random() < 0.08) {
            potions.push(createPotionItem(POTION_OF_MANA_TEMPLATE));
        }
    }

    if (npc.role === "Arcanist" && Math.random() < 0.6) {
        potions.push(createPotionItem(POTION_OF_MANA_TEMPLATE));
    }

    if (WEAPON_VENDOR_ROLES.includes(npc.role) && Math.random() < 0.25) {
        potions.push(...rollPotionItems(POTION_SKILL_TEMPLATES, randInt(1, 3)));
    }

    // Raging Bull is a wandering-merchant specialty - never on a fixed
    // vendor's shelf, just occasionally in a road peddler's pack.
    if (npc.role === "Wandering Merchant" && Math.random() < 0.25) {
        potions.push(createPotionItem(POTION_OF_RAGING_BULL_TEMPLATE));
    }

    // Tavern drinks (see TAVERN_DRINK_TEMPLATES): a bartender always has a
    // few on hand, an innkeeper sometimes. Guaranteed rather than part of
    // the trade-good roll so a tavern always sells alcohol.
    if (npc.role === "Bartender") {
        const drinkCount = randInt(2, 4);
        for (let i = 0; i < drinkCount; i++) {
            potions.push(createTavernDrinkItem(rand(TAVERN_DRINK_TEMPLATES)));
        }
    } else if (npc.role === "Innkeeper" && Math.random() < 0.5) {
        const innDrinkCount = randInt(1, 2);
        for (let i = 0; i < innDrinkCount; i++) {
            potions.push(createTavernDrinkItem(rand(TAVERN_DRINK_TEMPLATES)));
        }
    }

    return potions;
}

