// [oreKey, weight]. Exotic ores (star, ember, deepglass, moonsilver) are
// deliberately single-digit weights.
const ZONE_ORE_TABLES = {
    "Town":             [["iron", 82], ["silvered", 15], ["star", 3]],
    "Dungeon":          [["iron", 62], ["silvered", 20], ["ember", 9], ["deepglass", 6], ["star", 3]],
    "Ruins":            [["iron", 40], ["silvered", 28], ["moonsilver", 12], ["star", 10], ["deepglass", 6], ["ember", 4]],
    "Underground City": [["iron", 52], ["silvered", 25], ["ember", 8], ["deepglass", 8], ["moonsilver", 4], ["star", 3]],
    "Swamp":            [["bog", 72], ["iron", 15], ["deepglass", 6], ["silvered", 5], ["moonsilver", 2]]
};
// Fixtures that can be prospected for ore (one attempt each).
const FIXTURE_ORE_SOURCES = {
    "cave-in-rubble": 0.40,
    "rubble":         0.30,
    "stalagmites":    0.30,
    "heaved-slabs":   0.25,
    "cracked-wall":   0.20,
    "broken-floor":   0.15,
    "sunken-walls":   0.12,
    "fallen-column":  0.12
};
const PROSPECT_STAMINA_COST = 2;
const PROSPECT_ROLL_DC = 10;
const PROSPECT_FAIL_CHANCE_FACTOR = 0.5;
const CONTAINER_ORE_CHANCE = 0.07;
const CONTAINER_ORE_CART_CHANCE = 0.35;

function getOreTableForZone(zoneName) {
    const raw = String(zoneName || "");
    const direct = ZONE_ORE_TABLES[raw];
    if (direct) return direct;
    const key = Object.keys(ZONE_ORE_TABLES).find(k => k.toLowerCase() === raw.toLowerCase());
    return key ? ZONE_ORE_TABLES[key] : ZONE_ORE_TABLES["Town"];
}

// richBias (ore veins): the zone's commonest ore (first table entry) is
// weighted down, so the better grades turn up a little more often.
const ORE_RICH_COMMON_FACTOR = 0.6;

function rollOreKeyForZone(zoneName, richBias) {
    const table = getOreTableForZone(zoneName);
    const weights = table.map((entry, i) => (richBias && i === 0) ? entry[1] * ORE_RICH_COMMON_FACTOR : entry[1]);
    const total = weights.reduce((sum, w) => sum + w, 0);
    let roll = Math.random() * total;
    for (let i = 0; i < table.length; i++) {
        roll -= weights[i];
        if (roll < 0) return table[i][0];
    }
    return table[0][0];
}

function rollOreItemForZone(zoneName, richBias) {
    return cloneLootTemplate(ORE_TEMPLATES[rollOreKeyForZone(zoneName, richBias)]);
}

