    if (window.setupFreeform && page === 5 && typeof validateFreeformPage === "function" && !validateFreeformPage()) page = 7;
    // Page 3 (Your Past) needs an archetype before the traits page.
    if (page === 4 && typeof validatePastPage === "function" && !validatePastPage()) page = 3;
    document.querySelectorAll(".setup-page").forEach(p => p.classList.remove("active"));
    document.getElementById(`setupPage${page}`).classList.add("active");
    if (page === 1 && typeof updateSpeciesBlurb === "function") updateSpeciesBlurb();
    if (page === 2 && typeof updateGenitalSetupVisibility === "function") updateGenitalSetupVisibility();
    if (page === 2 && typeof updateClassBlurb === "function") updateClassBlurb();
    if (page === 3 && typeof renderPastPage === "function") renderPastPage();
    if (page === 4 && typeof renderApproachPage === "function") renderApproachPage();
    if (page === 5 && typeof refreshStartPage === "function") refreshStartPage();
    if (page === 6 && typeof renderLikesPage === "function") renderLikesPage();
    if (page === 7 && typeof renderFreeformPage === "function") renderFreeformPage();
