// ── AI-OFF TOPIC REPLIES ─────────────────────────────────────────
// Used when the AI is switched off (or fails): real content for the common
// topic options instead of a generic mood line. Returns "" when the option
// has no topic builder, and the caller falls back to the per-intent pools.
// Lore options carry the real fact in choice.contextNote (see
// buildNPCLoreNote), so a rumor or history question is answered with it.
const AI_OFF_SPEECH_LEADS = {
    friendly: ["They answer warmly.", "They smile and lean in a little.", "Their face softens as they speak."],
    neutral: ["They think for a moment.", "They answer plainly.", "They shrug, then speak."],
    hostile: ["They answer stiffly.", "They give you a hard look.", "They speak through clenched teeth."]
};
const AI_OFF_ROLE_WORK_LINES = [
    { tags: ["guard", "watch"], work: "Keep the peace, mostly. Long watches and not much thanks.", hardest: "The long hours, and the people who only notice us when something goes wrong." },
    { tags: ["healer", "priest", "cleric"], work: "I tend to the sick and the hurt, and I see to what the gods ask of me.", hardest: "Losing the ones I could not save." },
    { tags: ["bartender", "innkeeper", "cook"], work: "I keep folk fed and watered. Busy from open to close.", hardest: "Drunks, and the ones who will not pay." },
    { tags: ["clothier"], work: "I sell clothes, mend worn seams, alter designs and reinforce soft armour. Bring materials and I will quote before I start.", hardest: "Making a sound garment from scraps that were never meant to fit together." },
    { tags: ["smith", "blacksmith"], work: "I work the forge. Honest iron, honest prices.", hardest: "The heat, and customers who haggle over steel that could save their lives." },
    { tags: ["merchant", "trader", "vendor", "shopkeeper"], work: "I buy, I sell, and I keep an eye on the margins.", hardest: "The roads. Every cart is a gamble." },
    { tags: ["miner"], work: "I dig. Hard, dusty work, but it pays.", hardest: "Never knowing whether the ceiling will hold." },
    { tags: ["scout"], work: "I watch the roads and the treeline, and I report what I see.", hardest: "Being right about trouble when nobody wants to hear it." },
    { tags: ["archivist"], work: "I keep records and old stories from rotting away.", hardest: "Gaps. Whole years that nobody wrote down." }
];

function buildTopicFallbackReply(npc, choice, room) {
    if (!npc || !choice) return "";
    const id = String(choice.id || "");
    const band = typeof getConversationRelationshipBand === "function" ? getConversationRelationshipBand(npc) : "neutral";
    const pick = function (list) { return list[Math.floor(Math.random() * list.length)]; };
    const say = function (text) {
        return (pick(AI_OFF_SPEECH_LEADS[band] || AI_OFF_SPEECH_LEADS.neutral) + " <" + text + ">").trim();
    };
    const note = typeof choice.contextNote === "string" ? choice.contextNote : "";
    const role = String(npc.role || "").toLowerCase();
    const supplyReply = !choice.action && !note ? merchantSupplyReplyForQuestion(npc, choice.typedText || choice.promptText || choice.text) : "";
    if (supplyReply) return say(supplyReply);

    if (id === "ask-name") {
        const nm = typeof getNPCSelfName === "function" ? getNPCSelfName(npc) : (npc.givenName || npc.name || "");
        if (nm && nm !== "someone") return say(pick([`Name's ${nm}.`, `They call me ${nm}.`, `I'm ${nm}.`]));
    }

    if (note && (choice.loreFactId || id === "ask-lore-source")) {
        if (note.indexOf("Something the speaker told the player") === 0) {
            return say(/own work or experience/.test(note)
                ? pick(["It comes from my own work, so I would trust it.", "I saw enough of it myself to say so."])
                : pick(["Only what I heard from others. I cannot vouch for it.", "Hearsay, mostly. Take it as you like."]));
        }
        const m = note.match(/: "([\s\S]*?)"(?= \(They believe| Answer from)/);
        if (m && m[1]) {
            const secondhand = /only heard secondhand/.test(note);
            return say((secondhand ? pick(["Folk say ", "From what I have heard, ", "Word going round is that "]) : "") + m[1]);
        }
    }

    if (String(choice.intent || "").toLowerCase() === "greeting" && typeof getRenownGreetingDeed === "function") {
        const gd = getRenownGreetingDeed(npc);
        const gl = gd && typeof buildRenownTalkReply === "function" ? buildRenownTalkReply(npc, gd.id, room) : "";
        if (gl) { markRenownDeedTold(npc, gd.id); return say(gl); }
    }

    if (id === "ask-talk" && choice.deedTalkId && typeof buildRenownTalkReply === "function") {
        const talk = buildRenownTalkReply(npc, choice.deedTalkId, room);
        if (talk) return say(talk);
    }

    if (id === "ask-place") {
        const where = room ? String(room.displayName || room.name || room.type || "") : "";
        const zone = room && room.zone ? String(room.zone) : "";
        const inZone = !zone ? "" : (zone.toLowerCase() === "town" ? " in town" : " in the " + zone);
        if (where) {
            return say(pick([
                `This is ${where}${inZone}. Nothing more to it than what you see.`,
                `${where}${inZone}. I know it well enough.`
            ]));
        }
    }

    if (id === "ask-work" || id === "ask-work-hardest") {
        for (let i = 0; i < AI_OFF_ROLE_WORK_LINES.length; i++) {
            const entry = AI_OFF_ROLE_WORK_LINES[i];
            if (entry.tags.some(function (t) { return role.indexOf(t) >= 0; })) {
                return say(id === "ask-work" ? entry.work : entry.hardest);
            }
        }
        return say(id === "ask-work" ? "It keeps me busy, and it keeps me fed." : "The hours, mostly. It never lets up.");
    }

    if (id === "ask-seen" || id === "ask-seen-who") {
        const events = typeof getNPCAwareStoryEvents === "function" ? getNPCAwareStoryEvents(npc, { room: room }) : [];
        if (events.length) {
            const latest = events.slice().sort(function (a, b) { return (a.age || 0) - (b.age || 0); })[0];
            if (latest && latest.text) return say("Folk are still talking about it. " + latest.text);
        }
        return say(pick(["Nothing out of the ordinary.", "Quiet, really. Nothing I would call strange."]));
    }
    return "";
}

function pickNPCConversationFallbackReply(npc, interaction) {
    if (interaction && interaction.interactionFamily) return interaction.interactionFamily === "expression" ? "They acknowledge your gesture." : "They stay where they are. <Not just now.>";
    if (interaction && Object.prototype.hasOwnProperty.call(SOCIAL_GESTURES, interaction.socialGesture || "")) {
        return getConversationRelationshipBand(npc) === "hostile"
            ? "They keep their distance. <Leave me be.>"
            : SOCIAL_GESTURES[interaction.socialGesture].fallback;
    }
    const topical = buildTopicFallbackReply(npc, interaction, G.activeRoom);
    if (topical) return topical;
    const intentKey = String(interaction && interaction.intent || "talk").toLowerCase();
    const band = getConversationRelationshipBand(npc);

    // Check for species-specific replies first
    var species = String(npc && npc.species || "").toLowerCase();
    var speciesPool = SPECIES_FALLBACK_REPLIES[species];
    if (speciesPool) {
        // Romantic advances (seduce) have no species buckets - the
        // "flirt" bucket is the closest on-topic match; falling through to
        // "talk" produced unrelated replies (e.g. honor lines) to a seduce.
        var intentBucket = speciesPool[intentKey]
            || (intentKey === "seduce" ? speciesPool.flirt : null)
            || speciesPool["talk"];
        var speciesReplies = intentBucket[band] || intentBucket.neutral;
        if (speciesReplies && speciesReplies.length) {
            return speciesReplies[Math.floor(Math.random() * speciesReplies.length)];
        }
    }

    // Fall back to generic replies
    const bucket = NPC_FALLBACK_REPLIES[intentKey] || NPC_FALLBACK_REPLIES.talk;
    const pool = bucket[band] || bucket.neutral || NPC_FALLBACK_REPLIES.talk.neutral;
    return pool[Math.floor(Math.random() * pool.length)];
}

function queueConversationPrefetch(npc, options) {
    if (!npc || !Array.isArray(options) || !options.length) return options;
    if (!aiAvailable()) return options; // Use AI off: replies come from the fallback pools
    const room = G.activeRoom;
    // Encounter-starting intimacy options (action "intimacy" + startEncounter)
    // DO go through npcRespond when clicked, so they prefetch like any other
    // option; every other action option (trade, directions, function actions)
    // bypasses the reply pipeline and prefetching for them would be waste.
    const relevantOptions = options.filter(option => option && !option.noPrefetch && (option.promptText || option.text)
        && (!option.action || (option.action === "intimacy" && option.startEncounter === true)));
    if (!relevantOptions.length) return options;

    const ctx = typeof getNPCConversationContext === "function"
        ? getNPCConversationContext(npc, { room })
        : null;
    const bundleKey = buildConversationBundleKey(npc, relevantOptions, room, ctx);
    const optionSnapshots = relevantOptions.map(option => {
        option._conversationBundleKey = bundleKey;
        option._conversationReplyKey = getConversationReplyKey(bundleKey, option.id);
        return {
            id: option.id,
            intent: option.intent || "talk",
            promptText: option.promptText || option.text || "",
            replyKey: option._conversationReplyKey
        };
    });

    const missingOptions = optionSnapshots.filter(option => {
        const hasBundleCache = runtimeConversationState.replyCache[option.replyKey];
        const sessionKey = getConversationSessionReplyKey(npc, option.id);
        const hasSessionCache = sessionKey && runtimeConversationState.sessionReplyCache[sessionKey];
        const hasNPCCache = npc && npc.memory && npc.memory.cachedReplies && npc.memory.cachedReplies[option.id];
        
        // Also check if this specific option is already being prefetched
        const optionIdKey = `${npc.id || npc.name || "npc"}:${option.id}`;
        const isAlreadyPrefetching = runtimeConversationState.prefetchingOptionIds.has(optionIdKey);
        
        return !hasBundleCache && !hasSessionCache && !hasNPCCache && !isAlreadyPrefetching;
    });
    if (!missingOptions.length) return options;
    if (runtimeConversationState.bundlePromises[bundleKey]) return options;
    if (G.prefetchQueue.find(task => task && task.key && task.key.startsWith(bundleKey))) return options;

    // Split into batches of 4 to avoid overwhelming the AI
    const BATCH_SIZE = 4;
    const batches = [];
    for (let i = 0; i < missingOptions.length; i += BATCH_SIZE) {
        batches.push(missingOptions.slice(i, i + BATCH_SIZE));
    }

    let resolveBundle;
    runtimeConversationState.bundlePromises[bundleKey] = new Promise(resolve => {
        resolveBundle = resolve;
    });

    // Process batches sequentially with slight delay between them
    const processBatch = async (batchIndex) => {
        if (batchIndex >= batches.length) {
            delete runtimeConversationState.bundlePromises[bundleKey];
            if (resolveBundle) resolveBundle();
            return;
        }

        const batch = batches[batchIndex];
        const batchOptionIds = batch.map(option => option.id);
        
        // Build prompt for this batch - use the SAME bundleKey but different options
        const batchOptions = relevantOptions.filter(opt => 
            batchOptionIds.includes(opt.id)
        );
        // Build a simple instruction for this batch without the full bundle key context
        // Check if buildPrompt is available (may not be in iframe context)
        let batchPrompt = "";
        if (typeof buildPrompt === "function") {
            batchPrompt = buildPrompt(
                room,
                npc,
                buildConversationBatchInstruction(npc, batchOptions, room),
                { includeRandomQuirk: false, conversation: true, keepAwareness: batchOptions.some(o => o && o.contextNote), memoryTags: getConversationMemoryTags(npc, batchOptions, room) }
            );
        } else {
            // Fallback: skip this batch if buildPrompt is not available
            console.warn("buildPrompt function not available, skipping prefetch batch");
            delete runtimeConversationState.bundlePromises[bundleKey];
            if (resolveBundle) resolveBundle();
            return;
        }

        enqueuePrefetchTask({
            key: `${bundleKey}:batch:${batchIndex}`,
            priority: 100,
            run: async () => {
                // Mark these option IDs as being prefetched
                const npcId = npc.id || npc.name || "npc";
                batch.forEach(option => {
                    const optionIdKey = `${npcId}:${option.id}`;
                    runtimeConversationState.prefetchingOptionIds.add(optionIdKey);
                });
                
                let replyMap = {};
                let rawText = "";
                try {
                    const jsonPrefix = "{\"replies\":[";
                    const result = await callAI({
                        instruction: batchPrompt,
                        startWith: jsonPrefix,
                        endButtons: "none"
                    });
                    const continuation = typeof result === "string" ? result : result && result.text ? result.text : "";
                    rawText = String(continuation || "").trim().startsWith("{")
                        ? String(continuation || "").trim()
                        : `${jsonPrefix}${String(continuation || "").trim()}`;
                    
                    // Debug: Log raw AI response
                    console.log("[DEBUG] AI Response for batch:", {
                        npc: npc ? { name: npc.name, id: npc.id } : null,
                        batchOptionIds: batchOptionIds,
                        rawText: rawText
                    });
                    
                    replyMap = parseConversationReplyPayload(rawText, batchOptionIds);
                    let storedCount = 0;

                    batch.forEach(option => {
                        if (replyMap[option.id]) {
                            storeCachedConversationReply(npc, option, replyMap[option.id]);
                            storedCount += 1;
                        }
                    });

                    if (storedCount > 0) {
                        console.log(`Conversation prefetch cached ${storedCount}/${batch.length} replies for ${npc.name || "NPC"}.`);
                    }
                    
                    if (!Object.keys(replyMap).length) {
                        console.warn("Conversation prefetch returned no parseable replies:", rawText.slice(0, 400));
                    }
                } catch (batchErr) {
                    // Keep going: a failed batch must not leave bundlePromises
                    // unresolved (that blocked every later prefetch for this menu).
                    console.warn("Conversation prefetch batch failed:", batchErr);
                } finally {
                    // Always remove from prefetching set when done
                    batch.forEach(option => {
                        const optionIdKey = `${npcId}:${option.id}`;
                        runtimeConversationState.prefetchingOptionIds.delete(optionIdKey);
                    });
                }
                
                // Process next batch after a short delay
                setTimeout(() => processBatch(batchIndex + 1), 100);
            },
            finalize: () => {}
        });

        runPrefetchQueue();
    };

    // Start processing batches
    processBatch(0);
    
    return options;
}

// One live AI call for a single option (typed reply, canned reply, or a menu
// option whose prefetch has not landed). Same JSON prompt and parser as the
// batch prefetch, so affirmative / responseNeeded / replyOptions / playerTone
// all come back. Resolves to a reply object/string, or null on failure/timeout.
async function fetchLiveConversationReply(npc, choice, room) {
    if (!npc || !choice || !room) return null;
    if (!aiAvailable() || typeof buildPrompt !== "function") return null;
    const optionId = String(choice.id || choice.optionId || "live-reply");
    const liveChoice = Object.assign({}, choice, { id: optionId });
    let prompt = "";
    try {
        prompt = buildPrompt(
            room,
            npc,
            buildConversationBatchInstruction(npc, [liveChoice], room),
            { includeRandomQuirk: false, conversation: true, keepAwareness: !!liveChoice.contextNote, memoryTags: getConversationMemoryTags(npc, [liveChoice], room) }
        );
    } catch (buildErr) {
        console.warn("Live conversation prompt failed:", buildErr);
        return null;
    }
    if (!prompt) return null;

    const jsonPrefix = "{\"replies\":[";
    const call = (async function () {
        const result = await callAI({ instruction: prompt, startWith: jsonPrefix, endButtons: "none" });
        const continuation = typeof result === "string" ? result : (result && result.text ? result.text : "");
        const rawText = String(continuation || "").trim().startsWith("{")
            ? String(continuation || "").trim()
            : `${jsonPrefix}${String(continuation || "").trim()}`;
        const map = parseConversationReplyPayload(rawText, [optionId]);
        if (!map[optionId]) console.warn("Live conversation reply not parseable:", rawText.slice(0, 400));
        return map[optionId] || null;
    })();
    const timeout = new Promise(function (resolve) {
        setTimeout(function () { resolve(null); }, CONVERSATION_LIVE_REPLY_TIMEOUT_MS);
    });
    try {
        return await Promise.race([call, timeout]);
    } catch (liveErr) {
        console.warn("Live conversation reply failed:", liveErr);
        return null;
    }
}

// Resolves to the first non-empty value among the promises, or null once all
// of them have come back empty (or thrown).
function firstNonEmptyConversationReply(promises) {
    return new Promise(function (resolve) {
        let remaining = promises.length;
        if (!remaining) { resolve(null); return; }
        const settleEmpty = function () { remaining -= 1; if (remaining <= 0) resolve(null); };
        promises.forEach(function (p) {
            Promise.resolve(p).then(function (value) {
                if (value) resolve(value); else settleEmpty();
            }, settleEmpty);
        });
    });
}

// Get the NPC's reply for a clicked option without ever showing canned text
// unless the AI genuinely fails:
//  1. cached / quickly-finishing prefetch -> use it;
//  2. nothing in flight (typed or canned reply, noPrefetch) -> live call now;
//  3. prefetch still running -> give it a short head start, then race it
//     against a parallel live call for just this option.
async function resolveConversationReply(npc, choice, room) {
    const replyKey = choice._conversationReplyKey;
    const bundleKey = choice._conversationBundleKey;
    const pending = bundleKey ? runtimeConversationState.bundlePromises[bundleKey] : null;

    if (!pending) {
        return await fetchLiveConversationReply(npc, choice, room);
    }

    const quick = await waitForConversationReply(replyKey, bundleKey, CONVERSATION_LIVE_START_DELAY_MS);
    if (quick) return quick;

    const prefetchLeg = pending.then(function () {
        return (replyKey && runtimeConversationState.replyCache[replyKey]) || getCachedConversationReply(npc, choice) || null;
    });
    const overall = new Promise(function (resolve) {
        setTimeout(function () { resolve(null); }, CONVERSATION_LIVE_REPLY_TIMEOUT_MS);
    });
    return await Promise.race([
        firstNonEmptyConversationReply([fetchLiveConversationReply(npc, choice, room), prefetchLeg]),
        overall
    ]);
}

async function waitForConversationReply(replyKey, bundleKey, waitMs = CONVERSATION_PREFETCH_GRACE_MS) {
    if (replyKey && runtimeConversationState.replyCache[replyKey]) {
        return runtimeConversationState.replyCache[replyKey];
    }

    const pending = bundleKey ? runtimeConversationState.bundlePromises[bundleKey] : null;
    if (!pending) return "";

    await Promise.race([
        pending,
        new Promise(resolve => setTimeout(resolve, waitMs))
    ]);

    return replyKey ? (runtimeConversationState.replyCache[replyKey] || "") : "";
}

function rememberNPCConversationLine(npc, speaker, text, intent = "talk") {
    if (!npc || !text) return;
    if (typeof ensureNPCRelationshipState === "function") ensureNPCRelationshipState(npc);
    npc.memory.recentLines.push({
        speaker,
        intent,
        text: String(text).replace(/\s+/g, " ").trim(),
        timestamp: Date.now(),
        // Story turn, so the line expires with the story and not the clock (see buildNPCRecentExchangeBlock).
        turn: typeof getCurrentStoryTurn === "function" ? getCurrentStoryTurn() : 0
    });
    npc.memory.recentLines = npc.memory.recentLines.slice(-6);

    recordOverheardExchange(npc, speaker, text, intent);
}

// Anyone else humanoid, alive and present in the room when a line gets
// spoken picks up a lightweight "overheard" memory of it - separate from
// their own recentLines so it never gets misattributed as something they
// said themselves. No AI call, just bookkeeping alongside the exchange
// that's already happening, so this stays synchronous and cheap.
function recordOverheardExchange(sourceNpc, speaker, text, intent) {
    const room = G.activeRoom;
    if (!room || !Array.isArray(room.creatures) || room.creatures.length < 2) return;

    const trimmedText = String(text || "").replace(/\s+/g, " ").trim();
    if (!trimmedText) return;

    room.creatures.forEach(other => {
        if (!other || other === sourceNpc || !other.isHumanoid) return;
        if (other.hp <= 0 || other.unconscious || other.hidden || other.isHidden) return;
        if (typeof ensureNPCRelationshipState === "function") ensureNPCRelationshipState(other);

        other.memory.overheardLines = other.memory.overheardLines || [];
        other.memory.overheardLines.push({
            aboutName: sourceNpc && sourceNpc.name ? sourceNpc.name : "someone",
            speaker,
            intent,
            text: trimmedText,
            timestamp: Date.now()
        });
        other.memory.overheardLines = other.memory.overheardLines.slice(-4);
    });
}

function normalizeNPCReplyText(text) {
    return String(text || "")
        .replace(/[“”]/g, "\"")
        .replace(/[‘’]/g, "'")
        .replace(/\s+/g, " ")
        .trim();
}

async function npcRespond(npc, interaction) {
    socialReplyBegin(interaction, npc);
    if (!socialReplyFresh(interaction, npc)) return;
    if (!canConverseWithNPC(npc)) {
        clearChatOptions();
        // A handed-off encounter start can never run now; drop it so a
        // later, unrelated reply doesn't start the encounter out of nowhere.
        if (npc) delete npc._pendingIntimacyStart;
        return;
    }

    const room = G.activeRoom;
    const playerInput = typeof interaction === "string"
        ? interaction
        : (interaction && (interaction.promptText || interaction.text) ? (interaction.promptText || interaction.text) : "");
    const intent = interaction && interaction.intent ? interaction.intent : "talk";
    let responseText = "";
    const choice = interaction && typeof interaction === "object"
        ? interaction
        : { text: playerInput, promptText: playerInput, intent };

    // If this choice came from the rendered talk menu, it already carries the
    // batch key/reply key from that menu's JSON prefetch. Do not overwrite it.
    if (!choice.action && !choice._conversationBundleKey) {
        // Check if there's already a cached reply for this option
        const optionId = choice.id || choice.optionId;
        const hasCached = optionId && npc && npc.memory && npc.memory.cachedReplies && npc.memory.cachedReplies[optionId];
        
        // Only queue prefetch if there's no cached reply and no existing bundle promise
        // Build a bundle key to check for existing prefetch
        const ctx = typeof getNPCConversationContext === "function"
            ? getNPCConversationContext(npc, { room })
            : null;
        const tempBundleKey = buildConversationBundleKey(npc, [choice], room, ctx);
        
        if (!hasCached && !runtimeConversationState.bundlePromises[tempBundleKey] && 
            !G.prefetchQueue.find(task => task && task.key && task.key.startsWith(tempBundleKey))) {
            queueConversationPrefetch(npc, [choice]);
        }
        // Set the bundle key so waitForConversationReply can track it
        if (!choice._conversationBundleKey) {
            choice._conversationBundleKey = tempBundleKey;
            choice._conversationReplyKey = getConversationReplyKey(tempBundleKey, optionId || "");
        }
    }

    let responseObj = getCachedConversationReply(npc, choice);
    let affirmative;
    let responseNeeded;
    let replyOptions;
    let playerTone;
    let receptivity;
    const optionId = choice.id || choice.optionId;

    if (responseObj && typeof responseObj === "object") {
        // New format: object with text and affirmative fields
        responseText = responseObj.text || "";
        affirmative = responseObj.affirmative;
        responseNeeded = responseObj.responseNeeded;
        replyOptions = responseObj.replyOptions;
        playerTone = responseObj.playerTone;
        receptivity = responseObj.receptivity;

        // Debug: Log NPC response with affirmative
        console.log("[DEBUG] NPC Response:", {
            npc: npc ? { name: npc.name, id: npc.id } : null,
            optionId: optionId,
            responseText: responseText,
            affirmative: affirmative,
            isInquiry: choice.isInquiry
        });

        // Consume cached reply so a new one is fetched next time
        // DEFERRED for inquiry options: applyInquiryResponse needs to check
        // npc.memory.cachedReplies for the affirmative flag when it wasn't
        // passed directly. Removing it here would prevent that recovery.
        if (optionId && !choice.isInquiry) {
            removeCachedConversationReply(npc, optionId);
        }
    } else if (typeof responseObj === "string") {
        // Old format: just a text string
        responseText = responseObj;

        // Debug: Log NPC response (old format)
        console.log("[DEBUG] NPC Response (old format):", {
            npc: npc ? { name: npc.name, id: npc.id } : null,
            optionId: optionId,
            responseText: responseText
        });

        // Consume cached reply so a new one is fetched next time
        if (optionId && !choice.isInquiry) {
            removeCachedConversationReply(npc, optionId);
        }
    }
    
    if (!responseText && aiAvailable()) {
        addTypingIndicator();
        try {
            responseText = await resolveConversationReply(npc, choice, room);
        } catch (resolveErr) {
            console.warn("resolveConversationReply failed:", resolveErr);
            responseText = "";
        }
        removeTypingIndicator();
        // The reply may come back as an OBJECT ({ text, affirmative, ... })
        // rather than a string. If so, extract every field - especially
        // affirmative, which gates applyInquiryResponse.
        if (responseText && typeof responseText === "object" && !Array.isArray(responseText)) {
            if (responseText.affirmative !== undefined) affirmative = responseText.affirmative;
            if (responseText.responseNeeded !== undefined) responseNeeded = responseText.responseNeeded;
            if (responseText.replyOptions) replyOptions = responseText.replyOptions;
            if (responseText.playerTone) playerTone = responseText.playerTone;
            if (responseText.receptivity !== undefined) receptivity = responseText.receptivity;
            responseText = responseText.text || "";
        }
    }

    if (!socialReplyFresh(choice, npc)) return;

    // Last resort only: the live AI call failed or timed out.
    if (!responseText) {
        responseText = pickNPCConversationFallbackReply(npc, choice);
    }

    // Handle inquiry response with affirmative field
    console.log("[Engine Inquiry] check:", {
        isInquiry: choice && choice.isInquiry,
        applyInquiryExists: typeof window.applyInquiryResponse === "function",
        affirmative: affirmative,
        responseTextLen: responseText ? responseText.length : 0,
        engineVersion: window.__ENGINE_CORE_VERSION || "UNKNOWN"
    });
    if (choice && choice.isInquiry && typeof window.applyInquiryResponse === "function") {
        const processed = window.applyInquiryResponse(npc, choice, responseText, affirmative);
        if (processed && processed !== responseText) responseText = processed;
        // Now consume the cached reply for inquiry options (deferred from above)
        if (optionId) {
            removeCachedConversationReply(npc, optionId);
        }
    } else {
        console.warn("[Engine Inquiry] SKIPPED — isInquiry:", choice && choice.isInquiry,
            "applyInquiryResponse type:", typeof window.applyInquiryResponse);
    }

    // Asking their name is what makes the (hidden) given name public: from
    // here on npc.name is the real name, including this reply's chat label.
    const _nameSpokenAloud = typeof npcReplyMentionsOwnName === "function" && !npcNameIsKnownSafe(npc) && npcReplyMentionsOwnName(npc, responseText);
    if ((optionId === "ask-name" || choice.revealsName === true || _nameSpokenAloud) && typeof revealNPCName === "function") {
        const wasKnown = typeof npcNameIsKnown === "function" && npcNameIsKnown(npc);
        revealNPCName(npc);
        if (!wasKnown && typeof rememberStoryEvent === "function") {
            rememberStoryEvent("conversation", `${G.player.name} learned that ${npc.descriptorName || "the stranger"} is called ${npc.name}.`, 3);
        }
    }
    if (typeof applyNPCDrunkSpeech === "function") responseText = applyNPCDrunkSpeech(npc, responseText);
    addChatMessage("left", npc.name, responseText, { mode: "auto" });
    // The NPC has answered an offer to buy them a drink: act on their decision.
    if (choice && (choice.id === "offer-to-buy-drink" || choice.id === "offer-to-buy-both-drinks") && typeof resolveBuyDrinkOffer === "function") {
        resolveBuyDrinkOffer(npc, affirmative, responseText, choice.id === "offer-to-buy-both-drinks");
    }
    updateStoryOnNpcInteraction(npc, playerInput, responseText);

    if (typeof ensureNPCRelationshipState === "function") ensureNPCRelationshipState(npc);
    npc.memory.metPlayer = true;
    npc.memory.lastSpokenTo = Date.now();
    rememberNPCConversationLine(npc, "player", playerInput, intent);
    rememberNPCConversationLine(npc, "npc", responseText, intent);
    // What was just said (a question? a dodge? a hint of trouble?) so reactive
    // options only show when they fit (see _npcLiveReplyMeta in npc-data).
    if (typeof window.npcNoteReplyMeta === "function") window.npcNoteReplyMeta(npc, choice, responseText, affirmative);
    // Typed replies: apply the relationship effect now that the AI has rated
    // how the words landed (falls back to a keyword check if it did not).
    if (choice.judgeTone && typeof buildTypedToneImpact === "function") {
        const toneImpact = buildTypedToneImpact(npc, playerTone, choice.typedText || playerInput);
        if (toneImpact) applyNPCImpact(npc, toneImpact);
    }
    // Trust responseNeeded only when the line really asks/demands something.
    if (responseNeeded === true && !replyDemandsAnswer(responseText)) {
        responseNeeded = false;
        replyOptions = [];
    }
    // If the NPC's line expects an answer, remember that (and any canned
    // replies) so the menu can offer "Respond..." plus the suggestions.
    // Cleared again as soon as the player picks anything (chooseChatOption).
    npc.memory.pendingResponse = responseNeeded === true
        ? { needed: true, options: Array.isArray(replyOptions) ? replyOptions.slice(0, 3) : [] }
        : null;
    // The guide offers company only on a separate player-requested turn.
    if (typeof generateNPCBehavior === "function") npc.behavior = generateNPCBehavior(npc);
    if (G.activeNPC === npc && typeof refreshNPCDetailPanel === "function") {
        refreshNPCDetailPanel(npc);
    }

    saveGameState();
    socialReplyCompleted(choice, npc, responseText);

    // Pending encounter start (the phase-2 encounter-starting options,
    // handed off by handleIntimacyConversationChoice): the reply above is the
    // transition beat into the scene — unless the AI rated the advance
    // "lukewarm" or "refuse", in which case the moment doesn't take: the
    // exchange plays out as a normal beat and the talk menu comes back, so
    // the player can warm things up and try again. Receptivity only exists
    // on AI-produced replies (fallback-pool replies never carry it), so with
    // the AI off the encounter still starts.
    if (npc._pendingIntimacyStart) {
        delete npc._pendingIntimacyStart;
        const _receptivity = String(receptivity || "").toLowerCase();
        const _isResponsiveDesire = !!(choice && choice.responsiveDesire === true);
        // A bold responsive-desire advance (the "take-the-kiss" /
        // "press-the-advance" follow-ups) only stops for a clear refusal:
        // "lukewarm" there means hesitant-then-melting, which is the scene
        // starting. An ordinary advance stops for lukewarm or refuse.
        const _holdsOff = _isResponsiveDesire
            ? _receptivity === "refuse"
            : (_receptivity === "lukewarm" || _receptivity === "refuse");
        if (_holdsOff) {
            console.log("[Engine] Encounter start held off — receptivity:", _receptivity);
            if (_isResponsiveDesire) {
                // Escalating after a "no" stings: a refused bold advance costs
                // real goodwill, and the character pulls free and leaves the
                // room rather than stand in the aftermath (see
                // npcLeavesAfterRebuffedAdvance). The rebuff marker is NOT
                // re-armed — it was consumed at click time, and an ordinary
                // advance has to be refused again before the bold follow-ups
                // come back.
                if (typeof applyNPCImpact === "function") {
                    applyNPCImpact(npc, {
                        mood: -2, favor: -10, hostility: +5, attraction: -5,
                        intent: "awkward", markMet: true, actionTag: "advance-rebuffed"
                    });
                }
                npcLeavesAfterRebuffedAdvance(npc, responseText);
                return;
            }
            // An ordinary advance that got rebuffed unlocks the bold
            // responsive-desire follow-ups (see the NSFW catalogue's
            // take-the-kiss / press-the-advance entries).
            npc._advanceRebuffed = true;
            if (G.activeNPC === npc) {
                G.activeNPCMode = "talk";
                renderChatOptions(npc);
            }
            return;
        }
        startEncounterFromConversation(npc, choice, responseText);
        return;
    }

    renderChatAfterReply(npc);
}

// ── CHAT UI ──────────────────────────────────────────────────────

function getChatOptions(npc) {
    if (!canConverseWithNPC(npc)) return [];
    if (typeof queryConversationCatalogue === "function") {
        const room = G.activeRoom;
        const options = queryConversationCatalogue(npc, { room: room });
        if (npc && npc.name) {
            console.log("[DEBUG] Conversation options for", npc.name, "in", room ? room.type || room.displayName || "unknown" : "unknown", ":", options.map(o => ({id: o.id, label: o.label, action: o.action, phase: o.phase})));
        }
        if (Array.isArray(options) && options.length) {
            // Use AI off: nobody can answer free text, so drop "Say something...".
            const withReplies = withCannedReplyOptions(npc, options);
            if (!useAIEnabled()) return withReplies.filter(function (o) { return !(o && o.id === "respond-free"); });
            return withReplies;
        }
    }
    return [];
}

// When the NPC's last line asked for an answer (npc.memory.pendingResponse,
// set in npcRespond), put the canned replies that came with it just before
// the "Respond..." option. They are ordinary talk choices: noPrefetch keeps
// them out of the batch prefetch, and the "respond-" id prefix keeps them out
// of the used-option bookkeeping (see recordNPCConversationChoice).
function withCannedReplyOptions(npc, options) {
    const pending = npc && npc.memory ? npc.memory.pendingResponse : null;
    if (!pending || pending.needed !== true || !Array.isArray(pending.options) || !pending.options.length) return options;
    const at = options.findIndex(o => o && o.id === "respond-free");
    const scriptedGuideReplies = !useAIEnabled() && npc.guide && npc.guide.active && G.activeNPCMode === "talk" && pending.options.every(function (o) { return o && (o.guideTalk || o.guideParty); });
    if (at < 0 && !scriptedGuideReplies) return options; // ordinary restricted menus stay restricted
    const insertAt = at < 0 ? 0 : at;

    const stanceImpact = {
        friendly: { mood: 1, favor: 2, hostility: -1, intent: "talk", markMet: true, actionTag: "talk" },
        guarded: { mood: 0, favor: 0, hostility: 0, intent: "talk", markMet: true, actionTag: "talk" },
        hostile: { mood: -1, favor: -3, hostility: 3, intent: "talk", markMet: true, actionTag: "talk" }
    };
    const canned = pending.options.map((item, i) => ({
        id: "respond-canned-" + i,
        kind: "reply",
        tone: item.stance === "hostile" ? "hostile" : "friendly",
        stance: item.stance || "guarded",
        label: item.label,
        text: `You say, "${item.say}"`,
        promptText: item.say,
        guideParty: item.guideParty || null,
        guideTalk: item.guideTalk || null,
        intent: "talk",
        relationshipImpact: Object.assign({}, stanceImpact[item.stance] || stanceImpact.guarded),
        noPrefetch: true
    }));
    return options.slice(0, insertAt).concat(canned, options.slice(insertAt));
}

// Free-text reply. Plain text is spoken; starting with * describes an action
// (e.g. "*nod slowly" -> "You nod slowly.").
let typedResponseCounter = 0;

// LIVE CHAT: "Say something..." opens a text box that STAYS open after every
// reply, so the player can keep a real conversation going with Enter. The
// player leaves it with "Menu" (back to the option list), "Leave" (says
// goodbye) or Esc. chatLiveNPC remembers who the live chat is with.
let chatLiveNPC = null;

function endLiveChat() { chatLiveNPC = null; }

// After an NPC reply: keep the box open while a live chat is on, else the menu.
function renderChatAfterReply(npc) {
    if (G.activeNPC !== npc) return;
    if (chatLiveNPC && chatLiveNPC === npc && canConverseWithNPC(npc)) {
        showRespondInput(npc);
        return;
    }
    chatLiveNPC = null;
    G.activeNPCMode = "talk";
    renderChatOptions(npc);
}

function showRespondInput(npc) {
    if (typeof textModeState !== "undefined" && textModeState.enabled) {
        G.activeNPCMode = "talk";
        renderChatOptions(npc);
        textModeResult("completed", 'Use say "..." in the command box to speak, or use act wave / dance with <npc> for a social gesture.');
        focusTextModeInput();
        return;
    }
    const el = document.getElementById("chatOptionsEl");
    if (!el || !npc) return;

    chatLiveNPC = npc;
    G.activeNPCMode = "respond";
    el.innerHTML = "";

    // If the NPC just asked something, keep their suggested answers as quick replies.
    let canned = [];
    try {
        canned = withCannedReplyOptions(npc, [{ id: "respond-free" }]).filter(function (o) { return o && o.kind === "reply"; });
    } catch (e) { canned = []; }
    if (canned.length) {
        const chips = document.createElement("div");
        chips.className = "chat-respond-chips";
        chips.style.cssText = "display:flex;flex-wrap:wrap;gap:6px;margin-bottom:6px;width:100%;";
        canned.forEach(function (option) {
            const btn = document.createElement("button");
            btn.type = "button";
            btn.className = "chat-option-btn kind-reply" + (option.stance ? " stance-" + option.stance : "");
            btn.textContent = option.label;
            btn.onclick = function () { chooseChatOption(option); };
            chips.appendChild(btn);
        });
        el.appendChild(chips);
    }

    const row = document.createElement("div");
    row.className = "chat-respond-row";

    const input = document.createElement("input");
    input.type = "text";
    input.maxLength = 240;
    input.className = "chat-respond-input";
    input.placeholder = "Say something... (Enter to send, * to describe an action)";
    input.setAttribute("autocomplete", "off");

    const send = document.createElement("button");
    send.type = "button";
    send.className = "chat-option-btn kind-reply chat-respond-send";
    send.textContent = "Say it";

    const back = document.createElement("button");
    back.type = "button";
    back.className = "chat-option-btn kind-exit chat-respond-back";
    back.textContent = "Menu";

    const leave = document.createElement("button");
    leave.type = "button";
    leave.className = "chat-option-btn kind-exit chat-respond-leave";
    leave.textContent = "Leave";

    const cancel = function () {
        chatLiveNPC = null;
        G.activeNPCMode = "talk";
        renderChatOptions(npc);
    };
    const submit = function () {
        if (input.disabled) return;
        const raw = String(input.value || "").replace(/\s+/g, " ").trim();
        if (!raw) return;
        input.disabled = true;
        submitTypedResponse(npc, raw);
    };
    const leaveChat = function () {
        chatLiveNPC = null;
        let goodbye = null;
        try { goodbye = getChatOptions(npc).filter(function (o) { return o && o.id === "goodbye"; })[0] || null; } catch (e) { goodbye = null; }
        chooseChatOption(goodbye || { id: "goodbye", text: "You say goodbye and step away.", label: "Say goodbye", action: "disengage", intent: "goodbye", relationshipImpact: { mood: 0, favor: 1, intent: "goodbye", markMet: true, actionTag: "goodbye" } });
    };

    send.onclick = submit;
    back.onclick = cancel;
    leave.onclick = leaveChat;
    input.addEventListener("keydown", function (e) {
        e.stopPropagation();
        if (e.key === "Enter") { e.preventDefault(); submit(); }
        else if (e.key === "Escape") { e.preventDefault(); cancel(); }
    });

    row.appendChild(input);
    row.appendChild(send);
    row.appendChild(back);
    row.appendChild(leave);
    el.appendChild(row);
    setTimeout(function () { input.focus(); }, 0);
}

// ── DIRECTIONS ───────────────────────────────────────────────────
// "Ask for directions" (catalogue id ask-directions) lists named buildings the
// speaker knows and answers with a real route over the town map: a breadth-first
// walk over room exits (no AI call, so it is instant and always correct).
const DIRECTION_WORDS = { N: "north", S: "south", E: "east", W: "west", NE: "northeast", NW: "northwest", SE: "southeast", SW: "southwest" };
const DIRECTION_COUNT_WORDS = ["no", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"];
const DIRECTIONS_MENU_MAX = 6;
const DIRECTIONS_MAX_NODES = 800;

// Named buildings in this zone that the speaker can point to.
// Returns [{ key, buildingId, name, room }]; unsorted.
function getDirectionsCandidates(npc, ctx) {
    const here = G.activeRoom;
    if (!npc || !here || !G.roomMap) return [];
    const known = {};
    if (typeof getNPCKnownLoreFacts === "function") {
        const c = ctx || (typeof getNPCConversationContext === "function" ? getNPCConversationContext(npc, { room: here }) : null);
        if (c) getNPCKnownLoreFacts(npc, c).forEach(function (entry) { known[entry.fact.id] = true; });
    }
    const npcKey = typeof _loreNpcKey === "function" ? _loreNpcKey(npc) : String(npc.id || npc.name || "npc");
    const out = [];
    const seen = {};
    Object.keys(G.roomMap).forEach(function (key) {
        const r = G.roomMap[key];
        if (!r || !r.isEntrance || !r.buildingId || r.zone !== here.zone || seen[r.buildingId]) return;
        const name = r.buildingName || (r.buildingType === "Town Hall" ? "the Town Hall" : "");
        if (!name) return;
        if (here.buildingId && here.buildingId === r.buildingId) return;
        // A local knows most of their own town; the rest comes from the lore pool.
        const knows = known["place-" + r.buildingId] || (typeof _loreHash === "function" && _loreHash(npcKey + ":dir:" + r.buildingId) < 80);
        if (!knows) return;
        seen[r.buildingId] = true;
        out.push({ key: r.coords || key, buildingId: r.buildingId, name: name, room: r });
    });
    return out;
}
window.getDirectionsCandidates = getDirectionsCandidates;

// Shortest walk over known, unlocked exits from `fromRoom` to the room at
// `toKey`. Never cuts through someone else's building. Returns [{ dir, key }]
// (empty when already there) or null when there is no way.
function findDirectionsRoute(fromRoom, toKey, targetBuildingId) {
    if (!fromRoom || !G.roomMap || !fromRoom.coords) return null;
    const startKey = fromRoom.coords;
    if (startKey === toKey) return [];
    const prev = {};
    prev[startKey] = null;
    const queue = [startKey];
    let head = 0;
    while (head < queue.length && head < DIRECTIONS_MAX_NODES) {
        const key = queue[head++];
        const room = G.roomMap[key];
        if (!room || !room.exits) continue;
        const dirKeys = Object.keys(room.exits);
        for (let i = 0; i < dirKeys.length; i++) {
            const dir = normalizeDirection(dirKeys[i]);
            if (!dir || isVerticalDirection(dir) || isPortalExit(room, dir)) continue;
            const lock = getExitLock(room, dir);
            if (lock && lock.state === "locked") continue;
            const nextKey = room.exits[dirKeys[i]];
            const next = G.roomMap[nextKey];
            if (!next || next.zone !== fromRoom.zone || Object.prototype.hasOwnProperty.call(prev, nextKey)) continue;
            if (next.buildingId && next.buildingId !== targetBuildingId && next.buildingId !== fromRoom.buildingId) continue;
            prev[nextKey] = { from: key, dir: dir };
            if (nextKey === toKey) {
                const steps = [];
                let cur = nextKey;
                while (prev[cur]) {
                    steps.unshift({ dir: prev[cur].dir, key: cur });
                    cur = prev[cur].from;
                }
                return steps;
            }
            queue.push(nextKey);
        }
    }
    return null;
}

// "head west for three blocks to the Square, then north for two blocks"
function describeDirectionsRoute(fromRoom, steps) {
    if (!steps || !steps.length) return "";
    const segs = [];
    steps.forEach(function (st) {
        const last = segs[segs.length - 1];
        if (last && last.dir === st.dir) { last.count += 1; last.key = st.key; }
        else segs.push({ dir: st.dir, count: 1, key: st.key });
    });
    const parts = segs.map(function (seg, i) {
        const word = DIRECTION_WORDS[seg.dir] || seg.dir.toLowerCase();
        const n = seg.count < DIRECTION_COUNT_WORDS.length ? DIRECTION_COUNT_WORDS[seg.count] : String(seg.count);
        let text = (i === 0 ? "head " : "") + word + (seg.count > 1 ? " for " + n + " blocks" : " one block");
        const endRoom = G.roomMap[seg.key];
        const label = endRoom ? String(endRoom.displayName || endRoom.name || endRoom.type || "") : "";
        if (i < segs.length - 1 && /square|gate|plaza|crossroads|market/i.test(label)) text += " to the " + label.replace(/^the\s+/i, "");
        return text;
    });
    let out = parts.join(", then ");
    if (fromRoom && fromRoom.buildingId) out = "go out through the door, then " + out.replace(/^head /, "");
    return out;
}

function showDirectionsMenu(npc) {
    const el = document.getElementById("chatOptionsEl");
    if (!el || !npc) return;
    const here = G.activeRoom;
    if (typeof travelNPCBlock === "function") { const reason = travelNPCBlock(npc, "directions"); if (reason) return sharedChoiceResult("blocked", reason); }
    const list = travelDirections(npc);

    el.innerHTML = "";
    G.activeNPCMode = "talk";
    const menu = beginTravelMenu(npc, "directions", "Ask for directions — 1 turn per answer");
    list.forEach(function (dest) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "chat-option-btn kind-action";
        btn.textContent = "▸ Ask the way to " + dest.name;
        btn.onclick = function () { return handleDirectionsChoice(npc, dest); };
        el.appendChild(registerTravelButton(menu, btn, { action: "directions", dest: dest }));
    });
    const back = document.createElement("button");
    back.type = "button";
    back.className = "chat-option-btn kind-exit";
    back.textContent = list.length ? "Never mind" : "Nobody here can point you anywhere. Go back";
    back.onclick = function () { renderChatOptions(npc); return { status: "completed" }; };
    el.appendChild(registerTravelButton(menu, back, { action: "back" }));
    return publishTravelMenu(menu, el, { destinations: list.map(function (dest) { return { name: dest.name, routeAvailable: !!dest.route }; }) });
}

function handleDirectionsChoice(npc, dest) {
    if (!npc || !dest) return;
    const travelContext = typeof captureTravelAction === "function" ? captureTravelAction(npc, "directions", dest) : null;
    if (travelContext && travelContext.error) return travelContext.error;
    const route = dest.route !== undefined ? dest.route : getRouteForDestination(G.activeRoom, dest);
    const cap = dest.name.charAt(0).toUpperCase() + dest.name.slice(1);
    const band = typeof getConversationRelationshipBand === "function" ? getConversationRelationshipBand(npc) : "neutral";
    const intro = band === "friendly"
        ? rand(["Happy to.", "Easy enough.", "Of course."])
        : rand(["Right.", "Sure.", "Well enough."]);
    const where = typeof _placeWhere === "function" && dest.room ? _placeWhere(dest.room) : "";
    let line;
    let fact = "";
    if (route && route.length === 0) {
        line = "\"" + cap + "? You are standing in it.\"";
    } else if (route) {
        const text = describeDirectionsRoute(G.activeRoom, route);
        line = "\"" + intro + " From here, " + text + ". " + cap + (where ? " is " + where + "." : " is right there.") + "\"";
        fact = "Directions to " + dest.name + ": " + text + ".";
    } else {
        line = "\"I know where " + dest.name + " is" + (where ? ", " + where : "") + ", but I could not give you a clear way there from here.\"";
    }
    if (typeof applyNPCDrunkSpeech === "function") line = applyNPCDrunkSpeech(npc, line);

    const playerLine = "You ask the way to " + dest.name + ".";
    addChatMessage("player", "You", playerLine, { mode: "narration", animate: true });
    advanceNPCAffectTime(1);
    advanceStoryTurn(1);
    if (travelContext && !travelActionCurrent(travelContext)) return travelInterrupted(travelContext);
    addChatMessage("left", npc.name, line, { mode: "auto" });
    if (typeof rememberNPCConversationLine === "function") {
        rememberNPCConversationLine(npc, "player", playerLine, "curious");
        rememberNPCConversationLine(npc, "npc", line, "curious");
    }
    if (typeof recordNPCConversationChoice === "function") recordNPCConversationChoice(npc, { id: "ask-directions", intent: "curious" });
    applyNPCImpact(npc, { mood: 0, favor: 1, intent: "curious", markMet: true, actionTag: "ask-directions" });
    if (npc.memory) npc.memory.lastSpokenTo = Date.now();
    if (fact) addStoryFact(fact);
    G.activeNPCMode = "talk";
    if (route && route.length > 0) showLeadOfferMenu(npc, dest);
    else renderChatOptions(npc);
    saveGameState();
    if (travelContext) travelActionResult(travelContext, { destination: dest.name, routeAvailable: !!route, route: route ? route.map(function (step) { return { direction: DIRECTION_WORDS[step.dir] || step.dir.toLowerCase() }; }) : null });
    return { status: route && route.length > 0 ? "needs_input" : "completed" };
}

// ── ROUTES AND GUIDING ("show me the way") ─────────────────────────────────
// One cross-zone route finder serves two things: an NPC who leads the player
// to a place they know (Follow / Keep following), and an explorer finding its
// own way home from far away. findRoomRoute is a breadth-first walk over the
// exits that exist: it respects collapses, locks (the NPC's own access when an
// npc is passed, never a locked door for the player), skips portals and never
// cuts through somebody else's building. Returns [{ dir, key }] (empty when
// already there) or null when there is no way.
const ROUTE_MAX_NODES = 4000;

function findRoomRoute(fromRoom, toKey, opts) {
    if (!fromRoom || !G.roomMap || !fromRoom.coords || !toKey) return null;
    const o = opts || {};
    const npc = o.npc || null;
    const maxNodes = o.maxNodes || ROUTE_MAX_NODES;
    const startKey = fromRoom.coords;
    if (startKey === toKey) return [];
    const prev = {};
    prev[startKey] = null;
    const queue = [startKey];
    let head = 0;
    while (head < queue.length && head < maxNodes) {
        const key = queue[head++];
        const room = G.roomMap[key];
        if (!room || !room.exits) continue;
        const dirKeys = Object.keys(room.exits);
        for (let i = 0; i < dirKeys.length; i++) {
            const dir = normalizeDirection(dirKeys[i]);
            if (!dir || isPortalExit(room, dir)) continue;
            if (npc && isVerticalDirection(dir)) continue;      // NPCs do not use stairs on their own
            if (isExitCollapsed(room, dir)) continue;
            if (typeof getDoorObstruction === "function" && getDoorObstruction(room, dir)) continue;
            if (npc) { if (!npcLockAccess(npc, room, dir).ok) continue; }
            else if (isExitLocked(room, dir)) continue;
            const nextKey = room.exits[dirKeys[i]];
            const next = G.roomMap[nextKey];
            if (!next || Object.prototype.hasOwnProperty.call(prev, nextKey)) continue;
            if (next.buildingId && next.buildingId !== o.targetBuildingId && next.buildingId !== fromRoom.buildingId) continue;
            prev[nextKey] = { from: key, dir: dir };
            if (nextKey === toKey) {
                const steps = [];
                let cur = nextKey;
                while (prev[cur]) {
                    steps.unshift({ dir: prev[cur].dir, key: cur });
                    cur = prev[cur].from;
                }
                return steps;
            }
            queue.push(nextKey);
        }
    }
    return null;
}
window.findRoomRoute = findRoomRoute;

// Places this speaker can point to or lead to: the named buildings they know
// in this zone, and, for someone standing outside the Town zone, the way back
// to the town gate (they walked out of it).
function getGuideDestinations(npc, ctx) {
    const out = getDirectionsCandidates(npc, ctx).slice();
    const here = G.activeRoom;
    if (npc && npc.isHumanoid !== false && here && (here.zone || "Town") !== "Town" && typeof getTownGateRoom === "function") {
        const gate = getTownGateRoom();
        if (gate && (isExplorerNPC(npc) || npc._homeCoords)) out.push({ key: gate.coords, buildingId: undefined, name: "the town gate", room: gate, kind: "gate" });
    }
    return out;
}
window.getGuideDestinations = getGuideDestinations;

function getRouteForDestination(fromRoom, dest) {
    if (!dest) return null;
    if (dest.kind === "gate") return findRoomRoute(fromRoom, dest.key, {});
    return findDirectionsRoute(fromRoom, dest.key, dest.buildingId);
}

const GUIDE_MAX_ROUTE = 60;           // rooms: nobody walks you further than this
const GUIDE_KEEP_DELAY_MS = 3000;
const GUIDE_AGREE_LINES = ["All right, this way.", "Fine, I'll take you. Keep up.", "Come on, then."];
const GUIDE_AGREE_FRIENDLY = ["Of course. Follow me.", "Happy to. This way.", "Sure, I'll walk you there."];

// Why this NPC will not lead the player (a line in their voice), or "" when
// they will. Guards and staff on duty will not leave their post; the hostile
// and the unfriendly say no.
function getLeadRefusal(npc, dest, route) {
    if (!npc) return "I can't.";
    if (!isAwakeHumanoidNPC(npc) || npc._drunkBlackout || (npc.currentState && npc.currentState.sleeping)) return "...";
    if (npc.currentState && npc.currentState.fighting) return "Not now!";
    if ((npc.hostility || 0) >= 30) return "I'd sooner not be seen walking with you.";
    const favor = npc.memory && typeof npc.memory.favorability === "number" ? npc.memory.favorability : 0;
    if (favor < 0) return "Not today. I've told you the way; that will have to do.";
    if (typeof isGuardNPC === "function" && isGuardNPC(npc)) return "I can't leave my post. I've told you the way.";
    if (typeof isNPCScheduled === "function" && isNPCScheduled(npc) && typeof getNPCRoutineNow === "function" && getNPCRoutineNow(npc).where !== "home") {
        return "I can't leave my work. I've told you the way.";
    }
    if (route && route.length > GUIDE_MAX_ROUTE) return "That's a long walk. I'll point you, but I won't take you.";
    if (G.guiding && G.guiding.npc && G.guiding.npc !== npc) return "I'd not get in the way of someone already leading you.";
    return "";
}

function showLeadOfferMenu(npc, dest) {
    const el = document.getElementById("chatOptionsEl");
    if (!el) { renderChatOptions(npc); return; }
    const reason = travelNPCBlock(npc, "lead"); if (reason) return sharedChoiceResult("blocked", reason);
    el.innerHTML = "";
    G.activeNPCMode = "talk";
    const menu = beginTravelMenu(npc, "lead", "Ask them to lead you — 1 turn on agreement", dest);
    const ask = document.createElement("button");
    ask.type = "button";
    ask.className = "chat-option-btn kind-action";
    ask.textContent = "▸ Ask " + (npc.name || "them") + " to show you the way";
    ask.onclick = function () { return askNPCToLeadYou(npc, dest); };
    el.appendChild(registerTravelButton(menu, ask, { action: "lead", dest: dest }));
    const back = document.createElement("button");
    back.type = "button";
    back.className = "chat-option-btn kind-exit";
    back.textContent = "Thanks, that's enough";
    back.onclick = function () { renderChatOptions(npc); return { status: "completed" }; };
    el.appendChild(registerTravelButton(menu, back, { action: "back" }));
    return publishTravelMenu(menu, el, { destination: dest.name });
}

function askNPCToLeadYou(npc, dest) {
    if (!npc || !dest) return;
    const here = G.activeRoom;
    const travelContext = typeof captureTravelAction === "function" ? captureTravelAction(npc, "lead", dest) : null;
    if (travelContext && travelContext.error) return travelContext.error;
    const route = getRouteForDestination(here, dest);
    const refusal = getLeadRefusal(npc, dest, route);
    const playerLine = "You ask " + (npc.name || "them") + " to show you the way to " + dest.name + ".";
    addChatMessage("player", "You", playerLine, { mode: "narration", animate: true });
    let line;
    if (refusal) {
        line = "\"" + refusal + "\"";
    } else if (!route || !route.length) {
        line = "\"You are practically there.\"";
    } else {
        const band = typeof getConversationRelationshipBand === "function" ? getConversationRelationshipBand(npc) : "neutral";
        line = "\"" + rand(band === "friendly" ? GUIDE_AGREE_FRIENDLY : GUIDE_AGREE_LINES) + "\"";
    }
    if (typeof applyNPCDrunkSpeech === "function") line = applyNPCDrunkSpeech(npc, line);
    addChatMessage("left", npc.name, line, { mode: "auto" });
    if (typeof rememberNPCConversationLine === "function") {
        rememberNPCConversationLine(npc, "player", playerLine, "curious");
        rememberNPCConversationLine(npc, "npc", line, "curious");
    }
    if (refusal || !route || !route.length) {
        if (npc.memory) npc.memory.lastSpokenTo = Date.now();
        G.activeNPCMode = "talk";
        renderChatOptions(npc);
        return travelContext ? travelActionResult(travelContext, { destination: dest.name, refused: !!refusal, leading: false }) : { status: "completed" };
    }
    advanceNPCAffectTime(1);
    advanceStoryTurn(1);
    if (travelContext && !travelActionCurrent(travelContext)) return travelInterrupted(travelContext);
    startGuiding(npc, dest);
    applyNPCImpact(npc, { mood: 0, favor: 1, intent: "curious", markMet: true, actionTag: "lead-player" });
    if (npc.memory) npc.memory.lastSpokenTo = Date.now();
    disengageFromNPC(npc.name + " sets off toward " + dest.name + ", glancing back to see that you keep up. Use Follow to keep pace.");
    renderInteractSidePanels();
    if (travelContext) travelActionResult(travelContext, { destination: dest.name, leading: true, refused: false });
    return { status: "interrupted" };
}

// Session-only generation: old walking timers cannot resume a stopped/replaced walk.
let guideWalkSequence = 0;

function startGuiding(npc, dest) {
    if (G.guiding) endGuiding(G.guiding, "");
    guideWalkSequence++;
    G.guiding = { npc: npc, destKey: dest.key, destName: dest.name, buildingId: dest.buildingId, keep: false, startedTurn: getCurrentStoryTurn() };
    npc._guiding = true;
    addSessionFollower(npc);
}

function endGuiding(g, note) {
    if (!g) return;
    const npc = g.npc;
    if (G.guiding === g) { G.guiding = null; guideWalkSequence++; }
    if (npc) {
        npc._guiding = false;
        if ((G.sessionFollowers || []).indexOf(npc) >= 0 && !npc._inParty) removeSessionFollower(npc);
    }
    if (note && typeof queueTurnNote === "function") queueTurnNote(note);
    if (typeof renderInteractSidePanels === "function") renderInteractSidePanels();
    if (typeof travelWalkMaybeComplete === "function") travelWalkMaybeComplete();
}

// The active guide, or null (and cleaned up) when they are gone, down, or no
// longer with the player.
function getGuiding() {
    const g = G.guiding;
    if (!g) return null;
    const npc = g.npc;
    const room = G.activeRoom;
    const here = !!(npc && room && Array.isArray(room.creatures) && room.creatures.indexOf(npc) >= 0);
    if (!npc || !isAwakeHumanoidNPC(npc) || npc._drunkBlackout || (npc.currentState && npc.currentState.sleeping) || (G.sessionFollowers || []).indexOf(npc) < 0 || !here) {
        endGuiding(g, npc && npc.name ? "You lose track of " + npc.name + "." : "");
        return null;
    }
    return g;
}

// A hostile-looking bystander is not a reason to stop walking; combat is.
function guideBlocked() {
    return G.activeNPCMode === "combat";
}

function guideDecisionPending() {
    const p = G.player;
    return !p || p.dead || p.hp <= 0 || p.unconscious || p._dying || p._collapsing ||
        G.activeNPC || G.activeObject || G.activeItemModal ||
        (typeof hasPendingPartyLoot === "function" && hasPendingPartyLoot());
}

// Append actions to central narration without removing the new room's details.
// Publish only the added line, so text/TTS do not repeat the room description.
function guideAct(npc, text) {
    if (!npc || !text) return;
    const el = document.getElementById("narrationEl");
    if (el) {
        appendNarrationBreak(el);
        appendNarrationBreak(el);
        appendNarrationText(el, text);
    }
    if (typeof textModeState !== "undefined" && textModeState.enabled) publishTextModeOutput("narration", text, { source: "engine" });
}

function guideSay(npc, text) {
    if (!npc || !text || typeof addChatMessage !== "function") return;
    let line = "\"" + text + "\"";
    if (typeof applyNPCDrunkSpeech === "function") line = applyNPCDrunkSpeech(npc, line);
    addChatMessage("left", npc.name || "Your guide", line, { mode: "auto" });
    return line;
}

function completeGuidedArrival(g, text) {
    if (getGuiding() !== g || G.activeRoom.coords !== g.destKey || guideBlocked()) return "blocked";
    const npc = g.npc;
    const canTalk = !guideDecisionPending() && canConverseWithNPC(npc);
    endGuiding(g, "");
    applyNPCImpact(npc, { mood: 1, favor: 2, intent: "friendly", markMet: true, actionTag: "led-player" });
    // A fight, injury or another decision owns its own controls and narration.
    if (!canTalk) return "arrived";
    selectNPC(npc);
    if (G.activeNPC !== npc || G.activeNPCMode === "combat") return "arrived";
    const state = ensureNPCConversationState(npc);
    // Walking here continues an existing conversation. Unlock its topics
    // without replaying a greeting, charging a turn, or giving greeting rewards.
    if (state && state.sessionUsedOptionIds.indexOf("greet-known") < 0) state.sessionUsedOptionIds.push("greet-known");
    npc.memory.pendingResponse = null;
    startNPCConversation(npc);
    guideAct(npc, text || (npc.name || "Your guide") + " stops beside you at " + g.destName + ".");
    const line = guideSay(npc, "Here we are. " + g.destName.replace(/^./, function (c) { return c.toUpperCase(); }) + ".");
    if (line && typeof rememberNPCConversationLine === "function") rememberNPCConversationLine(npc, "npc", line, "friendly");
    npc.memory.lastSpokenTo = Date.now();
    saveGameState();
    return "arrived";
}

// One room along the way. Both manual and automatic following share this action.
function performGuidedStep() {
    const g = getGuiding();
    if (!g) return "blocked";
    const room = G.activeRoom;
    const player = G.player;
    const name = g.npc.name || "Your guide";
    if (guideBlocked()) {
        g.keep = false;
        guideAct(g.npc, name + " stops short.");
        guideSay(g.npc, "Not with that going on.");
        renderInteractSidePanels();
        return "blocked";
    }
    if (guideDecisionPending()) { stopKeepFollowing(); return "blocked"; }
    if (room.coords === g.destKey) return completeGuidedArrival(g);
    const route = findRoomRoute(room, g.destKey, { targetBuildingId: g.buildingId });
    if (!route || !route.length) {
        endGuiding(g, "");
        renderRoom();
        guideAct(g.npc, name + " frowns.");
        guideSay(g.npc, "The way is closed to us. I can't take you there from here.");
        return "blocked";
    }
    const step = route[0];
    const word = DIRECTION_WORDS[step.dir] || String(step.dir).toLowerCase();
    movePlayer(step.dir);
    if (G.activeRoom === room) {
        g.keep = false;
        return "blocked";
    }
    // Recheck the original actor and guide after movement/autonomy/entry hazards.
    if (G.player !== player || getGuiding() !== g) return "blocked";
    if (guideBlocked() || guideDecisionPending()) { g.keep = false; return "moved"; }
    if (G.activeRoom.coords === g.destKey) return completeGuidedArrival(g, name + " leads you " + word + " and stops.");
    guideAct(g.npc, name + " leads the way " + word + ".");
    return "moved";
}

function followGuideStep() {
    const ctx = typeof captureTravelStep === "function" ? captureTravelStep() : null;
    const result = performGuidedStep();
    if (typeof publishTravelStep === "function") publishTravelStep(ctx, result);
    return result;
}

function startKeepFollowing() {
    const g = getGuiding();
    if (!g) return;
    const run = ++guideWalkSequence;
    const task = typeof beginTravelWalk === "function" ? beginTravelWalk(g, run) : null;
    g.keep = true;
    runKeepFollowing(run);
    return task;
}

function stopKeepFollowing() {
    guideWalkSequence++;
    if (G.guiding) G.guiding.keep = false;
    if (typeof renderInteractSidePanels === "function") renderInteractSidePanels();
    if (typeof travelWalkMaybeComplete === "function") travelWalkMaybeComplete();
}

function runKeepFollowing(run) {
    try {
    if (run === undefined) run = guideWalkSequence;
    if (run !== guideWalkSequence) return;
    const g = getGuiding();
    if (!g || !g.keep) return;
    if (guideBlocked()) {
        g.keep = false;
        guideAct(g.npc, (g.npc.name || "Your guide") + " stops short.");
        guideSay(g.npc, "Not with that going on.");
        renderInteractSidePanels();
        return;
    }
    if (guideDecisionPending()) { stopKeepFollowing(); return; }
    const result = followGuideStep();
    const still = G.guiding;
    if (result === "moved" && still === g && still.keep && !guideBlocked()) {
        const room = G.activeRoom, player = G.player, moveSeq = player.moveSeq;
        setTimeout(function () {
            if (run !== guideWalkSequence || G.guiding !== g) return;
            if (G.activeRoom !== room || G.player !== player || player.moveSeq !== moveSeq) { stopKeepFollowing(); return; }
            runKeepFollowing(run);
        }, GUIDE_KEEP_DELAY_MS);
    } else if (still) {
        still.keep = false;
        if (guideBlocked() && result === "moved") {
            guideAct(still.npc, (still.npc.name || "Your guide") + " stops short.");
            guideSay(still.npc, "Not with that going on.");
        }
        renderInteractSidePanels();
    }
    } finally { if (typeof travelWalkMaybeComplete === "function") travelWalkMaybeComplete(); }
}

function stopFollowingGuide() {
    const g = G.guiding;
    if (!g) return;
    endGuiding(g, (g.npc && g.npc.name ? g.npc.name : "Your guide") + " shrugs and lets you go your own way.");
    renderRoom();
}

// Buttons for the left interact column while someone is leading the player.
function appendGuideButtons(leftEl, makeHeading) {
    const g = getGuiding();
    if (!g) return;
    leftEl.appendChild(makeHeading("Following " + (g.npc.name || "guide")));
    const add = function (label, title, fn) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "interact-side-btn";
        btn.textContent = label;
        btn.title = title || "";
        btn.onclick = fn;
        leftEl.appendChild(btn);
    };
    const route = findRoomRoute(G.activeRoom, g.destKey, { targetBuildingId: g.buildingId });
    const togo = route ? (route.length === 1 ? "one room to go" : route.length + " rooms to go") : "";
    add("Follow " + (g.npc.name || "guide"), "To " + g.destName + (togo ? ": " + togo : ""), function () { followGuideStep(); });
    if (g.keep) add("Stop walking", "Pause here", function () { stopKeepFollowing(); });
    else add("Keep following", "Walk the rest of the way unless something stops you", function () { startKeepFollowing(); });
    add("Stop following", "Let them go their own way", function () { stopFollowingGuide(); });
}

// -- GUIDE QUESTIONS ------------------------------------------------------
// The guide answers basic questions with scripted lines (GUIDE_KNOWLEDGE in
// cyoaftw-world-data.js). Suggested questions come from a menu; typed ones are
// matched by keyword in submitTypedResponse. Asking costs no story time.
function showGuideQuestionMenu(npc) {
    const el = document.getElementById("chatOptionsEl");
    if (!el || !npc) return;
    const reason = travelNPCBlock(npc, "questions"); if (reason) return sharedChoiceResult("blocked", reason);
    const list = typeof window.getGuideSuggestedQuestions === "function" ? window.getGuideSuggestedQuestions() : [];
    el.innerHTML = "";
    G.activeNPCMode = "talk";
    const menu = beginTravelMenu(npc, "questions", "Ask your guide a question — no turns");
    list.forEach(function (q) {
        if (q.id === "next") return;
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "chat-option-btn kind-action";
        btn.textContent = "\u25B8 " + q.question;
        btn.onclick = function () { return handleGuideAnswer(npc, q.id, null, null); };
        el.appendChild(registerTravelButton(menu, btn, { action: "questions", topic: q.id }));
    });
    const back = document.createElement("button");
    back.type = "button";
    back.className = "chat-option-btn kind-exit";
    back.textContent = "Never mind";
    back.onclick = function () { renderChatOptions(npc); return { status: "completed" }; };
    el.appendChild(registerTravelButton(menu, back, { action: "back" }));
    return publishTravelMenu(menu, el, { questions: list.filter(function (q) { return q.id !== "next"; }).map(function (q) { return { question: q.question }; }) });
}

// topicId: a GUIDE_KNOWLEDGE id. typedText: the player's own words, when typed.
function handleGuideAnswer(npc, topicId, typedText, choice) {
    if (!npc || !npc.guide || typeof window.getGuideTopic !== "function") return false;
    if (typeof travelNPCBlock === "function") { const reason = travelNPCBlock(npc, "questions"); if (reason) return sharedChoiceResult("blocked", reason); }
    const topic = window.getGuideTopic(topicId);
    if (!topic) return false;
    const bs = getPlayerBackstory();
    const line = window.getGuideTopicAnswer(topicId, bs);
    if (!line) return false;
    const playerLine = typedText ? 'You say, "' + typedText + '"' : 'You ask, "' + topic.question + '"';
    addChatMessage("player", "You", playerLine, { mode: "narration", animate: true });
    if (!npc.memory) npc.memory = {};
    npc.memory.pendingResponse = null;
    if (typeof rememberNPCConversationLine === "function") rememberNPCConversationLine(npc, "player", playerLine, "curious");
    npc.memory.lastSpokenTo = Date.now();
    G.activeNPCMode = "talk";
    const reply = queueGuideReply(npc, "topic-" + topicId, { lines: [line], replies: null, concern: topicId === "rest" ? "hurt" : "ready" }, playerLine, function () {
        if (typeof recordNPCConversationChoice === "function") {
            recordNPCConversationChoice(npc, { id: "guide-ask-" + topicId, intent: "curious", guideBeat: topicId === "next" ? "plan" : undefined });
        }
        if (typeof registerNPCToldMemory === "function") {
            registerNPCToldMemory(npc, "guide-" + topicId, "Answered their question: " + topic.question, { pinned: true, importance: 5, tags: ["guide", topicId] });
        }
    });
    if (reply && typeof reply.then === "function") { const result = reply.then(function (status) { return typeof travelGuideAnswerOutput === "function" ? travelGuideAnswerOutput(npc, topic, line, status) : status; }); return typeof textModeTrackTask === "function" ? textModeTrackTask(result) : result; }
    return true;
}


window.showGuideQuestionMenu = showGuideQuestionMenu;
window.handleGuideAnswer = handleGuideAnswer;

// ── SOCIAL FACTS ────────────────────────────────────────────────────────────
// Reveals one stored fact from the NPC's social sheet (see generateNPCSocial in
// cyoaftw-npc-data.js): standing, need, worry, liking or secret. Scripted, no
// AI call. The fact is marked known, becomes a story fact the player can act
// on, and the NPC warms a little to someone who asked.
const SOCIAL_FACT_IMPACT = {
    ties: { favor: 1, mood: 1 },
    standing: { favor: 1, mood: 0 },
    need: { favor: 1, mood: 0 },
    worry: { favor: 2, mood: 0 },
    liking: { favor: 1, mood: 1 },
    secret: { favor: 3, mood: 0 }
};

function handleSocialFact(npc, key, choice) {
    if (!npc || typeof window.getSocialFactAnswer !== "function") return false;
    const social = typeof window.ensureNPCSocial === "function" ? window.ensureNPCSocial(npc) : null;
    if (!social || !SOCIAL_FACT_IMPACT[key]) return false;
    const answer = window.getSocialFactAnswer(npc, key);
    if (!answer) return false;
    const ask = window.getSocialFactQuestion(npc, key);
    addChatMessage("player", "You", 'You ask, "' + ask + '"', { mode: "narration", animate: true });
    if (npc.memory) npc.memory.pendingResponse = null;
    if (typeof recordNPCConversationChoice === "function") {
        recordNPCConversationChoice(npc, { id: "ask-" + key, intent: "curious" });
    }
    // The facts are fixed; the live AI only voices them in the speaker's own
    // manner (see getSocialFactBrief). Scripted text is the fallback when the
    // AI is off, slow or unparseable.
    const room = G.activeRoom;
    const brief = typeof window.getSocialFactBrief === "function" ? window.getSocialFactBrief(npc, key) : "";
    const canAI = !!brief && room && typeof aiAvailable === "function" && aiAvailable() && typeof fetchLiveConversationReply === "function";
    if (!canAI) {
        finishSocialFact(npc, key, social, ask, answer, '"' + answer + '"');
        return true;
    }
    if (typeof setChatOptionsDisabled === "function") setChatOptionsDisabled(true);
    if (typeof addTypingIndicator === "function") addTypingIndicator();
    Promise.resolve(fetchLiveConversationReply(npc, { id: "ask-" + key, text: ask, promptText: ask, intent: "curious", contextNote: brief }, room))
        .catch(function () { return null; })
        .then(function (reply) {
            if (typeof removeTypingIndicator === "function") removeTypingIndicator();
            let spoken = reply && typeof reply === "object" ? reply.text : reply;
            spoken = typeof spoken === "string" ? spoken.trim() : "";
            if (spoken && typeof applyNPCDrunkSpeech === "function") spoken = applyNPCDrunkSpeech(npc, spoken);
            finishSocialFact(npc, key, social, ask, spoken || answer, spoken || ('"' + answer + '"'));
        });
    return true;
}

function finishSocialFact(npc, key, social, ask, told, shown) {
    const answer = window.getSocialFactAnswer(npc, key) || told;
    addChatMessage("left", npc.name, shown, { mode: "auto" });
    if (typeof rememberNPCConversationLine === "function") {
        rememberNPCConversationLine(npc, "player", 'You ask, "' + ask + '"', "curious");
        rememberNPCConversationLine(npc, "npc", told, "curious");
    }
    if (typeof registerNPCToldMemory === "function") {
        const toldImportance = { standing: 3, need: 4, worry: 5, liking: 3, secret: 7, ties: 3 };
        registerNPCToldMemory(npc, "social-" + key, "Told them: " + told, { importance: toldImportance[key] || 4, tags: [key] });
    }
    if (key === "standing") social.standingKnown = true;
    else if (key === "ties") npc.tiesKnown = true;
    else if (social[key]) social[key].known = true;
    const label = typeof window.getSocialIdentity === "function" ? window.getSocialIdentity(npc) : "";
    const who = npc.name + (label ? " (" + label + ")" : "");
    const verb = { standing: "described their place", need: "said they need", worry: "admitted they worry about", liking: "said they enjoy", secret: "confided", ties: "spoke of the people in their life" }[key] || "told";
    addStoryFact(who + " " + verb + ": " + (key === "standing" || key === "ties" ? answer : social[key].text));
    const impact = SOCIAL_FACT_IMPACT[key];
    if (typeof applyNPCImpact === "function") {
        applyNPCImpact(npc, { favor: impact.favor, mood: impact.mood, intent: "curious", actionTag: "ask-" + key });
    }
    if (npc.memory) npc.memory.lastSpokenTo = Date.now();
    if (G.activeNPC === npc) {
        G.activeNPCMode = "talk";
        if (typeof setChatOptionsDisabled === "function") setChatOptionsDisabled(false);
        renderChatOptions(npc);
    }
    saveGameState();
}
window.finishSocialFact = finishSocialFact;
window.handleSocialFact = handleSocialFact;

// ============================================================================
// LODGING - weekly room leases at an inn.
// Everyone but the nobles rents (see KINGDOM in world-data). The innkeeper lets
// a guest room by the week: the player gets a "Room key" for ONE assigned room,
// and the room is held for them (room.leasedBy) until the rent runs out. State:
// player.lodging = { buildingId, buildingName, roomCoords, paidUntil, houseName }.
// ============================================================================
const LODGING_DAY_TURNS = typeof STORY_DAY_TURNS === "number" ? STORY_DAY_TURNS : 54; // shared day/night calendar
const LODGING_WEEK_DAYS = 7;
const LODGING_WEEKLY_RENT = 35;       // a week of nightly tokens would be 42
const LODGING_KEY_ID = "room-key";

function getLodgingWeekTurns() { return LODGING_DAY_TURNS * LODGING_WEEK_DAYS; }

function getLodgingRoomDoors(room) {
    const out = [];
    if (!room || !room.locks) return out;
    Object.keys(room.locks).forEach(function (dir) {
        const lock = room.locks[dir];
        if (lock && (lock.keyId === "room-token" || lock.keyId === LODGING_KEY_ID)) out.push({ dir: dir, lock: lock });
    });
    return out;
}

// Both sides of a door carry a lock record; keep them in step.
function setLodgingDoorKey(room, dir, keyId, state) {
    const lock = room && room.locks ? room.locks[dir] : null;
    if (!lock) return;
    lock.keyId = keyId;
    if (state) lock.state = state;
    const other = room.exits && G.roomMap ? G.roomMap[room.exits[dir]] : null;
    const back = typeof oppositeDirection === "function" ? oppositeDirection(dir) : null;
    const otherLock = other && other.locks && back ? other.locks[back] : null;
    if (otherLock) {
        otherLock.keyId = keyId;
        if (state) otherLock.state = state;
    }
}

// The player's rented room does not exist until they pay. It is built then, in
// a free cell beside one of the inn's upstairs hallways, and stays in the world
// afterwards (their things stay in it) so a later week reuses it.
function findLodgingRoomSpot(buildingId) {
    if (!buildingId || !G.roomMap) return null;
    const dirs = ["W", "E", "N", "S"];
    let found = null;
    Object.keys(G.roomMap).forEach(function (coords) {
        const hall = G.roomMap[coords];
        if (found || !hall || hall.buildingId !== buildingId || hall.type !== "Upstairs Hallway") return;
        for (let i = 0; i < dirs.length; i++) {
            const dir = dirs[i];
            const target = getAdjacentCoords(hall.coords || coords, dir);
            if (target && !G.roomMap[target] && !(hall.exits && hall.exits[dir])) {
                found = { hall: hall, dir: dir, coords: target };
                return;
            }
        }
    });
    return found;
}

function createLodgingRoom(buildingId, buildingName) {
    const spot = findLodgingRoomSpot(buildingId);
    if (!spot) return null;
    const hall = spot.hall;
    const room = buildRoomInstance("Guest Room", hall.zone || "Town");
    if (!room) return null;
    const back = oppositeDirection(spot.dir);
    room.coords = spot.coords;
    room.buildingId = buildingId;
    room.buildingType = hall.buildingType || "Inn";
    room.buildingName = buildingName;
    room.isBuildingRoom = true;
    room.floor = hall.floor;
    room.isPlayerRoom = true;
    room.name = "Your Room";
    room.displayName = "Your Room";
    room.baseDescription = "Your rented room at " + buildingName + ". A real bed, a chest for your things, a wash basin, and a door that locks.";
    room.zoneTransitionStep = 0;
    room.exits = {};
    room.exits[back] = hall.coords;
    room.doors = {};
    room.doors[back] = "door";
    // Opens freely from inside; from the hall it needs the room key.
    room.locks = {};
    room.locks[back] = { state: "locked", level: 2, keyId: LODGING_KEY_ID, freeOpen: true };
    ensureRoomExits(hall);
    setRoomExit(hall, spot.dir, spot.coords);
    hall.doors = hall.doors || {};
    hall.doors[spot.dir] = "door";
    hall.locks = hall.locks || {};
    hall.locks[spot.dir] = { state: "locked", level: 2, keyId: LODGING_KEY_ID, freeOpen: false };
    G.roomMap[spot.coords] = room;
    return room;
}

function endLodging(lodging, lapsed) {
    const player = G.player;
    if (!lodging || !player) return;
    const entry = G.roomMap ? G.roomMap[lodging.roomCoords] : null;
    if (entry) {
        delete entry.leasedBy;
        getLodgingRoomDoors(entry).forEach(function (d) { setLodgingDoorKey(entry, d.dir, LODGING_KEY_ID, "locked"); });
    }
    if (Array.isArray(player.inventory)) {
        player.inventory = player.inventory.filter(function (it) { return !(it && it.leaseKey); });
    }
    player.lodging = null;
    player.lodgingRoom = { buildingId: lodging.buildingId, coords: lodging.roomCoords };
    if (lapsed) queueTurnNote("Your rent at " + lodging.buildingName + " has run out. The innkeeper takes the key back and locks your room. Your things stay inside until you pay again.");
}

// The player's current lease, or null. Lazily ends a lapsed one.
function getActiveLodging() {
    const l = G.player ? G.player.lodging : null;
    if (!l) return null;
    if (getCurrentStoryTurn() >= l.paidUntil) { endLodging(l, true); return null; }
    return l;
}

function describeLodgingRemaining(l) {
    const left = Math.max(0, l.paidUntil - getCurrentStoryTurn());
    const days = Math.ceil(left / LODGING_DAY_TURNS);
    return days <= 1 ? "less than a day" : days + " days";
}

function createLodgingKeyItem(buildingName) {
    return assignLootUID({
        id: LODGING_KEY_ID,
        name: "Room key",
        type: ["key", "misc"],
        leaseKey: true,
        value: 0,
        description: "An iron key on a wooden tag. It opens your rented room at " + buildingName + " while your rent is paid."
    });
}

function getReusableLodgingRoom(buildingId) {
    const mem = G.player ? G.player.lodgingRoom : null;
    if (!mem || mem.buildingId !== buildingId) return null;
    const r = G.roomMap[mem.coords];
    return r && r.isPlayerRoom ? r : null;
}

// The innkeeper's rent offer: say the terms, then let the player pay or leave.
function showRentRoomMenu(npc) {
    const el = document.getElementById("chatOptionsEl");
    const room = G.activeRoom;
    if (!el || !npc || !room) return;
    const reason = travelNPCBlock(npc, "rent"); if (reason) return sharedChoiceResult("blocked", reason);
    const player = G.player;
    const lodging = getActiveLodging();
    const buildingId = room.buildingId;
    const buildingName = room.buildingName || "the inn";
    const lh = typeof getBuildingLandholder === "function" ? getBuildingLandholder(buildingId, room.buildingType || "Inn") : null;
    const lord = lh ? lh.name : "the landlord";
    const renewing = !!(lodging && lodging.buildingId === buildingId);
    let line;
    let canPay = false;

    if (lodging && !renewing) {
        line = "\"You already hold a room at " + lodging.buildingName + ". Let that one go before you take another.\"";
    } else if (renewing) {
        line = "\"Your room is paid for another " + describeLodgingRemaining(lodging) + ". Another week is " + LODGING_WEEKLY_RENT + " coins, and the rent goes to " + lord + " all the same.\"";
        canPay = true;
    } else if (!getReusableLodgingRoom(buildingId) && !findLodgingRoomSpot(buildingId)) {
        line = "\"I am full up. Every room is let. Try again when someone's rent runs out, or pay for a night's token if one stands empty.\"";
    } else {
        line = "\"A room by the week is " + LODGING_WEEKLY_RENT + " coins, paid up front. I'll have one made up for you: a real bed, a chest, a lock. The land is " + lord + "'s and the rent goes up the ladder, so don't ask me to haggle. Fall behind and the room is let to someone else.\"";
        canPay = true;
    }
    addChatMessage("player", "You", 'You ask, "Can I rent a room by the week?"', { mode: "narration", animate: true });
    addChatMessage("left", npc.name, line, { mode: "auto" });

    el.innerHTML = "";
    G.activeNPCMode = "talk";
    const menu = beginTravelMenu(npc, "rent", "Weekly room rental — review and confirm payment separately");
    const approval = { npc: npc, used: false, valid: travelGuard(npc, "rent", null, true) };
    if (canPay) {
        const afford = (player.coins || 0) >= LODGING_WEEKLY_RENT;
        const pay = document.createElement("button");
        pay.type = "button";
        pay.className = "chat-option-btn kind-action";
        pay.textContent = (renewing ? "Pay for another week (" : "Rent the room (") + LODGING_WEEKLY_RENT + " coins)";
        pay.disabled = !afford;
        if (!afford) pay.title = "You can't afford it.";
        pay.onclick = function () { return rentInnRoom(npc, approval); };
        el.appendChild(registerTravelButton(menu, pay, { action: "pay" }));
    }
    const back = document.createElement("button");
    back.type = "button";
    back.className = "chat-option-btn kind-exit";
    back.textContent = "Never mind";
    back.onclick = function () { renderChatOptions(npc); return { status: "completed" }; };
    el.appendChild(registerTravelButton(menu, back, { action: "back" }));
    return publishTravelMenu(menu, el, { building: buildingName, fee: LODGING_WEEKLY_RENT, weekTurns: getLodgingWeekTurns(), renewing: renewing, canPay: canPay && (player.coins || 0) >= LODGING_WEEKLY_RENT });
}

function rentInnRoom(npc, approval) {
    if (!approval) return showRentRoomMenu(npc);
    if (approval.used || approval.npc !== npc || !approval.valid()) return sharedChoiceResult("blocked", "That rental quote changed. Review it again.");
    approval.used = true;
    const rentStart = getCurrentStoryTurn(), rentBefore = G.player.coins, rentRenewing = !!G.player.lodging;
    const room = G.activeRoom;
    const player = G.player;
    if (!room || !player || !npc) return;
    const buildingId = room.buildingId;
    const buildingName = room.buildingName || "the inn";
    if ((player.coins || 0) < LODGING_WEEKLY_RENT) { setNarration("You can't afford the rent."); return; }
    let lodging = getActiveLodging();
    let line;
    if (lodging && lodging.buildingId === buildingId) {
        player.coins -= LODGING_WEEKLY_RENT;
        lodging.paidUntil += getLodgingWeekTurns();
        line = "\"Paid up. Your room is yours for another week.\"";
    } else if (lodging) {
        return;
    } else {
        let leased = getReusableLodgingRoom(buildingId);
        let leasedCoords = leased ? leased.coords : null;
        if (!leased) {
            leased = createLodgingRoom(buildingId, buildingName);
            leasedCoords = leased ? leased.coords : null;
        }
        if (!leased) return showRentRoomMenu(npc);
        player.coins -= LODGING_WEEKLY_RENT;
        leased.leasedBy = "player";
        getLodgingRoomDoors(leased).forEach(function (d) { setLodgingDoorKey(leased, d.dir, LODGING_KEY_ID, "locked"); });
        const lh = typeof getBuildingLandholder === "function" ? getBuildingLandholder(buildingId, room.buildingType || "Inn") : null;
        player.lodging = {
            buildingId: buildingId,
            buildingName: buildingName,
            roomCoords: leasedCoords,
            paidUntil: getCurrentStoryTurn() + getLodgingWeekTurns(),
            houseName: lh ? lh.name : ""
        };
        player.inventory = Array.isArray(player.inventory) ? player.inventory : [];
        player.inventory.push(createLodgingKeyItem(buildingName));
        line = "\"Upstairs, along the hall: the door your key opens. The room is yours for a week.\"";
        if (typeof setStoryFlag === "function") setStoryFlag("has-lodging", true);
    }
    addChatMessage("left", npc.name, line, { mode: "auto" });
    rememberStoryEvent("social", (player.name || "The player") + " rented a room at " + buildingName + " for a week.", 4);
    if (typeof recordNPCConversationChoice === "function") {
        recordNPCConversationChoice(npc, { id: "rent-room", intent: "calm" });
    }
    renderStats();
    G.activeNPCMode = "talk";
    renderChatOptions(npc);
    saveGameState();
    publishTextModeOutput("travel", "You " + (rentRenewing ? "renew" : "rent") + " a room at " + buildingName + ".", { travel: { stage: "result", action: "rent", building: buildingName, fee: rentBefore - player.coins, turns: getCurrentStoryTurn() - rentStart, weekTurns: getLodgingWeekTurns(), renewed: rentRenewing, keyGiven: !rentRenewing, remainingTurns: player.lodging.paidUntil - getCurrentStoryTurn() } }, false);
    return { status: "completed" };
}
window.showRentRoomMenu = showRentRoomMenu;
window.rentInnRoom = rentInnRoom;
window.getActiveLodging = getActiveLodging;

function submitTypedResponse(npc, raw, options) {
    if (!npc || !raw) return;
    const isAction = !!(options && options.interaction) || !(options && options.speechOnly) && raw.charAt(0) === "*";
    let body = (isAction ? raw.replace(/^\*+\s*/, "").replace(/\*+\s*$/, "") : raw).replace(/"/g, "'").trim();
    if (!body) return;
    const familyAction = isAction && !(options && options.interaction) ? parseTextInteractionCommand(body) : null;
    if (familyAction || isAction && !(options && options.interaction) && !parseTextSocialCommand(body)) return submitFreeformNPCAction(npc, body);
    const social = options && options.interaction ? { args: options.interaction } : isAction ? parseTextSocialCommand(body) : null;
    if (social) {
        const reason = socialActionBlock(npc);
        if (reason) return socialActionFeedback("blocked", reason);
        if (social.args.target) {
            const matches = resolveTextNPCTarget(social.args.target).matches;
            if (matches.length !== 1 || matches[0] !== npc) return socialActionFeedback("blocked", "That gesture must address your current conversation partner. Choose them first, or use a targeted text command.");
        }
        const def = social.args.family ? null : SOCIAL_GESTURES[social.args.action];
        const target = typeof getNPCRoomSightName === "function" ? getNPCRoomSightName(npc) : npc.name || "them";
        body = def ? def.phrase + target + (def.invitation ? " to share a brief dance" : "")
            : social.args.family === "expression" ? "try to " + social.args.action + " toward " + target
            : social.args.family === "contact" ? "ask " + target + " whether you may " + social.args.action
            : "invite " + target + " to " + social.args.action;
    }

    // A drunk player's words come out slurred, on screen and to the NPC.
    const drunkTier = typeof getDrunkTier === "function" ? getDrunkTier(G.player) : 0;
    const spoken = !isAction && drunkTier >= 2 && typeof slurDrunkSpeech === "function" ? slurDrunkSpeech(body, drunkTier) : body;
    typedResponseCounter += 1;
    const choice = {
        id: "respond-typed-" + typedResponseCounter,
        kind: "reply",
        label: "Respond",
        text: isAction ? `You ${body}.` : `You say, "${spoken}"`,
        promptText: isAction ? `(action: ${body})` : spoken,
        intent: "talk",
        relationshipImpact: { mood: 0, favor: 0, hostility: 0, intent: "talk", markMet: true, actionTag: "talk" },
        // The relationship effect of typed words is decided AFTER the reply:
        // the AI rates the tone (playerTone) and npcRespond applies it via
        // buildTypedToneImpact. Until then the impact above is neutral.
        judgeTone: true,
        typedText: body,
        noPrefetch: true
    };
    if (social) {
        choice.socialGesture = social.args.action;
        choice.interactionFamily = social.args.family || "";
        choice.judgeTone = false;
        choice.promptText = "(social attempt: " + body + ")";
        choice.contextNote = "The player makes only this social gesture or invitation: " + body +
            ". React in character in 1-3 sentences; you may accept, decline or acknowledge it. A dance invitation does not assume agreement. Do not treat it as spoken words. You may describe a brief voluntary response, but do not invent items, payments, travel, secrets, combat outcomes or changes to health, skills or relationships. The engine owns all game effects.";
        if (choice.interactionFamily) choice.contextNote = "Player attempts only a " + choice.interactionFamily + ": " + body + ". React in character in 1-3 sentences. Expressions grant no contact. Invitations and gentle contact require your willingness; you may decline. Do not invent items, payments, secrets, travel, damage, healing or other game effects. The engine owns all game effects.";
        socialReplyState.set(choice, { player: G.player, room: G.activeRoom, npc: npc,
            target: typeof getNPCRoomSightName === "function" ? getNPCRoomSightName(npc) : npc.name || "the person", completed: false, interrupted: false, moveSeq: G.player.moveSeq || 0, session: npc.memory && npc.memory.conversationState && npc.memory.conversationState.sessionNumber || 0 });
    }
    // The guide knows basic, common things (see GUIDE_KNOWLEDGE in
    // cyoaftw-world-data.js). A typed question that matches a topic gets the
    // scripted answer (always right, no AI); anything else goes to the AI with a
    // note that the guide admits what they do not know.
    if (!isAction && npc.guide && npc.guide.active && typeof window.matchGuideTopic === "function") {
        const checkinBeat = getGuideTypedCheckinBeat(npc, body);
        if (checkinBeat && handleGuideTalk(npc, checkinBeat, choice)) return;
        const guideTopic = window.matchGuideTopic(body);
        if (guideTopic) {
            handleGuideAnswer(npc, guideTopic.id, spoken, null);
            return;
        }
        if (window.GUIDE_UNKNOWN_NOTE) choice.contextNote = window.GUIDE_UNKNOWN_NOTE;
    }
    // Asking their name in your own words: give the AI the real name so it
    // does not invent one, and make the name public once it is told.
    if (!isAction && typeof getTypedNameAskInfo === "function") {
        const nameAsk = getTypedNameAskInfo(npc, body);
        if (nameAsk) {
            choice.contextNote = nameAsk.note;
            choice.revealsName = nameAsk.reveal === true;
        }
    }
    G.activeNPCMode = "talk";
    if (!social) return chooseChatOption(choice);
    const state = socialReplyState.get(choice);
    publishTextModeOutput("social", choice.text, { status: "started",
        social: { gesture: choice.socialGesture, phase: "request", target: state.target, family: choice.interactionFamily || (choice.socialGesture === "dance" ? "invitation" : "expression"), invitation: !!(SOCIAL_GESTURES[choice.socialGesture] && SOCIAL_GESTURES[choice.socialGesture].invitation) || /^(invitation|contact)$/.test(choice.interactionFamily) }
    }, false);
    if (!socialReplyFresh(choice, npc)) return { status: "interrupted" };
    return Promise.resolve(chooseChatOption(choice)).then(function () {
        if (state.interrupted) return { status: "interrupted" };
        return state.completed ? { status: "completed" } : socialActionFeedback("blocked", "That social interaction could not finish. Pending commands are paused.");
    });
}

function clearChatOptions() {
    const el = document.getElementById("chatOptionsEl");
    if (el) el.innerHTML = "";
}

// -- COMBAT ---------------------------------------------------------------

// -- STAMINA ----------------------------------------------------------
// Every player attack (any style) costs stamina; heavy costs the most.
// At 0 stamina the player takes the "exhausted" status effect (a combat
// debuff, not unconsciousness - see STATUS_EFFECT_DEFINITIONS.exhausted).
// Recovery comes from Resting (attemptRest) or the Potion of Stamina -
// there is no passive per-turn regen.
const PLAYER_STAMINA_MAX = 20;

const COMBAT_ATTACK_STYLES = {
    light: {
        label: "Light",
        hitBonus: 2,
        damageBonus: -1,
        incomingBonus: -1,
        staminaCost: 1,
        text: "You press with a fast, controlled strike.",
        tip: "Fast and controlled: +2 to hit, slightly lighter damage (-1). The cheapest swing at 1 stamina."
    },
    balanced: {
        label: "Balanced",
        hitBonus: 1,
        damageBonus: 0,
        incomingBonus: 0,
        staminaCost: 2,
        text: "You commit to a measured attack.",
        tip: "A measured swing: +1 to hit, standard damage. The all-rounder at 2 stamina."
    },
    heavy: {
        label: "Heavy",
        hitBonus: -2,
        damageBonus: 3,
        incomingBonus: 2,
        staminaCost: 4,
        text: "You put your weight behind a heavy blow.",
        tip: "Full weight behind it: -2 to hit but +3 damage, and a miss leaves you open - their counter comes in harder. 4 stamina."
    },
    precise: {
        label: "Precise",
        hitBonus: 4,
        damageBonus: -2,
        incomingBonus: 0,
        staminaCost: 2,
        text: "You wait for a cleaner opening.",
        tip: "Wait for the clean opening: +4 to hit, reduced damage (-2). 2 stamina."
    }
};

const COMBAT_TARGETS = {
    torso: { label: "Torso", hitMod: 0, damageMod: 1, limbKey: "torso", tip: "The reliable shot: no penalty to hit, standard damage." },
    head:  { label: "Head",  hitMod: 4, damageMod: 1, limbKey: "head", tip: "Hardest to land (-4), same damage - but head wounds gut their attack." },
    arms:  { label: "Arms",  hitMod: 2, damageMod: 0, limbKey: "arms", tip: "2 harder to hit; damage lands on the arm - ruined arms wreck their swings." },
    legs:  { label: "Legs",  hitMod: 2, damageMod: 0, limbKey: "legs", tip: "2 harder to hit; damage lands on the leg - bad legs make fleeing and guarding hard." }
};

// The player's attack crits whenever their total clears the target's armor
// by this much (in addition to a natural 20 always critting). Raised from
// the original 8 -> 10 so a solid-but-not-exceptional roll (especially with
// a high-hit-bonus style like Light, or a headshot's armor penalty) doesn't
// crit quite so reliably. NPC attacks are unaffected - they only crit on a
// natural 20 (see resolveNPCCounter), so this only tunes the player's side.
const PLAYER_CRIT_MARGIN_THRESHOLD = 10;

// -- COMBAT SKILL TRACKING (player + NPC) ----------------------------------
// Weapon proficiency, attack/defense-style proficiency, and stat XP all
// accumulate here on both the player and NPCs.
//
// Impact, pass 1 (this pass): weapon proficiency and action-style proficiency
// feed small, hard-capped hit/armor bonuses back into combat math below (see
// getWeaponProficiencyHitBonus / getActionProficiencyHitBonus /
// getActionProficiencyArmorBonus). Deliberately hit-only, never damage -
// damage growth stays driven by the physicalProwess stat and gear, per
// design discussion, so proficiency rewards accuracy/consistency rather than
// bigger numbers.
//
// Impact, pass 2 (this pass): statXP crossing an escalating threshold now
// actually raises physicalProwess/endurance (see maybeLevelUpStat), and an
// endurance level tops up hpMax/hp (see applyEnduranceLevelHpGain). The
// threshold grows with the current stat value, so early levels come fast and
// later ones take a lot more fighting - see getStatLevelXPThreshold.
// physicalProwess has no hard cap; past STAT_LEVEL_SOFT_CAP each level costs extra (the hit/damage/
// armor formulas throughout this file were tuned around the 1-7
// character-creation range. Because attackNPC/attemptCombatEscape already
// read physicalProwess/flexibility straight off G.player.stats, the player's
// leveled-up stat feeds combat automatically with no other wiring; NPCs get
// the equivalent physicalProwess damage/hit bonus wired in explicitly below
// (see npcStatBonus in resolveNPCCounter) since they had no such bonus before
// this session.

function formatRollLine(label, roll, bonus, total, dc, hit, crit) {
    const bonusText = bonus >= 0 ? `+ ${bonus}` : `- ${Math.abs(bonus)}`;
    const outcome = roll === 1 ? "Critical Miss" : (crit ? "Critical Hit" : (hit ? "Hit" : "Miss"));
    return `[Roll] ${label}: d20(${roll}) ${bonusText} = ${total} vs ${dc} -> ${outcome}`;
}

function ensureCombatSkills(entity) {
    if (!entity || typeof entity !== "object") return null;
    entity.combatSkills = entity.combatSkills || {};
    entity.combatSkills.weapons = entity.combatSkills.weapons || {};
    entity.combatSkills.actions = entity.combatSkills.actions || {};
    entity.combatSkills.statXP = entity.combatSkills.statXP || {};
    return entity.combatSkills;
}

// -- STAT LEVELING (pass 2) -------------------------------------------------
const STAT_LEVEL_XP_MULTIPLIER = 10; // xpNeeded(current) = current * this
const STAT_LEVEL_SOFT_CAP = 12;      // no hard cap: past this each level costs extra (STAT_LEVEL_EXTRA_COST per point over)
const STAT_LEVEL_EXTRA_COST = 0.25;
const ENDURANCE_HP_PER_LEVEL = 2;

// Frame (somatotype) nudges how fast the PLAYER levels certain stats: a small
// multiplier on the stat XP they earn. Only applies when the player explicitly
// chose a frame at setup (older saves without one are left alone, so they do not
// silently get a bonus). NPCs are unaffected. Tunables: edit the table below.
const FRAME_STAT_XP_MULT = {
    ectomorph: { flexibility: 1.2, physicalProwess: 0.9 },
    mesomorph: { physicalProwess: 1.2 },
    endomorph: { endurance: 1.2 }
};
function getFrameStatXPMultiplier(entity, statKey) {
    if (!entity || entity !== G.player || !statKey) return 1;
    const frame = entity.appearance && entity.appearance.somatotype;
    const table = frame ? FRAME_STAT_XP_MULT[String(frame).toLowerCase()] : null;
    const mult = table ? table[statKey] : null;
    return typeof mult === "number" ? mult : 1;
}

// Base stamina pool: 1.5 points per Endurance, 1 point per Flexibility,
// combined and rounded UP once at character creation (see beginAdventure).
// Later growth from leveling either stat via the normal combat-skill XP
// system (see maybeLevelUpStat/applyStaminaLevelGain) is tracked against the
// same running exact total but is NOT re-rounded up each time - it's
// floored - so repeatedly leveling Endurance doesn't farm an extra half
// point of stamina on every other level the way re-ceiling would.
const STAMINA_PER_ENDURANCE = 1.5;
const STAMINA_PER_FLEXIBILITY = 1;

function calculateBaseStaminaExact(stats) {
    const endurance = stats && typeof stats.endurance === "number" ? stats.endurance : 3;
    const flexibility = stats && typeof stats.flexibility === "number" ? stats.flexibility : 3;
    return endurance * STAMINA_PER_ENDURANCE + flexibility * STAMINA_PER_FLEXIBILITY;
}

function getEntityStatValue(entity, statKey, fallback = 3) {
    const base = (entity && entity.stats && typeof entity.stats[statKey] === "number")
        ? entity.stats[statKey]
        : fallback;
    const wornBonus = statKey === "charisma"
        ? getWornCharismaBonus(entity) + getHygieneCharismaPenalty(entity)
        : 0;
    return Math.max(1, base + getStatusStatModifier(entity, statKey) + getCarriedStatBonus(entity, statKey) + wornBonus + getTiedGearPenalty(entity, statKey));
}

// Shared stat -> combat bonus formula: floor((stat - 3) / 2). 3-4 is +0,
// 5-6 is +1, 7-8 is +2, and so on. Deliberately NOT floored at 0: a stat of
// 1-2 is -1, so dumping a stat at character creation (or having it drained
// by status effects) has a real cost instead of being free, which keeps
// min-maxing honest. Stats are always >= 1 (see getEntityStatValue), so the
// penalty bottoms out at -1.
function getStatBonusFromValue(statValue) {
    return Math.floor((statValue - 3) / 2);
}

function getEntityStatCombatBonus(entity, statKey, fallback = 3) {
    return getStatBonusFromValue(getEntityStatValue(entity, statKey, fallback));
}

function getStatLevelXPThreshold(currentValue) {
    const v = Math.max(1, currentValue);
    const over = Math.max(0, v - STAT_LEVEL_SOFT_CAP);
    return Math.round(v * STAT_LEVEL_XP_MULTIPLIER * (1 + over * STAT_LEVEL_EXTRA_COST));
}

// -- SEVERING / WILLPOWER SAVE ------------------------------------------
// A severed limb doesn't automatically end the fight - the entity gets a
// willpower save to grit through it. Fail, and they go down (see the
// forced-outcome handling in attackNPC/resolveNPCCounter/
// determineCombatDefeatOutcome). Reuses the same generic stat-bonus formula
// every other stat check in this file uses, so a leveled-up willpower
// actually pays off here too.
const SEVER_WILLPOWER_SAVE_DC = 14;

function rollWillpowerSave(entity) {
    const roll = rollD20(entity);
    const bonus = getEntityStatCombatBonus(entity, "willpower");
    const total = roll + bonus;
    const success = roll !== 1 && (roll === 20 || total >= SEVER_WILLPOWER_SAVE_DC);
    return { roll, bonus, total, dc: SEVER_WILLPOWER_SAVE_DC, success };
}

// Generic stat check: d20 + the shared stat bonus (see getStatBonusFromValue)
// vs a DC. Same nat-1 auto-fail / nat-20 auto-success rule as the willpower
// save and attack rolls. Returns { roll, bonus, total, dc, success, critFail,
// critSuccess } so callers can narrate nat-1 / nat-20 differently and feed
// formatRollLine in debug mode. Used by the charisma "talk them down" action
// (see attemptTalkDown); rollWillpowerSave keeps its own fixed-DC wrapper.
function rollStatCheck(entity, statKey, dc) {
    const roll = rollD20(entity);
    const bonus = getEntityStatCombatBonus(entity, statKey);
    const total = roll + bonus;
    const success = roll !== 1 && (roll === 20 || total >= dc);
    return { roll, bonus, total, dc, success, critFail: roll === 1, critSuccess: roll === 20 };
}

// -- CHARISMA / ROOM AMBUSH SOFTENING ------------------------------------
// Charisma doesn't stop an ambush from being attempted - there's always a
// chance/roll for it, same as any other attack - it just softens the
// opening strike. Only charisma above the threshold does anything, and even
// then it's diminishing, same shape as the other stat-bonus formulas.
const ROOM_AMBUSH_OPENING_BONUS = 4; // matches the existing guard-checkpoint ambush
const ROOM_AMBUSH_CHARISMA_THRESHOLD = 4;

function getAmbushCharismaDiscount(entity) {
    const charisma = getEntityStatValue(entity, "charisma", 3);
    if (charisma <= ROOM_AMBUSH_CHARISMA_THRESHOLD) return 0;
    return Math.max(0, Math.floor((charisma - ROOM_AMBUSH_CHARISMA_THRESHOLD) / 2));
}

function getRoomAmbushOpeningBonus(entity) {
    return Math.max(0, ROOM_AMBUSH_OPENING_BONUS - getAmbushCharismaDiscount(entity));
}

// A point of endurance means more than a bigger number: it toughens the
// entity up right now, the same way a level-up heal would. Applied to both
// hp and hpMax so it's not just a bigger ceiling on an already-hurt entity.
function applyEnduranceLevelHpGain(entity, levels = 1) {
    if (!entity || levels <= 0) return;
    const gain = ENDURANCE_HP_PER_LEVEL * levels;
    entity.hpMax = Math.max(1, (typeof entity.hpMax === "number" ? entity.hpMax : 10) + gain);
    entity.hp = Math.max(0, (typeof entity.hp === "number" ? entity.hp : entity.hpMax) + gain);
}

// Player-only for now (see the STAMINA section - NPCs don't track stamina).
// Grows entity.staminaMaxExact by the stat's fractional per-point rate, then
// floors it to get the actual (integer) staminaMax - see the constants
// above for why this floors instead of ceiling like the base calculation
// does. Only bumps staminaMax (and grants the player the difference as
// current stamina, same as a level-up HP gain) when the floor actually
// crosses to a new integer.
function applyStaminaLevelGain(entity, statKey, levels = 1) {
    if (!entity || levels <= 0) return;
    const perPoint = statKey === "endurance" ? STAMINA_PER_ENDURANCE
        : statKey === "flexibility" ? STAMINA_PER_FLEXIBILITY
        : 0;
    if (!perPoint) return;

    if (typeof ensureEntityStamina === "function") ensureEntityStamina(entity);
    const staminaMaxExact = (typeof entity.staminaMaxExact === "number"
        ? entity.staminaMaxExact
        : (typeof entity.staminaMax === "number" ? entity.staminaMax : PLAYER_STAMINA_MAX)) + perPoint * levels;
    entity.staminaMaxExact = staminaMaxExact;

    const newMax = Math.max(1, Math.floor(staminaMaxExact));
    const gain = newMax - (typeof entity.staminaMax === "number" ? entity.staminaMax : newMax);
    entity.staminaMax = newMax;
    if (gain > 0) {
        entity.stamina = Math.min(entity.staminaMax, (typeof entity.stamina === "number" ? entity.stamina : entity.staminaMax) + gain);
    }
}

// Escalating threshold (current * STAT_LEVEL_XP_MULTIPLIER) means the first
// level comes quickly and each one after costs more successful actions than
// the last - a fresh fighter levels up fast, a veteran needs a lot more
// fighting for the next point, with extra cost per point beyond STAT_LEVEL_SOFT_CAP (never a hard stop).
// Looped in case one grant crosses more than one threshold at once (it
// shouldn't currently, since gains are +1 at a time, but this stays correct
// either way). Returns the level-up detail for the debug line, or null.
function maybeLevelUpStat(entity, statKey) {
    if (!entity || !statKey) return null;
    const skills = ensureCombatSkills(entity);
    if (!skills) return null;

    entity.stats = entity.stats || {};
    let leveled = null;
    const hpBeforeLevels = entity.hp;

    while (true) {
        const current = typeof entity.stats[statKey] === "number" ? entity.stats[statKey] : 3;

        const xp = skills.statXP[statKey] || 0;
        const threshold = getStatLevelXPThreshold(current);
        if (xp < threshold) break;

        skills.statXP[statKey] = xp - threshold;
        entity.stats[statKey] = current + 1;
        leveled = { statKey, from: current, to: current + 1, remainingXP: skills.statXP[statKey] };

        if (statKey === "endurance") {
            applyEnduranceLevelHpGain(entity, 1);
        }
        if (statKey === "endurance" || statKey === "flexibility") {
            applyStaminaLevelGain(entity, statKey, 1);
        }
        if (statKey === "willpower" && entity === G.player) {
            applyManaLevelGain(entity, 1);
        }

        // Faith - only the player's own growth counts (this same function
        // levels up NPC stats too, e.g. endurance from taking hits).
        if (entity === G.player) {
            if (statKey === "physicalProwess" || statKey === "endurance" || statKey === "willpower") {
                applyFaithDelta({ titan: 1 }, `grew stronger (${statKey})`);
            } else if (statKey === "charisma") {
                applyFaithDelta({ trickster: 1 }, "grew more charismatic");
            }
        }
    }

    if (leveled && statKey === "endurance") leveled.hpGained = Math.max(0, entity.hp - hpBeforeLevels);
    return leveled;
}

// gain: { weaponType?, actionKey?, statKey?, statAmount? }. Only the fields
// provided are tracked/incremented - callers pass just what actually
// happened (e.g. only statKey for "took a hit", weaponType+actionKey+statKey
// for "landed a hit"). Returns the updated counts (plus a leveledUp detail if
// this gain crossed a stat's threshold) for debug display.
function trackCombatSkillGain(entity, gain = {}) {
    const skills = ensureCombatSkills(entity);
    if (!skills) return null;

    const result = {};
    if (gain.weaponType) {
        skills.weapons[gain.weaponType] = (skills.weapons[gain.weaponType] || 0) + 1;
        result.weaponType = gain.weaponType;
        result.weaponCount = skills.weapons[gain.weaponType];
    }
    if (gain.actionKey) {
        skills.actions[gain.actionKey] = (skills.actions[gain.actionKey] || 0) + 1;
        result.actionKey = gain.actionKey;
        result.actionCount = skills.actions[gain.actionKey];
    }
    if (gain.statKey) {
        const baseAmount = typeof gain.statAmount === "number" ? gain.statAmount : 1;
        const amount = baseAmount * getFrameStatXPMultiplier(entity, gain.statKey);
        skills.statXP[gain.statKey] = (skills.statXP[gain.statKey] || 0) + amount;
        result.statKey = gain.statKey;
        result.statXP = skills.statXP[gain.statKey];

        const levelUp = maybeLevelUpStat(entity, gain.statKey);
        if (levelUp) result.leveledUp = levelUp;
    }
    return Object.keys(result).length ? result : null;
}

function formatSkillGainDebug(name, gain) {
    if (!G.combatRollDebugMode || !gain) return null;
    const parts = [];
    if (gain.weaponType) parts.push(`${gain.weaponType} proficiency ${gain.weaponCount}`);
    if (gain.actionKey) parts.push(`${gain.actionKey} proficiency ${gain.actionCount}`);
    if (gain.statKey) parts.push(`${gain.statKey} XP ${gain.statXP}`);
    if (!parts.length) return null;
    let line = `[Skills] ${name}: ${parts.join(", ")}`;
    if (gain.leveledUp) {
        line += ` -- LEVEL UP: ${gain.leveledUp.statKey} ${gain.leveledUp.from} -> ${gain.leveledUp.to}`;
        if (gain.leveledUp.hpGained > 0) line += ` (+${gain.leveledUp.hpGained} HP and max HP)`;
    }
    return line;
}

// -- COMBAT SKILL IMPACT, PASS 1 (hit-only, hard-capped) -------------------
// Diminishing returns by design: each bonus point costs more successful uses
// than the last would suggest on its own (flat divisor, hard cap), so early
// proficiency climbs fast in relative terms but the actual combat-math
// payoff levels off well before the counters do. No damage bonus here on
// purpose - see the block comment above.
// UNCAPPED: bonus = floor(scale * log2(1 + practice / divisor)). Each extra
// point needs roughly double the practice of the one before, but the curve
// never flattens, so effort is always rewarded a little (the old hard caps of
// +3 weapon / +2 action are gone). With scale 1.2: weapon +1 at 7 practice,
// +2 at 18, +3 at 38, +4 at 73, +5 at 137; action (divisor 6) +1 at 5, +2 at 13,
// +3 at 28, +4 at 55.
const WEAPON_PROFICIENCY_HIT_DIVISOR = 8;
const WEAPON_PROFICIENCY_HIT_SCALE = 1.2;
const ACTION_PROFICIENCY_HIT_DIVISOR = 6;
const ACTION_PROFICIENCY_HIT_SCALE = 1.2;
const ACTION_PROFICIENCY_ARMOR_DIVISOR = 6;
const ACTION_PROFICIENCY_ARMOR_SCALE = 1.2;

function getDiminishingProficiencyBonus(practice, divisor, scale) {
    if (!(practice > 0)) return 0;
    return Math.floor(scale * Math.log2(1 + practice / divisor) + 1e-9);
}

// Practice needed for the next +1 after `bonus`.
function getProficiencyNextThreshold(bonus, divisor, scale) {
    let p = Math.max(1, Math.ceil(divisor * (Math.pow(2, (bonus + 1) / scale) - 1)) - 1);
    while (getDiminishingProficiencyBonus(p, divisor, scale) < bonus + 1) p++;
    return p;
}

function getWeaponProficiencyHitBonus(entity, weaponType) {
    if (!weaponType) return 0;
    const prof = (entity && entity.combatSkills && entity.combatSkills.weapons && entity.combatSkills.weapons[weaponType]) || 0;
    return getDiminishingProficiencyBonus(prof, WEAPON_PROFICIENCY_HIT_DIVISOR, WEAPON_PROFICIENCY_HIT_SCALE);
}

function getActionProficiencyHitBonus(entity, actionKey) {
    if (!actionKey) return 0;
    const prof = (entity && entity.combatSkills && entity.combatSkills.actions && entity.combatSkills.actions[actionKey]) || 0;
    return getDiminishingProficiencyBonus(prof, ACTION_PROFICIENCY_HIT_DIVISOR, ACTION_PROFICIENCY_HIT_SCALE);
}

function getActionProficiencyArmorBonus(entity, actionKey) {
    if (!actionKey) return 0;
    const prof = (entity && entity.combatSkills && entity.combatSkills.actions && entity.combatSkills.actions[actionKey]) || 0;
    return getDiminishingProficiencyBonus(prof, ACTION_PROFICIENCY_ARMOR_DIVISOR, ACTION_PROFICIENCY_ARMOR_SCALE);
}

// Role-appropriate starting proficiency so combat-capable NPCs (guards, etc.)
// don't start every fight at 0 proficiency/0 stats. Also tracking-only: these
// seeded numbers aren't read by any combat formula yet.
function getRoleCombatTier(role) {
    const r = String(role || "").toLowerCase();
    if (["guard", "raider", "bandit", "cultist", "delver", "mercenary", "soldier"].some(t => r.includes(t))) return "combat";
    if (["blacksmith", "miner", "hunter", "scout", "wanderer"].some(t => r.includes(t))) return "moderate";
    return "civilian";
}

// flexibility doesn't track combat-tier the way strength/endurance do (a
// Scout can out-move a Guard despite being weaker in a straight fight), but
// giving it its own role-mapping is a bigger change than this pass needs -
// starting with the same tier shape, just skewed so "moderate" (scouts,
// hunters, wanderers) comes out the most agile of the three.
// hp/hpMax ranges by tier - before this, every NPC got a flat 10 HP
// regardless of role (see createNPC), which meant a single solid crit could
// one-shot anything from a villager to a hardened guard. Civilians stay
// fragile on purpose; combat-tier NPCs (guards, raiders, mercenaries...) now
// actually have enough HP to trade a few hits before going down.
const COMBAT_SKILL_TIER_BASELINES = {
    combat:   { weapon: [8, 20], action: [4, 12], physicalProwess: [4, 7], endurance: [4, 7], willpower: [4, 7], flexibility: [3, 6], hp: [16, 22] },
    moderate: { weapon: [2, 8],  action: [1, 5],  physicalProwess: [3, 5], endurance: [3, 5], willpower: [3, 5], flexibility: [4, 8], hp: [10, 14] },
    civilian: { weapon: [0, 2],  action: [0, 1],  physicalProwess: [2, 4], endurance: [2, 4], willpower: [2, 4], flexibility: [2, 5], hp: [6, 9] }
};

// Species size nudges endurance/hp on top of the role-tier baseline above -
// a "large" orc and a "tiny" kobold shouldn't come out with the same HP just
// because they're both civilian-tier. This pairs with the existing size
// swing on armor class (getEntityArmorClass: small = +1 AC, large = -1 AC),
// so bigger things are easier to land a hit on but can actually shrug more
// of it off, and smaller things are harder to hit but drop faster once you
// do land one.
const SIZE_COMBAT_MODIFIERS = {
    tiny:   { hp: -3, endurance: -1 },
    small:  { hp: -1, endurance: 0 },
    medium: { hp: 0,  endurance: 0 },
    large:  { hp: 5,  endurance: 2 }
};

// npc.size itself is only set later, by generateNPCEnrichment (called after
// seedNPCCombatSkills in createNPC) - so this reads the species template
// directly rather than depending on npc.size already being populated.
function getNPCSpeciesSize(npc) {
    if (!npc) return "medium";
    if (npc.size) return npc.size;
    if (typeof getSpeciesTemplate === "function") {
        const template = getSpeciesTemplate(npc.species);
        if (template && template.size) return template.size;
    }
    return "medium";
}

function seedNPCCombatSkills(npc) {
    if (!npc) return;
    const skills = ensureCombatSkills(npc);
    if (!skills) return;

    const tier = getRoleCombatTier(npc.role);
    const baseline = COMBAT_SKILL_TIER_BASELINES[tier];
    const sizeKey = getNPCSpeciesSize(npc);
    const sizeMod = SIZE_COMBAT_MODIFIERS[sizeKey] || SIZE_COMBAT_MODIFIERS.medium;

    const weaponType = (typeof getEntityWeaponProfile === "function" && getEntityWeaponProfile(npc).type) || null;
    if (weaponType) {
        skills.weapons[weaponType] = randInt(baseline.weapon[0], baseline.weapon[1]);
    }

    const aggressive = ["hostile", "aggressive", "bold"].includes(String(npc.temperament || "").toLowerCase());
    const primaryStyle = aggressive ? "heavy" : "balanced";
    skills.actions[primaryStyle] = randInt(baseline.action[0], baseline.action[1]);
    skills.actions.balanced = Math.max(skills.actions.balanced || 0, randInt(0, baseline.action[1]));

    npc.stats = npc.stats || {};
    if (typeof npc.stats.physicalProwess !== "number") {
        npc.stats.physicalProwess = randInt(baseline.physicalProwess[0], baseline.physicalProwess[1]);
    }
    if (typeof npc.stats.endurance !== "number") {
        npc.stats.endurance = Math.max(1, randInt(baseline.endurance[0], baseline.endurance[1]) + sizeMod.endurance);
    }
    if (typeof npc.stats.willpower !== "number") {
        npc.stats.willpower = randInt(baseline.willpower[0], baseline.willpower[1]);
    }
    if (typeof npc.stats.flexibility !== "number") {
        npc.stats.flexibility = randInt(baseline.flexibility[0], baseline.flexibility[1]);
    }

    // createNPC always sets hp/hpMax to the flat legacy default of 10 right
    // before calling this - only re-roll it from there, so re-running this
    // function (or a future caller that's already given the NPC a custom HP
    // pool) never clobbers a real value.
    if (baseline.hp && npc.hpMax === 10) {
        const hpMax = Math.max(2, randInt(baseline.hp[0], baseline.hp[1]) + sizeMod.hp);
        npc.hpMax = hpMax;
        npc.hp = hpMax;
    }
}

function ensureCombatState(entity) {
    if (!entity) return null;
    entity.combatState = entity.combatState || {};
    entity.combatState.limbs = entity.combatState.limbs || {};

    const maxHp = Math.max(1, entity.hpMax || entity.maxHp || entity.hp || 10);
    const plan = {
        head: 0.2,
        torso: 0.4,
        arms: 0.2,
        legs: 0.2
    };

    Object.entries(plan).forEach(([key, pct]) => {
        if (!entity.combatState.limbs[key]) {
            const max = Math.max(1, Math.round(maxHp * pct));
            entity.combatState.limbs[key] = {
                hp: max,
                max,
                bleed: 0,
                disabled: false
            };
        }
    });

    return entity.combatState;
}

// Delegates to getEntityStatValue with G.player - keeps this single
// player-specific accessor in sync with the generic one (status effects,
// carried-item stat bonuses) rather than duplicating that math here.
function getSetupStat(stat, fallback = 3) {
    return getEntityStatValue(G.player, stat, fallback);
}

function createPlayerStartingItem(name, slot, extras = {}) {
    const normalizedName = String(name || "").trim() || "item";
    return assignLootUID({
        id: `player-${slot}-${normalizedName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "item"}`,
        name: normalizedName,
        slot,
        type: extras.type || ["gear", slot],
        value: typeof extras.value === "number" ? extras.value : 0,
        modifier: typeof extras.modifier === "number" ? extras.modifier : 0,
        description: extras.description || "",
        ...extras
    });
}

// Unarmed describes an empty weapon slot; it is never a physical item.
function isUnarmedWeaponItem(item) {
    const name = typeof item === "string" ? item : getItemName(item);
    return String(name).trim().toLowerCase() === "unarmed";
}

function createLegacyWeaponItem(name) {
    const weaponName = String(name || "").trim();
    if (!weaponName || isUnarmedWeaponItem(weaponName)) return null;
    const baseDamageByWeapon = {
        dagger: 4,
        "short sword": 6,
        sword: 6,
        staff: 5,
        mace: 6,
        spear: 6,
        axe: 8,
        warhammer: 8
    };
    const lookupKey = weaponName.toLowerCase();

    return createPlayerStartingItem(weaponName, "weapon", {
        type: ["weapon", "weapon"],
        weaponType: getWeaponTypeFromName(weaponName, "generic"),
        damage: baseDamageByWeapon[lookupKey] || 4,
        value: 0,
        modifier: 0,
        description: `Your currently readied ${weaponName.toLowerCase()}.`
    });
}

function ensurePlayerEquipmentState(player) {
    if (!player || typeof player !== "object") return player;

    if (!Array.isArray(player.inventory)) player.inventory = [];
    if (!player.equipped || typeof player.equipped !== "object") player.equipped = {};
    ensurePlayerRucksack(player);

    const eq = player.equipped;
    const legacyWeaponName = typeof player.weapon === "string" ? player.weapon.trim() : "";

    // Clean up placeholders made by older saves before restoring real gear.
    if (isUnarmedWeaponItem(eq.weapon)) delete eq.weapon;
    for (let i = player.inventory.length - 1; i >= 0; i--) {
        if (isUnarmedWeaponItem(player.inventory[i])) player.inventory.splice(i, 1);
    }
    if (!eq.weapon && legacyWeaponName && !isUnarmedWeaponItem(legacyWeaponName)) {
        eq.weapon = createLegacyWeaponItem(legacyWeaponName);
    }

    player.weapon = eq.weapon ? getItemName(eq.weapon) : "unarmed";

    const defaultClothing = {
        upper: {
            name: "Traveler's tunic",
            type: ["clothes", "upper"],
            description: "A simple tunic that counts as your ordinary day clothes."
        },
        lower: {
            name: "Traveler's trousers",
            type: ["clothes", "lower"],
            description: "Simple trousers worn as your ordinary traveling clothes."
        },
        feet: {
            name: "Travel shoes",
            type: ["clothes", "feet"],
            description: "Practical shoes worn for everyday travel."
        }
    };

    if (!player._baselineClothingSeeded) {
        Object.entries(defaultClothing).forEach(([slot, item]) => {
            if (!eq[slot]) {
                eq[slot] = createPlayerStartingItem(item.name, slot, {
                    type: item.type,
                    value: 0,
                    modifier: 0,
                    description: item.description
                });
            }
        });
        player._baselineClothingSeeded = true;
    }

    return player;
}

const PLAYER_EQUIPMENT_SLOT_META = {
    head: { icon: "🪖", label: "Head" },
    weapon: { icon: "🗡", label: "Weapon" },
    hand: { icon: "✋", label: "Hand" },
    upper: { icon: "🧥", label: "Upper" },
    hands: { icon: "👐", label: "Hands" },
    lower: { icon: "👖", label: "Lower" },
    feet: { icon: "🥾", label: "Feet" },
    neck: { icon: "📿", label: "Amulet" },
    belt: { icon: "🎒", label: "Belt" },
    coinPouch: { icon: "💰", label: "Coins" }
};

function getPlayerEquipmentSlots() {
    return ["head", "weapon", "hand", "upper", "hands", "lower", "feet", "neck", "belt", "coinPouch"];
}

function getEquipmentSlotMeta(slot) {
    return PLAYER_EQUIPMENT_SLOT_META[slot] || { icon: "•", label: slot };
}

function getItemQuantity(item) {
    const quantity = Number(item && item.quantity);
    return Number.isFinite(quantity) && quantity > 0 ? Math.max(1, Math.floor(quantity)) : 1;
}

function getItemUnitValue(item) {
    let value = item && typeof item.value === "number" ? item.value : 1;
    if (typeof isNectarItem === "function" && isNectarItem(item)) value = Math.ceil(value * getNectarDrops(item) / getNectarCapacityDrops(item));
    return Math.max(1, value);
}

// -- ITEM SIZE AND CONTAINERS ---------------------------------------------
// Every item has a size in "units" (item.unitSize, stamped when it is made;
// anything older or made elsewhere gets one inferred from its name and type by
// getItemUnitSize, so nothing needs migrating). A container is any item with a
// capacity in the same units (item.container.maxUnitCapacity; a belt's
// pouchSlots counts). canContain() is the single place that decides whether
// something fits. Rough scale: 0 coin/gem/ring/key, 1 vial/potion/herb/scroll/
// letter/cloth shirt/pants, 2 skirt/flask/book/dagger/rope, 3-4 weapons,
// 5 greaves/chainmail, 8 plate armour/pack,
// 40 a body. A liquid container (container.liquid) holds one liquid, not items.
// The tables are built lazily so these helpers are safe to call while the
// file is still loading.
var __itemSizeRules = null;
function getItemSizeRules() {
    if (!__itemSizeRules) {
        __itemSizeRules = [
            [/(^|[^a-z])(coin|gem|ring|key|token|ruby|emerald|sapphire|diamond|pearl|flake|tooth|ribbon|charm)([^a-z]|$)/, 0],
            [/(^|[^a-z])(vial|phial|potion|herb|scroll|map|letter|note|receipt|slip|card|page|ration|twist|candle|bandage|lockpick|trinket|paper|ore|mixture|bark|root)([^a-z]|$)/, 1],
            [/(^|[^a-z])(plate|mail|armou?r|pack|backpack|tent|chest|barrel|crate|cauldron|anvil)([^a-z]|$)/, 8],
            [/(^|[^a-z])(shield|bedroll|greatsword|halberd|glaive|polearm|quarterstaff|staff|spear|axe|hammer|maul|mace|sword|club|trident|crossbow|bow)([^a-z]|$)/, 4],
            [/(^|[^a-z])(helmet|helm|boots?|cloak|coat|robe|jerkin|tunic|trousers|pants|leggings|gauntlets?)([^a-z]|$)/, 3]
        ];
    }
    return __itemSizeRules;
}

// Weapon size follows the actual weapon, before material/quality words such
// as "ruby" or "ore" can accidentally make it a tiny trinket.
function getWeaponUnitSize(item) {
    if (!item || typeof item !== "object") return null;
    const name = String(item.name || "").toLowerCase();
    if (/\b(great[ -]?sword|great[ -]?axe|battle[ -]?axe|war[ -]?hammer|war[ -]?maul|maul|halberd|glaive|polearm|quarterstaff|spellstaff|staff|spear|trident|crossbow|longbow|bow)\b/.test(name)) return 4;
    if (/\b(dagger|knife|dirk|stiletto|shiv|hatchet)\b/.test(name)) return 2;
    if (/\b(short[ -]?sword|long[ -]?sword|broadsword|sword|scimitar|sabre|saber|rapier|mace|morningstar|axe|hammer|club|flail|whip)\b/.test(name)) return 3;
    const types = [].concat(item.type || []).map(function (t) { return String(t).toLowerCase(); });
    if (item.slot !== "weapon" && types.indexOf("weapon") < 0) return null;
    const kind = String(item.weaponType || "").toLowerCase();
    if (kind === "dagger") return 2;
    if (["staff", "spear", "polearm", "bow", "crossbow"].indexOf(kind) >= 0) return 4;
    if (["sword", "mace", "axe", "flail", "whip"].indexOf(kind) >= 0) return 3;
    return null;
}

function getApparelUnitSize(item) {
    if (!item || typeof item !== "object" || (item.container && item.container.bag)) return null;
    const name = String(item.name || "").toLowerCase().replace(/-/g, " ");
    const types = [].concat(item.type || []).map(function (type) { return String(type).toLowerCase(); });
    const apparel = /\b(shirts?|tunics?|blouses?|vests?|trousers|pants|breeches|shorts|leggings|skirts?|kilts?|dresses|dress|robes?|cloaks?|coats?|jackets?|jerkins?|gambesons?|greaves?|chausses|cuirass|breastplate|hauberk|haubergeon|chainmail|mail|armou?r|helmets?|helms?|hoods?|caps?|hats?|gloves?|gauntlets?|bracers?|vambraces?|boots?|shoes?|sandals?|slippers?|sabatons?|belts?|girdles?|sashes|sash)\b/.test(name);
    if (!apparel && types.indexOf("clothes") < 0 && types.indexOf("armor") < 0 && types.indexOf("armour") < 0) return null;
    if (/\b(greaves?|chausses)\b/.test(name)) return 5;
    if (/\b(chain\s*mail|chain shirt|mail|hauberk|haubergeon|scale armou?r)\b/.test(name)) return 5;
    const material = String(item.material || (item.durability && item.durability.material) || "").toLowerCase();
    const metal = /^(iron|steel|gold|silver|bronze|metal)$/.test(material) || /\b(iron|steel|bronze|metal|plate|plated)\b/.test(name);
    const leather = /leather|hide/.test(material) || /\b(leather|hide|jerkin)\b/.test(name);
    if (/\b(helmets?|helms?|gauntlets?|bracers?|vambraces?|sabatons?)\b/.test(name)) return 3;
    if (/\b(belts?|girdles?|sashes|sash|hoods?|caps?|hats?|gloves?)\b/.test(name)) return metal ? 3 : 1;
    if (/\b(boots?)\b/.test(name)) return metal ? 3 : 2;
    if (/\b(shoes?|sandals?|slippers?)\b/.test(name)) return metal ? 3 : 1;
    if (/\b(plate|plated|breastplate|cuirass)\b/.test(name)) return 8;
    if (metal) return 5;
    if (/\b(skirts?|kilts?|dress|dresses)\b/.test(name)) return 2;
    if (leather) return 3;
    if (/\b(robes?|cloaks?|coats?|jackets?|gambesons?|padded)\b/.test(name)) return 2;
    return 1;
}

function inferItemUnitSize(item) {
    if (!item || typeof item !== "object") return 1;
    if (item.objectType === "body") return 40;
    const weaponSize = getWeaponUnitSize(item);
    if (weaponSize !== null) return weaponSize;
    const apparelSize = getApparelUnitSize(item);
    if (apparelSize !== null) return apparelSize;
    return inferItemUnitSizeFromRules(item);
}

function inferItemUnitSizeFromRules(item) {
    const types = Array.isArray(item.type) ? item.type.join(" ") : String(item.type || "");
    const text = (String(item.name || "") + " " + String(item.id || "").replace(/-/g, " ") + " " + types).toLowerCase();
    const rules = getItemSizeRules();
    for (let i = 0; i < rules.length; i++) {
        if (rules[i][0].test(text)) return rules[i][1];
    }
    return 2;
}

function getItemUnitSize(item) {
    if (!item || typeof item !== "object") return 0;
    if (item.unitSizeInferred === true) return inferItemUnitSize(item);
    // Older generated gear stamped defaults without recording their source.
    // Upgrade values matching those old rules; preserve other custom sizes.
    if (item.unitSizeInferred === undefined && item.unitSize === inferItemUnitSizeFromRules(item)) return inferItemUnitSize(item);
    if (typeof item.unitSize === "number" && Number.isFinite(item.unitSize) && item.unitSize >= 0) return item.unitSize;
    return inferItemUnitSize(item);
}

// The container record for an item, or null. Explicit item.container wins; a
// belt's pouchSlots become its capacity; a potion is a one-unit vial of liquid.
function getItemContainer(item) {
    if (!item || typeof item !== "object") return null;
    if (item.container && typeof item.container === "object") return item.container;
    if (typeof item.pouchSlots === "number" && item.pouchSlots > 0) return { maxUnitCapacity: item.pouchSlots };
    if (isPotionItem(item)) return { maxUnitCapacity: 1, emptyId: "empty-vial", liquid: true };
    return null;
}

function getContainerCapacity(item) {
    const c = getItemContainer(item);
    return c && typeof c.maxUnitCapacity === "number" ? Math.max(0, c.maxUnitCapacity) : 0;
}

// Units used directly inside a container. A nested container uses its own
// size here; its contents use the nested container's capacity.
function getContainerUsedUnits(item) {
    if (!item || !Array.isArray(item.packed)) return 0;
    return item.packed.reduce(function (sum, it) {
        return sum + (getItemUnitSize(it) * getItemQuantity(it));
    }, 0);
}

function containerHoldsItem(container, item) {
    if (!container || !Array.isArray(container.packed)) return false;
    return container.packed.some(function (it) { return it === item || containerHoldsItem(it, item); });
}

// { ok, reason }: can `item` (a stack of `quantity`) go into `container`?
function canContain(container, item, quantity) {
    const cap = getContainerCapacity(container);
    if (!container || !item) return { ok: false, reason: "Nothing to put there." };
    if (cap <= 0) return { ok: false, reason: "That is not a container." };
    if (container === item || containerHoldsItem(item, container)) return { ok: false, reason: "That cannot go inside itself." };
    const c = getItemContainer(container);
    if (c && c.liquid) return { ok: false, reason: "It only holds liquid." };
    // A container inside a container counts only its own size, not what it holds.
    const size = getItemUnitSize(item) * Math.max(1, quantity || getItemQuantity(item));
    if (size > cap) return { ok: false, reason: "It is too big for that." };
    if (getContainerUsedUnits(container) + size > cap) return { ok: false, reason: "There is no room left." };
    return { ok: true, reason: "" };
}

// -- empty bottles: what you are left holding -------------------------------
var __emptyContainerDefs = null;
function getEmptyContainerDefs() {
    if (!__emptyContainerDefs) {
        __emptyContainerDefs = {
            "empty-vial": { name: "Empty vial", noun: "vial", value: 1, unitSize: 1, cap: 1, desc: "A small stoppered glass vial, clean and empty." },
            "empty-flask": { name: "Empty flask", noun: "flask", value: 1, unitSize: 2, cap: 2, desc: "A stoppered flask, clean and empty." },
            "empty-bottle": { name: "Empty bottle", noun: "bottle", value: 1, unitSize: 2, cap: 3, desc: "A glass bottle with a cork, clean and empty." }
        };
    }
    return __emptyContainerDefs;
}

function createEmptyContainer(emptyId) {
    const def = getEmptyContainerDefs()[emptyId];
    if (!def) return null;
    const item = cloneLootTemplate({ id: emptyId, name: def.name, value: def.value, type: ["misc"], unitSize: def.unitSize, description: def.desc });
    item.container = { maxUnitCapacity: def.cap, emptyId: emptyId, liquid: true, fillable: true };
    item.stackKey = emptyId;
    return item;
}

function isEmptyFillableItem(item) {
    return !!(item && item.container && item.container.fillable && (item.physicalDefinition && !item.container.emptyId ? !item.liquid || item.liquid.volume <= 0 : /^empty-/.test(String(item.stackKey || item.id || ""))));
}

// Which empty container an item leaves behind once emptied (id, or "").
function getEmptyContainerId(item) {
    if (!item) return "";
    const c = getItemContainer(item);
    if (c && c.emptyId && getEmptyContainerDefs()[c.emptyId]) return c.emptyId;
    const text = (String(item.id || "") + " " + String(item.name || "")).toLowerCase();
    if (/bottle|wine|spirits/.test(text) && !/mug/.test(text)) return "";   // keep bottles of drink as before
    if (/(^|[^a-z])(flask|waterskin|canteen)([^a-z]|$)/.test(text)) return "empty-flask";
    return "";
}

// Puts the empty container into the player's pack and returns a short line.
function giveBackEmptyContainer(item) {
    const emptyId = getEmptyContainerId(item);
    if (!emptyId || !G.player) return "";
    const empty = createEmptyContainer(emptyId);
    if (!empty) return "";
    if (!Array.isArray(G.player.inventory)) G.player.inventory = [];
    G.player.inventory.push(empty);
    return "You keep the " + empty.name.toLowerCase() + ".";
}

// -- supplies you can eat or drink --------------------------------------------
// item.consume = { verb, stamina, heal } wins; otherwise a few known supplies
// are matched by name. Returns null for anything that is not food or drink.
function getSupplyUse(item) {
    if (!item || typeof item !== "object") return null;
    if (item.consume && typeof item.consume === "object") {
        return { verb: item.consume.verb || "Eat", stamina: item.consume.stamina || 0, heal: item.consume.heal || 0 };
    }
    const types = Array.isArray(item.type) ? item.type : [];
    const text = (String(item.id || "") + " " + String(item.name || "")).toLowerCase();
    if (types.indexOf("potion") >= 0 || types.indexOf("alcohol") >= 0 || types.indexOf("herb") >= 0) return null;
    if (/(^|[^a-z])ration([^a-z]|$)/.test(text)) return { verb: "Eat", stamina: 4, heal: 0 };
    if (types.indexOf("supply") < 0) return null;
    if (/cider/.test(text)) return { verb: "Drink", stamina: 3, heal: 0 };
    if (/fish|jerky|bread|cheese|twist|biscuit|meat/.test(text)) return { verb: "Eat", stamina: 3, heal: 0 };
    return null;
}

function getInventoryUseSubtitle(item) {
    const use = getSupplyUse(item);
    if (use) return use.verb === "Drink" ? "Drinkable" : "Edible";
    if (isEmptyFillableItem(item)) return "Empty - fill it at clean water";
    return "Carry only";
}

function useSupplyEntry(stackKey) {
    const entry = buildPlayerInventoryEntries(G.player).find(function (c) { return c.key === stackKey; });
    const use = entry ? getSupplyUse(entry.item) : null;
    if (!entry || !use) return null;
    const consumed = takeInventoryEntryAmount(G.player, stackKey, 1);
    if (!consumed) return null;
    const bits = [];
    if (use.stamina > 0) {
        const gained = restoreEntityStamina(G.player, use.stamina);
        if (gained > 0) bits.push("+" + gained + " stamina");
    }
    if (use.heal > 0 && typeof G.player.hp === "number") {
        const before = G.player.hp;
        G.player.hp = Math.min(G.player.hpMax || before, before + use.heal);
        if (G.player.hp > before) bits.push("+" + (G.player.hp - before) + " HP");
    }
    const kept = giveBackEmptyContainer(consumed);
    renderStats();
    return "You " + (use.verb === "Drink" ? (getEmptyContainerId(consumed) ? "drink from" : "drink") : "eat") + " the " + getItemName(consumed).toLowerCase() + (bits.length ? " (" + bits.join(", ") + ")." : ".") + (kept ? " " + kept : "");
}

// Tipping a potion out: the liquid soaks away, the bottle stays with you.
function pourOutPotionEntry(stackKey) {
    if (!materialExecution) return runMaterialAction("pour", null, stackKey).text || "";
    const entry = buildPlayerInventoryEntries(G.player).find(function (c) { return c.key === stackKey; });
    if (!entry || !isPotionItem(entry.item)) return "";
    const consumed = takeInventoryEntryAmount(G.player, stackKey, 1);
    if (!consumed) return "";
    const kept = giveBackEmptyContainer(consumed);
    materialCheckpoint();
    advanceStoryTurn(1);
    if (!materialCurrent()) return materialInterrupted();
    saveGameState();
    return "You tip out the " + getItemName(consumed).toLowerCase() + " and the liquid soaks into the floor." + (kept ? " " + kept : "");
}

// Filling an empty container from clean water (see openFixtureCard).
function getFillableEmptyEntries() {
    return buildPlayerInventoryEntries(G.player).filter(function (e) { return isEmptyFillableItem(e.item); });
}

function createFilledWaterContainer(emptyId) {
    const def = getEmptyContainerDefs()[emptyId];
    if (!def) return null;
    const stamina = def.cap >= 2 ? 2 : 1;
    const item = cloneLootTemplate({ id: "water-" + emptyId, name: capitaliseFirst(def.noun) + " of water", value: 1, type: ["misc", "supply"], unitSize: def.unitSize,
        description: "A " + def.noun + " of clean water, stoppered." });
    item.container = { maxUnitCapacity: def.cap, emptyId: emptyId, liquid: true };
    item.consume = { verb: "Drink", stamina: stamina, heal: 0 };
    item.stackKey = "water-" + emptyId;
    return item;
}


// -- CARRYING: pockets, hand, belt, rucksack, tied-on gear ------------------
// The player no longer carries without limit. Every carried item sits in one
// place (item.stowed); a garment's places are named after the garment's key
// (item._ck), so what is in the pockets or on the belt follows the garment when
// it is taken off and carried: two 1-unit pockets per worn lower garment (not skirts),
// the free hand (1 unit), the belt (its pouchSlots) and the rucksack
// (player.rucksack.capacity). Items go to the first place with room and take
// no thought from the player; size-0 items take no space but still need some
// place to exist (a naked, pack-less player holds one thing in the hand at
// most). Bulkier gear (size 2-4) can be tied on: 3 belt loops and 1 strap per
// rucksack strap (2), at a cost of 1 flexibility per 2 tied items. The pack
// list itself stays flat; restowPlayerPack() re-places anything unplaced or
// whose place has gone (pants removed, belt taken off), and anything that
// cannot be placed is "overflow" (kept, but nothing new fits until it is
// resolved). Only picking things up from the world and buying refuse an item;
// rewards, crafted goods and unequipping simply overflow.
const PACK_RUCKSACK_CAPACITY = 18;
const PACK_BELT_LOOPS = 3;
const PACK_STRAPS = 2;
const PACK_TIE_MAX_SIZE = 4;
const PACK_SKIRT_PATTERN = /skirt|kilt|loincloth|dress/i;

function createRucksackItem(capacity) {
    const item = cloneLootTemplate({ id: "rucksack", name: "Rucksack", value: 5, type: ["misc", "pack"], unitSize: 8,
        description: "A worn canvas rucksack with two shoulder straps and room for a day's gear." });
    item.container = { maxUnitCapacity: capacity || PACK_RUCKSACK_CAPACITY, bag: true, label: "rucksack", straps: PACK_STRAPS, wearable: "back" };
    ensureContainerKey(item);
    return item;
}

// Every player starts with one (old saves included). player.rucksack holds the
// worn item; null means it was set down or lost and is not replaced.
function ensurePlayerRucksack(player) {
    if (!player || typeof player !== "object") return null;
    if (player.rucksack === undefined) {
        player.rucksack = createRucksackItem(PACK_RUCKSACK_CAPACITY);
    } else if (player.rucksack && !player.rucksack.container) {
        player.rucksack = createRucksackItem(player.rucksack.capacity || PACK_RUCKSACK_CAPACITY);
    }
    // Upgrade the original starter pack in existing saves.
    if (player.rucksack && /^rucksack(?:-|$)/.test(player.rucksack.id || "") && player.rucksack.container.maxUnitCapacity === 12) {
        player.rucksack.container.maxUnitCapacity = PACK_RUCKSACK_CAPACITY;
    }
    return player.rucksack;
}

function ensureContainerKey(item) {
    if (item && typeof item === "object" && !item._ck) item._ck = "ck-" + Math.random().toString(36).slice(2, 9);
    return item ? item._ck : "";
}

// The storage a garment provides, worn or carried. Its places are named after
// the garment's own key (item._ck, which survives equipping and unequipping),
// so whatever is stowed in them follows the garment: take the trousers off and
// the pocket contents ride along in the carried trousers.
function getGarmentPlaces(item) {
    const out = { storage: [], ties: [] };
    if (!item || typeof item !== "object" || Array.isArray(item)) return out;
    if (item.container && item.container.bag) {
        const ck = ensureContainerKey(item);
        out.storage.push({ id: "bag:" + ck, label: item.container.label || "bag", cap: Math.max(0, item.container.maxUnitCapacity || 0) });
        const straps = item.container.straps || 0;
        for (let i = 1; i <= straps; i++) out.ties.push({ id: "strap:" + ck + ":" + i, kind: "rucksack", label: "pack strap" });
        return out;
    }
    const slot = getItemEquipSlot(item);
    if (slot === "lower" && !PACK_SKIRT_PATTERN.test(getItemName(item))) {
        const ck = ensureContainerKey(item);
        out.storage.push({ id: "pocket:" + ck + ":1", label: "pocket", cap: 1 });
        out.storage.push({ id: "pocket:" + ck + ":2", label: "pocket", cap: 1 });
    } else if (slot === "belt") {
        const ck = ensureContainerKey(item);
        out.storage.push({ id: "belt:" + ck, label: "belt", cap: getContainerCapacity(item) || 3 });
        for (let i = 1; i <= PACK_BELT_LOOPS; i++) out.ties.push({ id: "loop:" + ck + ":" + i, kind: "belt", label: "belt loop" });
    }
    return out;
}

function getPlayerStoragePlaces(player) {
    const places = [];
    if (!player) return places;
    const eq = player.equipped && typeof player.equipped === "object" ? player.equipped : {};
    ["lower", "belt"].forEach(function (slot) {
        getGarmentPlaces(eq[slot]).storage.forEach(function (p) { places.push(p); });
    });
    getGarmentPlaces(player.rucksack).storage.forEach(function (p) { places.push(p); });
    if (!eq.hand) places.push({ id: "hand", label: "hand", cap: 1 });
    return places;
}

function getPlayerTieSpots(player) {
    const spots = [];
    if (!player) return spots;
    const eq = player.equipped && typeof player.equipped === "object" ? player.equipped : {};
    getGarmentPlaces(eq.belt).ties.forEach(function (t) { spots.push(t); });
    getGarmentPlaces(player.rucksack).ties.forEach(function (t) { spots.push(t); });
    return spots;
}

// Places in garments that are carried (not worn): still valid homes for what
// is already stowed there, but never chosen for new items.
function getCarriedGarmentPlaces(player) {
    const map = {};
    ((player && player.inventory) || []).forEach(function (it) {
        const g = getGarmentPlaces(it);
        g.storage.forEach(function (p) { map[p.id] = { cap: p.cap, tie: false, owner: it }; });
        g.ties.forEach(function (t) { map[t.id] = { cap: 1, tie: true, owner: it }; });
    });
    return map;
}

function isTieSpotId(id) {
    return /^(loop|strap):/.test(String(id || ""));
}

function canTieItemSize(item) {
    const size = getItemUnitSize(item);
    return size >= 2 && size <= PACK_TIE_MAX_SIZE;
}

// Places `item` (all of it, or as many units as fit, splitting the stack) into
// the first places with room. Returns true if every unit was placed.
function placeItemInPack(item, places, used, inventory) {
    const size = getItemUnitSize(item);
    let qty = getItemQuantity(item);
    if (size === 0) {
        if (!places.length) return false;
        item.stowed = places[places.length - 1].id;
        return true;
    }
    for (let i = 0; i < places.length && qty > 0; i++) {
        const place = places[i];
        const fit = Math.floor((place.cap - used[place.id]) / size);
        if (fit <= 0) continue;
        if (fit >= qty) {
            used[place.id] += size * qty;
            item.stowed = place.id;
            if (item.quantity !== undefined || qty > 1) item.quantity = qty;
            return true;
        }
        const part = cloneItemForStackAmount(item, fit);
        part.stowed = place.id;
        used[place.id] += size * fit;
        inventory.push(part);
        qty -= fit;
        item.quantity = qty;
    }
    return qty <= 0;
}

function restowPlayerPack(player) {
    player = player || G.player;
    if (!player || !Array.isArray(player.inventory)) return;
    ensurePlayerRucksack(player);
    unpackAllContainers(player);
    const places = getPlayerStoragePlaces(player);
    const ties = getPlayerTieSpots(player);
    const carried = getCarriedGarmentPlaces(player);
    const placeById = {};
    const tieById = {};
    const used = {};
    const tiedUsed = {};
    const carriedUsed = {};
    places.forEach(function (p) { placeById[p.id] = p; used[p.id] = 0; });
    ties.forEach(function (t) { tieById[t.id] = t; });
    const loose = [];
    player.inventory.forEach(function (item) {
        if (!item) return;
        const id = item.stowed;
        const qty = getItemQuantity(item);
        const size = getItemUnitSize(item) * qty;
        if (id && item._ck && String(id).split(":")[1] === item._ck) { loose.push(item); return; }   // never inside itself
        if (id && tieById[id] && !tiedUsed[id] && qty === 1 && canTieItemSize(item)) { tiedUsed[id] = true; return; }
        if (id && placeById[id] && used[id] + size <= placeById[id].cap) { used[id] += size; return; }
        const c = id ? carried[id] : null;
        if (c) {
            if (c.tie && !carriedUsed[id] && qty === 1 && canTieItemSize(item)) { carriedUsed[id] = 1; return; }
            if (!c.tie && (carriedUsed[id] || 0) + size <= c.cap) { carriedUsed[id] = (carriedUsed[id] || 0) + size; return; }
        }
        loose.push(item);
    });
    loose.forEach(function (item) {
        if (!placeItemInPack(item, places, used, player.inventory)) item.stowed = "overflow";
    });
}

// How many units of `item` would still fit (pockets, hand, belt, rucksack).
function packRoomUnits(item) {
    const player = G.player;
    if (!player) return 0;
    restowPlayerPack(player);
    const places = getPlayerStoragePlaces(player);
    if (!places.length) return 0;
    const size = getItemUnitSize(item);
    if (size === 0) return 99;
    const used = {};
    places.forEach(function (p) { used[p.id] = 0; });
    (player.inventory || []).forEach(function (it) {
        if (it && used[it.stowed] !== undefined) used[it.stowed] += getItemUnitSize(it) * getItemQuantity(it);
    });
    return places.reduce(function (sum, p) { return sum + Math.floor((p.cap - used[p.id]) / size); }, 0);
}

function packHasRoomFor(item, qty) {
    return packRoomUnits(item) >= Math.max(1, qty || getItemQuantity(item));
}

// Adds an item to the player's pack. { ok, refused }: `refused` is the item
// (or the part of the stack) that did not fit and is NOT in the pack. With
// opts.force it always goes in, overflowing if there is no place.
function addToPlayerPack(item, opts) {
    const force = !!(opts && opts.force);
    if (!item) return { ok: true, refused: null };
    const player = G.player;
    if (!Array.isArray(player.inventory)) player.inventory = [];
    restowPlayerPack(player);
    player.inventory.push(item);
    restowPlayerPack(player);
    if (item.stowed !== "overflow") return { ok: true, refused: null };
    if (force) return { ok: true, refused: null, overflow: true };
    const idx = player.inventory.indexOf(item);
    if (idx >= 0) player.inventory.splice(idx, 1);
    delete item.stowed;
    return { ok: false, refused: item };
}

function packFullText(refused, res) {
    const items = (refused || []).filter(Boolean);
    const names = items.map(function (it) { return getItemName(it); });
    const unique = names.filter(function (n, i) { return names.indexOf(n) === i; });
    const list = unique.length > 2 ? unique.slice(0, 2).join(", ") + " and more" : unique.join(" and ");
    const hasTie = getPlayerTieSpots(G.player).length > 0;
    let text = "You have nowhere to put " + (list || "that") + ". Your pockets, belt and pack are full" +
        (hasTie ? "; drop something, or tie a bulkier item to a belt loop or pack strap (it costs some flexibility) to make room." : "; drop something to make room.");
    if (res && res.lines && res.lines.length) text += " " + res.lines.join(" ");
    return text;
}

function getTiedItems(player) {
    const worn = {};
    getPlayerTieSpots(player).forEach(function (t) { worn[t.id] = true; });
    return ((player && player.inventory) || []).filter(function (it) { return it && worn[it.stowed]; });
}

function getTiedGearPenalty(entity, statKey) {
    if (statKey !== "flexibility" || !entity || !Array.isArray(entity.inventory)) return 0;
    const n = getTiedItems(entity).length;
    return n > 0 ? -Math.ceil(n / 2) : 0;
}

function findContainerOwner(player, ck) {
    if (!ck) return null;
    if (player && player.rucksack && player.rucksack._ck === ck) return { item: player.rucksack, worn: true };
    const eq = (player && player.equipped) || {};
    const slots = Object.keys(eq);
    for (let i = 0; i < slots.length; i++) {
        const it = eq[slots[i]];
        if (it && !Array.isArray(it) && it._ck === ck) return { item: it, worn: true };
    }
    const found = ((player && player.inventory) || []).filter(function (it) { return it && it._ck === ck; })[0];
    return found ? { item: found, worn: false } : null;
}

function getStowageLabel(id) {
    if (!id) return "";
    if (id === "overflow") return "no room (overloaded)";
    const parts = String(id).split(":");
    const kind = parts[0];
    if (kind === "pocket" || kind === "belt" || kind === "loop" || kind === "bag") {
        const owner = findContainerOwner(G.player, parts[1]);
        const base = kind === "pocket" ? "pocket" : (kind === "belt" ? "belt" : (kind === "bag" ? ((owner && owner.item.container && owner.item.container.label) || "bag") : "belt loop"));
        if (owner && !owner.worn) return base + " of carried " + getItemName(owner.item).toLowerCase();
        return base;
    }
    if (kind === "strap") return "pack strap";
    return id;
}

function describeEntryStowage(stackKey) {
    const labels = [];
    (G.player.inventory || []).forEach(function (it) {
        if (!it || getInventoryEntryKey(it) !== stackKey) return;
        const l = getStowageLabel(it.stowed);
        if (l && labels.indexOf(l) < 0) labels.push(l);
    });
    return labels.length ? "Carried in: " + labels.join(", ") : "";
}

function describePackCapacity() {
    const player = G.player;
    if (!player) return "";
    restowPlayerPack(player);
    const places = getPlayerStoragePlaces(player);
    const ties = getPlayerTieSpots(player);
    const tieIds = {};
    ties.forEach(function (t) { tieIds[t.id] = true; });
    const used = {};
    let overflow = 0;
    let inside = 0;
    places.forEach(function (p) { used[p.id] = 0; });
    (player.inventory || []).forEach(function (it) {
        if (!it) return;
        if (used[it.stowed] !== undefined) used[it.stowed] += getItemUnitSize(it) * getItemQuantity(it);
        else if (it.stowed === "overflow") overflow += 1;
        else if (it.stowed && !tieIds[it.stowed]) inside += 1;
    });
    const bits = [];
    const pockets = places.filter(function (p) { return p.label === "pocket"; });
    if (pockets.length) bits.push("pockets " + pockets.reduce(function (n, p) { return n + used[p.id]; }, 0) + "/" + pockets.length);
    places.filter(function (p) { return p.label !== "pocket"; }).forEach(function (p) { bits.push(p.label + " " + used[p.id] + "/" + p.cap); });
    if (ties.length) {
        const tied = getTiedItems(player).length;
        const pen = getTiedGearPenalty(player, "flexibility");
        bits.push("tied on " + tied + "/" + ties.length + (pen ? " (" + pen + " flexibility)" : ""));
    }
    if (!bits.length) bits.push("nothing to carry things in");
    return "Carrying: " + bits.join("  \u00b7  ")
        + (inside ? "  \u00b7  " + inside + " item" + (inside === 1 ? "" : "s") + " inside carried clothes" : "")
        + (overflow ? "  \u00b7  " + overflow + " item" + (overflow === 1 ? "" : "s") + " with no room" : "");
}

function getFreeTieSpot(kind) {
    const player = G.player;
    const taken = {};
    getTiedItems(player).forEach(function (it) { taken[it.stowed] = true; });
    return getPlayerTieSpots(player).filter(function (t) { return t.kind === kind && !taken[t.id]; })[0] || null;
}

function isEntryTied(stackKey) {
    return (G.player.inventory || []).some(function (it) { return it && isTieSpotId(it.stowed) && getInventoryEntryKey(it) === stackKey; });
}

function tieItemOn(stackKey, kind) {
    const player = G.player;
    restowPlayerPack(player);
    const item = (player.inventory || []).filter(function (it) { return it && getInventoryEntryKey(it) === stackKey && !isTieSpotId(it.stowed); })[0];
    if (!item) return "You no longer have that.";
    if (!canTieItemSize(item)) return "That is not something you can tie on.";
    const spot = getFreeTieSpot(kind);
    if (!spot) return "There is nowhere left to tie anything.";
    const before = getTiedGearPenalty(player, "flexibility");
    let target = item;
    if (getItemQuantity(item) > 1) {
        item.quantity = getItemQuantity(item) - 1;
        target = cloneItemForStackAmount(item, 1);
        player.inventory.push(target);
    }
    target.stowed = spot.id;
    restowPlayerPack(player);
    const after = getTiedGearPenalty(player, "flexibility");
    return "You tie the " + getItemName(target).toLowerCase() + " to a " + spot.label + "." + (after < before ? " It swings as you move (" + after + " flexibility)." : "");
}

function untieItem(stackKey) {
    const player = G.player;
    const item = (player.inventory || []).filter(function (it) { return it && isTieSpotId(it.stowed) && getInventoryEntryKey(it) === stackKey; })[0];
    if (!item) return "";
    const prev = item.stowed;
    item.stowed = null;
    restowPlayerPack(player);
    if (item.stowed === "overflow") {
        item.stowed = prev;
        return "There is no room to put the " + getItemName(item).toLowerCase() + " away, so it stays tied on.";
    }
    return "You untie the " + getItemName(item).toLowerCase() + " and stow it.";
}


// -- Searching your own containers: pockets, belt, rucksack, carried clothes --
// Lists what is stowed in each (the items stay in the one flat pack list; this
// just shows where they are). No turn cost.

// -- Burning and breaking containers ------------------------------------------
// When a pack, pocketed garment or similar container is destroyed (fire, force),
// each thing inside rolls the same loss chance a broken chest uses; what survives
// falls to the room floor, and anything that was a liquid spills (and, with
// fire, can catch). The container itself is gone.
function queueGearBreakNotes() {
    if (!Array.isArray(G._gearBreakNotes)) G._gearBreakNotes = [];
    return G._gearBreakNotes;
}

function breakCarryContainer(item, method, lines) {
    const player = G.player;
    const room = G.activeRoom || (player && getRoom(player.coords));
    if (!item || !room) return false;
    const out = Array.isArray(lines) ? lines : [];
    let where = "";
    let slotKey = null;
    if (player && player.rucksack === item) where = "rucksack";
    else if (player && player.equipped && typeof player.equipped === "object") {
        Object.keys(player.equipped).forEach(function (k) { if (player.equipped[k] === item) { where = "worn"; slotKey = k; } });
    }
    if (!where && player && Array.isArray(player.inventory) && player.inventory.indexOf(item) >= 0) where = "pack";
    if (!where && Array.isArray(room.items) && room.items.indexOf(item) >= 0) where = "floor";
    if (!where) return false;
    const name = getItemName(item);
    const contents = Array.isArray(item.packed) ? item.packed.slice() : [];
    item.packed = [];
    if (where !== "floor" && player) {
        const ids = getContainerPlaceIdMap(item);
        const kept = [];
        player.inventory.forEach(function (it) {
            if (it && it !== item && ids[it.stowed]) contents.push(it);
            else kept.push(it);
        });
        player.inventory.length = 0;
        kept.forEach(function (it) { player.inventory.push(it); });
    }
    if (where === "rucksack") player.rucksack = null;
    else if (where === "worn") delete player.equipped[slotKey];
    else if (where === "pack") player.inventory.splice(player.inventory.indexOf(item), 1);
    else room.items.splice(room.items.indexOf(item), 1);
    item.broken = true;

    const fire = method === "fire";
    const lost = [];
    const survivors = [];
    let spilledFire = false;
    contents.forEach(function (it) {
        const total = getItemQuantity(it);
        const chance = getChestLossChance(it, fire ? "fire" : "force", fire ? "fire" : "");
        const liq = getItemLiquid(it);
        let units = 0;
        for (let i = 0; i < total; i++) if (Math.random() < chance) units += 1;
        if (units > 0) lost.push({ name: getItemName(it), units: units, total: total });
        if (liq && units > 0) {
            const extra = addRoomLiquid(room, liq.type, liq.volume * units);
            if (extra) out.push(extra);
            if (fire && LIQUID_TYPES[liq.type] && LIQUID_TYPES[liq.type].flammable) spilledFire = true;
        }
        if (units >= total) return;
        if (units > 0) it.quantity = total - units;
        delete it.stowed;
        survivors.push(it);
    });
    room.items = Array.isArray(room.items) ? room.items : [];
    survivors.forEach(function (it) {
        it.hidden = false; it.isHidden = false; it.visible = true;
        room.items.push(it);
    });
    const plural = /(s|trousers|pants)$/i.test(name) && !/ss$/i.test(name);
    const verb = fire ? (plural ? "burn through" : "burns through") : (plural ? "give out and tear apart" : "gives out and tears apart");
    const poss = where === "floor" ? "The " : "Your ";
    out.push(poss + name + " " + verb + ".");
    if (contents.length) {
        const loss = describeChestContentLoss(lost, true, fire ? "fire" : "force");
        if (loss) out.push(loss);
        if (survivors.length) {
            const names = survivors.map(function (it) { const q = getItemQuantity(it); return q > 1 ? q + " " + getItemName(it) : withIndefiniteArticle(getItemName(it)); });
            const list = names.length <= 1 ? names.join("") : names.slice(0, -1).join(", ") + " and " + names[names.length - 1];
            out.push("What is left spills onto the floor: " + list + ".");
        }
    }
    if (spilledFire) igniteRoomLiquids(room, out);
    if (player) restowPlayerPack(player);
    if (!Array.isArray(lines) && out.length) queueGearBreakNotes().push.apply(queueGearBreakNotes(), out);
    return true;
}

// Fire spells aimed at a loose item lying in the room.
function isFlammableRoomItem(item) {
    if (!item || item.objectType === "body") return false;
    if (isBurnableItem(item)) return true;
    const d = ensureDurability(item, "item");
    const mat = d ? DURABILITY_MATERIALS[d.material] : null;
    return !!(mat && mat.fire >= 1.5);
}

function getRoomItemSpellBlockReason(room, cost, spell) {
    if (roomHasActiveHostile(room)) return "Too dangerous right now.";
    if (spell.element !== "fire") return "Only fire will take hold here.";
    if (G.player.mana < cost) return "Not enough mana (" + cost + " needed).";
    return "";
}

function castSpellAtRoomItem(item, spellId) {
    const room = G.activeRoom;
    const player = G.player;
    const spell = WIZARD_SPELLS[spellId];
    if (!room || !player || !item || !spell || !spell.damageDie || !playerUsesMana(player)) return;
    const where = getBurnTargetLocation(item);
    if (!where) return;
    if (getCastableSpellIds(player).indexOf(spellId) < 0) { setNarration("You have not learned that spell, or it is not in a spellbook you are carrying."); return; }
    const cost = getEffectiveSpellManaCost(player, spell);
    const block = getRoomItemSpellBlockReason(room, cost, spell);
    if (block) { setNarration(block); return; }
    spendPlayerMana(player, cost);
    environmentActionCheckpoint();
    advanceStoryTurn(1);
    if (!environmentActionCurrent()) return environmentActionInterrupted();
    const name = getItemName(item);
    const lines = [spell.castLine];
    const mine = where !== "floor";
    if (isCarryContainerItem(item)) {
        lines.push((mine ? "You send flame into your " : "Flames take the ") + name + ".");
        breakCarryContainer(item, "fire", lines);
    } else {
        if (where === "floor") room.items.splice(room.items.indexOf(item), 1);
        else if (where === "pack") consumeOneFromInventory(item);
        else Object.keys(player.equipped).forEach(function (k) { if (player.equipped[k] === item) delete player.equipped[k]; });
        lines.push((mine ? "Your " : "The ") + name + " catches and burns away to ash.");
    }
    fixtureFireReactions(room, lines);
    renderStats();
    saveGameState();
    if (environmentExecution && textModeState.enabled) { if (!mine) { closeItemModal(); renderRoom(); } setNarration(lines.join(" ")); return; }
    if (mine && typeof refreshInventoryUi === "function") { refreshInventoryUi(lines.join(" ")); return; }
    if (typeof closeItemModal === "function") closeItemModal();
    renderRoom();
    setNarration(lines.join(" "));
}

// Whose it is does not matter: floor, pack, worn, or the rucksack itself.
function getBurnTargetLocation(item) {
    const room = G.activeRoom;
    const player = G.player;
    if (!item) return "";
    if (room && Array.isArray(room.items) && room.items.indexOf(item) >= 0) return "floor";
    if (!player) return "";
    if (player.rucksack === item) return "worn";
    if (Array.isArray(player.inventory) && player.inventory.indexOf(item) >= 0) return "pack";
    const eq = player.equipped && typeof player.equipped === "object" ? player.equipped : {};
    if (Object.keys(eq).some(function (k) { return k !== "coinPouch" && eq[k] === item; })) return "worn";
    return "";
}

function getOwnItemFireSpellButtons(item) {
    const out = [];
    addRoomItemSpellButtons(item, out);
    return out.map(function (b) {
        const btn = createEquipmentActionButton(b.textContent, b.onclick, { disabled: b.disabled });
        if (b.title) btn.title = b.title;
        return btn;
    });
}

function addRoomItemSpellButtons(item, buttons) {
    if (!isFlammableRoomItem(item) || !playerIsSpellcaster(G.player) || !playerUsesMana(G.player)) return;
    const room = G.activeRoom;
    getCastableSpellIds(G.player).forEach(function (spellId) {
        const spell = WIZARD_SPELLS[spellId];
        if (!spell || !spell.damageDie || spell.element !== "fire") return;
        const cost = getEffectiveSpellManaCost(G.player, spell);
        const reason = getRoomItemSpellBlockReason(room, cost, spell);
        buttons.push(createCombatButton("Set it alight: " + spell.name + " (" + cost + " mana)", environmentCardCallback("cast", item, spellId), { disabled: !!reason, title: reason || "" }));
    });
}

// -- Contents travel with their container ------------------------------------
// While you have a container (worn or carried) its contents sit in your flat
// pack list tagged with the container's places. When it leaves you (set down,
// sold, handed over, stored away) they are moved INTO the container item
// (item.packed, tags kept) so they go with it; when a container with packed
// contents comes back to you, restowPlayerPack unpacks them again. Anyone can
// search a container lying on the floor and take things out one at a time.
function getContainerPlaceIdMap(item) {
    const g = getGarmentPlaces(item);
    const ids = {};
    g.storage.forEach(function (p) { ids[p.id] = true; });
    g.ties.forEach(function (t) { ids[t.id] = true; });
    return ids;
}

function packContainerContents(player, item, visited) {
    if (!player || !item || !Array.isArray(player.inventory)) return 0;
    visited = visited || new Set();
    if (visited.has(item)) return 0;
    visited.add(item);
    const ids = getContainerPlaceIdMap(item);
    if (!Object.keys(ids).length) return 0;
    const moved = player.inventory.filter(function (it) { return it && it !== item && ids[it.stowed]; });
    if (!moved.length) return 0;
    // Pack inner containers first so all descendants leave with the outer bag.
    moved.forEach(function (it) { packContainerContents(player, it, visited); });
    const keep = player.inventory.filter(function (it) { return moved.indexOf(it) < 0; });
    player.inventory.length = 0;
    keep.forEach(function (it) { player.inventory.push(it); });
    if (!Array.isArray(item.packed)) item.packed = [];
    moved.forEach(function (it) { item.packed.push(it); });
    return moved.length;
}

function unpackContainerContents(player, item) {
    if (!player || !item || !Array.isArray(item.packed) || !item.packed.length) return 0;
    if (!Array.isArray(player.inventory)) player.inventory = [];
    const moved = item.packed.length;
    item.packed.forEach(function (it) { player.inventory.push(it); });
    item.packed = [];
    return moved;
}

function unpackAllContainers(player) {
    if (!player) return;
    const eq = player.equipped && typeof player.equipped === "object" ? player.equipped : {};
    const holders = (player.inventory || []).slice();
    Object.keys(eq).forEach(function (k) { if (eq[k] && !Array.isArray(eq[k])) holders.push(eq[k]); });
    if (player.rucksack) holders.push(player.rucksack);
    const seen = new Set();
    for (let i = 0; i < holders.length; i++) {
        const holder = holders[i];
        if (!holder || seen.has(holder)) continue;
        seen.add(holder);
        if (Array.isArray(holder.packed)) holders.push.apply(holders, holder.packed);
        unpackContainerContents(player, holder);
    }
}

function isCarryContainerItem(item) {
    return getGarmentPlaces(item).storage.length > 0;
}

function isItemWornByPlayer(item) {
    const player = G.player;
    if (!player || !item) return false;
    if (player.rucksack === item) return true;
    const eq = player.equipped || {};
    return Object.keys(eq).some(function (k) { return eq[k] === item; });
}

// First storage place of `container` with room for `unit`, given the items
// already inside (their tags say which place each is in).
function getContainerFreePlace(container, unit, contents) {
    const g = getGarmentPlaces(container);
    const size = getItemUnitSize(unit) * getItemQuantity(unit);
    const used = {};
    g.storage.forEach(function (pl) { used[pl.id] = 0; });
    (contents || []).forEach(function (it) {
        if (it && used[it.stowed] !== undefined) used[it.stowed] += getItemUnitSize(it) * getItemQuantity(it);
    });
    for (let i = 0; i < g.storage.length; i++) {
        if (g.storage[i].cap - used[g.storage[i].id] >= size) return g.storage[i];
    }
    return null;
}

function getContainerContents(container) {
    if (isItemWornByPlayer(container) || (G.player.inventory || []).indexOf(container) >= 0) {
        const ids = getContainerPlaceIdMap(container);
        return (G.player.inventory || []).filter(function (it) { return it && it !== container && ids[it.stowed]; });
    }
    return Array.isArray(container.packed) ? container.packed : [];
}

function splitOneUnit(list, item) {
    const qty = getItemQuantity(item);
    if (qty <= 1) {
        const idx = list.indexOf(item);
        if (idx >= 0) list.splice(idx, 1);
        return item;
    }
    item.quantity = qty - 1;
    const one = cloneItemForStackAmount(item, 1);
    one.stowed = item.stowed;
    return one;
}

// Takes one unit out of a container into the player's own places (anywhere but
// the container itself). Returns a message.
function getFromContainer(container, item, options) {
    const finish = function (message, moved) { return options && options.result ? { message: message, moved: moved || 0 } : message; };
    const player = G.player;
    const inWorld = !(isItemWornByPlayer(container) || (player.inventory || []).indexOf(container) >= 0);
    const qty = getItemQuantity(item);
    if (inWorld) {
        const list = Array.isArray(container.packed) ? container.packed : [];
        if (list.indexOf(item) < 0) return finish("It is no longer there.", 0);
        const prevStowed = item.stowed;
        const unit = qty > 1 ? cloneItemForStackAmount(item, 1) : item;
        delete unit.stowed;
        const r = addToPlayerPack(unit);
        if (r.refused) { item.stowed = prevStowed; return packFullText([r.refused]); }
        if (qty > 1) item.quantity = qty - 1;
        else { const at = list.indexOf(item); if (at >= 0) list.splice(at, 1); }
        return finish("You take " + withIndefiniteArticle(getItemName(unit)) + " out.", 1);
    }
    restowPlayerPack(player);
    const own = getContainerPlaceIdMap(container);
    const places = getPlayerStoragePlaces(player).filter(function (pl) { return !own[pl.id]; });
    const used = {};
    places.forEach(function (pl) { used[pl.id] = 0; });
    (player.inventory || []).forEach(function (it) { if (it && used[it.stowed] !== undefined) used[it.stowed] += getItemUnitSize(it) * getItemQuantity(it); });
    const size = getItemUnitSize(item);
    const target = places.filter(function (pl) { return size === 0 || pl.cap - used[pl.id] >= size; })[0];
    if (!target) return finish("There is no room for it anywhere else on you.", 0);
    let unit = item;
    if (qty > 1) { item.quantity = qty - 1; unit = cloneItemForStackAmount(item, 1); player.inventory.push(unit); }
    unit.stowed = target.id;
    return finish("You take " + withIndefiniteArticle(getItemName(unit)) + " out and put it in your " + target.label + ".", 1);
}

// Puts one unit from the player's pack into a container.
function carryContainerHoldsItem(container, item, player) {
    const seen = new Set();
    let current = item;
    while (current && !seen.has(current)) {
        if (current === container) return true;
        seen.add(current);
        const owner = findContainerOwner(player, String(current.stowed || "").split(":")[1]);
        current = owner && owner.item;
    }
    return containerHoldsItem(container, item);
}

function storeInCarryContainer(container, stackKey, options) {
    const finish = function (message, moved) { return options && options.result ? { message: message, moved: moved || 0 } : message; };
    const player = G.player;
    const inWorld = !(isItemWornByPlayer(container) || (player.inventory || []).indexOf(container) >= 0);
    restowPlayerPack(player);
    const contents = getContainerContents(container);
    const item = (player.inventory || []).filter(function (it) {
        return it && it !== container && contents.indexOf(it) < 0 && getInventoryEntryKey(it) === stackKey && !carryContainerHoldsItem(it, container, player);
    })[0];
    if (!item) return finish("You no longer have that.", 0);
    const qty = getItemQuantity(item);
    const place = getContainerFreePlace(container, { ...item, quantity: 1 }, contents);
    if (!place) return finish("There is no room left in the " + getItemName(container).toLowerCase() + " for that.", 0);
    let unit = item;
    if (qty > 1) {
        item.quantity = qty - 1;
        unit = cloneItemForStackAmount(item, 1);
        if (!inWorld) player.inventory.push(unit);
    } else if (inWorld) {
        packContainerContents(player, item);
        player.inventory.splice(player.inventory.indexOf(item), 1);
    }
    unit.stowed = place.id;
    if (inWorld) {
        if (!Array.isArray(container.packed)) container.packed = [];
        container.packed.push(unit);
    }
    return finish("You put " + withIndefiniteArticle(getItemName(unit)) + " in the " + getItemName(container).toLowerCase() + ".", 1);
}

// The card for searching a container: what is in it, with Get next to each
// item, and what you could Store from your pack. Works for worn and carried
// containers and for ones lying on the floor.
function openContainerCard(container, message) {
    if (typeof textLootCaptureCard === "function" && textLootCaptureCard(container, { message: message })) return;
    const modal = document.getElementById("itemModal");
    const titleEl = document.getElementById("itemModalTitle");
    const descEl = document.getElementById("itemModalDesc");
    const statsEl = document.getElementById("itemModalStats");
    const actionsEl = document.getElementById("itemModalActions");
    if (!modal || !titleEl || !descEl || !statsEl || !actionsEl || !container) return;
    if (typeof activeReadingSession !== "undefined" && activeReadingSession) { activeReadingSession.cancel(); activeReadingSession = null; }
    clearItemModalContents();
    restowPlayerPack(G.player);

    const onFloor = !(isItemWornByPlayer(container) || (G.player.inventory || []).indexOf(container) >= 0);
    const g = getGarmentPlaces(container);
    const contents = getContainerContents(container);
    const cap = g.storage.reduce(function (n, pl) { return n + pl.cap; }, 0);
    const used = contents.reduce(function (n, it) { return n + (g.storage.some(function (pl) { return pl.id === it.stowed; }) ? getItemUnitSize(it) * getItemQuantity(it) : 0); }, 0);
    const name = getItemName(container);
    titleEl.textContent = name.charAt(0).toUpperCase() + name.slice(1);
    descEl.style.whiteSpace = "";
    descEl.style.cursor = "";
    descEl.title = "";
    descEl.onclick = null;
    descEl.textContent = (message ? message + " " : "") + "Room used: " + used + " of " + cap + "." + (onFloor ? "" : (isItemWornByPlayer(container) ? "" : " (Carried, so what is inside does not count toward what you can carry.)"));
    statsEl.textContent = "";
    statsEl.style.display = "none";
    actionsEl.innerHTML = "";

    const listEl = getItemModalContentsEl();
    const tieIds = {};
    g.ties.forEach(function (t) { tieIds[t.id] = true; });
    const refresh = function (msg) {
        renderStats();
        if (typeof updateInventoryContextPanels === "function") updateInventoryContextPanels();
        saveGameState();
        openContainerCard(container, msg);
        const em = document.getElementById("equipmentManager");
        if (em && em.classList.contains("active") && typeof renderEquipment === "function") renderEquipment();
    };
    if (listEl) {
        const head1 = document.createElement("div");
        head1.style.cssText = "font-size:12px;color:#999;margin-top:4px;";
        head1.textContent = "Inside";
        listEl.appendChild(head1);
        if (!contents.some(isLootItemVisible)) {
            const empty = document.createElement("div");
            empty.style.cssText = "font-size:13px;color:#999;font-style:italic;";
            empty.textContent = "Nothing visible here.";
            listEl.appendChild(empty);
        }
        contents.filter(isLootItemVisible).forEach(function (it) {
            const label = formatInventoryItemLabel(it, getItemQuantity(it)) + (tieIds[it.stowed] ? " (tied on)" : "");
            const buttons = [{ label: onFloor ? "Take" : "Get", onClick: function () { refresh(getFromContainer(container, it)); } }];
            if (getDirectEquipmentSlot(it)) buttons.push({ label: "Equip", onClick: function () {
                const list = (G.player.inventory || []).includes(it) ? G.player.inventory : container.packed;
                refresh(equipPlayerItemFromSource(it, list));
            } });
            addItemModalRow(listEl, label, it.description || "", buttons);
        });
        const entries = buildPlayerInventoryEntries(G.player).filter(function (e) {
            return e.item !== container && contents.indexOf(e.item) < 0 && !containerHoldsItem(e.item, container);
        });
        if (entries.length) {
            const head2 = document.createElement("div");
            head2.style.cssText = "font-size:12px;color:#999;margin-top:10px;";
            head2.textContent = "Store from your pack";
            listEl.appendChild(head2);
            entries.slice(0, 40).forEach(function (e) {
                addItemModalRow(listEl, formatInventoryItemLabel(e.item, e.totalQuantity), e.item.description || "", [{ label: "Store", onClick: function () { refresh(storeInCarryContainer(container, e.key)); } }]);
            });
        }
    }

    getLootSearchActions(container, "carry").forEach(function (action) {
        const button = createEquipmentActionButton(action.label, action.run, { disabled: !!action.reason });
        button.title = action.reason || action.title; actionsEl.appendChild(button);
    });
    const doneBtn = document.createElement("button");
    doneBtn.type = "button";
    doneBtn.className = "primary";
    doneBtn.textContent = "Done";
    doneBtn.onclick = () => { if (onFloor) leaveItemModal(); else dismissItemModal(); };
    actionsEl.appendChild(doneBtn);
    const closeBtn = document.getElementById("itemModalClose");
    if (closeBtn) closeBtn.onclick = () => { if (onFloor) leaveItemModal(); else dismissItemModal(); };
    modal.onclick = (e) => { if (e.target === modal) { if (onFloor) leaveItemModal(); else dismissItemModal(); } };
    G.activeItemModal = container;
    modal.classList.add("active");
    doneBtn.focus();
}

function searchOwnContainer(container) {
    return searchLootContents(container, "carry");
}

// Sets the rucksack down in the room (what is in it goes with it).
function dropRucksack() {
    const player = G.player;
    const sack = player && player.rucksack;
    if (!sack) return "You are not wearing a rucksack.";
    if (!G.activeRoom) return "There is nowhere to put it down.";
    packContainerContents(player, sack);
    player.rucksack = null;
    if (!dropItemIntoCurrentRoom(sack)) { player.rucksack = sack; unpackAllContainers(player); return "There is nowhere to put it down."; }
    restowPlayerPack(player);
    return "You slip the rucksack off your shoulders and set it down.";
}

function wearRucksack(item) {
    const player = G.player;
    if (!player || !item) return "";
    if (player.rucksack) return "You already have a rucksack on.";
    const idx = player.inventory.indexOf(item);
    if (idx >= 0) player.inventory.splice(idx, 1);
    delete item.stowed;
    player.rucksack = item;
    restowPlayerPack(player);
    return "You shrug the " + getItemName(item).toLowerCase() + " onto your back.";
}

function fillContainerAtFixture(fixture, stackKey) {
    const entry = getFillableEmptyEntries().find(function (e) { return e.key === stackKey; });
    if (!entry) { setNarration("You no longer have that."); return; }
    if (entry.item.physicalDefinition && !entry.item.container.emptyId && typeof fillWorldObjectAtFixture === "function") return fillWorldObjectAtFixture(fixture, entry);
    const taken = takeInventoryEntryAmount(G.player, stackKey, 1);
    if (!taken) return;
    const filled = createFilledWaterContainer(taken.stackKey || stackKey);
    if (!filled) { G.player.inventory.push(taken); return; }
    G.player.inventory.push(filled);
    advanceStoryTurn(1);
    setNarration("You dip the " + getItemName(taken).toLowerCase().replace(/^empty /, "") + " into the " + getEntityName(fixture) + " and stopper it. " + getItemName(filled) + ".");
    refreshInventoryUi();
    saveGameState();
}

function getWeaponDamageByName(name = "") {
    const weaponName = String(name || "").toLowerCase();
    if (weaponName.includes("dagger") || weaponName.includes("knife")) return 4;
    if (weaponName.includes("staff")) return 5;
    if (weaponName.includes("mace") || weaponName.includes("club")) return 6;
    if (weaponName.includes("sword")) return 6;
    if (weaponName.includes("spear")) return 6;
    if (weaponName.includes("axe")) return 8;
    if (weaponName.includes("hammer") || weaponName.includes("maul")) return 8;
    return 4;
}

function getItemEquipSlot(item) {
    if (!item || typeof item !== "object") return null;
    // Ruined items (e.g. clothing torn off a body) can never be equipped.
    if (item.ruined || item.unusable) return null;
    if (typeof item.slot === "string" && PLAYER_EQUIPMENT_SLOT_META[item.slot] && item.slot !== "coinPouch") {
        return item.slot;
    }

    const types = Array.isArray(item.type)
        ? item.type.map(entry => String(entry).toLowerCase())
        : [String(item.type || "").toLowerCase()];

    if (types.includes("weapon")) return "weapon";
    if (types.includes("belt")) return "belt";
    // A boss relic is held in the Hand slot: carried in the pack its stat
    // bonus still applies, but its power only works while it is held.
    if (types.includes("boss-relic")) return "hand";

    const slotMatch = getPlayerEquipmentSlots().find(slot => slot !== "coinPouch" && types.includes(slot));
    if (slotMatch) return slotMatch;

    const name = getItemName(item).toLowerCase();
    if (/(dagger|knife|sword|axe|mace|hammer|maul|staff|spear|trident|glaive|halberd|whip|flail)/.test(name)) return "weapon";
    if (/(belt|girdle|sash)/.test(name)) return "belt";
    if (/(helmet|hood|cap|hat|helm)/.test(name)) return "head";
    if (/(glove|gauntlet|bracer|vambrace)/.test(name)) return "hands";
    if (/(boot|shoe|sandal|slipper)/.test(name)) return "feet";
    if (/(trouser|pants|leggings|greaves|skirt)/.test(name)) return "lower";
    if (/(shirt|tunic|vest|coat|armor|shirt|robe|blouse|jerkin|mail)/.test(name)) return "upper";
    return null;
}

function isItemEquippable(item) {
    return !!getItemEquipSlot(item);
}

function prepareItemForEquip(item, slot) {
    if (!item || typeof item !== "object" || !slot) return item;

    item.slot = slot;
    const types = Array.isArray(item.type) ? item.type.map(entry => String(entry).toLowerCase()) : [];

    if (slot === "weapon") {
        item.type = ["weapon", "weapon"];
        if (!item.weaponType) item.weaponType = getWeaponTypeFromName(getItemName(item), "generic");
        if (typeof item.damage !== "number") item.damage = getWeaponDamageByName(getItemName(item));
        return item;
    }

    const nextTypes = types.slice();
    if (!nextTypes.includes(slot)) nextTypes.push(slot);
    if (!nextTypes.includes("clothes") && !nextTypes.includes("armor") && ["head", "upper", "hands", "lower", "feet"].includes(slot)) {
        nextTypes.unshift("clothes");
    }
    if (slot === "belt" && !nextTypes.includes("belt")) nextTypes.unshift("belt");
    item.type = nextTypes;
    return item;
}

function cloneItemForStackAmount(item, quantity) {
    if (!item || typeof item !== "object") return null;

    const clone = {
        ...item,
        type: Array.isArray(item.type) ? item.type.slice() : item.type
    };

    delete clone._uid;
    delete clone.id;

    const nextQuantity = Math.max(1, Math.floor(quantity || 1));
    if (nextQuantity > 1 || typeof item.quantity === "number") {
        clone.quantity = nextQuantity;
    } else {
        delete clone.quantity;
    }

    return assignLootUID(clone);
}

function getInventoryStackKey(item) {
    if (!item || typeof item !== "object") return "";
    if (item.physicalDefinition && item._uid) return "world-object:" + item._uid;
    // Containers and pocketed garments keep their own identity and contents.
    if (isCarryContainerItem(item)) return "container:" + ensureContainerKey(item);
    if (typeof isNectarItem === "function" && isNectarItem(item)) return "nectar:" + getItemName(item).toLowerCase() + ":" + getNectarCapacityDrops(item) + ":" + getNectarDrops(item);
    if (item.stackKey) return String(item.stackKey);

    const types = Array.isArray(item.type) ? item.type.map(entry => String(entry).toLowerCase()).sort().join(",") : String(item.type || "").toLowerCase();
    return [
        getItemName(item).toLowerCase(),
        item.slot || "",
        types,
        typeof item.damage === "number" ? item.damage : "",
        typeof item.armor === "number" ? item.armor : "",
        typeof item.modifier === "number" ? item.modifier : "",
        getItemUnitValue(item)
    ].join("|");
}

// Keep identical items in different places independently actionable. The
// underlying stack key still describes item identity for recipes and trading.
function getInventoryEntryKey(item) {
    return JSON.stringify([getInventoryStackKey(item), item && item.stowed || ""]);
}

function buildPlayerInventoryEntries(player) {
    const inventory = Array.isArray(player && player.inventory) ? player.inventory : [];
    const grouped = new Map();

    inventory.forEach(item => {
        if (!isLootItemVisible(item)) return;
        const key = getInventoryEntryKey(item);
        const entry = grouped.get(key) || {
            key,
            item,
            totalQuantity: 0
        };

        entry.totalQuantity += getItemQuantity(item);
        if (!grouped.has(key)) grouped.set(key, entry);
    });

    return Array.from(grouped.values()).sort((a, b) => {
        return getItemName(a.item).localeCompare(getItemName(b.item));
    });
}

function takeInventoryEntryAmount(player, stackKey, amount) {
    if (!player || !Array.isArray(player.inventory)) return null;

    const targetAmount = Math.max(1, Math.floor(amount || 1));
    let remaining = targetAmount;
    let sample = null;

    for (let i = player.inventory.length - 1; i >= 0 && remaining > 0; i--) {
        const item = player.inventory[i];
        if (!item || getInventoryEntryKey(item) !== stackKey) continue;
        if (!sample) sample = item;

        const itemQuantity = getItemQuantity(item);
        if (itemQuantity > remaining) {
            item.quantity = itemQuantity - remaining;
            remaining = 0;
            break;
        }

        player.inventory.splice(i, 1);
        remaining -= itemQuantity;
    }

    const removed = targetAmount - remaining;
    if (!sample || removed <= 0) return null;
    return cloneItemForStackAmount(sample, removed);
}

function getInventoryEntryMaxEquipAmount(entry) {
    return entry && isItemEquippable(entry.item) ? 1 : 0;
}

function isPotionItem(item) {
    return !!(item && Array.isArray(item.type) && item.type.includes("potion"));
}

// Drinking a potion is the "use" action for the potion economy (see
// seedNPCPotionStock/POTION_STAT_TEMPLATES et al for where they come from).
// Applies the potion's effect - a timed status effect via
// STATUS_EFFECT_DEFINITIONS, or an instant full heal for the Potion of
// Health, which has no status-effect entry since it isn't a timed thing -
// and returns the narration line to show, or null.
function applyPotionEffect(entity, item, options = {}) {
    if (!entity || !item || !item.statusKey) return null;

    // An alchemy-table mixture (see ALCHEMY TABLE): what it does was designed
    // when it was mixed and is only revealed by drinking it.
    if (item.mixture) {
        return applyMixtureEffect(entity, item, options) || (options.isPlayer ? "You drink it, and nothing seems to happen." : null);
    }

    if (item.statusKey === "potionHealth") {
        entity.hp = entity.hpMax;
        if (entity === G.player) closeAllWounds(entity, 1);
        return options.isPlayer ? "You drink the potion and feel your wounds close - you're back to full health." : null;
    }

    if (item.statusKey === "potionLuck") {
        entity.luckyRollPending = true;
        return options.isPlayer ? "A strange calm settles over you - your next roll of the dice feels destined to land true." : null;
    }

    if (item.statusKey === "potionMana") {
        if (!playerUsesMana(entity)) return options.isPlayer ? "You have no magic to restore, and the potion is wasted." : null;
        restorePlayerMana(entity, entity.manaMax);
        return options.isPlayer ? "You drink the potion and feel a cool clarity flood back in - your mana is restored." : null;
    }

    if (item.statusKey === "potionStamina") {
        ensureEntityStamina(entity);
        restoreEntityStamina(entity, entity.staminaMax);
        return options.isPlayer ? "You drink the potion and feel a burst of second wind - your stamina is restored." : null;
    }

    // Raging Bull: max stamina first (like the stamina potion), then the
    // timed effect whose whole point is behavioral - no stamina drain from
    // anything (see spendEntityStamina's guard).
    if (item.statusKey === "ragingBull") {
        ensureEntityStamina(entity);
        restoreEntityStamina(entity, entity.staminaMax);
        return applyStatusEffect(entity, "ragingBull", options.name, options)
            || (options.isPlayer ? "The Raging Bull's heat renews in your veins - your strength still feels bottomless." : null);
    }

    const def = STATUS_EFFECT_DEFINITIONS[item.statusKey];
    if (!def) return null;

    const line = applyStatusEffect(entity, item.statusKey, options.name, options);
    if (line) return line;

    // applyStatusEffect returns null when it just refreshed an
    // already-active effect rather than applying a fresh one - the player
    // still drank something, so they still get a line about it.
    return options.isPlayer ? `You feel the ${def.label.toLowerCase()}'s effects renew.` : null;
}

// Alcohol consumables (see TAVERN_DRINK_TEMPLATES / ROLE_TRADE_GOODS'
// Bartender and Innkeeper pools). Drinkable by any entity - the player via
// drinkInventoryEntry, an NPC via offerDrinkToNPC (fed by the "offer-drink"
// conversation option in cyoaftw-npc-data.js).
function isAlcoholItem(item) {
    return !!(item && Array.isArray(item.type) && item.type.includes("alcohol"));
}

// Drinking alcohol stacks the "drunk" status effect (see
// STATUS_EFFECT_DEFINITIONS.drunk for what each stack does) by the drink's
// alcoholPotency, refreshing its clock. Returns a narration line for the
// drinker that varies by how drunk they ended up, or null for a
// non-alcohol item. Entity-generic; for an NPC, each drink also loosens
// their inhibitions (npc.memory.disinhibition - the same pool the
// conversation catalogue's min/maxDisinhibition conditions read).
function applyAlcoholEffect(entity, item, options = {}) {
    if (!entity || !isAlcoholItem(item)) return null;
    const potency = typeof item.alcoholPotency === "number" ? Math.max(1, item.alcoholPotency) : 1;
    const name = options.name || entity.name || "They";

    for (let i = 0; i < potency; i++) {
        applyStatusEffect(entity, "drunk", name, { isPlayer: !!options.isPlayer });
    }
    const effect = getActiveStatusEffects(entity).find(candidate => candidate.key === "drunk");
    const stacks = effect ? (effect.stacks || 1) : 0;

    if (!options.isPlayer && entity.memory && typeof applyNPCRelationshipImpact === "function") {
        applyNPCRelationshipImpact(entity, { disinhibition: 3 * potency, actionTag: "offer-drink" });
    }

    const levelLines = [
        "The drink goes down easy, leaving a pleasant warmth behind.",
        "The warmth spreads through you. Your tongue feels looser already.",
        "The room tilts gently at the edges. You are properly drunk now.",
        "Everything feels warm and funnier than it should. You are drunk as a lord."
    ];
    return options.isPlayer ? levelLines[Math.min(stacks, levelLines.length) - 1] : null;
}

// Whether the player currently carries any drinkable alcohol - powers the
// offer-drink conversation option's condition (see cyoaftw-npc-data.js).
function playerHasAlcohol() {
    if (!G || !G.player) return false;
    return buildPlayerInventoryEntries(G.player).some(candidate => isAlcoholItem(candidate.item));
}

// "Offer them a drink" (the offer-drink conversation option's action):
// hands the first alcohol entry in the player's inventory to the NPC, who
// drinks it - drunk stacks plus a disinhibition bump via
// applyAlcoholEffect - and warms to the gesture. Shows its own chat lines;
// the function-action conversation path skips the AI reply (see
// chooseChatOption).
function offerDrinkToNPC(npc) {
    if (!npc || !G || !G.player) return false;

    const entries = buildPlayerInventoryEntries(G.player);
    const entry = entries.find(candidate => isAlcoholItem(candidate.item));
    if (!entry) return false;

    const consumed = takeInventoryEntryAmount(G.player, entry.key, 1);
    if (!consumed) return false;

    const drinkName = getItemName(consumed);
    const npcName = npc.name || "They";
    applyAlcoholEffect(npc, consumed, { name: npcName, isPlayer: false });
    if (typeof applyNPCRelationshipImpact === "function") {
        applyNPCRelationshipImpact(npc, { mood: 1, favor: 3, hostility: -1, markMet: true, intent: "gift", actionTag: "offer-drink" });
    }

    const effect = getActiveStatusEffects(npc).find(candidate => candidate.key === "drunk");
    const stacks = effect ? (effect.stacks || 1) : 0;
    const reactionLines = [
        `${npcName} takes the ${drinkName}, a careful swallow, and nods their thanks.`,
        `${npcName} drinks deep, colour rising in their cheeks.`,
        `${npcName} drains it and sets the vessel down harder than they meant to.`,
        `${npcName} empties it in one go, steadying themselves on the nearest thing.`
    ];

    if (typeof addChatMessage === "function") {
        // The option click already showed "You offer them a drink."; the drink is named in the reaction.
        addChatMessage("left", npcName, reactionLines[Math.min(stacks, reactionLines.length) - 1], { mode: "auto" });
    }
    if (typeof refreshInventoryUi === "function") refreshInventoryUi();
    if (typeof saveGameState === "function") saveGameState();
    return true;
}

// ── SLOPPY DRUNK: stumbles, sickness and blackouts ──────────────────
// Rolled on movement attempts while the "drunk" status effect is active:
// movePlayer for the player, relocateNPCBetweenRooms for any NPC walking
// under its own power. Bigger creatures hold their liquor better (see
// getAlcoholSizeTolerance); "sloppy" (3+ stacks) opens up vomiting, and at
// the 4-stack cap there is a real chance of blacking out entirely.
const DRUNK_SLOPPY_MIN_STACKS = 3;
const DRUNK_BLACKOUT_MIN_STACKS = 4;
const DRUNK_BLACKOUT_CHANCE = 0.15;              // per move attempt at max stacks, x tolerance
const DRUNK_VOMIT_CHANCE = 0.12;                // per move attempt when sloppy, x tolerance
const DRUNK_STUMBLE_CHANCE_PER_STACK = 0.08;    // per stack, x tolerance

function getDrunkStacks(entity) {
    const effect = getActiveStatusEffects(entity).find(candidate => candidate.key === "drunk");
    return effect ? (effect.stacks || 1) : 0;
}

// Creature size impacts tolerance: a large body waters the drink down, a
// small one concentrates it (see getBodySizeRank / BODY_SIZE_RANK).
function getAlcoholSizeTolerance(entity) {
    let rank = 2; // medium default
    try {
        if (typeof getBodySizeRank === "function") rank = getBodySizeRank(entity);
    } catch (err) { rank = 2; }
    let base = 1;                 // medium
    if (rank >= 3) base = 0.5;    // large
    else if (rank <= 0) base = 1.5;   // tiny
    else if (rank === 1) base = 1.25; // small
    // Satyrs hold their wine: fewer stumbles, vomits and blackouts per stack.
    let sp = "";
    try {
        sp = (typeof G !== "undefined" && G && entity === G.player) ? String(getPlayerSpeciesKey() || "") : String((entity && entity.species) || "");
    } catch (err) { sp = ""; }
    if (sp.toLowerCase() === "satyr") base *= SATYR_DRINK_TOLERANCE;
    return base;
}
const SATYR_DRINK_TOLERANCE = 0.5;

// Vomiting buys a little clarity: one stack gone (and the whole effect,
// if that was the last of it).
function reduceDrunkStacks(entity, amount) {
    const effects = ensureStatusEffects(entity);
    const idx = effects.findIndex(effect => effect.key === "drunk");
    if (idx < 0) return;
    effects[idx].stacks = Math.max(0, (effects[idx].stacks || 1) - amount);
    if (effects[idx].stacks <= 0) removeStatusEffect(entity, "drunk");
}

// One roll per movement attempt by a drunk entity. Returns null when the
// move proceeds normally, or { kind: "stumble"|"vomit"|"passout", line }.
// A stumble or vomit just blocks this move (the caller narrates the line);
// a "passout" is the caller's signal that the entity is going down - the
// player blacks out for a few story turns (see movePlayer), an NPC is
// knocked out through the standard unconscious-body flow (see
// relocateNPCBetweenRooms / moveDefeatedNPCToRoomObject).
function rollDrunkMovementEvent(entity, options = {}) {
    const stacks = getDrunkStacks(entity);
    if (stacks <= 0) return null;

    const isPlayer = !!options.isPlayer;
    const name = options.name || entity.name || "They";
    const crowdNames = Array.isArray(options.crowdNames) ? options.crowdNames.filter(who => who) : [];
    const dirWord = options.dir ? String(options.dir) : null;
    const tolerance = getAlcoholSizeTolerance(entity);

    const passoutRange = stacks >= DRUNK_BLACKOUT_MIN_STACKS ? DRUNK_BLACKOUT_CHANCE * tolerance : 0;
    const vomitRange = stacks >= DRUNK_SLOPPY_MIN_STACKS ? DRUNK_VOMIT_CHANCE * tolerance : 0;
    const stumbleRange = stacks * DRUNK_STUMBLE_CHANCE_PER_STACK * tolerance;
    const roll = Math.random();

    if (roll < passoutRange) {
        return {
            kind: "passout",
            line: isPlayer
                ? "The floor swings up at you and everything goes black. You come to some time later, face down where you stood, your mouth dry as sand."
                : `${name}'s eyes lose focus, their knees buckle, and they slide to the floor - dead drunk.`
        };
    }

    if (roll < passoutRange + vomitRange) {
        reduceDrunkStacks(entity, 1);
        return {
            kind: "vomit",
            line: isPlayer
                ? rand([
                    "You stop mid-stride, stomach heaving, and lose the last drink against the base of the wall. You feel a little steadier afterward.",
                    "A cold sweat, then you're leaning on the doorframe, bringing everything back up. Better now - marginally."
                ])
                : rand([
                    `${name} doubles over and noisily loses their drink against the floor.`,
                    `${name} turns green and is sick against the nearest wall.`
                ])
        };
    }

    if (roll < passoutRange + vomitRange + stumbleRange) {
        // Bumping into someone beats bumping into a wall, if anyone's around.
        if (Math.random() < 0.4 && crowdNames.length) {
            const bystander = rand(crowdNames);
            return {
                kind: "stumble",
                line: isPlayer
                    ? `You lurch ${dirWord ? dirWord + "ward" : "for the exit"} and plough straight into ${bystander}, who shoves you back to where you started.`
                    : `${name} lurches sideways and ploughs straight into ${bystander}, who shoves them right back.`
            };
        }
        return {
            kind: "stumble",
            line: isPlayer
                ? rand([
                    `You set off ${dirWord ? dirWord + "ward" : "for the exit"}, but the floor tilts and you bounce off the wall instead.`,
                    dirWord ? `You sway into the ${dirWord} way and clip your hip on the doorframe - still standing in the same room.` : "You clip your hip on the doorframe and stay standing in the same room.",
                    dirWord ? `Your feet and the ${dirWord} way have a disagreement; the wall breaks the tie.` : "Your feet have a disagreement about which way to go; the wall breaks the tie."
                ])
                : rand([
                    `${name} lurches for the exit, bounces off the frame, and stays where they are.`,
                    `${name} weaves into the wall and, after a moment's thought, decides to stay put.`
                ])
        };
    }

    return null;
}

// Natural wake-up for a drunk blackout body: the alcohol's decay window
// (recorded on the body at blackout time - see relocateNPCBetweenRooms)
// sets the pace. Each autonomy tick rolls once per body: about a 10%
// chance right after they go down, ramping up through the decay window,
// and guaranteed once the drink has fully worn off. Defeat-knockout
// bodies are never auto-woken - only the drink puts itself out.
const DRUNK_WAKE_BASE_CHANCE = 0.1;
const DRUNK_WAKE_RAMP_CHANCE = 0.4;

function tickDrunkBlackoutWake() {
    const now = typeof getCurrentStoryTurn === "function" ? getCurrentStoryTurn() : 0;
    const map = G && G.roomMap && typeof G.roomMap === "object" ? G.roomMap : {};
    Object.keys(map).forEach(function (key) {
        const room = map[key];
        if (!room || !Array.isArray(room.items)) return;
        const here = room === (G && G.activeRoom);
        for (let i = room.items.length - 1; i >= 0; i--) {
            const body = room.items[i];
            if (!body || !body._drunkBlackout || body.bodyState !== "unconscious" || body.dead) continue;

            // Type-checked rather than || - defaults, since turn 0 is a
            // legitimate (and falsy) blackout time.
            const blackoutAtTurn = typeof body._drunkBlackoutAtTurn === "number" ? body._drunkBlackoutAtTurn : now;
            const decayAtTurn = typeof body._drunkBlackoutDecayAtTurn === "number" ? body._drunkBlackoutDecayAtTurn : blackoutAtTurn + 10;
            const window = Math.max(1, decayAtTurn - blackoutAtTurn);
            const elapsed = Math.max(0, now - blackoutAtTurn);
            let chance = DRUNK_WAKE_BASE_CHANCE + DRUNK_WAKE_RAMP_CHANCE * Math.min(1, elapsed / window);
            if (now >= decayAtTurn) chance = 1;

            if (Math.random() < chance) {
                const aftermath = wakeDrunkBlackoutBody(body, room);
                if (here) {
                    const baseWake = body.bound && body.captiveProne
                        ? `${body.name} groans and stirs — then thrashes against the ropes binding them, still hog-tied and prone.`
                        : `${body.name} groans, stirs, and drags themselves upright - awake, and clearly regretting the last round.`;
                    setNarration(aftermath ? `${baseWake} ${aftermath}` : baseWake);
                    if (typeof renderRoom === "function") renderRoom();
                }
            }
        }
    });
}

// The stand-them-up half of the natural wake: the same body mechanics as
// the manual wakeUnconsciousBody, but hangover-flavored instead of
// defeat-flavored - no hostility swing, no "shaken" mood. The blackout
// bookkeeping fields come off with the rest.
function wakeDrunkBlackoutBody(body, room) {
    if (!body || !room) return;
    room.items = Array.isArray(room.items) ? room.items : [];
    room.creatures = Array.isArray(room.creatures) ? room.creatures : [];

    const itemIndex = room.items.findIndex(entry => entry === body || (entry && body.id && entry.id === body.id));
    if (itemIndex < 0) return;
    room.items.splice(itemIndex, 1);

    body.name = body.originalName || String(body.name || "").replace(/^unconscious\s+/i, "") || body.species || "drunkard";
    body.bodyState = null;
    body.objectType = null;
    body.isUnconsciousBody = false;
    body.unconscious = false;
    body.dead = false;
    body.hidden = false;
    body.isHidden = false;
    body.bleedingOut = false;
    body.hp = Math.max(1, Math.ceil((body.hpMax || 10) * 0.25));
    const bindMode = applyPendingBodyBind(body);
    body.action = bindMode === "prone"
        ? "is bound hand and foot, lying prone and helpless"
        : (bindMode === "follow" ? "is bound, wrists lashed to a neck rope" : "is upright again, squinting at the world");
    body.description = "";
    delete body._panelDescription;
    delete body._drunkBlackout;
    delete body._drunkBlackoutAtTurn;
    delete body._drunkBlackoutDecayAtTurn;
    if (typeof generateNPCBehavior === "function") body.behavior = generateNPCBehavior(body);

    room.creatures.push(body);
    if (G && G.activeObject === body) G.activeObject = null;
    if (room === (G && G.activeRoom) && typeof selectNPC === "function") selectNPC(body);
    // Woke into a prepared bind, or into the aftermath of being used while
    // out: the evidence joins the wake narration (the caller appends the
    // returned suffix), and the first reaction is spoken. The stale guards
    // inside keep the bubble silent when the player is not the one
    // looking at them.
    return applyWakeAftermath(body, room, "", bindMode || null);
}

// The "Drink" action on a potion inventory entry (see
// renderEquipmentInventoryEntry). Consumes exactly one unit via the same
// stack-splitting helper Equip/Drop already use.
function drinkInventoryEntry(stackKey) {
    const entries = buildPlayerInventoryEntries(G.player);
    const entry = entries.find(candidate => candidate.key === stackKey);
    if (!entry || !(isPotionItem(entry.item) || isAlcoholItem(entry.item))) return null;

    const consumed = takeInventoryEntryAmount(G.player, stackKey, 1);
    if (!consumed) return null;

    const line = isAlcoholItem(consumed)
        ? applyAlcoholEffect(G.player, consumed, { isPlayer: true, name: "You" })
        : applyPotionEffect(G.player, consumed, { isPlayer: true, name: "You" });
    // The bottle stays with you (a potion leaves an empty vial).
    const kept = giveBackEmptyContainer(consumed);
    return line && kept ? line + " " + kept : line;
}

// The "Read" action on a deity tome inventory entry (see
// renderEquipmentInventoryEntry). Consumes the tome and grants knowledge of
// that deity (see learnDeity/DEITY_ARCHETYPES) - the other way, besides an
// NPC conversation, to earn the right to choose that deity as a patron.
function readInventoryEntry(stackKey) {
    const entries = buildPlayerInventoryEntries(G.player);
    const entry = entries.find(candidate => candidate.key === stackKey);
    if (!entry || !isDeityTomeItem(entry.item)) return null;

    const deity = getDeityArchetype(entry.item.deityId);
    if (!deity) return null;

    const alreadyKnew = Array.isArray(G.player.knownDeities) && G.player.knownDeities.includes(deity.id);
    const consumed = takeInventoryEntryAmount(G.player, stackKey, 1);
    if (!consumed) return null;

    learnDeity(deity.id, `${G.player.name} read of ${deity.name} in ${getItemName(consumed)}.`);
    applyFaithDelta({ [deity.id]: 2 }, `read ${deity.name}'s tome`);

    return alreadyKnew
        ? `You reread ${getItemName(consumed)} - you already knew of ${deity.name}.`
        : `You read ${getItemName(consumed)} and learn of ${deity.name}, god of ${deity.domain}.`;
}

// -- WRITTEN-MATERIAL LORE NOTES --------------------------------------
// Generic "lore"-tagged flavor loot (folded notes, sealed letters, scroll
// fragments, etc. - see NPC_MISC_LOOT/NPC_ZONE_LOOT) had only a fixed,
// generic description before. Reading one now rolls a random topic and
// asks the AI to write the note's actual contents once, the first time
// it's read - cached on the item (generatedContent) so rereading it always
// shows the same text and never re-hits the AI. Deity tomes (isDeityTomeItem)
// are a separate, more specific system and are excluded here.
// Use AI off: how often a deity says yes to a favor / a death prayer.
const AI_OFF_FAVOR_GRANT_CHANCE = 0.8;
const AI_OFF_REVIVAL_WORTHY_CHANCE = 0.7;

const LORE_NOTE_TOPICS = ["recipe", "treasure", "deity", "rumor", "warning", "history", "confession"];

function isGenericLoreItem(item) {
    return !!(item && Array.isArray(item.type) && item.type.includes("lore") && !isDeityTomeItem(item));
}

function buildLoreTopicInstruction(topicId, deity) {
    switch (topicId) {
        case "recipe":
            return "Write a short, in-universe recipe or preparation method for a potion (Potion of Health, Potion of Luck, Potion of Stamina, or one you invent) - a brief list of ingredients and a hurried method, like a recipe card.";
        case "treasure":
            return "Hint at the location of a rare treasure, a hidden cache, or an unusual and notable individual (a rare NPC) somewhere in the world - vague and evocative, like a real clue rather than a literal map.";
        case "deity":
            return deity
                ? `Write a short passage revealing something of ${deity.name}, god of ${deity.domain}. ${deity.lore} Frame it as something the writer witnessed, believed, or was taught.`
                : "Write a short passage of religious devotion to one of the old gods, without naming a specific one.";
        case "rumor":
            return "Share a local rumor or bit of gossip about people or events nearby - the kind of thing overheard in a tavern.";
        case "warning":
            return "Write a warning about a specific danger, creature, or place nearby, as if left by someone who barely escaped it.";
        case "history":
            return "Recount a short fragment of local history or legend - a past event, a fallen figure, or a ruin's original purpose.";
        case "confession":
            return "Write a short personal confession or regret from whoever wrote this - something private they never told anyone.";
        default:
            return "Write a short, evocative fragment of in-universe writing.";
    }
}

const LORE_NOTE_FALLBACKS = {
    recipe: [
        "Potion of Health: two parts bruised herb to one of clear spring water, simmered, never boiled. Strain through linen and bottle while warm. Do not let it cool in the open.",
        "Stamina draught, as taught to me: crushed root, a pinch of salt, and honey if you have it. Steep a quarter hour. Drink it before the walk, not after.",
        "A luck tonic, poorly remembered: silver-leaf, a drop of wine, and patience. If it turns cloudy, pour it out and begin again."
    ],
    treasure: [
        "What I could not carry I left where the old road bends, under the stone that looks wrong. Count the steps from the broken marker. Come back for it, if I do not.",
        "They say a man who lives off the road keeps a strongbox he will not show anyone. Find him and be kind to him first.",
        "Hidden in plain sight, where the lamp never reaches. I have said too much already."
    ],
    rumor: [
        "Heard in the tap-room: the watch is not telling everything about the last few weeks. Someone is paying to keep it quiet.",
        "They say a stranger has been asking after the old families, and no one can say where they sleep.",
        "Prices are up and nobody will say why. Ask the carters, they know."
    ],
    warning: [
        "Do not go past the last marker after dark. I did, and I am not sure what followed me back.",
        "Whatever is in the lower ground is hungry, and it learns. Go in loud and you will not come out.",
        "Do not drink from the standing water out there. Ask me how I know."
    ],
    history: [
        "This was a place of some note before the war. The walls remember the banners that once hung here, even if no one else does.",
        "They say the first stones were laid by those who fled the old capital. They built low and thick, and they built to last.",
        "The ruin was not always a ruin. Ask the oldest in town what it was for, and watch who changes the subject."
    ],
    confession: [
        "I never told anyone I was the one who left the gate open that night. I think about it every day.",
        "I took what was not mine, and I have been repaying it in small ways ever since. It is never enough.",
        "If you are reading this, I did not make it back. Tell her I was not afraid."
    ]
};

function buildLoreNoteFallback(topicId, deity) {
    if (topicId === "deity") {
        if (deity && deity.lore) return String(deity.lore);
        return "Written in a careful hand: a prayer to the old gods, asking only for a little light to walk by.";
    }
    const bank = LORE_NOTE_FALLBACKS[topicId] || LORE_NOTE_FALLBACKS.rumor;
    return bank[Math.floor(Math.random() * bank.length)];
}

// Generates and caches the note's contents on first read. Returns the
// cached text on every later call without touching the AI again.
async function generateLoreNoteContent(item, readingContext) {
    if (!item) return null;
    if (item.generatedContent) return item.generatedContent;

    let topicId = rand(LORE_NOTE_TOPICS);
    let deity = null;

    if (topicId === "deity") {
        const player = G.player;
        ensurePlayerDeityState(player);
        const candidates = Object.keys(DEITY_ARCHETYPES).filter(id => !player.knownDeities.includes(id));
        if (candidates.length) {
            deity = getDeityArchetype(rand(candidates));
        } else {
            // Already knows every deity - a "reveals a deity" note would be
            // a dead end, so fall back to a different topic instead.
            topicId = rand(LORE_NOTE_TOPICS.filter(id => id !== "deity"));
        }
    }

    let content = null;
    if (aiAvailable()) {
        try {
            const instruction = [
                `You are writing the contents of a found "${getItemName(item)}" in a fantasy roleplay game.`,
                item.description ? `Physical description of the item: ${item.description}` : "",
                buildLoreTopicInstruction(topicId, deity),
                "Keep it to 2 to 4 sentences, written as the in-universe text itself - no title, no meta-commentary, no preamble.",
                "Return ONLY valid JSON, no markdown fences, no commentary, in exactly this shape:",
                "{\"content\":\"the written text itself\"}"
            ].filter(Boolean).join("\n");

            const jsonPrefix = "{\"content\":\"";
            const result = await callAI({ instruction, startWith: jsonPrefix, endButtons: "none" });
            const continuation = typeof result === "string" ? result : (result && result.text ? result.text : "");
            const rawText = String(continuation || "").trim().startsWith("{")
                ? String(continuation || "").trim()
                : `${jsonPrefix}${String(continuation || "").trim()}`;
            const parsed = typeof tryParseConversationJSON === "function" ? tryParseConversationJSON(rawText) : null;
            content = parsed && typeof parsed.content === "string" ? parsed.content.trim() : null;
        } catch (e) {
            console.warn("Lore note generation failed:", e);
        }
    }

    if (!content) {
        // AI off or failed: a stock passage for the rolled topic.
        content = buildLoreNoteFallback(topicId, deity);
    }

    if (readingContext && !readingContext.valid()) return null;
    item.generatedContent = content;
    item.generatedTopic = topicId;
    if (topicId === "deity" && deity) item.generatedDeityId = deity.id;
    if (readingContext) readingContext.contentGenerated();

    return content;
}

// The "Read" action on a generic lore-note inventory entry (see
// renderEquipmentInventoryEntry). Not consumed - it's information, not a
// one-use item - so rereading it just shows the cached content again. If
// the roll landed on the "deity" topic, reading it grants that deity's
// knowledge the same as reading its dedicated tome would.
async function readLoreNoteEntry(stackKey, readingContext) {
    const entries = buildPlayerInventoryEntries(G.player);
    const entry = entries.find(candidate => candidate.key === stackKey);
    if (!entry || !isGenericLoreItem(entry.item)) return null;

    const content = await generateLoreNoteContent(entry.item, readingContext);
    if (readingContext && !readingContext.valid()) return null;

    if (entry.item.generatedTopic === "deity" && entry.item.generatedDeityId) {
        const deity = getDeityArchetype(entry.item.generatedDeityId);
        if (deity) {
            learnDeity(deity.id, `${G.player.name} read of ${deity.name} in ${getItemName(entry.item)}.`);
            applyFaithDelta({ [deity.id]: 2 }, `read of ${deity.name} in a lore note`);
        }
    }

    return String(content || "").trim();
}

// -- ITEM EXAMINATION (trade panel) ------------------------------------
// The "Examine" button next to Buy/Sell (see createTradeItemRow) - an AI
// call weaves the item's mechanical properties (name, description, type
// tags) together with any lore already established on it (a deity tome's
// lore, or a lore note's generated content/deity - see
// generateLoreNoteContent) into one cohesive paragraph, instead of just
// repeating the static description. Cached on the item (examineText) so
// examining it again never re-hits the AI.

// The item card shows the AI flavor (examineText) in place of item.description,
// which for special gear is where the plain-English effect lives. So the real
// effect is rebuilt from the item's data here and shown on its own "Effect:"
// line(s) beside the flavor - the flavor can never hide what the item does.
function buildItemEffectLines(item) {
    const lines = [];
    if (!item || typeof item !== "object") return lines;

    if (typeof isClassGearItem === "function" && isClassGearItem(item)) {
        lines.push("Effect: " + describeItemAffinity(item) + ". Other classes gain nothing from it.");
    }
    if (typeof item.enchantDamageBonus === "number" && item.enchantDamageBonus !== 0) {
        lines.push("Effect: " + (item.enchantDamageBonus > 0 ? "+" : "") + item.enchantDamageBonus + " damage from its enchantment.");
    }
    if (item.elementalDamage && item.elementalDamage.type) {
        lines.push("Effect: +" + (item.elementalDamage.amount || 1) + " " + item.elementalDamage.type + " damage on hit.");
    }
    if (item.enchantment === "elusion") lines.push("Effect: +2 dodge while worn.");
    if (item.enchantment === "fireproof") lines.push("Effect: +3 fire resistance.");
    if (item.enchantment === "frostguard") lines.push("Effect: +3 frost resistance.");
    if (item.buff && typeof describeItemBuff === "function" && describeItemBuff(item)) {
        lines.push("Effect: " + describeItemBuff(item) + ".");
    }
    // Potions and other consumables keep their effect text in the description.
    if (item.statusKey && item.description) {
        lines.push("Effect: " + item.description);
    }
    return lines;
}

function buildItemExamineInstruction(item) {
    const tags = Array.isArray(item.type) ? item.type.join(", ") : "";
    const deityId = item.deityId || item.generatedDeityId || null;
    const deity = deityId ? getDeityArchetype(deityId) : null;

    return [
        item.isFixture
            ? `You are writing a vivid, in-universe examination of a fixture of the environment called "${getItemName(item)}"${item.roomName ? `, found in "${item.roomName}"` : ""}, in a fantasy roleplay game. It is part of the room and cannot be carried.`
            : `You are writing a vivid, in-universe examination of an item called "${getItemName(item)}" in a fantasy roleplay game.`,
        item.description ? `Its known description: ${item.description}` : "",
        tags ? `Its category tags: ${tags}.` : "",
        item.generatedContent ? `Its written contents (already established - do not contradict this): "${item.generatedContent}"` : "",
        deity ? `It is tied to ${deity.name}, god of ${deity.domain}. ${deity.lore}` : "",
        "Write a short, cohesive paragraph (2 to 4 sentences) describing what a careful look at this item reveals - texture, craftsmanship, wear, or some subtle detail - consistent with everything given above. Do not invent facts that contradict what's already established.",
        "Return ONLY valid JSON, no markdown fences, no commentary, in exactly this shape:",
        "{\"examine\":\"the examination text itself\"}"
    ].filter(Boolean).join("\n");
}

async function generateItemExamineText(item) {
    if (!item) return null;
    if (item.examineText) return item.examineText;

    let text = null;
    let fromAI = false;
    if (aiAvailable()) {
        try {
            const instruction = buildItemExamineInstruction(item);
            const jsonPrefix = "{\"examine\":\"";
            const result = await callAI({ instruction, startWith: jsonPrefix, endButtons: "none" });
            const continuation = typeof result === "string" ? result : (result && result.text ? result.text : "");
            const rawText = String(continuation || "").trim().startsWith("{")
                ? String(continuation || "").trim()
                : `${jsonPrefix}${String(continuation || "").trim()}`;
            const parsed = typeof tryParseConversationJSON === "function" ? tryParseConversationJSON(rawText) : null;
            text = parsed && typeof parsed.examine === "string" ? parsed.examine.trim() : null;
            fromAI = !!text;
        } catch (e) {
            console.warn("Item examine generation failed:", e);
        }
    }

    if (!text) {
        text = item.description || `A closer look reveals nothing more than what's already plain to see about ${getItemName(item)}.`;
    }

    // Only AI text is cached: the plain description must not block a proper
    // examine text once Use AI is switched back on.
    if (fromAI) item.examineText = text;
    return text;
}

// Opens the item card (same small window used for looting containers and
// examining equipment) focused on the item: examine text (generated on first
// look, cached on the item), its real numbers, and a comparison with what the
// player wears in that slot. Does not touch coins, inventory, stock or the
// room text - Close just dismisses the card and the trade menu stays put.
async function examineTradeItem(item) {
    if (!item) return;
    if (typeof openEquipmentExamine === "function") {
        const slot = typeof getItemEquipSlot === "function" ? getItemEquipSlot(item) : null;
        openEquipmentExamine(item, { slot: slot || null, equipped: false });
        return;
    }
    const text = await generateItemExamineText(item);
    showTradeMessage(`${getItemName(item)}: "${text}"`, true);
    saveGameState();
}

// -- ASK ABOUT ITEM (trade panel) --------------------------------------
// The "Ask" button next to Examine/Buy/Sell (see createTradeItemRow) - the
// SELLER's own in-character reaction to the item, not another neutral
// description. Deliberately not cached (unlike examineText/generatedContent)
// since an NPC's opinion is meant to feel alive - it can vary with mood,
// favorability, and temperament from one visit to the next, the same way
// their ordinary dialogue replies are generated fresh each time rather
// than memorized verbatim.
// discoveredTrait, when set (see askAboutTradeItem's reveal), asks the AI
// to weave in a plausible in-character backstory for why the item turns
// out to be special - deliberately without exact numbers, since the
// mechanical summary is appended verbatim by code afterward rather than
// trusted to the model, so the player always sees the real effect
// correctly stated.
function buildAskAboutItemInstruction(npc, item, discoveredTrait) {
    const memory = npc.memory || {};
    const favorability = typeof memory.favorability === "number" ? memory.favorability : 0;
    const hostility = typeof npc.hostility === "number" ? npc.hostility : 0;
    const personaSummary = npc.persona && npc.persona.summary ? npc.persona.summary : (npc.backstory || "");
    const tags = Array.isArray(item.type) ? item.type.join(", ") : "";
    const deityId = item.deityId || item.generatedDeityId || null;
    const deity = deityId ? getDeityArchetype(deityId) : null;

    return [
        `You are ${getNPCSelfNameSafe(npc)}, a ${npc.species}${npc.role ? ` working here as ${npc.role}` : ""}, currently trading with the player.`,
        getNPCNameKnowledgeLine(npc),
        personaSummary ? `Who you are: ${personaSummary}` : "",
        `Temperament: ${npc.temperament || "neutral"}. Your favorability toward the player: ${favorability}/100. Hostility: ${hostility}/100.`,
        `The player asks you about an item on the table: "${getItemName(item)}".`,
        item.description ? `Its plain description: ${item.description}` : "",
        tags ? `Its category tags: ${tags}.` : "",
        item.generatedContent ? `Its already-established written contents: "${item.generatedContent}"` : "",
        deity ? `It is tied to ${deity.name}, god of ${deity.domain}.` : "",
        discoveredTrait
            ? `As you talk, something clicks - you realize this item is actually a "${discoveredTrait.label}". Tell a specific, personal story explaining why it's special (why it was sold, who it belonged to, what happened to it) that would justify that name. Do not mention exact numbers, percentages, or game mechanics - just tell the story naturally, in character.`
            : "Answer in your own voice, in character, 1 to 3 sentences - your personal opinion of it, where you got it, an anecdote, a warning, or a haggling remark, colored by your temperament and how you feel about the player right now. Do not just restate the plain description as if reciting a label.",
        "Do not break character. Do not refer to yourself as an AI.",
        "Return ONLY valid JSON, no markdown fences, no commentary, in exactly this shape:",
        "{\"reply\":\"what you say, without quotation marks around it\"}"
    ].filter(Boolean).join("\n");
}

// Whether an item is secretly enchanted was already decided when it was
// generated (see maybeEnchantItem) - asking about it here doesn't roll
// anything, it just reveals whichever trait was already secretly assigned,
// the first time the player asks about that specific item. The trait is
// permanently attached to the item itself (item.hiddenTrait), so it
// survives being bought, sold, looted, or dropped, and its mechanical
// effect ("luck" feeding rollD20, "stat" feeding getEntityStatValue/
// getSetupStat) applies to whoever ends up carrying it, not just the
// player, from the moment it was generated - reveal only uncovers it, it
// doesn't turn it on.
// AI off (or failed): a short in-character remark picked by mood and whether
// the item has a secret trait to reveal.
function buildAskAboutItemFallback(npc, item, discoveredTrait) {
    const name = getItemName(item);
    const hostility = npc && typeof npc.hostility === "number" ? npc.hostility : 0;
    const favor = npc && npc.memory && typeof npc.memory.favorability === "number" ? npc.memory.favorability : 0;
    const band = hostility >= 60 || favor <= -20 ? "hostile" : (favor >= 30 ? "friendly" : "neutral");
    const pool = discoveredTrait ? {
        friendly: [`I should tell you, friend: the ${name} is not what it looks like. I have held onto it for a reason.`, `Between us, the ${name} has a story. Take care of it and it will take care of you.`],
        neutral: [`There is more to the ${name} than meets the eye. I will say no more than that.`, `The ${name}? It came to me in a roundabout way. It is worth more than it looks.`],
        hostile: [`Fine. The ${name} is better than it looks. Do not make me regret saying so.`, `You want the truth? The ${name} is special. Pay for it accordingly.`]
    } : {
        friendly: [`The ${name}? A fair piece. I would be glad to see it go to someone who will use it.`, `I would take the ${name} myself, if I could afford to keep it.`],
        neutral: [`The ${name}. Does the job. Nothing fancy, nothing to hide.`, `It is what it looks like. Take a good look before you pay.`],
        hostile: [`Buy it or do not. I have not got all day for questions.`, `It is what it is. Stop wasting my time.`]
    };
    const list = pool[band] || pool.neutral;
    return list[Math.floor(Math.random() * list.length)];
}

async function askAboutTradeItem(npc, item) {
    const start = merchantQuestionStart(npc, item);
    if (start.error) return start.error;

    let discoveredTrait = null;
    if (item && item.hiddenTrait && !item.hiddenTraitRevealed) {
        item.hiddenTraitRevealed = true;
        discoveredTrait = item.hiddenTrait;
    }

    if (discoveredTrait) {
        rememberStoryEvent("lore", G.player.name + " discovered " + getItemName(item) + " is a " + discoveredTrait.label + ".", 5, { tags: ["item-discovery"] });
        saveGameState();
    }
    const request = merchantQuestionWait(npc, item, start.entry, discoveredTrait);
    let reply = null;
    if (aiAvailable()) {
        try {
            const instruction = buildAskAboutItemInstruction(npc, item, discoveredTrait);
            const jsonPrefix = "{\"reply\":\"";
            const result = await callAI({ instruction, startWith: jsonPrefix, endButtons: "none" });
            const continuation = typeof result === "string" ? result : (result && result.text ? result.text : "");
            const rawText = String(continuation || "").trim().startsWith("{")
                ? String(continuation || "").trim()
                : `${jsonPrefix}${String(continuation || "").trim()}`;
            const parsed = typeof tryParseConversationJSON === "function" ? tryParseConversationJSON(rawText) : null;
            reply = parsed && typeof parsed.reply === "string" ? parsed.reply.trim() : null;
        } catch (e) {
            console.warn("Ask-about-item failed:", e);
        }
    }

    if (!request.valid()) return merchantQuestionInterrupted(npc, request);
    if (!reply) reply = buildAskAboutItemFallback(npc, item, discoveredTrait);

    let message = `${npc.name}: "${reply}"`;
    if (discoveredTrait) {
        message += ` You've discovered ${getItemName(item)} is a ${discoveredTrait.label}: ${discoveredTrait.summary}!`;

    }

    showTradeMessage(message, true);
    merchantQuestionOutput(npc, item, request, reply, message);
    renderTradeOptions(npc);
    return { status: "completed" };
}

function formatInventoryItemLabel(item, quantityOverride = null) {
    if (!item) return "item";

    const quantity = quantityOverride == null ? getItemQuantity(item) : Math.max(1, Math.floor(quantityOverride || 1));
    const nectarLabel = typeof isNectarItem === "function" && isNectarItem(item) ? " (" + getNectarDrops(item) + " drops)" : "";
    const baseName = getItemName(item) + nectarLabel + (isItemSlimy(item) ? " (slimy)" : "");
    if (quantity <= 1) return baseName;
    return `${baseName} x${quantity}`;
}

// Pulled out of a slime: coated for a while, then it dries off.
const SLIME_COAT_TURNS = 40;
function isItemSlimy(item) {
    return !!(item && typeof item._slimyUntil === "number" && item._slimyUntil > getCurrentStoryTurn());
}

function createDroppedCoinsItem(amount) {
    const quantity = Math.max(1, Math.floor(amount || 1));
    return assignLootUID({
        name: quantity === 1 ? "Coin" : `${quantity} coins`,
        type: ["coin", "currency"],
        quantity,
        value: 1,
        description: quantity === 1 ? "A single loose coin." : `A small pile of ${quantity} loose coins.`
    });
}

function dropItemIntoCurrentRoom(item) {
    const room = G.activeRoom || getRoom(G.player && G.player.coords);
    if (!room || !item) return false;

    room.items = Array.isArray(room.items) ? room.items : [];
    packContainerContents(G.player, item);
    item.hidden = false;
    item.isHidden = false;
    item.visible = true;
    room.items.push(item);
    return true;
}

// Remove a worn item from a character's equipment slot and drop it into the
// current room (the floor). Used by the intimacy clothing actions so
// undressing leaves real, takeable clothes in the room instead of silently
// returning them to inventory — the player has to pick them back up.
// Returns the dropped item, or null.
function dropWornClothingToRoom(character, slotKey) {
    if (!character || !slotKey || slotKey === "coinPouch") return null;
    const eq = character.equipped;
    if (!eq || !eq[slotKey]) return null;
    const item = eq[slotKey];
    delete eq[slotKey];
    if (Array.isArray(item)) return null; // legacy array slot — discard
    if (!dropItemIntoCurrentRoom(item)) {
        eq[slotKey] = item; // no room available — don't destroy the item
        return null;
    }
    return item;
}
window.dropWornClothingToRoom = dropWornClothingToRoom;

function moveEquippedItemToInventory(slot) {
    ensurePlayerEquipmentState(G.player);
    const eq = G.player.equipped || {};
    const item = eq[slot];
    if (!item || slot === "coinPouch") return null;

    delete eq[slot];
    delete item.stowed;
    G.player.inventory.push(item);
    if (slot === "weapon") G.player.weapon = "unarmed";
    return item;
}

function dropEquippedItemToRoom(slot) {
    ensurePlayerEquipmentState(G.player);
    const eq = G.player.equipped || {};
    const item = eq[slot];
    if (!item || slot === "coinPouch") return false;

    delete eq[slot];
    if (slot === "weapon") G.player.weapon = "unarmed";
    if (dropItemIntoCurrentRoom(item)) return true;

    eq[slot] = item;
    if (slot === "weapon") G.player.weapon = getItemName(item);
    return false;
}

function equipInventoryEntry(stackKey) {
    ensurePlayerEquipmentState(G.player);

    const entry = buildPlayerInventoryEntries(G.player).find(candidate => candidate.key === stackKey);
    if (!entry) return false;

    const slot = getItemEquipSlot(entry.item);
    if (!slot) return false;

    const item = takeInventoryEntryAmount(G.player, stackKey, 1);
    if (!item) return false;

    prepareItemForEquip(item, slot);
    delete item.stowed;

    const existing = G.player.equipped[slot];
    if (existing) G.player.inventory.push(existing);

    G.player.equipped[slot] = item;
    G.player.weapon = slot === "weapon" ? getItemName(item) : (G.player.equipped.weapon ? getItemName(G.player.equipped.weapon) : "unarmed");
    return true;
}

// Keep source lists so direct equipment moves the selected object, never a
// same-named item elsewhere. Hidden items and bodies are not loose gear.
function getAccessibleEquipmentSources(entity, includeFloor) {
    const sources = [];
    const seen = new Set();
    function visit(list, floor) {
        (list || []).forEach(function (item) {
            if (!item || seen.has(item) || item.hidden || item.isHidden || item.concealed || item.visible === false || item.objectType === "body") return;
            seen.add(item);
            if (!floor || isRoomItemTakeable(item)) sources.push({ item: item, list: list });
            if (Array.isArray(item.packed)) visit(item.packed, floor);
        });
    }
    visit(entity && entity.inventory, false);
    const worn = Object.values(entity && entity.equipped || {}).concat(entity && entity.rucksack || []);
    worn.forEach(function (item) { if (item && Array.isArray(item.packed)) visit(item.packed, false); });
    if (includeFloor) visit(G.activeRoom && G.activeRoom.items, true);
    return sources;
}

function getDirectEquipmentSlot(item) {
    if (!item || item.ruined || item.unusable || item.hidden || item.isHidden || item.concealed) return null;
    if (item.container && item.container.wearable === "back") return "back";
    return getItemEquipSlot(item);
}

// Equip without first finding pack space. Only the displaced piece needs
// storage; if it cannot fit, set it down with any contents still inside.
function equipPlayerItemFromSource(item, list, fixture) {
    const player = G.player;
    const slot = getDirectEquipmentSlot(item);
    if (!player || !slot || !Array.isArray(list) || !list.includes(item)) return "That item is no longer available.";
    const accessible = getAccessibleEquipmentSources(player, true).some(function (source) { return source.item === item && source.list === list; });
    const room = G.activeRoom;
    const inFixture = fixture && room && (room.structural || []).includes(fixture) && fixture.opened && !fixture.concealed && ensureContainerContents(fixture).items === list;
    if (!accessible && !inFixture) return "That item is no longer available.";
    if (typeof worldObjectEquipBlock === "function") {
        const physicalBlock = worldObjectEquipBlock(item, list);
        if (physicalBlock) return physicalBlock;
    }
    ensurePlayerEquipmentState(player);
    const unit = splitOneUnit(list, item);
    delete unit.stowed;
    const old = slot === "back" ? player.rucksack : player.equipped[slot];
    if (slot === "back") player.rucksack = unit;
    else {
        prepareItemForEquip(unit, slot);
        player.equipped[slot] = unit;
    }
    if (slot === "weapon") player.weapon = getItemName(unit);
    if (old && !Array.isArray(old)) { delete old.stowed; player.inventory.push(old); }
    restowPlayerPack(player);
    let message = "You equip " + getItemName(unit) + ".";
    if (old && !Array.isArray(old)) {
        if (old.stowed === "overflow" && room) {
            packContainerContents(player, old);
            player.inventory.splice(player.inventory.indexOf(old), 1);
            dropItemIntoCurrentRoom(old);
            restowPlayerPack(player);
            message += " You set " + getItemName(old) + " on the floor because your storage is full.";
        } else message += " You stow " + getItemName(old) + ".";
    }
    return message;
}

function equipRoomItem(item) {
    const message = equipPlayerItemFromSource(item, G.activeRoom && G.activeRoom.items);
    closeItemModal();
    resetNpcPanel();
    refreshInventoryUi(message);
}

function dropInventoryEntryToRoom(stackKey, amount) {
    ensurePlayerEquipmentState(G.player);

    const item = takeInventoryEntryAmount(G.player, stackKey, amount);
    if (!item) return null;

    const itemTypes = Array.isArray(item.type) ? item.type.map(entry => String(entry).toLowerCase()) : [];
    if (getItemQuantity(item) > 1 && !itemTypes.includes("coin")) {
        item.name = formatInventoryItemLabel(item, getItemQuantity(item));
    }

    if (!dropItemIntoCurrentRoom(item)) {
        G.player.inventory.push(item);
        return null;
    }

    return item;
}

function getEquippedItem(entity, slot) {
    if (!entity || !entity.equipped) return null;
    return entity.equipped[slot] || null;
}

function getItemArmorValue(item) {
    if (!item || Array.isArray(item)) return 0;
    const buffBonus = item.buff && item.buff.kind === "armor" ? (item.buff.bonus || 0) : 0;
    const wornFactor = item.armorBroken === true ? DURABILITY_ARMOR_BROKEN_FACTOR : 1;
    if (typeof item.armor === "number") return Math.max(0, Math.floor((item.armor + buffBonus) * wornFactor));
    if (typeof item.modifier === "number") return Math.max(0, item.modifier + buffBonus);
    return Math.max(0, buffBonus);
}

function getEntityWeaponItem(entity) {
    return getEquippedItem(entity, "weapon");
}

function getEntityWeaponName(entity) {
    const equippedWeapon = getEntityWeaponItem(entity);
    return String(
        (equippedWeapon && (equippedWeapon.name || equippedWeapon.displayName)) ||
        (entity && entity.weapon) ||
        "unarmed"
    );
}

function getWeaponTypeFromName(name = "", fallback = "generic") {
    const key = String(name || "").toLowerCase();
    if (key.includes("dagger")) return "dagger";
    if (key.includes("sword") || key.includes("scimitar") || key.includes("saber") || key.includes("rapier")) return "sword";
    if (key.includes("axe")) return "axe";
    if (key.includes("mace") || key.includes("hammer") || key.includes("maul") || key.includes("morningstar")) return "mace";
    if (key.includes("spear") || key.includes("trident")) return "spear";
    if (key.includes("halberd") || key.includes("glaive") || key.includes("polearm")) return "polearm";
    if (key.includes("staff")) return "staff";
    if (key.includes("flail")) return "flail";
    if (key.includes("whip")) return "whip";
    return fallback;
}

// Blunt causes trauma (no bleed, but a crit can knock an entity out outright
// - see determineCombatDefeatOutcome). Puncture always draws blood on a hit.
// Edge is "a bit of both": it keeps the original crit/heavy/torso bleed rule
// and is the only type that can sever a limb on a finishing crit.
const WEAPON_DAMAGE_TYPE = {
    dagger: "puncture",
    spear: "puncture",
    sword: "edge",
    axe: "edge",
    polearm: "edge",
    whip: "edge",
    mace: "blunt",
    staff: "blunt",
    flail: "blunt",
    generic: "blunt"
};

function getWeaponDamageType(weaponType) {
    return WEAPON_DAMAGE_TYPE[weaponType] || "blunt";
}

// -- STRIKE NARRATION (weapon / natural-attack aware) ------------------------
// Text only - nothing in here rolls dice or changes damage. Used by
// attackNPC / resolveNPCCounter (player-vs-NPC fights) to describe a hit or
// miss by what actually hit: edge weapons slash and cut (and bleed), puncture
// weapons stab and pierce, blunt weapons batter and bruise, and creatures with
// no weapon fight with their own bodies (a wolf mostly bites, sometimes
// claws). Hits also scale by how big the blow was compared to the target's max
// hp. The damage number stays, in parentheses, after the description.
//
// Creatures: when an NPC is unarmed, pickNaturalAttackMode picks one of its
// natural attacks per swing (weighted). With NATURAL_ATTACKS_AFFECT_DAMAGE_TYPE
// on, that attack's damage type also drives the real combat rules (a bite is
// puncture, so it bleeds; claws are edge) - turn it off to keep every unarmed
// creature as plain blunt damage while still narrating bites and claws.
// A species can define its own `naturalAttacks` array on its SPECIES_TEMPLATES
// entry (same shape as the modes below) to override this table.
const NATURAL_ATTACKS_AFFECT_DAMAGE_TYPE = true;

const NATURAL_BITE = {
    label: "bite", noun: "bite", verbs: ["bite", "sink its teeth into", "clamp down on"],
    damageType: "puncture", weight: 7,
    miss: ["{A}'s jaws snap shut on empty air.", "You jerk away from {A}'s bite."],
    watchedMiss: ["{A}'s jaws snap shut on empty air as {D} twists aside.", "{D} jerks away from {A}'s bite."]
};
const NATURAL_CLAW = {
    label: "claw", noun: "claw swipe", verbs: ["claw", "rake", "scratch"],
    damageType: "edge", weight: 3,
    miss: ["{A}'s claws rake the air beside you.", "You twist clear of {A}'s claws."],
    watchedMiss: ["{A}'s claws rake the air where {D} stood.", "{D} twists clear of {A}'s claws."]
};

const NATURAL_ATTACK_PROFILES = {
    wolf: [NATURAL_BITE, Object.assign({}, NATURAL_CLAW, { verbs: ["claw", "rake", "maul"] })],
    dog: [NATURAL_BITE, NATURAL_CLAW],
    bear: [
        Object.assign({}, NATURAL_CLAW, { weight: 6, verbs: ["maul", "rake", "slash at"] }),
        Object.assign({}, NATURAL_BITE, { weight: 4 })
    ],
    boar: [{
        label: "gore", noun: "goring charge", verbs: ["gore", "slam its tusks into", "ram"],
        damageType: "puncture", weight: 1,
        miss: ["{A} charges past you, tusks missing by a hair.", "You throw yourself aside as {A} rushes by."],
        watchedMiss: ["{A} charges past {D}, tusks missing by a hair."]
    }],
    spider: [Object.assign({}, NATURAL_BITE, { weight: 1, verbs: ["bite", "sink its fangs into"] })],
    snake: [Object.assign({}, NATURAL_BITE, { weight: 1, verbs: ["bite", "sink its fangs into"] })],
    bat: [Object.assign({}, NATURAL_BITE, { weight: 6 }), Object.assign({}, NATURAL_CLAW, { weight: 4 })],
    rat: [
        Object.assign({}, NATURAL_BITE, { weight: 8, verbs: ["bite", "gnaw at", "sink its teeth into"] }),
        Object.assign({}, NATURAL_CLAW, { weight: 2, verbs: ["scratch", "claw"] })
    ],
    kobold: [Object.assign({}, NATURAL_CLAW, { weight: 6 }), Object.assign({}, NATURAL_BITE, { weight: 4 })],
    lizardfolk: [Object.assign({}, NATURAL_CLAW, { weight: 6 }), Object.assign({}, NATURAL_BITE, { weight: 4 })],
    wolfkin: [Object.assign({}, NATURAL_CLAW, { weight: 5 }), Object.assign({}, NATURAL_BITE, { weight: 5 })],
    catfolk: [Object.assign({}, NATURAL_CLAW, { weight: 7 }), Object.assign({}, NATURAL_BITE, { weight: 3 })],
    skeleton: [{
        label: "strike", noun: "strike", verbs: ["batter", "strike", "club"],
        damageType: "blunt", weight: 1,
        miss: ["{A}'s bony fist swings wide of you.", "You duck {A}'s clumsy swing."],
        watchedMiss: ["{A}'s bony fist swings wide of {D}."]
    }]
};

// Unknown creatures: pick a reasonable set from their surface type, and
// otherwise a plain strike - so a new species never needs an entry to work.
// Slimes come in colours: green (acid: venom that also eats items), purple (poison:
// venom that leaves items alone), blue (frost), grey (plain).
// There are no fire slimes. The colour is rolled at creation (anatomy.body.color).
const SLIME_VARIANTS = {
    green: { element: "", venom: true, acid: true, adj: "acidic" },
    purple: { element: "", venom: true, acid: false, adj: "toxic" },
    blue: { element: "frost", venom: false, adj: "frigid" },
    grey: { element: "", venom: false, adj: "sluggish" }
};
function isSlimeEntity(entity) {
    return !!entity && String(entity.species || "").toLowerCase() === "slime";
}
function getSlimeVariant(entity) {
    if (!isSlimeEntity(entity)) return null;
    const color = String((entity.anatomy && entity.anatomy.body && entity.anatomy.body.color) || "grey").toLowerCase();
    if (SLIME_VARIANTS[color]) return SLIME_VARIANTS[color];
    // skin-tone phrases such as "emerald green" or "frost blue"
    if (/green/.test(color)) return SLIME_VARIANTS.green;
    if (/purple|violet/.test(color)) return SLIME_VARIANTS.purple;
    if (/blue|frost/.test(color)) return SLIME_VARIANTS.blue;
    return SLIME_VARIANTS.grey;
}
const NATURAL_SLIME_ENGULF = {
    label: "engulf", noun: "slimy lash", verbs: ["slam a wet pseudopod into", "lash", "smother"],
    damageType: "blunt", weight: 1,
    miss: ["{A} surges at you, a wet pseudopod slapping the floor beside you.", "You skip back as {A} slops toward you."],
    watchedMiss: ["{A} surges at {D}, a wet pseudopod slapping the ground."]
};
function getNaturalAttackProfiles(entity) {
    if (!entity) return null;
    if (isSlimeEntity(entity)) {
        const v = getSlimeVariant(entity);
        return [v && v.element ? Object.assign({}, NATURAL_SLIME_ENGULF, { element: v.element }) : NATURAL_SLIME_ENGULF];
    }
    const template = typeof getSpeciesTemplate === "function" ? getSpeciesTemplate(entity.species) : null;
    if (template && Array.isArray(template.naturalAttacks) && template.naturalAttacks.length) {
        return template.naturalAttacks;
    }

    const speciesKey = String(entity.species || "").toLowerCase();
    const keys = Object.keys(NATURAL_ATTACK_PROFILES);
    // Whole-word match, so "Dire Wolf" finds wolf but "Pirate" never finds rat.
    const matched = keys.find(key => speciesKey === key) ||
        keys.find(key => new RegExp("\\b" + key + "\\b").test(speciesKey));
    if (matched) return NATURAL_ATTACK_PROFILES[matched];

    // Unarmed people just use their fists (the default blunt narration).
    if (entity.isHumanoid !== false && (!template || template.isHumanoid)) return null;

    const surface = template && template.anatomyProfile ? String(template.anatomyProfile.surfaceType || "") : "";
    if (surface === "fur" || surface === "scales") return [NATURAL_BITE, NATURAL_CLAW];
    return [{
        label: "strike", noun: "strike", verbs: ["strike", "lash out at", "batter"],
        damageType: "blunt", weight: 1,
        miss: ["{A} lashes out and misses you.", "You evade {A}'s attack."]
    }];
}

// Only an unarmed non-player picks one; anyone holding a weapon fights with it.
function pickNaturalAttackMode(entity, weaponProfile) {
    if (!entity || entity === G.player) return null;
    // Ghosts have their own touch attack (see resolveNPCCounter's ghost branch).
    if (typeof isEntityIncorporeal === "function" && isEntityIncorporeal(entity)) return null;
    const weaponName = String((weaponProfile && weaponProfile.name) || "unarmed").toLowerCase();
    if (weaponName !== "unarmed") return null;

    const modes = getNaturalAttackProfiles(entity);
    if (!modes || !modes.length) return null;

    const total = modes.reduce((sum, mode) => sum + (typeof mode.weight === "number" ? mode.weight : 1), 0);
    let roll = Math.random() * total;
    for (let i = 0; i < modes.length; i++) {
        roll -= (typeof modes[i].weight === "number" ? modes[i].weight : 1);
        if (roll <= 0) return modes[i];
    }
    return modes[modes.length - 1];
}

// Base-form verbs per weapon type. Phrasal verbs ("sink its teeth into") are
// conjugated on the first word only.
const STRIKE_VERBS_BY_WEAPON = {
    sword: ["slash", "cut", "carve", "slice"],
    axe: ["hew", "chop", "cleave", "hack"],
    polearm: ["slash", "hew", "cut"],
    dagger: ["stab", "jab", "pierce", "nick"],
    spear: ["pierce", "stab", "skewer"],
    whip: ["lash", "flay"],
    mace: ["crush", "batter", "pound"],
    staff: ["crack", "whack", "bash"],
    flail: ["batter", "lash", "pound"],
    generic: ["bludgeon", "batter", "bash"],
    unarmed: ["punch", "pummel", "clout", "strike"]
};

const STRIKE_TAILS = {
    edge: {
        glancing: [", leaving a shallow graze", ", barely breaking the skin"],
        solid: [", cutting in", ", leaving a clean cut"],
        heavy: [", biting deep", ", opening a long wound"],
        brutal: [", cleaving deep into flesh", ", laying it open"]
    },
    puncture: {
        glancing: [", leaving a shallow nick", ", barely pricking the skin"],
        solid: [", breaking skin", ", going in"],
        heavy: [", driving in deep", ", going deep"],
        brutal: [", driving in savagely", ", tearing deep"]
    },
    blunt: {
        glancing: [", a glancing blow", ", landing awkwardly"],
        solid: [", leaving a welt", ", landing solidly"],
        heavy: [", a sickening crack ringing out", ", leaving a deep bruise"],
        brutal: [", a bone-jarring crunch echoing out", ", battering flesh and bone"]
    }
};

// -- BLOODLESS BODIES ---------------------------------------------------------
// Skeletons have no blood to lose: they never bleed, and nothing about them is
// described as cut, gashed or bleeding. Blows crack and chip bone instead
// ("bone"). Zombies, ghouls and revenants are dead flesh: no bleeding either,
// but torn rather than cracked ("deadflesh"). Anything can opt in with
// entity.bloodless = true (+ optional entity.bodyKind). Ghosts and the like are
// incorporeal and handled separately (see isEntityIncorporeal).
function getBodyKind(entity) {
    if (!entity || (typeof G !== "undefined" && G && entity === G.player)) return null;
    if (entity.bloodless === true) return entity.bodyKind || "bone";
    const species = typeof normalizeSpeciesName === "function" ? normalizeSpeciesName(entity.species) : String(entity.species || "").toLowerCase();
    if (species === "skeleton") return "bone";
    if (species === "zombie" || species === "ghoul" || species === "revenant") return "deadflesh";
    return null;
}

// Verbs that suit hitting bone: no cutting, carving, slicing or flaying.
const STRIKE_VERBS_BONE = {
    sword: ["strike", "hack", "chop", "hew"],
    dagger: ["jab", "strike"],
    spear: ["strike", "jab", "thrust at"],
    polearm: ["hew", "strike", "hack"],
    whip: ["strike", "crack"]
};

const STRIKE_TAILS_BONE = {
    edge: {
        glancing: [", scoring a pale line across the bone", ", skittering off the bone"],
        solid: [", chipping the bone", ", biting a notch from it"],
        heavy: [", splintering bone", ", hacking a deep notch into the bone"],
        brutal: [", shearing through brittle bone", ", sending bone shards spinning away"]
    },
    puncture: {
        glancing: [", scratching dry bone", ", finding only a hollow ring"],
        solid: [", cracking into bone", ", lodging with a dry crack"],
        heavy: [", punching through bone with a dry crack", ", splintering bone around the blow"],
        brutal: [", driving through bone in a spray of splinters", ", shattering what it strikes"]
    },
    blunt: {
        glancing: [", a dull knock against bone", ", glancing off with a hollow rap"],
        solid: [", bone cracking audibly", ", leaving a spidering crack"],
        heavy: [", a sharp crack ringing out", ", bone splintering under the blow"],
        brutal: [", bone shattering with a crunch", ", scattering bone fragments"]
    }
};
const STRIKE_TAILS_DEADFLESH = {
    edge: {
        glancing: [", barely marking the dry hide", ", scraping across leathery skin"],
        solid: [", slicing into dead, dry flesh", ", leaving a clean, dry cut"],
        heavy: [", opening a long, dry rent", ", tearing deep into dead flesh"],
        brutal: [", cleaving through dead flesh and rot", ", laying it open"]
    },
    puncture: {
        glancing: [", pricking dead skin", ", barely breaking the dry hide"],
        solid: [", going in with a dry rasp", ", sinking into dead flesh"],
        heavy: [", driving deep into dead flesh", ", going in to the hilt"],
        brutal: [", tearing through dead flesh", ", driving in savagely"]
    },
    blunt: {
        glancing: [", a glancing blow", ", landing awkwardly"],
        solid: [", a dull thud into dead flesh", ", landing solidly"],
        heavy: [", a sickening crack ringing out", ", caving in dead flesh"],
        brutal: [", a bone-jarring crunch echoing out", ", battering flesh and bone to pulp"]
    }
};
const STRIKE_CRACK_CLAUSES = {
    bone: ["Cracks spiderweb across the bone.", "A fresh crack runs along the bone.", "Dry splinters of bone fall away."],
    deadflesh: ["Dry flesh sloughs away from the wound.", "The wound gapes, dark and dry."]
};
const FINISH_BODY_LINES = {
    bone: {
        corpse: ["{D} comes apart in a clatter, bones scattering across the floor.", "{D} collapses into a heap of loose bones, the light gone from its sockets."],
        unconscious: ["{D} rattles, sags, and goes still, a motionless heap of bone.", "{D} folds in on itself with a clatter and does not move."]
    },
    deadflesh: {
        corpse: ["{D} jerks once, slumps, and finally lies still.", "{D} topples stiffly and does not rise."],
        unconscious: ["{D} sags and falls, unmoving.", "{D} crumples stiffly and goes still."]
    }
};
const LIMB_DISABLE_BODY_LINES = {
    bone: {
        head: ["{name}'s skull cracks, and it lurches, jaw hanging askew."],
        arms: ["{name}'s arm bones crack and dangle uselessly."],
        legs: ["{name}'s leg bones crack; it staggers, barely upright."],
        torso: ["{name}'s ribs cave in with a dry crack, and it lurches."]
    },
    deadflesh: {
        head: ["{name}'s head lolls, torn and dry, and it lurches blindly."],
        arms: ["{name}'s arm hangs by dry sinew, nearly useless."],
        legs: ["{name}'s leg gives way under the damage; it drags itself upright."],
        torso: ["{name} lurches, the damage to its torso slowing every movement."]
    }
};
const DISABLED_LIMB_STATES_BODY = {
    bone: {
        head: "is cracked open and lolling",
        arms: "dangle from cracked joints",
        legs: "are cracked and can barely hold it up",
        torso: "is cracked and caved in"
    },
    deadflesh: {
        head: "is torn and lolling",
        arms: "hang by dry sinew",
        legs: "are torn and barely hold it up",
        torso: "is torn open and dry"
    }
};
const WOUND_WORDS_BODY = {
    bone: { edge: "chipped", puncture: "pitted", blunt: "cracked", other: "damaged" },
    deadflesh: { edge: "torn", puncture: "torn", blunt: "crushed", other: "damaged" }
};

function getStrikeTails(c, damageClass) {
    if (c && c.defenderBody === "bone") return STRIKE_TAILS_BONE[damageClass];
    if (c && c.defenderBody === "deadflesh") return STRIKE_TAILS_DEADFLESH[damageClass];
    return STRIKE_TAILS[damageClass];
}

// The "Blood wells from the wound." sentence for a bleeding hit, or a crack /
// slough sentence for a bloodless body on a heavy blow.
function getStrikeAftermathClause(c, damageClass, tier) {
    if (c && c.defenderBody) {
        if (!(c.crit || tier === "heavy" || tier === "brutal")) return "";
        return rand(STRIKE_CRACK_CLAUSES[c.defenderBody] || []);
    }
    if (c && c.bled && STRIKE_BLEED_CLAUSES[damageClass]) return rand(STRIKE_BLEED_CLAUSES[damageClass]);
    return "";
}

const STRIKE_BLEED_CLAUSES = {
    edge: ["Blood wells from the wound.", "A gash opens, bleeding freely."],
    puncture: ["Blood wells from the wound.", "Blood runs from the puncture."]
};

const STRIKE_PLAYER_MISS_LINES = {
    edge: ["Your {w} cuts only air as {D} twists aside.", "{D} slips away from your {w}.", "You swing at {D} and miss."],
    puncture: ["Your {w} thrusts past {D}.", "{D} sidesteps your thrust."],
    blunt: ["Your {w} whistles past {D}.", "{D} ducks under your swing."],
    unarmed: ["Your blow goes wide of {D}.", "{D} slips your punch."]
};

const STRIKE_NPC_MISS_LINES = {
    edge: ["{A}'s blade cuts only air.", "You twist away from {A}'s slash."],
    puncture: ["{A}'s thrust goes past you.", "You sidestep {A}'s thrust."],
    blunt: ["{A}'s swing whistles past you.", "You duck {A}'s blow."],
    unarmed: ["{A}'s blow goes wide of you.", "You slip {A}'s punch."]
};

function conjugateStrikeVerb(verb) {
    const parts = String(verb).split(" ");
    const first = parts[0];
    let third;
    if (/(s|x|z|ch|sh)$/.test(first)) third = first + "es";
    else if (/[^aeiou]y$/.test(first)) third = first.slice(0, -1) + "ies";
    else third = first + "s";
    parts[0] = third;
    return parts.join(" ");
}

function getStrikePartWord(targetKey) {
    return { torso: "torso", head: "head", arms: "arm", legs: "leg" }[targetKey] || "torso";
}

function getStrikeDamageTier(damage, hpMax, crit) {
    const ratio = damage / Math.max(1, hpMax || 1);
    let tier = ratio < 0.15 ? "glancing" : ratio < 0.3 ? "solid" : ratio < 0.5 ? "heavy" : "brutal";
    if (crit && (tier === "glancing" || tier === "solid")) tier = "heavy";
    return tier;
}

function getStrikeDamageClass(damageType) {
    return (damageType === "edge" || damageType === "puncture") ? damageType : "blunt";
}

function fillStrikeTemplate(template, vars) {
    return String(template)
        .replace(/\{A\}/g, vars.A || "")
        .replace(/\{D\}/g, vars.D || "")
        .replace(/\{w\}/g, vars.w || "weapon");
}

// c: { attackerName, attackerIsPlayer, defenderName, defenderIsPlayer, weapon,
//      naturalMode, damageType, targetKey, damage, blocked, hpMax, crit, bled }
function getStrikeVerbList(c) {
    if (c.naturalMode && c.naturalMode.verbs) return c.naturalMode.verbs;
    if (c.defenderBody === "bone" && c.weapon && STRIKE_VERBS_BONE[c.weapon.type]) {
        const wn = String(c.weapon.name || "unarmed").toLowerCase();
        if (wn !== "unarmed") return STRIKE_VERBS_BONE[c.weapon.type];
    }
    const weaponName = String((c.weapon && c.weapon.name) || "unarmed").toLowerCase();
    if (weaponName === "unarmed") return STRIKE_VERBS_BY_WEAPON.unarmed;
    return STRIKE_VERBS_BY_WEAPON[c.weapon && c.weapon.type] || STRIKE_VERBS_BY_WEAPON.generic;
}

// Attach attribution at the action's source, never by guessing from prose.
// These stay plain text so names use the same safe typewriter as narration.
function getCombatActionLabel(entity) {
    if (entity && entity === G.player) return "Player";
    const label = typeof entity === "string" ? entity
        : entity && (entity.name || entity.displayName || entity.type);
    return String(label || "Unknown").replace(/\s+/g, " ").trim();
}

function formatCombatActionLine(actor, target, text) {
    const line = String(text || "");
    if (!line.trim() || /^\[[^\]]+\]/.test(line.trim())) return line;
    const prefix = `(${getCombatActionLabel(actor)}) → (${getCombatActionLabel(target)}) `;
    return line.startsWith(prefix) ? line : prefix + line;
}

function formatCombatStrikeLine(context, text) {
    return formatCombatActionLine(
        context.attackerIsPlayer ? "Player" : context.attackerName,
        context.defenderIsPlayer ? "Player" : context.defenderName,
        text
    );
}

function buildStrikeHitLine(c) {
    const damageClass = getStrikeDamageClass(c.damageType);
    const tier = getStrikeDamageTier(c.damage, c.hpMax, c.crit);
    const part = getStrikePartWord(c.targetKey);
    const verb = rand(getStrikeVerbList(c));
    const defPart = c.defenderIsPlayer ? `your ${part}` : `${c.defenderName}'s ${part}`;
    const weaponName = String((c.weapon && c.weapon.name) || "unarmed").toLowerCase();
    const armed = !c.naturalMode && weaponName !== "unarmed";

    let base;
    if (c.attackerIsPlayer) {
        base = armed
            ? rand([`Your ${weaponName} ${conjugateStrikeVerb(verb)} ${defPart}`, `You ${verb} ${defPart} with your ${weaponName}`])
            : `You ${verb} ${defPart}`;
    } else if (armed) {
        base = `${c.attackerName} ${conjugateStrikeVerb(verb)} ${defPart} with ${withIndefiniteArticle(weaponName)}`;
    } else {
        base = `${c.attackerName} ${conjugateStrikeVerb(verb)} ${defPart}`;
    }

    const physicalAction = c.attackerIsPlayer && !armed && /^(push|shove)$/.test(c.physicalAction || "") ? c.physicalAction : "";
    if (physicalAction) base = `You ${physicalAction} ${c.defenderName} hard`;
    const tail = physicalAction ? "" : rand(getStrikeTails(c, damageClass)[tier]);
    const hpDamage = Number.isFinite(c.hpLost) ? c.hpLost : c.damage;
    const hpChange = c.defenderIsPlayer && Number.isFinite(c.hpBefore) && Number.isFinite(c.hpAfter)
        ? `; HP ${c.hpBefore} → ${c.hpAfter}` : "";
    const numberText = `(${hpDamage} damage${hpChange}${c.blocked > 0 ? `; ${c.blocked} absorbed by gear` : ""})`;
    let line = `${base}${tail} ${numberText}${c.crit ? "!" : "."}`;
    const aftermath = getStrikeAftermathClause(c, damageClass, tier);
    if (aftermath) line += ` ${aftermath}`;
    return formatCombatStrikeLine(c, line);
}

function buildStrikeMissLine(c) {
    const damageClass = getStrikeDamageClass(c.damageType);
    const weaponName = String((c.weapon && c.weapon.name) || "unarmed").toLowerCase();
    const unarmed = !c.naturalMode && weaponName === "unarmed";
    const vars = { A: c.attackerName, D: c.defenderName, w: weaponName };

    if (c.attackerIsPlayer && unarmed && /^(push|shove)$/.test(c.physicalAction || "")) {
        return formatCombatStrikeLine(c, `You try to ${c.physicalAction} ${c.defenderName}, but fail to connect.`);
    }

    if (c.attackerIsPlayer) {
        const pool = STRIKE_PLAYER_MISS_LINES[unarmed ? "unarmed" : damageClass];
        return formatCombatStrikeLine(c, fillStrikeTemplate(rand(pool), vars));
    }
    if (c.naturalMode && Array.isArray(c.naturalMode.miss) && c.naturalMode.miss.length) {
        return formatCombatStrikeLine(c, fillStrikeTemplate(rand(c.naturalMode.miss), vars));
    }
    const pool = STRIKE_NPC_MISS_LINES[unarmed ? "unarmed" : damageClass];
    return formatCombatStrikeLine(c, fillStrikeTemplate(rand(pool), vars));
}

// Only edge weapons sever (see applyCombatDamage); a short extra beat for it.
function buildStrikeSeverLine(c) {
    const part = getStrikePartWord(c.targetKey);
    const defPart = c.defenderIsPlayer ? `your ${part}` : `${c.defenderName}'s ${part}`;
    if (c.defenderBody === "bone") return `The blow shatters through ${defPart}, knocking it clean away!`;
    if (c.defenderBody === "deadflesh") return `The blow cleaves clean through ${defPart}, and it falls away!`;
    return `The blow cleaves clean through ${defPart}, severing it!`;
}

// -- Finishing blows ----------------------------------------------------------
// The hit that ends a fight: the normal strike description (forced to a
// heavy-or-better tier, with the damage figure in a player-facing fight) plus
// a sentence for what that blow did - dead or senseless for an NPC, or
// the player going under. Chosen by weapon damage class and whether the blow
// landed on the head. {D} is the defender's name.
const FINISH_NPC_LINES = {
    corpse: {
        edge: {
            head: ["{D} drops without a sound, dead before hitting the ground.", "The light goes out of {D}'s eyes and they fall, lifeless."],
            body: ["{D} staggers, blood pouring from the wound, then crumples, lifeless.", "{D} sways, a deep wound spilling blood, and falls dead."]
        },
        puncture: {
            head: ["{D} stiffens, then slides to the ground, dead.", "{D} goes rigid and drops, the life gone from them."],
            body: ["{D} stiffens, gasps once, and goes still.", "{D} sags around the wound and the life drains out of them."]
        },
        blunt: {
            head: ["Bone gives way with a wet crunch and {D} drops dead.", "{D}'s skull gives way and they fall lifeless."],
            body: ["{D}'s ribs cave in and they topple, never to rise.", "The blow drives the life out of {D}, who crumples dead."]
        }
    },
    unconscious: {
        edge: {
            head: ["{D} reels, pale and gasping, and collapses unconscious.", "{D}'s eyes roll back and they drop, out cold."],
            body: ["{D} staggers, the fight draining out of them, and slumps senseless.", "{D} sways, then collapses unconscious from the wound."]
        },
        puncture: {
            head: ["{D} jerks, eyes rolling back, and drops senseless.", "{D} reels and collapses, out cold."],
            body: ["{D} sags around the wound and slumps unconscious.", "{D} gasps, folds, and collapses senseless."]
        },
        blunt: {
            head: ["{D}'s eyes roll back and they drop senseless.", "{D} goes slack mid-stagger and hits the ground out cold."],
            body: ["The breath leaves {D} in a rush and they fold, out cold.", "{D} doubles over, then collapses, senseless."]
        }
    }
};

const FINISH_PLAYER_LINES = {
    edge: {
        head: ["Blood floods your vision and your legs give out."],
        body: ["Your legs give out as blood loss and pain overwhelm you."]
    },
    puncture: {
        head: ["Your vision tunnels and your legs fold beneath you."],
        body: ["Pain floods you as the strength drains out of your legs."]
    },
    blunt: {
        head: ["Your skull rings like a bell and the world goes white."],
        body: ["The breath is driven from your lungs and your legs fold beneath you."]
    }
};

// c: a hit context (see buildStrikeHitLine); outcome: "corpse" |
// "unconscious" for an NPC defender, ignored when c.defenderIsPlayer.
// c.watched selects the third-person, number-free strike wording.
function buildFinishingBlowLine(c, outcome) {
    const damageClass = getStrikeDamageClass(c.damageType);
    const zone = c.targetKey === "head" ? "head" : "body";
    const strikeCtx = Object.assign({}, c, { crit: true, bled: false });
    const strike = c.watched ? buildWatchedStrikeHitLine(strikeCtx) : buildStrikeHitLine(strikeCtx);

    const bodyFinish = !c.defenderIsPlayer && c.defenderBody ? FINISH_BODY_LINES[c.defenderBody] : null;
    const pool = c.defenderIsPlayer
        ? FINISH_PLAYER_LINES[damageClass][zone]
        : bodyFinish
        ? bodyFinish[outcome === "corpse" ? "corpse" : "unconscious"]
        : FINISH_NPC_LINES[outcome === "corpse" ? "corpse" : "unconscious"][damageClass][zone];
    return `${strike} ${fillStrikeTemplate(rand(pool), { D: c.defenderName })}`;
}

// -- Third-person versions, for fights the player is only watching (see
// reinforcementOpeningStrike's options.watched / resolveSkirmishRound): same
// weapon verbs, natural attacks, blow-size tails and bleed clauses as above,
// but no damage figures and no body part (those strikes always land on the
// torso mechanically, so the text just names the target).
const STRIKE_WATCHED_MISS_LINES = {
    edge: ["{A} swings at {D} but the blade finds only air.", "{D} twists clear of {A}'s slash."],
    puncture: ["{A}'s thrust goes wide of {D}.", "{D} sidesteps {A}'s thrust."],
    blunt: ["{A}'s swing whistles past {D}.", "{D} ducks under {A}'s blow."],
    unarmed: ["{A}'s blow goes wide of {D}.", "{D} slips {A}'s punch."],
    natural: ["{A} lunges at {D} but misses.", "{D} twists clear of {A}."]
};

function buildWatchedStrikeHitLine(c) {
    const damageClass = getStrikeDamageClass(c.damageType);
    const tier = getStrikeDamageTier(c.damage, c.hpMax, c.crit);
    const verb = rand(getStrikeVerbList(c));
    const weaponName = String((c.weapon && c.weapon.name) || "unarmed").toLowerCase();
    const armed = !c.naturalMode && weaponName !== "unarmed";

    const base = armed
        ? `${c.attackerName} ${conjugateStrikeVerb(verb)} ${c.defenderName} with ${withIndefiniteArticle(weaponName)}`
        : `${c.attackerName} ${conjugateStrikeVerb(verb)} ${c.defenderName}`;
    let line = `${base}${rand(getStrikeTails(c, damageClass)[tier])}${c.crit ? "!" : "."}`;
    const aftermath = getStrikeAftermathClause(c, damageClass, tier);
    if (aftermath) line += ` ${aftermath}`;
    return formatCombatStrikeLine(c, line);
}

function buildWatchedStrikeMissLine(c) {
    const damageClass = getStrikeDamageClass(c.damageType);
    const weaponName = String((c.weapon && c.weapon.name) || "unarmed").toLowerCase();
    const vars = { A: c.attackerName, D: c.defenderName, w: weaponName };

    if (c.naturalMode) {
        const pool = Array.isArray(c.naturalMode.watchedMiss) && c.naturalMode.watchedMiss.length
            ? c.naturalMode.watchedMiss
            : STRIKE_WATCHED_MISS_LINES.natural;
        return formatCombatStrikeLine(c, fillStrikeTemplate(rand(pool), vars));
    }
    const pool = STRIKE_WATCHED_MISS_LINES[weaponName === "unarmed" ? "unarmed" : damageClass];
    return formatCombatStrikeLine(c, fillStrikeTemplate(rand(pool), vars));
}

// What a natural attack looks like as the NPC's opening "plan" line.
function buildNaturalPlanLine(npcName, styleKey, mode) {
    const noun = mode.noun || mode.label || "attack";
    if (styleKey === "light") return `${npcName} snaps back with a quick ${noun}.`;
    if (styleKey === "heavy") return `${npcName} lunges with a heavy ${noun}.`;
    return `${npcName} attacks with a ${noun}.`;
}

function getUnarmedInteractionProfile() {
    return getEntityWeaponProfile(null, { unarmed: true });
}

function getEntityWeaponProfile(entity, options) {
    const unarmed = !!(options && options.unarmed);
    const weaponItem = unarmed ? null : getEntityWeaponItem(entity);
    const weaponName = (unarmed ? "unarmed" : getEntityWeaponName(entity)).toLowerCase();
    const weaponType = String((weaponItem && weaponItem.weaponType) || getWeaponTypeFromName(weaponName, "generic")).toLowerCase();

    let damageDie = !!weaponItem && typeof weaponItem.damage === "number" ? Math.max(2, weaponItem.damage) : 4;
    if (!(!!weaponItem && typeof weaponItem.damage === "number")) {
        if (weaponName.includes("dagger")) damageDie = 4;
        else if (weaponName.includes("staff")) damageDie = 5;
        else if (weaponName.includes("mace")) damageDie = 6;
        else if (weaponName.includes("sword")) damageDie = 6;
        else if (weaponName.includes("axe")) damageDie = 8;
        else if (weaponName.includes("hammer") || weaponName.includes("maul")) damageDie = 8;
        else if (weaponName.includes("spear")) damageDie = 6;
    }

    let hitBonus = 0;
    let damageBonus = 0;
    // A broken weapon (see FORGE SERVICES) barely works until it is mended.
    if (weaponItem && weaponItem.broken === true) {
        return {
            item: weaponItem,
            name: unarmed ? "unarmed" : getEntityWeaponName(entity),
            type: weaponType,
            damageDie: 2,
            hitBonus: -2,
            damageBonus: 0,
            elementalType: null,
            broken: true
        };
    }
    if (weaponType === "dagger") hitBonus += 1;
    if (weaponType === "sword" || weaponType === "spear" || weaponType === "polearm") hitBonus += 1;
    if (weaponType === "axe" || weaponType === "mace" || weaponType === "flail") damageBonus += 1;

    if (!!weaponItem && typeof weaponItem.quality === "number") {
        hitBonus += Math.max(-1, Math.min(1, weaponItem.quality));
    }

    // Forge edge (see FORGE SERVICES): honed/coated blades fight a little
    // better until edgeHits runs out (spent in attackNPC, per landed hit).
    if (weaponItem && weaponItem.edgeHits > 0) {
        damageBonus += weaponItem.edgeBonus || 0;
        hitBonus += weaponItem.edgeHitBonus || 0;
    }

    // Enchanter service bonuses (see ENCHANTER SERVICES) - enchantDamageBonus
    // from a "increase total damage" success, elementalDamage.amount from an
    // "add elemental damage" success. Both just add flat damage; the
    // elemental one also carries a flavor type for the item's display name
    // (see renameEnchantedItem) but there's no resistance/weakness system
    // behind it yet - it's damage same as any other.
    let elementalType = null;
    if (!!weaponItem && typeof weaponItem.enchantDamageBonus === "number") {
        damageBonus += weaponItem.enchantDamageBonus;
    }
    if (weaponItem && weaponItem.elementalDamage && typeof weaponItem.elementalDamage.amount === "number") {
        damageBonus += weaponItem.elementalDamage.amount;
        elementalType = weaponItem.elementalDamage.type || null;
    }
    // Bless Weapon / Enchanting: a temporary buff adds damage and converts ALL
    // of the weapon's damage to its element (the weapon stays blunt or edged).
    if (weaponItem && weaponItem.buff && weaponItem.buff.kind === "weapon") {
        damageBonus += weaponItem.buff.bonus || 0;
        elementalType = weaponItem.buff.element || elementalType;
    }

    return {
        item: weaponItem,
        name: unarmed ? "unarmed" : getEntityWeaponName(entity),
        type: weaponType,
        damageDie,
        hitBonus,
        damageBonus,
        elementalType
    };
}

function getWeaponDamageDie(entity) {
    const weaponName = getEntityWeaponName(entity).toLowerCase();
    if (weaponName.includes("dagger")) return 4;
    if (weaponName.includes("staff")) return 5;
    if (weaponName.includes("mace")) return 6;
    if (weaponName.includes("sword")) return 6;
    return getEntityWeaponProfile(entity).damageDie;
}

function getEquippedArmorTotal(entity) {
    if (!entity || !entity.equipped) return 0;
    return ["head", "upper", "hands", "lower", "feet"].reduce((sum, slot) => {
        return sum + getItemArmorValue(entity.equipped[slot]);
    }, 0);
}

function getTargetArmorClassBonus(entity, targetKey = "torso") {
    const eq = (entity && entity.equipped) || {};
    const headArmor = getItemArmorValue(eq.head);
    const upperArmor = getItemArmorValue(eq.upper);
    const handsArmor = getItemArmorValue(eq.hands);
    const lowerArmor = getItemArmorValue(eq.lower);
    const feetArmor = getItemArmorValue(eq.feet);

    if (targetKey === "head") return Math.min(2, headArmor);
    if (targetKey === "torso") return Math.min(3, Math.ceil(upperArmor / 2));
    if (targetKey === "arms") return Math.min(2, Math.floor((upperArmor + handsArmor) / 3));
    if (targetKey === "legs") return Math.min(2, Math.floor((lowerArmor + feetArmor) / 3));
    return 0;
}

function getEquipmentDodgeBonus(entity) {
    const eq = (entity && entity.equipped) || {};
    return ["upper", "lower", "feet", "head"].reduce((sum, slot) => {
        const item = eq[slot];
        if (!item || Array.isArray(item)) return sum;
        let next = sum;
        if (typeof item.dodgeBonus === "number") next += item.dodgeBonus;
        if (item.enchantment === "elusion") next += 2;
        return next;
    }, 0);
}

function getEntityArmorClass(entity, targetKey = "torso") {
    if (!entity) return 10;

    const totalArmor = getEquippedArmorTotal(entity);
    let armorClass = typeof entity.armor === "number" ? entity.armor : 10;

    if (totalArmor > 0) {
        armorClass = 10 + Math.min(6, Math.floor(totalArmor / 2));
    }

    const sizeForArmor = (typeof G !== "undefined" && G && entity === G.player) ? getPlayerSpeciesSize() : entity.size;
    if (sizeForArmor === "small") armorClass += 1;
    if (sizeForArmor === "large") armorClass -= 1;
    if (typeof G !== "undefined" && G && entity === G.player) {
        if (sizeForArmor === "tiny") armorClass += 2;
        armorClass += getPlayerSpeciesTrait("armorBonus", 0);
    }

    armorClass += getTargetArmorClassBonus(entity, targetKey);
    armorClass += getEquipmentDodgeBonus(entity);
    if (entity.sundered && entity.sundered.amount > 0) {
        if (getStatusClock() > entity.sundered.untilTurn) entity.sundered = null;
        else armorClass -= entity.sundered.amount;
    }

    return Math.max(5, armorClass);
}

function getTargetDamageReduction(entity, targetKey = "torso", damageTypes = "physical") {
    const eq = (entity && entity.equipped) || {};
    const types = (Array.isArray(damageTypes) ? damageTypes : [damageTypes]).slice();
    if (types.indexOf("frost") >= 0 && types.indexOf("ice") < 0) types.push("ice");
    if (types.indexOf("ice") >= 0 && types.indexOf("frost") < 0) types.push("frost");
    const slotsByTarget = {
        head: ["head"],
        torso: ["upper"],
        arms: ["upper", "hands"],
        legs: ["lower", "feet"]
    };
    const slots = slotsByTarget[targetKey] || ["upper"];

    let reduction = 0;
    slots.forEach(slot => {
        const item = eq[slot];
        if (!item || Array.isArray(item)) return;

        if (types.includes("physical")) {
            reduction += getItemArmorValue(item);
        }
    });

    const scaled = targetKey === "head"
        ? Math.ceil(reduction / 2)
        : targetKey === "torso"
            ? Math.ceil(reduction / 3)
            : Math.floor(reduction / 4);

    // Element resistance is flat (see getElementResistance), not scaled by body part.
    let elemental = 0;
    types.forEach(function (t) {
        if (t === "physical" || t === "ice") return;
        const r = getElementResistance(entity, t);
        if (r > elemental || (elemental === 0 && r < 0)) elemental = r;
    });

    return Math.max(0, Math.min(5, scaled)) + elemental;
}

function getCombatTargetOptions(npc) {
    hydrateNPCSpeciesFlags(npc);
    if (npc && npc.isHumanoid === false) {
        return ["torso", "head"];
    }
    return ["torso", "head", "arms", "legs"];
}

function createCombatButton(label, onClick, options = {}) {
    const btn = document.createElement("button");
    btn.className = `chat-option-btn combat-option-btn${options.className ? " " + options.className : ""}`;
    btn.textContent = label;
    btn.disabled = options.disabled === true;
    if (options.title) btn.title = options.title;
    btn.onclick = onClick;
    return btn;
}

function appendCombatGroup(el, title, buttons) {
    if (!el.children.length && el.classList) el.classList.remove("text-combat-menu");
    const group = document.createElement("div");
    group.className = "combat-action-group";

    const heading = document.createElement("div");
    heading.className = "combat-action-heading";
    heading.textContent = title;
    group.appendChild(heading);

    buttons.forEach(btn => group.appendChild(btn));
    el.appendChild(group);
}

// Shared semantic combat actions. The menu and command adapters consume these
// definitions directly; the command parser never clicks or scrapes UI buttons.
function combatActionDescriptor(label, run, options = {}) {
    const name = String(label).replace(/\s*\([^)]*\)\s*$/, "").trim();
    return {
        id: options.id || name.toLowerCase(), primary: options.primary || name.toLowerCase(), name: name, label: label, run: run,
        disabled: options.disabled === true, title: options.title || "",
        className: options.className || "", targets: options.targets || null, aliases: options.aliases || []
    };
}

function createCombatActionButton(action) {
    return createCombatButton(action.label, action.run, { disabled: action.disabled, title: action.title, className: action.className });
}

function getCombatHealTargetActions(power, npc) {
    return [G.player].concat(getHealableAllies()).map(function (entity) {
        const self = entity === G.player;
        const hurt = entityNeedsHealing(entity);
        const label = self ? "Yourself" : entity.name || "Ally";
        return combatActionDescriptor(label + (hurt ? " (" + entity.hp + "/" + entity.hpMax + ")" : " (unhurt)"), function () { useDeityPower(power.id, npc, self ? null : entity); }, {
            id: self ? "self" : encEntityKey(entity), disabled: !hurt && !power.heal.fullStamina, title: hurt ? power.summary : "No need."
        });
    });
}


function getCombatActionGroups(npc) {
    if (!npc) return [];
    const groups = [];
    function addGroup(name, actions) {
        actions.forEach(function (action) { action.group = name; action.id = name + ":" + action.id; });
        groups.push({ name: name, actions: actions });
    }
    addGroup("Attack", [
        combatActionDescriptor("Light strike", () => renderCombatTargetMenu(npc, "light"), { title: COMBAT_ATTACK_STYLES.light.tip }),
        combatActionDescriptor("Balanced strike", () => renderCombatTargetMenu(npc, "balanced"), { title: COMBAT_ATTACK_STYLES.balanced.tip }),
        combatActionDescriptor("Heavy strike", () => renderCombatTargetMenu(npc, "heavy"), { title: COMBAT_ATTACK_STYLES.heavy.tip }),
        combatActionDescriptor("Precise strike", () => renderCombatTargetMenu(npc, "precise"), { title: COMBAT_ATTACK_STYLES.precise.tip })
    ]);

    // Wizards: cast from the spellbook (see WIZARD_SPELLS / castSpellAtNPC).
    if (playerIsSpellcaster(G.player)) {
        const known = getCastableSpellIds(G.player);
        const spellButtons = known.map(id => {
            const spell = WIZARD_SPELLS[id];
            const cost = getEffectiveSpellManaCost(G.player, spell);
            const enough = G.player.mana >= cost;
            return combatActionDescriptor(`${spell.name} (${cost} mana)`, () => castSpellAtNPC(npc, id), {
                disabled: !enough,
                title: enough ? spell.summary : `Not enough mana (${cost} needed).`
            });
        });
        if (!spellButtons.length) {
            spellButtons.push(combatActionDescriptor(
                getUnlearnedBookSpellIds(G.player).length ? "Study your spellbook to learn a spell" : (getPlayerSpellbooks(G.player).length ? "No spells copied yet" : "You have no spellbook"),
                () => {}, { disabled: true }
            ));
        }
        addGroup("Spells", spellButtons);
    }
    const enchantButtons = getEnchantCombatActions(npc);
    if (enchantButtons.length) addGroup("Enchanting", enchantButtons);

    // Clerics: the patron deity's gifts (see DEITY_POWERS).
    if (playerHasDeityPowers(G.player)) {
        const deity = getDeityArchetype(G.player.deity);
        const powerButtons = getUsablePowers(G.player).map(power => {
            const cost = getDeityPowerManaCost(G.player, power);
            const block = getDeityPowerBlockReason(G.player, power);
            const enough = !!power.granted || G.player.mana >= cost;
            return combatActionDescriptor(`${power.name} (${getPowerCostLabel(G.player, power)})`, () => activateDeityPower(power, npc), {
                disabled: !!block || !enough || power.use === "body" || power.use === "world",
                targets: power.heal && power.heal.ally && getHealableAllies().length ? function () { return getCombatHealTargetActions(power, npc); } : null,
                title: block || (power.use === "body" ? "Used from a body's own menu. " + power.summary : (power.use === "world" ? "Not in the middle of a fight. " + power.summary : (enough ? power.summary : `Not enough mana (${cost} needed).`)))
            });
        });
        addGroup(deity ? deity.name + "'s gifts" : "Powers", powerButtons);
    }

    // Techniques the player devised (see SYNERGIES).
    const techniqueButtons = getSynergyCombatActions(npc);
    if (techniqueButtons.length) addGroup("Techniques", techniqueButtons);

    // Rogues: a sneak attack on someone helpless, or from hiding.
    if (getRogueRank(G.player) >= ROGUE_BACKSTAB_MIN_RANK) {
        const sneakBlock = getBackstabBlockReason(npc);
        const rogueButtons = [];
        if (playerHasTechnique(G.player, "backstab")) {
            rogueButtons.push(combatActionDescriptor(`Sneak attack (${COMBAT_ATTACK_STYLES.light.staminaCost + ROGUE_BACKSTAB_STAMINA} stamina)`, () => attemptBackstab(npc), {
                disabled: !!sneakBlock,
                title: sneakBlock || "A precise strike at a vital spot, with bonus to hit and damage."
            }));
        }
        getRogueTechniqueActions(npc).forEach(function (b) { rogueButtons.push(b); });
        if (rogueButtons.length) addGroup("Rogue", rogueButtons);
    }

    // Fighters: maneuvers and a second wind.
    if (getFighterRank(G.player) >= 1) {
        const fighterButtons = Object.keys(FIGHTER_MANEUVERS).concat(Object.keys(FIGHTER_EXTRA_MANEUVERS)).filter(function (k) {
            return playerHasTechnique(G.player, k);
        }).map(function (k) {
            const m = getFighterManeuverDef(k);
            const block = getManeuverBlockReason(k, npc);
            return combatActionDescriptor(`${m.label} (${m.stamina + (COMBAT_ATTACK_STYLES[m.style] ? COMBAT_ATTACK_STYLES[m.style].staminaCost : 0)} stamina)`, () => attemptManeuver(npc, k), {
                disabled: !!block, title: block || m.tip
            });
        });
        Object.keys(FIGHTER_STANCES).filter(function (k) { return playerHasTechnique(G.player, k); }).forEach(function (k) {
            const s = FIGHTER_STANCES[k];
            const block = getStanceBlockReason(k);
            fighterButtons.push(combatActionDescriptor(`${s.label} (${s.stamina} stamina)`, () => useFighterStance(npc, k), { disabled: !!block, title: block || s.tip }));
        });
        const windBlock = getSecondWindBlockReason();
        fighterButtons.push(combatActionDescriptor("Second wind", () => useSecondWind(npc), {
            disabled: !!windBlock, title: windBlock || "Catch your breath: recover stamina and a little HP, at the cost of a turn."
        }));
        addGroup("Fighter", fighterButtons);
    }

    addGroup("Defense", [
        combatActionDescriptor("Defend", () => performCombatDefense(npc, "defend"), { title: COMBAT_STANCES.defend.tip }),
        combatActionDescriptor("Guard", () => performCombatDefense(npc, "guard"), { title: canHoldCombatStance("guard") ? COMBAT_STANCES.guard.tip : "You are too winded to hold Guard. Try Defend.", disabled: !canHoldCombatStance("guard") }),
        combatActionDescriptor("Counter", () => performCombatDefense(npc, "counter"), { title: canHoldCombatStance("counter") ? COMBAT_STANCES.counter.tip : "You are too winded to hold Counter. Try Defend.", disabled: !canHoldCombatStance("counter") }),
        combatActionDescriptor("Escape", () => attemptCombatEscape(npc), { title: "Break away from the fight (a flexibility contest - their hostility and wounded legs count against them). A failed escape gives them a free swing." })
    ]);

    addGroup("Other", [
        combatActionDescriptor("Talk them down", () => attemptTalkDown(npc), { disabled: !canConverseWithNPC(npc), title: "Try to end the fight with words: a Charisma check - success calms them and drops their hostility." }),
        ...(getGhostVice(npc) ? [combatActionDescriptor(getGhostVice(npc).lure.label, () => playOnGhostVice(npc), { title: "Play on the ghost's " + getGhostVice(npc).label })] : []),
        combatActionDescriptor("Bandage wounds", () => bandageInCombat(npc), {
            disabled: getTotalBleed(G.player) <= 0 || !findBandageInInventory(),
            title: getTotalBleed(G.player) <= 0 ? "You have no bleeding wounds to bandage." : !findBandageInInventory() ? "You have no bandages." : "Bind your bleeding wounds with a bandage - stops the bleed, costs the turn."
        }),
        combatActionDescriptor("Step back", () => renderNPCActionMenu(npc), { title: "Drop out of the fight stance and back to their action menu - the fight is still live." })
    ]);


    return groups;
}

function renderCombatActionMenu(npc) {
    const el = document.getElementById("chatOptionsEl");
    if (!el || !npc) return;

    // Rising Shadow turned a blow and hid the player: the fight is over for now.
    if (G.player && G.player._relicDisengage) {
        G.player._relicDisengage = false;
        G.activeNPCMode = "menu";
        if (typeof renderNPCActionMenu === "function") renderNPCActionMenu(npc);
        return;
    }

    // Any unbound surrendered follower runs the moment a fight starts
    // (fleeUnboundCaptives) — combat is their best and most reliable opening.
    fleeUnboundCaptives();
    dropCarriedBodyForCombat();

    G.activeNPCMode = "combat";
    el.innerHTML = "";
    // Portrait of whoever the fight is currently against (follows the target
    // as the focus moves between opponents).
    if (typeof renderNPCPortrait === "function") renderNPCPortrait(npc);

    // Combat can start without the player picking an NPC (room ambush, guard
    // challenge, NPC-initiated attack), so nothing else has hidden the
    // direction pad yet. Hide it here so the player can't walk out mid-fight.
    setExitGridVisible(false);

    // Party fights: turn order and a target picker (see COMBAT ENCOUNTERS).
    if (typeof appendEncounterStatus === "function") appendEncounterStatus(el, npc);

    getCombatActionGroups(npc).forEach(function (group) {
        appendCombatGroup(el, group.name, group.actions.map(createCombatActionButton));
    });
    const textButton = createCombatButton("Text mode", function () { setTextMode(true); }, { className: "combat-text-toggle", title: "Type combat commands" });
    textButton.id = "combatTextModeBtn";
    el.appendChild(textButton);
    el.classList.add("text-combat-menu");

    // Touch screens have no hover for the tooltips above: the little "?"
    // opens them in a closable window instead (CSS hides it on
    // hover-capable devices).
    appendCombatHelpButton(el);
}

function renderCombatTargetMenu(npc, styleKey) {
    const el = document.getElementById("chatOptionsEl");
    if (!el || !npc) return;

    const style = COMBAT_ATTACK_STYLES[styleKey] || COMBAT_ATTACK_STYLES.balanced;
    el.innerHTML = "";

    const buttons = getCombatTargetOptions(npc).map(targetKey => {
        const target = COMBAT_TARGETS[targetKey];
        return createCombatButton(
            `${style.label}: ${target.label}`,
            () => attackNPC(npc, { style: styleKey, target: targetKey }),
            { title: (style.tip ? style.tip + "\n" : "") + (target.tip || "") }
        );
    });

    buttons.push(createCombatButton("Back", () => renderCombatActionMenu(npc)));
    appendCombatGroup(el, "Target", buttons);
    appendCombatHelpButton(el);
}

// -- COMBAT ACTION HELP (mobile "?" button) --------------------------------
// Every combat action button carries its explanation as a hover tooltip
// (button title), but touch screens have no hover: the little "?" button in
// the action menu - hidden on hover-capable devices by CSS - opens this
// window instead. It lists the tooltips of the buttons currently on screen,
// so spells, powers and maneuvers explain themselves here too. The backdrop
// and the Close button dismiss it.
function closeCombatHelpWindow() {
    const modal = document.getElementById("combatHelpModal");
    if (modal) modal.classList.remove("active");
    refreshRoomViewAfterClose();
}

function showCombatHelpWindow() {
    const modal = document.getElementById("combatHelpModal");
    const entriesEl = document.getElementById("combatHelpEntriesEl");
    if (!modal || !entriesEl) return;
    entriesEl.innerHTML = "";
    document.querySelectorAll("#chatOptionsEl button.combat-option-btn:not(.combat-help-btn)").forEach(function (btn) {
        const tip = btn.getAttribute("title");
        if (!tip) return;
        const row = document.createElement("div");
        row.className = "combat-help-entry";
        const label = document.createElement("div");
        label.className = "combat-help-entry-label";
        label.textContent = btn.textContent;
        const text = document.createElement("div");
        text.className = "combat-help-entry-text";
        text.textContent = tip;
        row.appendChild(label);
        row.appendChild(text);
        entriesEl.appendChild(row);
    });
    if (!entriesEl.childNodes.length) {
        const none = document.createElement("div");
        none.className = "combat-help-entry-text";
        none.textContent = "No action explanations right now.";
        entriesEl.appendChild(none);
    }
    modal.classList.add("active");
}

function appendCombatHelpButton(el) {
    // Its own group so the whole block (heading included) is hidden on
    // hover-capable devices by the .combat-help-group CSS rule.
    const group = document.createElement("div");
    group.className = "combat-action-group combat-help-group";
    const heading = document.createElement("div");
    heading.className = "combat-action-heading";
    heading.textContent = "Help";
    group.appendChild(heading);
    group.appendChild(createCombatButton("?", showCombatHelpWindow, {
        className: "combat-help-btn",
        title: "What do these actions do?"
    }));
    el.appendChild(group);
}

// Human-readable limb names for wound narration (state keys stay as-is
// elsewhere - this is display-only).
const COMBAT_LIMB_LABELS = { head: "head", torso: "torso", arms: "arms", legs: "legs" };
const COMBAT_LIMB_VERBS = { head: "is", torso: "is", arms: "are", legs: "are" };

// What a limb at 0 hp actually looks like, instead of the mechanical word
// "disabled" - by limb and by what last hurt it. Follows the limb label, so
// each reads as "<label> <this>" ("head is ringing", "arms hang limp").
const DISABLED_LIMB_STATES = {
    head: {
        blunt: "is ringing from the blow, leaving them dazed",
        edge: "is bloodied and swimming",
        puncture: "is bloodied and swimming",
        other: "is reeling"
    },
    arms: {
        blunt: "are numb and hanging useless",
        edge: "hang limp, torn open",
        puncture: "hang limp around the wound",
        other: "hang limp"
    },
    legs: {
        blunt: "are barely able to hold their weight",
        edge: "are torn open and barely hold them up",
        puncture: "are barely holding them up",
        other: "can barely hold their weight"
    },
    torso: {
        blunt: "is badly battered, every breath a struggle",
        edge: "is badly torn, every breath a struggle",
        puncture: "is badly pierced, every breath a struggle",
        other: "is badly hurt, every breath a struggle"
    }
};

// Disabled-limb wording for elemental damage: { element: { head, arms, legs, torso } }.
const ELEMENT_LIMB_STATES = {
    fire: { head: "is scorched and blistered, eyes streaming", arms: "hang blistered and useless", legs: "are scorched and barely hold them", torso: "is burned raw, every breath a struggle" },
    frost: { head: "is numb with cold, thoughts slow", arms: "are stiff with cold and will not close", legs: "are frozen stiff and barely hold them", torso: "is locked with cold, every breath a struggle" },
    shock: { head: "is ringing, vision sparking", arms: "twitch and will not obey", legs: "spasm and barely hold them", torso: "is seized by the current, every breath a struggle" },
    holy: { head: "is seared by the light, eyes shut tight", arms: "hang scorched and trembling", legs: "buckle under the burning light", torso: "is burned by the light, every breath a struggle" },
    shadow: { head: "is clouded and cold, the world fading", arms: "hang grey and drained", legs: "are drained of strength and barely hold them", torso: "is drained cold, every breath a struggle" },
    earth: { head: "is ringing from the crushing blow", arms: "are crushed and hanging useless", legs: "are crushed and barely hold their weight", torso: "is crushed, every breath a struggle" },
    wind: { head: "is cut and bleeding, hair torn", arms: "hang flayed with fine cuts", legs: "are cut to ribbons and barely hold them", torso: "is lashed with cuts, every breath a struggle" },
    arcane: { head: "is dazed, thoughts scattered by raw magic", arms: "tingle and will not answer", legs: "tingle and barely hold them", torso: "hums with raw magic, every breath a struggle" },
    water: { head: "is streaming and ringing, eyes stinging", arms: "hang waterlogged and heavy", legs: "are numb and heavy with soaking cold", torso: "is battered by the water, every breath a struggle" }
};

function describeDisabledLimbState(limbKey, lastDamageType) {
    const states = DISABLED_LIMB_STATES[limbKey];
    if (!states) return "is badly hurt";
    const el = normalizeKillElement(lastDamageType);
    if (el && ELEMENT_LIMB_STATES[el] && ELEMENT_LIMB_STATES[el][limbKey]) return ELEMENT_LIMB_STATES[el][limbKey];
    return states[lastDamageType] || states.other;
}

// Natural-language phrase for a single limb's wound state, or null if the
// limb isn't hurt enough to mention. Used by describeCombatWounds below.
// Includes the verb so multi-limb lists still read naturally when joined
// ("head is disabled and legs are wounded").
function describeLimbWoundPhrase(limbKey, limb, bodyKind) {
    const label = COMBAT_LIMB_LABELS[limbKey] || limbKey;
    const verb = COMBAT_LIMB_VERBS[limbKey] || "is";
    const ratio = limb.max > 0 ? limb.hp / limb.max : 1;
    if (limb.severed) return `${label} ${verb} ${bodyKind === "bone" ? "knocked clean away" : "severed clean off"}`;
    if (limb.disabled || ratio <= 0) {
        if (bodyKind && DISABLED_LIMB_STATES_BODY[bodyKind] && DISABLED_LIMB_STATES_BODY[bodyKind][limbKey]) {
            return `${label} ${DISABLED_LIMB_STATES_BODY[bodyKind][limbKey]}`;
        }
        return `${label} ${describeDisabledLimbState(limbKey, limb.lastDamageType)}`;
    }
    const lastType = limb.lastDamageType;
    const bodyWords = bodyKind ? WOUND_WORDS_BODY[bodyKind] : null;
    const woundWord = bodyWords ? (bodyWords[lastType] || bodyWords.other)
        : lastType === "edge" ? "gashed"
        : lastType === "puncture" ? "pierced"
        : lastType === "blunt" ? "bruised"
        : "wounded";
    if (ratio <= 0.35) return `${label} ${verb} badly ${woundWord}`;
    if (ratio <= 0.65) return `${label} ${verb} ${woundWord}`;
    return null;
}

// Joins wound phrases into a natural list ("head disabled and torso
// wounded" / "head disabled, torso wounded, and legs wounded") instead of a
// bare comma-separated dump.
function joinWoundPhrases(parts) {
    if (!parts.length) return "";
    if (parts.length === 1) return parts[0];
    if (parts.length === 2) return `${parts[0]} and ${parts[1]}`;
    return `${parts.slice(0, -1).join(", ")}, and ${parts[parts.length - 1]}`;
}

function describeCombatWounds(entity) {
    if (isSlimeEntity(entity)) return "";
    const state = ensureCombatState(entity);
    if (!state) return "";

    const parts = [];
    const wBodyKind = getBodyKind(entity);
    Object.entries(state.limbs).forEach(([key, limb]) => {
        const phrase = describeLimbWoundPhrase(key, limb, wBodyKind);
        if (phrase) parts.push(phrase);
    });

    return joinWoundPhrases(parts);
}

// -- LUCK (Potion of Luck) ---------------------------------------------------
// Not a status effect (no duration, no stat/combat modifier) - a one-shot
// flag that forces the entity's next d20 roll to come up a natural 20,
// then clears itself. rollD20 is a drop-in replacement for randInt(1, 20)
// at the specific "this entity is taking an action" roll sites (the
// player's attack roll, an escape attempt, a willpower save, an NPC's
// counter-attack roll) - see its call sites for which ones. Rolls that
// aren't tied to one entity acting (trade-acceptance checks, ambush
// tie-breaks) intentionally still use plain randInt.
function consumeLuckyRoll(entity) {
    if (entity && entity.luckyRollPending) {
        entity.luckyRollPending = false;
        return 20;
    }
    return null;
}

// -- HIDDEN ITEM TRAITS -------------------------------------------------
// Small curios can secretly be enchanted - a permanent property carried on
// the item itself (item.hiddenTrait) rather than anything tied to the
// player, so it works from either side of a trade (buying a lucky charm
// off a merchant, or having them notice one of yours) and persists through
// being sold, looted, or dropped since it's just data on the item object.
//
// Whether an item is enchanted, and which trait it got, is decided once,
// at the moment the item is generated (see maybeEnchantItem, called from
// the NPC loot-generation sites) - not when the player asks about it. That
// way its price (see below) reflects the hidden value from the moment it
// exists, and the mechanical effect (luck feeding rollD20, stat bonuses
// feeding getEntityStatValue/getSetupStat) is active immediately, exactly
// as if the item were openly magical - only the item's IDENTITY as
// enchanted, and which trait it carries, stays secret from the player.
// Asking a merchant about an eligible item (askAboutTradeItem) doesn't
// roll anything anymore; it just reveals (and permanently caches, via
// item.hiddenTraitRevealed) whichever trait was already secretly assigned,
// if any. Two effect types exist so far - "luck" (rollD20) and "stat" (a
// flat bonus to one named stat) - but the shape is generic enough that a
// future trait type just needs a new case wherever that effect applies.
const ITEM_ENCHANT_CHANCE = 0.05;
const ITEM_ENCHANT_VALUE_MULTIPLIER = 1.4;
const HIDDEN_ITEM_TRAIT_LUCK_CAP = 0.25;
const HIDDEN_ITEM_TRAIT_STAT_CAP = 3;

const HIDDEN_ITEM_TRAITS = [
    { id: "luckyHeirloom", label: "Lucky Heirloom", effectType: "luck", effectValue: 0.05, summary: "+5% chance any roll comes up fortunate" },
    { id: "faithfulTrinket", label: "Faithful Trinket", effectType: "luck", effectValue: 0.04, summary: "+4% chance any roll comes up fortunate" },
    { id: "graveKeptCharm", label: "Grave-Kept Charm", effectType: "luck", effectValue: 0.03, summary: "+3% chance any roll comes up fortunate" },
    { id: "gamblersToken", label: "Gambler's Token", effectType: "luck", effectValue: 0.06, summary: "+6% chance any roll comes up fortunate" },
    { id: "keensightBand", label: "Keensight Band", effectType: "stat", statKey: "physicalProwess", effectValue: 1, summary: "+1 Physical Prowess" },
    { id: "steadyStepCharm", label: "Steady-Step Charm", effectType: "stat", statKey: "flexibility", effectValue: 1, summary: "+1 Flexibility" },
    { id: "unbrokenWillToken", label: "Unbroken-Will Token", effectType: "stat", statKey: "willpower", effectValue: 1, summary: "+1 Willpower" },
    { id: "hardyKeepsake", label: "Hardy Keepsake", effectType: "stat", statKey: "endurance", effectValue: 1, summary: "+1 Endurance" },
    { id: "silverTonguedTrinket", label: "Silver-Tongued Trinket", effectType: "stat", statKey: "charisma", effectValue: 1, summary: "+1 Charisma" }
];

// Restricted to small curios rather than every item - potions already have
// their own effect system, and weapons/armor have the Enchanter's tier
// system, so a hidden trait here is specifically the "turns out this odd
// little trinket was special all along" moment, not a second enchantment
// track. Deity tomes are excluded too - they're already special (they
// grant deity knowledge) and their nature isn't meant to be hidden.
// Already-enchanted items are excluded so this can't reroll/stack past
// one trait per item.
function isItemEligibleForHiddenTrait(item) {
    if (!item || item.hiddenTrait || isDeityTomeItem(item)) return false;
    const tags = Array.isArray(item.type) ? item.type : [];
    return tags.includes("trinket") || tags.includes("relic") || tags.includes("token") || tags.includes("misc");
}

// Called right after a fresh loot item is generated (see the loot rolls in
// the NPC-inventory builder). A flat, one-time chance for the item to be
// secretly enchanted - if it hits, a random trait is assigned immediately
// (item.hiddenTrait) and the item's value is bumped up to reflect that
// hidden worth, but item.hiddenTraitRevealed stays false until the player
// actually asks about it (askAboutTradeItem).
function maybeEnchantItem(item) {
    if (!isItemEligibleForHiddenTrait(item)) return item;
    if (Math.random() >= ITEM_ENCHANT_CHANCE) return item;

    const traitDef = rand(HIDDEN_ITEM_TRAITS);
    item.hiddenTrait = { id: traitDef.id, label: traitDef.label, effectType: traitDef.effectType, effectValue: traitDef.effectValue, statKey: traitDef.statKey, summary: traitDef.summary };
    item.hiddenTraitRevealed = false;
    if (typeof item.value === "number") {
        item.value = Math.max(item.value + 1, Math.ceil(item.value * ITEM_ENCHANT_VALUE_MULTIPLIER));
    }
    return item;
}

// Sums every "luck"-type hidden trait the entity is carrying, in inventory
// or equipped - capped so stacking several lucky charms can't make good
// rolls a near-certainty, just a meaningfully better chance. Applies
// whether or not the trait has been revealed to the player yet - the
// effect is real from the moment the item was secretly enchanted.
function getCarriedLuckBonusChance(entity) {
    if (!entity) return 0;

    const items = [];
    if (Array.isArray(entity.inventory)) items.push(...entity.inventory);
    if (entity.equipped && typeof entity.equipped === "object") {
        Object.keys(entity.equipped).forEach(slot => {
            if (entity.equipped[slot]) items.push(entity.equipped[slot]);
        });
    }

    const total = items.reduce((sum, item) => {
        if (item && item.hiddenTrait && item.hiddenTrait.effectType === "luck") {
            return sum + (item.hiddenTrait.effectValue || 0);
        }
        return sum;
    }, 0);

    return Math.min(total, HIDDEN_ITEM_TRAIT_LUCK_CAP);
}

// Mirrors getCarriedLuckBonusChance for "stat"-type hidden traits - sums
// the bonus to one specific stat across everything the entity carries or
// has equipped, capped so several stacked charms can't run away with a
// stat. Also applies before the trait is revealed, same as luck above.
// ── GRIME / HYGIENE ─────────────────────────────────────────────────────
// Runtime dirtiness for the person AND their gear. Hygiene (the person) is a
// 0-100 number on the entity, 100 = freshly washed; item grime is a 0-100
// number per worn item, 0 = clean. The primary sources are EVENT-based -
// combat exchanges and intimacy acts - while the slow turn/environment tick
// below is a background trickle that only matters over very long stretches
// without a wash (see addIntimacyActGrime for the sex hook). Grime clears at
// water/hygiene room objects (wash-basin, fountain - see
// isWashableRoomObject/washAtRoomObject). Charisma penalties come in tiers
// so a little dirt never matters socially - only sustained neglect does.
// Entities/items without the fields read as clean, so old saves and NPCs
// (which never accrue) are unaffected until they get dirty.
const GRIME_TIER_DIRTY = 40;
const GRIME_TIER_FILTHY = 70;
const HYGIENE_TIER_GRIMY = 70;
const HYGIENE_TIER_FILTHY = 40;
const HYGIENE_TIER_REPULSIVE = 10;
const GRIME_TURN_TICK = 20;             // story turns between trickle ticks
const GRIME_TURN_AMOUNT = 1;            // background trickle per tick
const GRIME_ENVIRONMENT_AMOUNT = 2;     // extra per tick in dirty room types
const GRIME_COMBAT_AMOUNT = 5;          // per combat exchange the player is attacked in
const GRIME_INTIMACY_AMOUNT = 5;        // per act during an intimacy encounter
const GRIME_INTIMACY_AMOUNT_HIGH = 15; // ejaculation/watersports/anal acts (see addIntimacyActGrime)

const DIRTY_ROOM_TYPE_PATTERNS = [
    "marsh", "swamp", "submerged", "sunken", "broken ground",
    "cavern", "tunnel", "cellar", "alleyway", "mine shaft", "collapsed gallery"
];

function isDirtyRoomType(room) {
    if (!room) return false;
    const text = `${room.type || ""} ${room.displayName || ""}`.toLowerCase();
    return DIRTY_ROOM_TYPE_PATTERNS.some(pattern => text.includes(pattern));
}

function getHygieneCharismaPenalty(entity) {
    const hygiene = entity && typeof entity.hygiene === "number" ? entity.hygiene : 100;
    if (hygiene < HYGIENE_TIER_REPULSIVE) return -3;
    if (hygiene < HYGIENE_TIER_FILTHY) return -2;
    if (hygiene < HYGIENE_TIER_GRIMY) return -1;
    return 0;
}

function getItemGrimeCharismaPenalty(item) {
    const grime = item && typeof item.grime === "number" ? item.grime : 0;
    if (grime >= GRIME_TIER_FILTHY) return -2;
    if (grime >= GRIME_TIER_DIRTY) return -1;
    return 0;
}

// An item's live charisma: its base value (quality tier, or a future
// specialty/revealing value) minus the grime it has picked up. Filthy armor
// (base 0) drags charisma down too - dirty gear reads badly even when it
// was never fashionable to begin with.
function getEffectiveItemCharisma(item) {
    const base = item && typeof item.charisma === "number" ? item.charisma : 0;
    return base + getItemGrimeCharismaPenalty(item);
}

function getHygieneLabel(entity) {
    const hygiene = entity && typeof entity.hygiene === "number" ? entity.hygiene : 100;
    if (hygiene < HYGIENE_TIER_REPULSIVE) return "Filthy";
    if (hygiene < HYGIENE_TIER_FILTHY) return "Grimy";
    if (hygiene < HYGIENE_TIER_GRIMY) return "Travel-worn";
    return "Fresh";
}

function getItemGrimeLabel(item) {
    const grime = item && typeof item.grime === "number" ? item.grime : 0;
    if (grime >= GRIME_TIER_FILTHY) return "filthy";
    if (grime >= GRIME_TIER_DIRTY) return "grimy";
    return "clean";
}

// Add grime to a person and everything they wear (capped at 100). The person's
// hygiene counts DOWN from 100; item grime counts UP from 0.
function addEntityGrime(entity, amount) {
    if (!entity || !(amount > 0)) return;
    if (typeof entity.hygiene !== "number") entity.hygiene = 100;
    entity.hygiene = Math.max(0, entity.hygiene - Math.min(100, amount));
    if (entity.equipped && typeof entity.equipped === "object") {
        Object.keys(entity.equipped).forEach(slot => {
            const item = entity.equipped[slot];
            if (!item || Array.isArray(item)) return;
            const grime = typeof item.grime === "number" ? item.grime : 0;
            if (grime < 100) item.grime = Math.min(100, grime + Math.min(100, amount));
        });
    }
}

// A room object offers washing when its tags include "water" or "hygiene"
// (see the room templates in cyoaftw-world-data.js: Guest Room's wash-basin,
// Square's fountain). This is the grime-clearing counterpart to
// addEntityGrime and the turn/combat accrual hooks.
function isWashableRoomObject(item) {
    if (!item || Array.isArray(item)) return false;
    const tags = Array.isArray(item.tags) ? item.tags.map(tag => String(tag || "").toLowerCase()) : [];
    // Hazardous (stagnant) or ritual (mirror pool) water is not for washing.
    if (tags.includes("hazard") || tags.includes("ritual")) return false;
    return tags.includes("water") || tags.includes("hygiene");
}

// First washable fixture in the room (from room.structural or loose room
// items), or null. Used by the Interact menu's "Wash up" entry.
function findWashableInRoom(room) {
    if (!room) return null;
    if (typeof ensureRoomFixtureState === "function") ensureRoomFixtureState(room);
    const pools = [room.structural, room.items];
    for (let p = 0; p < pools.length; p++) {
        const list = Array.isArray(pools[p]) ? pools[p] : [];
        for (let i = 0; i < list.length; i++) {
            if (pools[p] === room.structural && !isFixtureVisible(list[i], room)) continue;
            if (isWashableRoomObject(list[i])) return list[i];
        }
    }
    return null;
}

function washAtRoomObject(item) {
    performWash();
    renderRoomObjectActionMenu(item);
}

function performWash() {
    const player = G.player;
    if (!player) return;

    const wasGrimy = getHygieneCharismaPenalty(player) !== 0 ||
        (player.equipped && typeof player.equipped === "object" &&
            Object.keys(player.equipped).some(slot =>
                getItemGrimeCharismaPenalty(player.equipped[slot]) !== 0));

    // Washing scrubs the person and the clothes they are wearing. Spare
    // clothes in the pack keep their grime until worn and washed. It also
    // clears lingering smell notes (see addSmellMark in
    // nsfw/intimacy-system.js).
    player.hygiene = 100;
    delete player.smellNotes;
    if (player.equipped && typeof player.equipped === "object") {
        Object.keys(player.equipped).forEach(slot => {
            const equippedItem = player.equipped[slot];
            if (equippedItem && typeof equippedItem.grime === "number" && equippedItem.grime > 0) {
                equippedItem.grime = 0;
            }
        });
    }

    renderStats();
    setNarration(wasGrimy
        ? "You wash off the road dust, sweat and blood - yourself and your worn clothes both - and feel presentable again."
        : "You freshen up with a quick wash, though you were already fairly clean.");
    saveGameState();
}

// Charisma from WORN clothing (equipped slots only - carrying loot in the
// pack does nothing). Clothes get this from their quality tier; specialty or
// revealing items will set the field directly at higher values. The cap is a
// generous sanity guard, not a balance lever: current content tops out at +6
// (tailored upper/lower/feet). Raise it when specialty gear needs headroom.
const WORN_CHARISMA_BONUS_CAP = 10;

function getWornCharismaBonus(entity) {
    if (!entity || !entity.equipped || typeof entity.equipped !== "object") return 0;
    let total = 0;
    Object.keys(entity.equipped).forEach(slot => {
        const item = entity.equipped[slot];
        if (item && !Array.isArray(item)) total += getEffectiveItemCharisma(item);
    });
    return Math.min(total, WORN_CHARISMA_BONUS_CAP);
}

function getCarriedStatBonus(entity, statKey) {
    if (!entity || !statKey) return 0;

    const items = [];
    if (Array.isArray(entity.inventory)) items.push(...entity.inventory);
    if (entity.equipped && typeof entity.equipped === "object") {
        Object.keys(entity.equipped).forEach(slot => {
            if (entity.equipped[slot]) items.push(entity.equipped[slot]);
        });
    }

    // Ordinary trinkets cap at HIDDEN_ITEM_TRAIT_STAT_CAP among themselves; a
    // boss relic's rolled bonus (1d6 + portal tier) sits on top of that cap -
    // it is the trophy it is. Totals are tracked separately so the order the
    // items are carried in never matters.
    let relicTotal = 0;
    let trinketTotal = 0;
    items.forEach((item) => {
        if (item && item.hiddenTrait && item.hiddenTrait.effectType === "stat" && item.hiddenTrait.statKey === statKey) {
            const add = item.hiddenTrait.effectValue || 0;
            if (item.bossRelic === true) relicTotal += add;
            else trinketTotal = Math.min(trinketTotal + add, HIDDEN_ITEM_TRAIT_STAT_CAP);
        }
    });

    return relicTotal + trinketTotal;
}

function rollD20(entity) {
    const lucky = consumeLuckyRoll(entity);
    if (lucky !== null) return lucky;

    const luckBonusChance = getCarriedLuckBonusChance(entity);
    if (luckBonusChance > 0 && Math.random() < luckBonusChance) return 20;

    return randInt(1, 20);
}

// -- STATUS EFFECTS ---------------------------------------------------------
// Temporary stat penalties (and, for torsoDisabled, a temporary HP cap) that
// get applied when a limb is disabled in combat - not a random crit chance,
// a direct consequence of the existing wound system (see applyCombatDamage's
// `newlyDisabledLimb`, checked in attackNPC/resolveNPCCounter). Duration is
// tracked against the same story-turn counter conversation cooldowns already
// use (getCurrentStoryTurn), so effects fade with story progress rather than
// real time or a fixed number of combat rounds. Built generically enough
// that a future trigger (a potion, a room effect, an NPC ability) can just
// call applyStatusEffect(entity, key) with a new entry in
// STATUS_EFFECT_DEFINITIONS - it doesn't need to be limb-disable-specific.
