// Reflects the current INTERACT_MENU_ACTIONS on the two columns flanking the
// exit grid (observe left, act right) - called whenever the exit grid becomes
// visible (see setExitGridVisible) and after anything that changes
// eligibility (rest, sleep, search, ...).
function renderInteractSidePanels(expanded = false) {
    const leftEl = document.getElementById("interactLeftEl");
    const rightEl = document.getElementById("interactRightEl");
    if (!leftEl || !rightEl) return;
    leftEl.innerHTML = "";
    rightEl.innerHTML = "";

    const room = G.activeRoom;
    if (!room || !G.player || G.activeNPC || G.activeObject) return;

    const makeHeading = function (text) {
        const heading = document.createElement("div");
        heading.className = "interact-side-heading";
        heading.textContent = text;
        return heading;
    };
    const observeButtons = [];
    const actButtons = [];
    INTERACT_MENU_ACTIONS.forEach(action => {
        if (!action.visible(room)) return;
        const reason = action.disabledReason ? action.disabledReason(room) : "";
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "interact-side-btn";
        btn.textContent = action.label;
        btn.title = reason || action.title || "";
        btn.disabled = !!reason;
        btn.onclick = function () { action.run(room); };
        (action.group === "observe" ? observeButtons : actButtons).push(btn);
    });

    if (typeof appendGuideButtons === "function" && G.guiding) appendGuideButtons(leftEl, makeHeading);
    if (typeof getCrowdFocus === "function" && getCrowdFocus(room)) {
        leftEl.appendChild(makeHeading("Group"));
        const walkBtn = document.createElement("button");
        walkBtn.type = "button";
        walkBtn.className = "interact-side-btn";
        walkBtn.textContent = "Walk away from group";
        walkBtn.onclick = function () { walkAwayFromCrowdGroup(); };
        leftEl.appendChild(walkBtn);
    }
    if (observeButtons.length) {
        leftEl.appendChild(makeHeading("Observe"));
        observeButtons.forEach(btn => leftEl.appendChild(btn));
    }
    if (actButtons.length) {
        rightEl.appendChild(makeHeading("Act"));
        actButtons.forEach(btn => rightEl.appendChild(btn));
    }
    // Desktop shows every action in a grid. CSS collapses the extra actions
    // only on mobile; keeping them in the DOM also handles window resizing.
    if (!expanded) {
        [leftEl, rightEl].forEach(function (panel) {
            const buttons = Array.from(panel.querySelectorAll("button"));
            if (buttons.length <= 3) return;
            buttons.slice(2).forEach(btn => btn.classList.add("interact-side-overflow"));
            // Hide a heading on mobile when all its buttons are collapsed.
            Array.from(panel.querySelectorAll(".interact-side-heading")).forEach(function (heading) {
                let next = heading.nextElementSibling;
                let hasPrimary = false;
                while (next && !next.classList.contains("interact-side-heading")) {
                    if (next.tagName === "BUTTON" && !next.classList.contains("interact-side-overflow")) hasPrimary = true;
                    next = next.nextElementSibling;
                }
                if (!hasPrimary) heading.classList.add("interact-side-overflow");
            });
            const more = document.createElement("button");
            more.type = "button";
            more.className = "interact-side-btn interact-side-more";
            more.textContent = "More…";
            more.setAttribute("aria-label", panel === leftEl ? "More to observe" : "More actions");
            more.setAttribute("aria-controls", "chatOptionsEl");
            more.onclick = function () { openInteractActionPanel(panel.id); };
            panel.appendChild(more);
        });
    }
}

// Rebuild on opening so eligibility, disabled reasons and guide controls
// reflect the current room. Reuse the existing action callbacks.
function openInteractActionPanel(panelId) {
    if (!G.activeRoom || !G.player || G.activeNPC || G.activeObject) return;
    const el = document.getElementById("chatOptionsEl");
    const panel = document.getElementById(panelId);
    if (!el || !panel) return;
    renderInteractSidePanels(true);
    const groups = [];
    Array.from(panel.children).forEach(function (child) {
        if (child.classList.contains("interact-side-heading")) {
            groups.push({ title: child.textContent, buttons: [] });
        } else if (child.tagName === "BUTTON") {
            if (!groups.length) groups.push({ title: "", buttons: [] });
            const run = child.onclick;
            groups[groups.length - 1].buttons.push(createCombatButton(child.textContent, function () {
                resetNpcPanel();
                if (run) run();
            }, { disabled: child.disabled, title: child.title }));
        }
    });
    clearChatLog();
    setExitGridVisible(false);
    el.innerHTML = "";
    groups.forEach(group => appendCombatGroup(el, group.title, group.buttons));
    appendCombatGroup(el, "", [createCombatButton("Back", function () { returnToRoomView(); })]);
    const first = el.querySelector("button:not(:disabled)");
    if (first) first.focus();
}

// The interact options are no longer behind a center button: they sit in the
// two columns beside the exit grid (see renderInteractSidePanels). The
// sub-menus' Back buttons still call this, so it now means "return to the
// room view" - resetNpcPanel clears the chat options and re-shows the exit
// grid with freshly rendered side panels. The old guards stay: nothing to
// return to mid-conversation or mid-combat.
// A final dismissal returns to the current exploration view. Child windows
// keep their parent menu, conversation, or fight until that view also closes.
function refreshRoomViewAfterClose() {
    const room = G.activeRoom;
    if (!room || !G.player || G.activeNPC || G.activeObject || G.activeNPCMode === "combat") return false;
    const overlays = ["itemModal", "preferencesModal", "saveMenuModal", "equipmentManager", "mapManager", "combatHelpModal"];
    if (overlays.some(function (id) {
        const el = document.getElementById(id);
        return el && el.classList.contains("active");
    })) return false;
    if (typeof isCharacterSheetOpen === "function" && isCharacterSheetOpen()) return false;
    const options = document.getElementById("chatOptionsEl");
    if (options && options.querySelector("button, input, textarea, select")) return false;
    renderRoom();
    const lead = room.baseDescription ? String(room.baseDescription).trim() : (room.displayName || room.name || "This place");
    renderNarrationWithRoomObservations(room, lead);
    setExitGridVisible(true);
    return true;
}

function returnToRoomView() {
    resetNpcPanel();
    return refreshRoomViewAfterClose();
}

function openInteractMenu() {
    const room = G.activeRoom;
    const player = G.player;
    if (!room || !player || G.activeNPC || G.activeObject) return;

    returnToRoomView();
}

function closeInteractMenu() {
    returnToRoomView();
}

function attemptRest() {
    const room = G.activeRoom;
    const player = G.player;
    if (!room || !player || G.activeNPC || G.activeObject) return;

    if (isRoomCollapsed(room)) {
        setNarration("There is no room left to rest in, only rubble and dust.");
        return;
    }
    if (!playerNeedsRest(player)) {
        setNarration("You are already rested.");
        return;
    }

    if (roomHasActiveHostile(room)) {
        setNarration("You can't rest with danger nearby.");
        return;
    }

    const designated = typeof isRestfulRoom === "function" && isRestfulRoom(room);
    const healPerTurn = (designated ? REST_HEAL_PER_TURN_DESIGNATED : REST_HEAL_PER_TURN_UNDESIGNATED) +
        Math.round(getClassPerk(player, "restHealBonus", 0) * (getFaithPathDef(player) ? getFaithPathDef(player).restHealMult : 1)) +
        getEquippedAffinityTotal(player, "restHeal");
    const manaPerTurn = (designated ? REST_MANA_PER_TURN_DESIGNATED : REST_MANA_PER_TURN_UNDESIGNATED) +
        getClassPerk(player, "restManaBonus", 0) + getEquippedAffinityTotal(player, "restMana") +
        (getFaithPathDef(player) ? getFaithPathDef(player).restManaBonus : 0);

    const bedQuality = getRestBedQuality(room);
    const bedMult = bedQuality === "proper" ? REST_BED_MULT_PROPER : (bedQuality === "makeshift" ? REST_BED_MULT_MAKESHIFT : 1);
    const bedHeal = Math.max(1, Math.round(healPerTurn * bedMult));   // also the per-turn STAMINA recovery (unchanged)
    const bedMana = Math.round(manaPerTurn * bedMult);
    // HP is slower in the exploration zones (fractions carry over between turns).
    // A bed still multiplies it; stamina and mana are not affected.
    const slowHeal = isSlowHealRoom(room);
    const perkHeal = Math.max(0, healPerTurn - (designated ? REST_HEAL_PER_TURN_DESIGNATED : REST_HEAL_PER_TURN_UNDESIGNATED));
    const slowHpPerTurn = (REST_HP_PER_TURN_SLOW + perkHeal * REST_HP_SLOW_BONUS_FACTOR) * bedMult;

    let turnsRested = 0;
    let healed = 0;
    let staminaRecovered = 0;
    let manaRecovered = 0;
    let interrupted = false;
    const partyWoke = [];

    for (let i = 0; i < REST_MAX_TURNS_PER_ACTION; i++) {
        if (!playerNeedsRest(player)) break;

        advanceStoryTurn(1);
        if (typeof runNPCAutonomyTick === "function") runNPCAutonomyTick();
        turnsRested++;
        if (turnsRested === 1) resetSpeciesRestState(player, null);

        // HP per turn: zone rule, then the open-wound factor (never below the floor).
        let hpPerTurn = slowHeal ? slowHpPerTurn : bedHeal;
        const woundFactor = getWoundHealFactor(player);
        if (woundFactor < 1) hpPerTurn = Math.max(hpPerTurn * woundFactor, Math.min(hpPerTurn, WOUND_HEAL_FLOOR_PER_TURN));
        player._restHpCarry = (player._restHpCarry || 0) + hpPerTurn;
        const hpStep = Math.floor(player._restHpCarry + 1e-9);
        player._restHpCarry = Math.max(0, player._restHpCarry - hpStep);
        const wokeLines = restHealParty(room, hpStep, { rest: true });
        if (wokeLines.length) partyWoke.push.apply(partyWoke, wokeLines);
        const before = player.hp;
        player.hp = Math.min(player.hpMax, player.hp + hpStep);
        healed += player.hp - before;
        if (player.hp > before) healPlayerLimbs(player, (player.hp - before) / player.hpMax);
        staminaRecovered += restoreEntityStamina(player, bedHeal);
        manaRecovered += restorePlayerMana(player, bedMana);

        if (roomHasActiveHostile(room)) {
            interrupted = true;
            break;
        }
    }

    if (player.hp >= player.hpMax) player._restHpCarry = 0;
    if (turnsRested >= 3 && !bedQuality && !(typeof getActiveLodging === "function" && getActiveLodging()) && typeof setStoryFlag === "function") {
        if (room.zone === "Town") setStoryFlag("slept-rough", true);
    }
    renderStats();

    const recoveryBits = [];
    if (staminaRecovered > 0) recoveryBits.push(`${staminaRecovered} stamina`);
    if (manaRecovered > 0) recoveryBits.push(`${manaRecovered} mana`);
    const staminaNote = recoveryBits.length ? ` and ${recoveryBits.join(" and ")}` : "";

    let bedNote = bedQuality === "proper" ? " The bed makes it a real rest." : (bedQuality === "makeshift" ? " Even a rough bed helps." : "");
    if (hasOpenWound(player) && getWoundTreatmentKey(player) !== "both") bedNote += " Your wounds are not fully tended, so they heal slowly (Tend wounds, beside the exits).";
    if (!interrupted && !playerNeedsRest(player)) {
        const buffText = applyBedRestBonus(player, bedQuality);
        if (buffText) bedNote += " " + buffText;
    }
    if (getRestingPartyMembers(room).length) bedNote += " Your companions rest alongside you.";
    const withParty = function (t) { return partyWoke.length ? `${t}${bedNote} ${partyWoke.join(" ")}` : t + bedNote; };
    const bleedingCompanions = getDownedCompanionBodies(room).filter(function (b) { return b.bleedingOut; });
    const bleedNote = bleedingCompanions.length ? " Someone is still bleeding - bind their wounds." : "";

    if (interrupted) {
        setNarration(withParty(`You rest for ${turnsRested} turn${turnsRested === 1 ? "" : "s"}, recovering ${healed} HP${staminaNote}, before something dangerous arrives!`));
        if (typeof triggerRoomAmbush === "function") triggerRoomAmbush(room);
    } else if (!playerNeedsRest(player)) {
        // Resting passes story turns (NPCs wander in/out, items move), so the
        // narration is rebuilt WITH the room's current occupants and fixtures
        // rather than replacing them with a bare rest summary - the player
        // doesn't have to "Look around" again to see what's here now.
        renderNarrationWithRoomObservations(room, withParty(`You rest for ${turnsRested} turn${turnsRested === 1 ? "" : "s"} and recover fully.${bleedNote}`));
    } else {
        renderNarrationWithRoomObservations(room, withParty(`You rest for ${turnsRested} turn${turnsRested === 1 ? "" : "s"}, recovering ${healed} HP${staminaNote}${slowHeal && !bedQuality ? " - wounds knit slowly down here; a night in a bed would do far more" : (designated ? "" : " - recovery is slow away from a proper resting spot")}.${bleedNote}`));
    }

    renderInteractSidePanels();
    scheduleGuideArrival();
    schedulePressureEvent();
    saveGameState();
}

// ── SHRINE / ALTAR PRAYER (choosing a patron deity) ───────────────
// A Shrine or Altar room is the only place the player can choose a patron
// deity (see choosePatronDeity) - and only from deities they already know
// of (see learnDeity/DEITY_ARCHETYPES). This does not touch player.hp/
// combat state at all; it's purely the "pick a patron" UI, distinct from
// the "Pray to your Deity" death-revival choice (see triggerPlayerDeath/
// renderDeathChoice), which uses whichever patron was chosen here.
// Which deities a given NPC role is most likely to bring up when asked
// (see the "ask-deity" catalogue entry in cyoaftw-npc-data.js and
// chooseChatOption's dispatch to handleAskAboutDeity below). Any role not
// listed here can mention any of the five.
const DEITY_ROLE_AFFINITY = {
    "Priest": ["healer", "guardian", "titan"],
                "Archivist": ["trickster", "titan", "healer", "guardian", "outcast"],
    "Cultist": ["trickster", "outcast", "titan"]
};

// Grants the player knowledge of one deity they don't already know of,
// picked from whatever this NPC's role is most likely to speak of. A no-op
// if the player already knows every deity that role could mention (the
// catalogue entry's excludedActionTags already keeps this from firing twice
// in one conversation anyway).
function handleAskAboutDeity(npc) {
    const player = G.player;
    if (!player || !npc) return;
    ensurePlayerDeityState(player);

    const affinity = DEITY_ROLE_AFFINITY[npc.role] || Object.keys(DEITY_ARCHETYPES);
    const candidates = affinity.filter(id => !player.knownDeities.includes(id));
    if (!candidates.length) return;

    const deityId = rand(candidates);
    const deity = getDeityArchetype(deityId);
    if (!deity) return;

    learnDeity(deityId, `${npc.name} told ${player.name} of ${deity.name}.`);
}

// Distinct from handleAskAboutDeity above (generic lore, weighted by role,
// picks any not-yet-known deity) - this reveals the ONE specific deity
// this particular NPC personally follows (npc.deity, assigned once when
// they were generated inside a shrine room - see spawnNPCsForRoom). Works
// even if the player already knows that deity generically; the point is
// learning who THIS devotee follows, not just adding a new deity to the
// player's list (though learnDeity is a no-op either way if it's already
// known).
function handleAskAboutOwnDeity(npc) {
    const player = G.player;
    if (!player || !npc) return;
    const npcDeityId = ensureNPCDeity(npc) || npc.deity;
    const deity = npcDeityId ? getDeityArchetype(npcDeityId) : null;
    if (!deity) return;

    learnDeity(deity.id, `${npc.name} revealed they follow ${deity.name}.`);
}

// Template-driven rather than a hardcoded type-string list, so every
// zone's designated shrine room (see ZONE_SHRINE_ROOMS) plus any bonus
// prayer-capable room (e.g. Ruins' "Altar") is picked up automatically -
// a room counts as a shrine whenever its ROOM_TEMPLATES entry has
// isShrine: true, not because of what it happens to be named.
function isShrineRoom(room) {
    if (!room) return false;
    const template = typeof getRoomTemplate === "function" ? getRoomTemplate(room.type) : null;
    return !!(template && template.isShrine);
}

// Praying at a shrine (altar) is always possible: the shrine is dedicated to
// ONE deity (room.shrineDeityId) and anyone praying there without changing it
// prays to that deity, whoever they follow. Reflects current eligibility on the
// Pray button (below the exit grid) - called whenever the exit grid becomes
// visible (see setExitGridVisible), same as renderInteractSidePanels.
function updatePrayButton() {
    const btn = document.getElementById("prayBtn");
    if (!btn) return;

    const room = G.activeRoom;
    const player = G.player;
    if (player) ensurePlayerDeityState(player);
    const visible = isShrineRoom(room) && !!player && !G.activeNPC && !G.activeObject;
    btn.style.display = visible ? "block" : "none";
    if (!visible) return;

    btn.disabled = false;
    btn.title = "Pray at the shrine, or dedicate it to a deity you know.";
}

// ── PRAYER (devotion) ─────────────────────────────────────────────
// The first deity a player prays to becomes their patron for good
// (choosePatronDeity refuses to change it afterwards). Prayer costs stamina
// and story turns, and the same shrine or fixture cannot be prayed at again
// for PRAYER_COOLDOWN_TURNS. A shrine's dedication can be changed only as part
// of a prayer, so it changes at most once per cooldown.
const PRAYER_COOLDOWN_TURNS = 50;
const PRAYER_STAMINA_COST = 2;
const PRAYER_TURNS = 2;
const PRAYER_FAITH_GAIN = 2;

const PRAYER_TEXT = {
    trickster: "You pray with a grin you cannot quite suppress. Nothing answers, exactly, but your pockets feel lighter and your luck, somehow, looser.",
    titan: "You kneel and set your jaw. The prayer is a vow to endure, and the stone around you seems to take its measure of you and wait.",
    healer: "You bow your head and ask for mercy, for yourself and for whoever needs it. A gentle warmth gathers and settles over you.",
    guardian: "You kneel with a straight back and pledge to stand where you are needed. The silence that follows feels like a hand on the shoulder.",
    outcast: "You pray to the one the others turned away. No light answers, but you feel less alone in the dark."
};

// ── DIVINE POWER ──────────────────────────────────────────────────
// Each deity has a pool of divine power (G.story.divine.power[deityId]), the
// currency their future actions will be paid from. It has no upper limit and
// never drops below 0.
//   - Every DIVINE_TALLY_INTERVAL_TURNS story turns each deity counts the
//     shrines currently dedicated to them (room.shrineDeityId) and gains
//     DIVINE_POWER_PER_SHRINE for each one (tickDivinePower, from
//     advanceStoryTurn). Only shrine rooms count, not ritual fixtures.
//   - Every prayer, at a shrine or fixture, gives the deity prayed to
//     DIVINE_PRAYER_GAIN, whoever prayed and whoever they follow. Nobody is
//     penalised for praying to a deity that is not their own.
//   - Dedicating a shrine to a deity (changing its dedication as part of a
//     prayer) gives the new deity DIVINE_DEDICATION_GAIN, on top of the
//     prayer's own gain.
//   - Answering a dying player's prayer for revival costs the deity
//     DIVINE_REVIVAL_COST. A deity with less than that cannot answer (the
//     death screen shows the prayer as unavailable), and a refused prayer
//     costs nothing.
//   - Defiling (shrine or fixture, once per DEFILE_COOLDOWN_TURNS per place)
//     takes DIVINE_DEFILE_LOSS from that place's deity.
const DIVINE_TALLY_INTERVAL_TURNS = 200;
const DIVINE_POWER_PER_SHRINE = 10;
const DIVINE_PRAYER_GAIN = 2;
const DIVINE_DEDICATION_GAIN = 5;
const DIVINE_REVIVAL_COST = 10;
const DIVINE_DEFILE_LOSS = 1;
const DEFILE_COOLDOWN_TURNS = 50;

function getDivineState() {
    G.story = ensureStoryStateShape(G.story);
    return G.story.divine;
}

function getDivinePower(deityId) {
    const value = getDivineState().power[deityId];
    return typeof value === "number" ? value : 0;
}

// Returns the change actually applied (a loss is limited by what is left).
function adjustDivinePower(deityId, delta) {
    if (!DEITY_ARCHETYPES[deityId] || typeof delta !== "number" || delta === 0) return 0;
    const before = getDivinePower(deityId);
    const after = Math.max(0, before + delta);
    getDivineState().power[deityId] = after;
    return after - before;
}

function countDedicatedShrines() {
    const counts = {};
    Object.keys(DEITY_ARCHETYPES).forEach(function (id) { counts[id] = 0; });
    Object.keys(G.roomMap || {}).forEach(function (coords) {
        const room = G.roomMap[coords];
        if (!room || !isShrineRoom(room)) return;
        const id = getShrineDeityId(room);
        if (id && counts.hasOwnProperty(id)) counts[id]++;
    });
    return counts;
}

function tallyDivinePower() {
    const counts = countDedicatedShrines();
    Object.keys(counts).forEach(function (id) {
        if (counts[id] > 0) adjustDivinePower(id, counts[id] * DIVINE_POWER_PER_SHRINE);
    });
    getDivineState().lastShrineCounts = counts;
    return counts;
}

function tickDivinePower() {
    const state = getDivineState();
    const now = G.story.turnCounter || 0;
    let guard = 0;
    while (now - state.lastTallyTurn >= DIVINE_TALLY_INTERVAL_TURNS) {
        state.lastTallyTurn += DIVINE_TALLY_INTERVAL_TURNS;
        tallyDivinePower();
        if (++guard >= 50) { state.lastTallyTurn = now; break; }
    }
}

// Copy of every deity's current power, for debugging and future deity actions.
function getDivinePowerSummary() {
    const out = {};
    Object.keys(DEITY_ARCHETYPES).forEach(function (id) { out[id] = getDivinePower(id); });
    return out;
}

// A defiled place stays fouled (no prayer or offering) until the defile
// cooldown has passed, and cannot be defiled again until then either.
function isRecentlyDefiled(holder) {
    if (!holder || typeof holder.lastDefileTurn !== "number") return false;
    return getCurrentStoryTurn() - holder.lastDefileTurn < DEFILE_COOLDOWN_TURNS;
}

function getDefileBlockReason(holder, room) {
    if (!holder || !room || !G.player) return "Nothing to defile.";
    if (roomHasActiveHostile(room)) return "Too dangerous right now.";
    if (isRecentlyDefiled(holder)) {
        const left = DEFILE_COOLDOWN_TURNS - (getCurrentStoryTurn() - holder.lastDefileTurn);
        return `It is already fouled (${left} more turn${left === 1 ? "" : "s"} before it can be defiled again).`;
    }
    return "";
}

// Shared by shrines and ritual fixtures. Returns the narration text.
function performDefile(deityId, holder, label) {
    const serviceContext = shrineServiceExecution && shrineServiceExecution.spec.action === "defile" ? shrineServiceExecution : null;
    const player = G.player;
    const deity = getDeityArchetype(deityId);
    shrineServiceStart(serviceContext);
    advanceStoryTurn(1);
    if (!shrineServiceCurrent(serviceContext)) return shrineServiceInterrupted(serviceContext);
    const serviceHPBefore = player.hp, serviceFaithBefore = player.faith ? player.faith.score : null;
    holder.lastDefileTurn = getCurrentStoryTurn();
    adjustDivinePower(deityId, -DIVINE_DEFILE_LOSS);

    const faith = { [deityId]: -DEFILE_FAITH_LOSS };
    if (deityId !== "trickster") faith.trickster = 1;
    if (deityId !== "outcast") faith.outcast = 1;
    applyFaithDelta(faith, `defiled the ${label}`);
    rememberStoryEvent("faith", `${player.name} defiled the ${label}${deity ? ", sacred to " + deity.name : ""}.`, 3, { tags: ["faith", "defiled"] });

    const lines = [FIXTURE_DEFILE_TEXT[deityId]];
    if (Math.random() < 0.3 && typeof player.hp === "number" && player.hp > 1) {
        const loss = Math.min(player.hp - 1, randInt(1, 3));
        player.hp -= loss;
        lines.push(`A sudden chill bites at you (-${loss} HP).`);
    }
    shrineServiceRecord(serviceContext, { hpLost: Math.max(0, serviceHPBefore - player.hp), faithChange: player.faith && serviceFaithBefore !== null ? player.faith.score - serviceFaithBefore : 0, faithScore: player.faith ? player.faith.score : null });
    return lines.join(" ");
}

function defileShrine() {
    if (!shrineServiceExecution || shrineServiceExecution.spec.action !== "defile") return requestShrineService("defile");
    const serviceContext = shrineServiceExecution;
    const serviceNarration = function (message) { return shrineServiceNarration(message, serviceContext); };
    const room = G.activeRoom;
    if (!room || !G.player || !isShrineRoom(room)) return;
    const block = getDefileBlockReason(room, room);
    if (block) { serviceNarration(block); return; }
    const text = performDefile(getShrineDeityId(room), room, "shrine");
    if (text && text.status === "interrupted") return text;
    renderStats();
    renderShrinePrayerMenu();
    serviceNarration(text);
    saveGameState();
}

// kind "favor" (asking a patron for a blessing) skips the same-place prayer
// cooldown: a blessing has its own cooldown (lastFavorTurn) so it never locks
// out praying, dedicating or defiling at that shrine, and the reverse.
function getPrayerBlockReason(holder, room, kind) {
    const player = G.player;
    if (!player || !room || !holder) return "There is nothing to pray to.";
    if (roomHasActiveHostile(room)) return "You cannot pray with danger nearby.";
    if (isRecentlyDefiled(holder)) return "You fouled this place recently. It does not feel welcoming yet.";
    ensureEntityStamina(player);
    if (player.stamina < PRAYER_STAMINA_COST) return `You are too worn out to pray properly (${PRAYER_STAMINA_COST} stamina needed).`;
    const last = kind === "favor"
        ? (typeof holder.lastFavorTurn === "number" ? holder.lastFavorTurn : null)
        : (typeof holder.lastPrayerTurn === "number" ? holder.lastPrayerTurn : null);
    if (last !== null) {
        const left = PRAYER_COOLDOWN_TURNS - (getCurrentStoryTurn() - last);
        if (kind === "favor" && left > 0) return `You have only just asked for a blessing here (${left} more turn${left === 1 ? "" : "s"} before you can ask again).`;
        if (left > 0) return `You have only just prayed here (${left} more turn${left === 1 ? "" : "s"} before you can pray here again).`;
    }
    return "";
}

// Shared by shrines and ritual fixtures. Returns the narration text.
function performPrayer(deityId, holderLabel) {
    const player = G.player;
    const deity = getDeityArchetype(deityId);
    ensurePlayerDeityState(player);
    ensureEntityStamina(player);
    player.stamina = Math.max(0, player.stamina - PRAYER_STAMINA_COST);
    shrinePrayerCommitted();
    advanceStoryTurn(PRAYER_TURNS);
    if (!shrinePrayerCurrent()) return shrinePrayerInterrupted();

    const lines = [];
    const becameFollower = !player.deity;
    if (!player.knownDeities.includes(deityId)) {
        learnDeity(deityId, `${player.name} prayed at the ${holderLabel} and learned it is sacred to ${deity.name}.`);
        lines.push(`Something tells you this place is sacred to ${deity.name}.`);
    }
    if (becameFollower) {
        choosePatronDeity(deityId);
        lines.push(`You have pledged yourself to ${deity.name}, god of ${deity.domain}. It cannot be undone.`);
    } else if (player.deity !== deityId) {
        const own = getDeityArchetype(player.deity);
        lines.push(`You pray to ${deity.name}, though you follow ${own ? own.name : "another"}. Your own standing is unchanged.`);
    } else {
        applyFaithDelta({ [deityId]: PRAYER_FAITH_GAIN }, `prayed at the ${holderLabel}`);
    }
    adjustDivinePower(deityId, DIVINE_PRAYER_GAIN);
    rememberStoryEvent("faith", `${player.name} prayed to ${deity.name} at the ${holderLabel}.`, 3, { tags: ["faith", "prayer"] });
    return [PRAYER_TEXT[deityId]].concat(lines).join(" ");
}

function getPrayerButtonLabel(deityId, verbPrefix) {
    const player = G.player;
    const known = playerKnowsDeity(deityId);
    const deity = getDeityArchetype(deityId);
    let label = verbPrefix + (known && deity ? deity.name : "the shrine's god");
    if (!player.deity) label += " (pledges you to them for good)";
    return label;
}

function getShrineDeityId(room) {
    if (!room) return null;
    if (!room.shrineDeityId || !DEITY_ARCHETYPES[room.shrineDeityId]) room.shrineDeityId = rand(Object.keys(DEITY_ARCHETYPES));
    return room.shrineDeityId;
}

function prayAtShrine(newDeityId) {
    if (!shrineExecution) return requestShrinePrayer(newDeityId);
    const player = G.player;
    const room = G.activeRoom;
    if (!player || !room || !isShrineRoom(room)) return;
    ensurePlayerDeityState(player);
    const current = getShrineDeityId(room);
    const target = newDeityId && newDeityId !== current ? newDeityId : current;
    if (target !== current && !player.knownDeities.includes(target)) return;
    const block = getPrayerBlockReason(room, room);
    if (block) { setNarration(block); return; }

    let rededicated = "";
    if (target !== current) {
        room.shrineDeityId = target;
        adjustDivinePower(target, DIVINE_DEDICATION_GAIN);
        rededicated = `You rededicate the shrine to ${getDeityArchetype(target).name}. `;
        shrineRecordDedication(rededicated);
        rememberStoryEvent("faith", `${player.name} rededicated the shrine to ${getDeityArchetype(target).name}.`, 4, { tags: ["faith", "shrine-dedication"] });
    }
    const text = performPrayer(target, "shrine");
    if (text && text.status === "interrupted") return text;
    room.lastPrayerTurn = getCurrentStoryTurn();

    renderStats();
    renderShrinePrayerMenu();
    shrinePrayerNarration(rededicated + text);
    saveGameState();
}

function openShrinePrayerMenu() {
    const access = shrineSceneBlock();
    if (access) return sharedChoiceResult("blocked", access);
    const room = G.activeRoom;
    const player = G.player;
    if (!room || !player || !isShrineRoom(room) || G.activeNPC || G.activeObject) return;
    ensurePlayerDeityState(player);

    clearChatLog();
    setExitGridVisible(false);
    renderShrinePrayerMenu();
    const dedicatedId = getShrineDeityId(room);
    const dedicated = getDeityArchetype(dedicatedId);
    setNarration(playerKnowsDeity(dedicatedId) && dedicated
        ? `You kneel before the shrine, which is dedicated to ${dedicated.name}.`
        : "You kneel before the shrine.");
}

// ── DIVINE FAVORS ─────────────────────────────────────────────────
// A follower whose faith is above FAVOR_FAITH_THRESHOLD can pray at any
// shrine for a favor from their own patron. Asking is a prayer (stamina,
// turns, the shrine's prayer cooldown, +DIVINE_PRAYER_GAIN to the patron).
// The patron judges whether the request is worthy (an AI call, like the death
// prayer) and chooses the amount: 5 is the norm, 1-10 is allowed. Granting
// costs the patron divine power in proportion to the amount, and a patron
// cannot grant more than it can pay for. A refusal costs nothing.
// Two kinds of favor, all of them temporary:
//   - a stat blessing (any deity): +2 to one stat for amount x 10 turns;
//   - a one-time power (the patron's specialty, DEITY_FAVOR_DEFS): added to
//     player.divineBoons and shown in the Powers menu for anyone, cleric or
//     not, without mana. "uses" favors give `amount` uses; "duration" favors
//     give ONE use whose effect lasts `amount` rounds. Unused powers fade
//     after FAVOR_BOON_LIFETIME_TURNS.
const FAVOR_FAITH_THRESHOLD = 100;
const FAVOR_NORMAL_AMOUNT = 5;
const FAVOR_MAX_AMOUNT = 10;
const FAVOR_BOON_LIFETIME_TURNS = 300;
const FAVOR_STAT_TURNS_PER_UNIT = 10;
const FAVOR_STAT_COST = 5;

const FAVOR_STAT_DEFS = {
    physicalProwess: { label: "Physical Prowess", effect: "blessProwess" },
    flexibility: { label: "Flexibility", effect: "blessFlexibility" },
    willpower: { label: "Willpower", effect: "blessWillpower" },
    endurance: { label: "Endurance", effect: "blessEndurance" },
    charisma: { label: "Charisma", effect: "blessCharisma" }
};

// cost = divine power for the norm of 5 units (scaled by amount; fixedAmount
// favors cost exactly `cost` for their one unit).
// Regrowth: every patron can restore a severed limb (a god is all-powerful,
// only powered by faith); the cast line is the patron's own voice. The healer
// keeps the plain id "regrowth".
function makeRegrowthFavor(id, castLine) {
    return { id: id, name: "Regrowth", cost: 20, mode: "uses", fixedAmount: 1, unit: "use",
        ask: "regrowth: one chance to restore a severed arm or leg, whole and sound",
        power: { use: "world", regrow: true,
            summary: "Regrow one lost arm or leg, whole and sound (your patron chooses which). Not in the middle of a fight.",
            castLine: castLine } };
}
const DEITY_FAVOR_DEFS = {
    healer: [
        makeRegrowthFavor("regrowth", "You kneel and give yourself to the Healer's mercy. Warmth gathers in the stump, and bone, sinew and skin knit outward until the limb is whole again."),
        { id: "healingHands", name: "Healing Hands", cost: 10, mode: "uses", unit: "uses",
          ask: "healing hands: several uses of a strong healing touch for yourself or an ally",
          power: { use: "any", heal: { die: 8, bonus: 4, ally: true, clearBleed: true },
            summary: "Heal yourself or an ally for d8+4 and your willpower bonus, and stop the bleeding.",
            castLine: "The Healer's warmth pours through your hands and wounds close beneath them." } },
        { id: "divineResurrection", name: "Resurrection", cost: 25, mode: "uses", fixedAmount: 1, unit: "use",
          ask: "resurrection: one chance to bring a fallen body back to life",
          power: { use: "body", resurrection: true,
            summary: "Bring a dead or fallen body back to life. Used from the body's own menu.",
            castLines: {
                healer: "You kneel over the body and pour out everything the Healer gives you. Mercy answers.",
                guardian: "You stand over the fallen and call the Guardian to keep what is theirs. Duty answers.",
                titan: "You set your hands on the body and demand it rise. The Titan's strength answers.",
                trickster: "You grin at death and spin the Trickster's coin over the body. It lands on life.",
                outcast: "You call the forsaken back from the dark. The Outcast lets this one go." } } }
    ],
    guardian: [
        makeRegrowthFavor("regrowthGuardian", "You stand where the loss is and ask the Guardian to make you whole to keep your post. Duty answers: the stump fills out, and a sound limb takes its place."),
        { id: "divineWard", name: "Divine Ward", cost: 15, mode: "duration", unit: "rounds",
          ask: "a divine ward: a short time of complete immunity to physical damage",
          power: { use: "any", buff: "divineWard",
            summary: "Become immune to all physical damage for a short time. Elemental harm still hurts.",
            castLine: "You raise your hand and the Guardian's ward closes around you like a wall of light." } }
    ],
    titan: [
        makeRegrowthFavor("regrowthTitan", "You grit your teeth and demand the Titan's strength take back what was cut away. Bone thickens, muscle snaps taut, and the limb is yours again."),
        { id: "titansWrath", name: "Titan's Wrath", cost: 12, mode: "uses", unit: "uses",
          ask: "the Titan's wrath: several uses of a devastating blow that can stun",
          power: { use: "combat", damage: { die: 10, bonus: 5, type: "blunt", stunChance: 0.4, outcome: "unconscious" },
            summary: "A crushing blow of d10+5 and your willpower bonus, with a 40% chance to stun.",
            castLine: "You bellow the Titan's name and bring the full weight of a mountain down.",
            hitLine: "The blow crashes into {name}.", heavyLine: "The Titan's wrath lands on {name} like a falling mountain.",
            stunLine: "{name} reels, stunned by the force of it!" } }
    ],
    trickster: [
        makeRegrowthFavor("regrowthTrickster", "You flip the Trickster's coin and call it for the limb. It lands on your side with a grin, and the arm or leg is back as if it had only been hiding."),
        { id: "shapeshifter", name: "Shapeshifter", cost: 20, mode: "uses", fixedAmount: 3, unit: "uses",
          ask: "the shapeshifter's gift: three chances to cast off who you are and become someone entirely new, a stranger to everyone you have met, with the chance to return to yourself. Spend the last chance and the new shape is yours for good",
          power: { use: "world", shapeshift: true,
            summary: "Re-roll your species and looks and become a stranger to everyone (every relationship resets, your patron's excepted). Three uses. You can Revert while a use remains; spend the last one and the new shape is permanent.",
            castLine: "You flip an imaginary coin. The Trickster catches it, grins, and your bones begin to slide." } }
    ],
    outcast: [
        makeRegrowthFavor("regrowthOutcast", "You offer what little the forsaken have left to the Outcast. The dark gives it back, and shadow knits into flesh until the limb is whole."),
        { id: "veilOfTheForsaken", name: "Veil of the Forsaken", cost: 12, mode: "duration", unit: "rounds",
          ask: "the veil of the forsaken: a short time of true invisibility that attacks and blows cannot break",
          power: { use: "any", buff: "veiled",
            summary: "Become invisible for a short time. Guards, ambushes and watchers cannot find you, and fighting does not break it.",
            castLine: "You draw the dark over yourself and the world forgets you are there." } }
    ]
};

// When a favor is granted the patron's power moves through the player: a
// surge, a moment where the god's will holds their body, then the return of
// their own. The patron writes this itself in the judgment (the "surge" field);
// these are the fallback when it does not.
const FAVOR_SURGE_LINES = {
    healer: "Warmth pours through you in a slow, golden tide, and for a heartbeat a gentle will takes your hands and moves them as its own, tender and unhurried, before letting go. Your skin tingles with borrowed mercy, and your faculties are yours again.",
    guardian: "A steady, immovable force settles over you like armour made of light. For a moment a vigilant will stands in your body and holds your gaze on the horizon, before it steps back and returns your limbs to you. Your skin prickles with the memory of it.",
    titan: "Strength crashes through you like a landslide. For one moment a vast will takes hold of your body, your fists clench and your spine locks straight, and then it releases you, trembling and humming, with your own mind back in its place.",
    trickster: "A giggle runs up your spine, and a bright, mischievous will snatches your body for a heartbeat. Your fingers snap, your head tilts, a coin you never held spins in your palm, and then it lets go, leaving you grinning and dizzy.",
    outcast: "The dark folds around you like an old friend's arm. A quiet, bitter will slips into your limbs and walks you a single step through the shadows, then lets you go, and the cold of it tingles on your skin as your faculties return."
};

// When a granted gift is all used up (the last use, or the moment a timed
// effect ends) the power leaves the body. The patron writes this too (the
// "fade" field of the judgment); these are the fallback.
const FAVOR_FADE_LINES = {
    healer: "The warmth drains out of you like water from cupped hands, and your wounds and weariness feel suddenly close again. Did you always feel this fragile?",
    guardian: "The light that held you upright withdraws, and the world is abruptly full of edges. Did you always feel this exposed?",
    titan: "The surge of power in your body ebbs like a tide going out, leaving your arms light and foolish. Did you always feel this small and weak?",
    trickster: "The luck goes out of the air like a snuffed candle, and the world is tediously, horribly ordinary again. Did you always feel this helpless?",
    outcast: "The dark lets go of you, and the cold that follows feels like being left behind all over again. Did you always feel this alone?"
};

// ── SHAPESHIFTER (the Trickster's gift) ──────────────────────────
// Three uses. Each use re-rolls (uniformly at random, the Trickster's way) the player's species, undead included (skeleton, ghost), and physical traits
// (player.appearance: species, somatotype, build, hair, eyes, skin) and gender,
// with the size fields following the new gender (never the name) and resets every NPC's relationship with the player to a
// stranger's, since nobody knows the new face. Companions who travelled with the
// player are released for the same reason. Revert (a second, free entry that
// shows while the player is in a borrowed shape) restores the original looks and
// the relationships that were set aside, as long as a use remains; spending the
// last use locks the new shape in for good and the set-aside relationships are
// discarded. A patron's own faith is not a relationship with an NPC and is never
// touched. State: player.shapeshift = { active, original, locked }.
const SHAPESHIFT_REVERT_COSTS_USE = false;
const SHAPESHIFT_OPTIONS = {
    species: ["human", "elf", "dwarf", "halfling", "dragonborn", "orc", "goblin", "lizardfolk", "kobold", "catfolk", "wolfkin", "satyr", "skeleton", "rat", "ghost", "slime"],   // fallback; the roll uses every SPECIES_TEMPLATES entry
    somatotype: ["ectomorph", "mesomorph", "endomorph"],
    build: ["lean", "athletic", "sturdy", "broad", "soft", "slight"],
    hairColor: ["black", "dark brown", "brown", "auburn", "red", "blond", "gray", "white"],
    hairStyle: ["cropped", "short", "loose", "long", "braided", "tied back", "curly", "messy"],
    eyeColor: ["brown", "hazel", "green", "blue", "gray", "amber"],
    skinTone: ["fair", "light", "olive", "tan", "brown", "dark brown", "deep brown"]
};
// The per-NPC fields that make up "what they think of the player". The NPC's
// own name and what the player has learned (nameKnown, loreTold, trade history)
// stay: the player is the one who changed, not the world.
const SHAPESHIFT_NPC_MEMORY_KEYS = ["metPlayer", "everGreeted", "favorability", "lastMood", "playerActions",
    "playerActionTags", "recentLines", "aggressionCount", "cachedReplies", "cachedReplySigs", "lastSpokenTo",
    "attraction", "attractionEarned", "attractionSwing", "lust", "arousal", "disinhibition", "actDisinhibition",
    "conversationState", "typedTones", "typeAlignmentGain", "firstImpressionDone", "speciesReactionDone", "pendingResponse",
    "crimeDisapproval", "leftFollowing", "leftAckTurn", "leftOverLoot", "leftOverCrime",
    "memoryEntries", "memoryTier", "knownDeeds", "sawDeeds", "namedDeeds", "toldDeeds", "reportPending", "reportTurn", "giftedDeeds", "intimidation"];

function getShapeshiftState(player) {
    const p = player || G.player;
    if (!p) return null;
    if (!p.shapeshift || typeof p.shapeshift !== "object") p.shapeshift = { active: false, original: null, locked: false };
    return p.shapeshift;
}

function isPlayerShapeshifted(player) {
    const st = getShapeshiftState(player);
    return !!(st && st.active);
}

function shapeshiftEachNPC(fn) {
    const seen = new Set();
    const visit = function (n) {
        if (!n || typeof n !== "object" || seen.has(n)) return;
        seen.add(n);
        fn(n);
    };
    const map = G.roomMap && typeof G.roomMap === "object" ? G.roomMap : {};
    Object.keys(map).forEach(function (k) {
        const room = map[k];
        if (room && Array.isArray(room.creatures)) room.creatures.forEach(visit);
    });
    (G.partyMembers || []).forEach(visit);
    (G.sessionFollowers || []).forEach(visit);
}

function snapshotNPCRelationship(npc) {
    const snap = { hostility: npc.hostility, memory: {} };
    const mem = npc.memory || {};
    SHAPESHIFT_NPC_MEMORY_KEYS.forEach(function (k) {
        if (Object.prototype.hasOwnProperty.call(mem, k) && typeof mem[k] !== "undefined") {
            snap.memory[k] = JSON.parse(JSON.stringify(mem[k]));
        }
    });
    return snap;
}

function clearNPCRelationshipMemory(npc) {
    SHAPESHIFT_NPC_MEMORY_KEYS.forEach(function (k) { delete npc.memory[k]; });
}

// A stranger's blank slate (the same defaults a freshly made NPC starts with).
function resetNPCRelationshipToStranger(npc) {
    clearNPCRelationshipMemory(npc);
    const m = npc.memory;
    m.metPlayer = false;
    m.everGreeted = false;
    m.lastMood = "neutral";
    m.playerActions = [];
    m.playerActionTags = [];
    m.recentLines = [];
    m.aggressionCount = 0;
    m.cachedReplies = {};
    m.lastSpokenTo = 0;
    m.favorability = typeof getBaseFavorabilityForTemperament === "function"
        ? getBaseFavorabilityForTemperament(npc.temperament)
        : (npc.temperament === "hostile" ? -40 : 0);
    // Attraction is re-derived from the new looks at the next interaction
    // (recomputeNPCAttraction), starting with nothing earned.
    m.attraction = 0;
    m.attractionEarned = 0;
    m.lust = 0;
    m.arousal = 0;
    m.disinhibition = 0;
    m.actDisinhibition = {};
    if (typeof getBaseHostilityForTemperament === "function") npc.hostility = getBaseHostilityForTemperament(npc.temperament);
}

function restoreNPCRelationship(npc) {
    const snap = npc._trueSelf;
    if (!snap) { resetNPCRelationshipToStranger(npc); return; }
    clearNPCRelationshipMemory(npc);
    Object.keys(snap.memory).forEach(function (k) { npc.memory[k] = snap.memory[k]; });
    if (typeof snap.hostility === "number") npc.hostility = snap.hostility;
    delete npc._trueSelf;
}

// Every species template in the world data, uniformly (undead and beasts included).
function getShapeshiftSpeciesPool() {
    if (typeof SPECIES_TEMPLATES !== "undefined" && Array.isArray(SPECIES_TEMPLATES) && SPECIES_TEMPLATES.length) {
        const names = SPECIES_TEMPLATES.map(function (t) { return t && t.species ? String(t.species).toLowerCase() : ""; }).filter(Boolean);
        if (names.length) return names;
    }
    return SHAPESHIFT_OPTIONS.species;
}

function shapeshiftPick(list, current) {
    const pool = list.filter(function (v) { return v !== current; });
    const from = pool.length ? pool : list;
    return from[Math.floor(Math.random() * from.length)];
}

function describeShapeshiftForm(a, gender) {
    const bits = [];
    if (a.build) bits.push(a.build + " build");
    if (a.hairColor) bits.push(a.hairColor + " hair" + (a.hairStyle ? " (" + a.hairStyle + ")" : ""));
    if (a.eyeColor) bits.push(a.eyeColor + " eyes");
    if (a.skinTone) bits.push(a.skinTone + " skin");
    return "a " + (gender && gender !== "none" ? gender + " " : "") + (a.species || "human") + (bits.length ? ", with " + bits.join(", ") : "");
}

// Shapes that cannot wear or hold things (a rat, a ghost; a skeleton can, so it
// keeps its gear) let everything they were wearing or wielding fall where they
// stand. Add a species name here to give another shape the same rule.
const SHAPESHIFT_NO_GEAR_SPECIES = ["rat", "ghost", "slime"];

// A body that cannot wear or hold things lets everything it was wearing or wielding
// fall where it stands. Coins stay; the pack stays; the gear lies on the floor of
// the current room to be picked up again.
function dropEquipmentForShape(lines) {
    if (!G.player) return 0;
    ensurePlayerEquipmentState(G.player);
    let dropped = 0;
    getPlayerEquipmentSlots().forEach(function (slot) {
        if (slot === "coinPouch") return;
        const item = G.player.equipped && G.player.equipped[slot];
        if (!item || Array.isArray(item)) return;
        if (dropEquippedItemToRoom(slot)) dropped++;
    });
    if (dropped) lines.push("Your gear slides off a body that can no longer wear it and clatters to the floor around you.");
    return dropped;
}

function releaseCompanionsForShapeshift(lines) {
    const left = [];
    (G.partyMembers || []).slice().forEach(function (m) { left.push(m); removeFromParty(m); });
    (G.sessionFollowers || []).slice().forEach(function (f) { if (left.indexOf(f) < 0) left.push(f); removeSessionFollower(f); });
    if (left.length) lines.push("Those who travelled with you look at the stranger you have become and do not know you. They drift away.");
}

// One use of Shapeshifter: re-roll the form, reset every relationship.
// `lastUse` is true when this consumed the final use (the new shape is permanent).
function performShapeshift(lines, lastUse) {
    const player = G.player;
    const st = getShapeshiftState(player);
    if (!player.appearance || typeof player.appearance !== "object") player.appearance = {};
    const a = player.appearance;
    if (!st.active) {
        // First shift of this gift: remember who you were, and what they thought of you.
        st.original = {};
        Object.keys(SHAPESHIFT_OPTIONS).forEach(function (k) { st.original[k] = a[k]; });
        st.original.gender = player.gender;
        st.original.statsGender = player.stats ? player.stats.gender : undefined;
        st.original.penisSize = a.penisSize;
        st.original.vaginaSize = a.vaginaSize;
        shapeshiftEachNPC(function (npc) {
            if (npc.memory && !npc._trueSelf) npc._trueSelf = snapshotNPCRelationship(npc);
        });
        st.active = true;
        st.locked = false;
    }
    Object.keys(SHAPESHIFT_OPTIONS).forEach(function (k) {
        a[k] = shapeshiftPick(k === "species" ? getShapeshiftSpeciesPool() : SHAPESHIFT_OPTIONS[k], a[k] || (k === "species" ? "human" : undefined));
    });
    // Gender is re-rolled too (male, female or non-binary, never the current one),
    // and the size fields follow the same gating as character setup
    // (genitalGateForGender): only the ones that apply to the new gender exist.
    const curGender = String(player.gender || (player.stats && player.stats.gender) || "male").toLowerCase();
    player.gender = shapeshiftPick(["male", "female", "non-binary"], curGender);
    if (player.stats && typeof player.stats.gender !== "undefined") player.stats.gender = player.gender;
    const gate = typeof genitalGateForGender === "function" ? genitalGateForGender(player.gender) : "penis";
    const sizes = ["small", "medium", "large"];
    if (gate === "penis" || gate === "both") a.penisSize = shapeshiftPick(sizes, a.penisSize); else delete a.penisSize;
    if (gate === "vagina" || gate === "both") a.vaginaSize = shapeshiftPick(sizes, a.vaginaSize); else delete a.vaginaSize;
    releaseCompanionsForShapeshift(lines);
    shapeshiftEachNPC(function (npc) {
        if (npc.memory) resetNPCRelationshipToStranger(npc);
    });
    lines.push("When it settles you are " + describeShapeshiftForm(a, player.gender) + ". Nobody here has ever seen you before.");
    if (SHAPESHIFT_NO_GEAR_SPECIES.indexOf(String(a.species).toLowerCase()) >= 0) dropEquipmentForShape(lines);
    if (lastUse) lockInShapeshift(lines);
    rememberStoryEvent("faith", player.name + " took a new shape through the Trickster's gift.", 6, { tags: ["faith", "shapeshift"] });
}

function lockInShapeshift(lines) {
    const st = getShapeshiftState(G.player);
    st.active = false;
    st.original = null;
    st.locked = true;
    shapeshiftEachNPC(function (npc) { delete npc._trueSelf; });
    if (lines) lines.push("The shape sets like cooling wax, and you feel the road back close behind you. This is who you are now.");
}

function performShapeshiftRevert(lines) {
    const player = G.player;
    const st = getShapeshiftState(player);
    if (!st.active || !st.original) return;
    if (!player.appearance || typeof player.appearance !== "object") player.appearance = {};
    Object.keys(SHAPESHIFT_OPTIONS).forEach(function (k) {
        if (typeof st.original[k] === "undefined") delete player.appearance[k]; else player.appearance[k] = st.original[k];
    });
    if (typeof st.original.gender === "undefined") delete player.gender; else player.gender = st.original.gender;
    if (player.stats && typeof st.original.statsGender !== "undefined") player.stats.gender = st.original.statsGender;
    ["penisSize", "vaginaSize"].forEach(function (k) {
        if (typeof st.original[k] === "undefined") delete player.appearance[k]; else player.appearance[k] = st.original[k];
    });
    releaseCompanionsForShapeshift(lines);
    shapeshiftEachNPC(function (npc) {
        if (npc.memory) restoreNPCRelationship(npc);
    });
    st.active = false;
    st.original = null;
    lines.push("You are yourself again: " + describeShapeshiftForm(player.appearance, player.gender) + ". Those who knew you know you once more; those you met in the other shape never knew you at all.");
}

let favorRequestPending = false;

function findFavorDef(favorId) {
    const ids = Object.keys(DEITY_FAVOR_DEFS);
    for (let i = 0; i < ids.length; i++) {
        const hit = DEITY_FAVOR_DEFS[ids[i]].find(function (d) { return d.id === favorId; });
        if (hit) return hit;
    }
    return null;
}

function getFavorCost(def, amount) {
    if (def.fixedAmount) return def.cost;
    return Math.max(1, Math.ceil(def.cost * amount / FAVOR_NORMAL_AMOUNT));
}

function getFavorMinCost(def) {
    return def.fixedAmount ? def.cost : getFavorCost(def, 1);
}

// Largest amount (0 if none) the deity could pay for with `power` on hand.
function getMaxAffordableFavorAmount(def, power) {
    if (def.fixedAmount) return power >= def.cost ? def.fixedAmount : 0;
    for (let a = FAVOR_MAX_AMOUNT; a >= 1; a--) {
        if (getFavorCost(def, a) <= power) return a;
    }
    return 0;
}

function ensureDivineBoons(player) {
    if (!player) return [];
    if (!Array.isArray(player.divineBoons)) player.divineBoons = [];
    return player.divineBoons;
}

// Unused powers fade; expired ones are dropped whenever the list is read.
function getDivineBoons(player) {
    const list = ensureDivineBoons(player);
    const now = getCurrentStoryTurn();
    for (let i = list.length - 1; i >= 0; i--) {
        if (!list[i] || !findFavorDef(list[i].favorId)) { list.splice(i, 1); continue; }
        if (typeof list[i].expiresAtTurn === "number" && list[i].expiresAtTurn <= now) {
            // An unused gift fades with time.
            queueTurnNote(list[i].fade || FAVOR_FADE_LINES[list[i].deityId] || "");
            list.splice(i, 1);
        }
    }
    return list;
}

function getGrantedPowers(player) {
    return getDivineBoons(player).map(function (boon) {
        const def = findFavorDef(boon.favorId);
        const spec = Object.assign({}, def.power, {
            id: boon.id, name: def.name, manaCost: 0, minFaith: 0, minRank: 0,
            granted: true, boonId: boon.id, usesLeft: boon.usesLeft,
            fadeText: boon.fade || FAVOR_FADE_LINES[boon.deityId] || ""
        });
        if (def.mode === "duration") {
            spec.durationTurns = boon.amount;
            spec.summary = def.power.summary + ` Lasts ${boon.amount} rounds.`;
        }
        return spec;
    }).reduce(function (all, spec) {
        all.push(spec);
        // Shapeshifter: while you wear a borrowed shape a free Revert sits beside it.
        if (spec.shapeshift && isPlayerShapeshifted(player)) {
            all.push(Object.assign({}, spec, {
                id: "revert-" + spec.boonId, name: "Revert", shapeshift: false, shapeshiftRevert: true,
                free: !SHAPESHIFT_REVERT_COSTS_USE, costLabel: SHAPESHIFT_REVERT_COSTS_USE ? "uses a charge" : "free",
                summary: "Return to your own shape and the relationships you had. Available only while a use of Shapeshifter remains: spend the last one and the new shape is permanent.",
                castLine: "You reach for the shape you were born to, and it comes back to you like an old coat."
            }));
        }
        return all;
    }, []);
}

// Returns the fade-out narration when this was the last use of a counted gift
// (timed gifts fade when their effect ends instead, see setStatusFadeText), else "".
function consumeBoonUse(boonId) {
    const list = ensureDivineBoons(G.player);
    const idx = list.findIndex(function (b) { return b && b.id === boonId; });
    if (idx < 0) return "";
    list[idx].usesLeft -= 1;
    if (list[idx].usesLeft > 0) return "";
    const boon = list.splice(idx, 1)[0];
    const def = findFavorDef(boon.favorId);
    return def && def.mode === "uses" ? (boon.fade || FAVOR_FADE_LINES[boon.deityId] || "") : "";
}

// Remembers what to say when this effect on the entity ends (see
// pruneExpiredStatusEffects): the patron's power leaving the body.
function setStatusFadeText(entity, key, text) {
    if (!entity || !text) return;
    const effect = ensureStatusEffects(entity).find(function (e) { return e.key === key; });
    if (effect) effect.fadeText = text;
}

function playerHoldsFavor(player, favorId) {
    return getDivineBoons(player).some(function (b) { return b.favorId === favorId; });
}

function grantDivineBoon(player, def, amount, surge, fade) {
    const list = ensureDivineBoons(player);
    list.push({
        surge: surge || "",
        fade: fade || "",
        surgeShown: false,
        id: "boon-" + getCurrentStoryTurn() + "-" + randInt(100, 999),
        favorId: def.id,
        deityId: player.deity,
        amount: amount,
        usesLeft: def.mode === "uses" ? amount : 1,
        expiresAtTurn: getCurrentStoryTurn() + FAVOR_BOON_LIFETIME_TURNS
    });
}

// Full health and stamina, bleeding stopped (the surge that comes with a gift).
function restorePlayerFully(player) {
    if (typeof player.hpMax === "number") player.hp = player.hpMax;
    ensureEntityStamina(player);
    if (typeof player.staminaMax === "number") player.stamina = player.staminaMax;
    clearPlayerBleeding(player);
    if (typeof closeAllWounds === "function") closeAllWounds(player, 1);
}

// The first time a granted power is used (and only then, however many uses or
// rounds it has) the patron's power moves through the player: the surge the
// patron wrote when it granted the gift, a full restore, and a line saying how
// long the gift lasts. Call BEFORE consumeBoonUse. Returns the lines to show.
function takeBoonFirstUseLines(power) {
    const player = G.player;
    const boon = power && power.boonId ? ensureDivineBoons(player).find(function (b) { return b && b.id === power.boonId; }) : null;
    if (!boon || boon.surgeShown) return [];
    boon.surgeShown = true;
    const def = findFavorDef(boon.favorId);
    const lines = [];
    lines.push(boon.surge || FAVOR_SURGE_LINES[boon.deityId] || "Divine power rushes through you.");
    restorePlayerFully(player);
    lines.push("Fatigue and ailments wash away, and your wounds close: you are whole and rested.");
    if (def && def.mode === "uses") {
        const left = boon.usesLeft - 1;
        lines.push(left > 0 ? `You can call on ${def.name} ${left} more time${left === 1 ? "" : "s"}.` : `This is the last use of ${def.name}.`);
    } else if (def) {
        lines.push(`${def.name} will hold for ${boon.amount} rounds.`);
    }
    return lines;
}

function describeFavorAmount(def, amount) {
    if (def.mode === "uses") return amount === 1 ? "one use" : `${amount} uses`;
    return `one use, lasting ${amount} rounds`;
}

// Why the player cannot ask their patron for anything right now, or "".
function getFavorRequestBlockReason(room) {
    const player = G.player;
    if (!player || !room || !isShrineRoom(room)) return "There is no shrine here.";
    const deity = getDeityArchetype(player.deity);
    if (!deity) return "You have no patron to ask.";
    ensurePlayerFaithState(player);
    const faith = player.faith ? player.faith.score : 0;
    if (faith <= FAVOR_FAITH_THRESHOLD) return `Your faith (${faith}) is not yet strong enough to ask a favor. It must be above ${FAVOR_FAITH_THRESHOLD}.`;
    if (favorRequestPending) return "Your prayer is still being answered.";
    const block = getPrayerBlockReason(room, room, "favor");
    if (block) return block;
    if (getDivinePower(player.deity) < 1) return `${deity.name} is too weak to grant a favor now.`;
    return "";
}

function getFavorOptionBlockReason(player, option) {
    const deity = getDeityArchetype(player.deity);
    const power = getDivinePower(player.deity);
    if (option.kind === "stat") {
        if (hasActiveStatusEffect(player, option.def.effect)) return "You are already blessed in this.";
        if (power < FAVOR_STAT_COST / FAVOR_NORMAL_AMOUNT) return `${deity.name} is too weak to grant this now.`;
        return "";
    }
    if (playerHoldsFavor(player, option.def.id)) return "You already hold this gift.";
    if (option.def.power && option.def.power.regrow && !getSeveredLimbKeys(player).length) return "You have no lost limb to restore.";
    if (power < getFavorMinCost(option.def)) return `${deity.name} is too weak to grant this now.`;
    return "";
}

function buildFavorJudgmentInstruction(deity, player, option, maxAmount, normCost) {
    const traits = getPlayerTraitCounts();
    const traitSummary = Object.keys(traits)
        .filter(function (key) { return typeof traits[key] === "number" && traits[key] > 0; })
        .map(function (key) { return `${key} (${traits[key]})`; })
        .join(", ");
    const dominantTrait = getPlayerDominantTrait();
    const recentEvents = (G.story && Array.isArray(G.story.recentEvents) ? G.story.recentEvents : [])
        .slice(0, 8).map(function (evt) { return evt && evt.text; }).filter(Boolean);
    const knownFacts = (G.story && Array.isArray(G.story.discoveredFacts) ? G.story.discoveredFacts : []).slice(-12);
    const faith = player.faith ? player.faith.score : 0;
    const askText = option.kind === "stat"
        ? `a blessing to strengthen their ${option.def.label} for a time (+2, lasting about ${FAVOR_STAT_TURNS_PER_UNIT} turns per unit of amount)`
        : option.def.ask;
    const unit = option.kind === "stat" ? "tens of turns" : (option.def.unit || "uses");
    return [
        `You are ${deity.name}, a deity in a fantasy roleplay game, god of ${deity.domain}.`,
        deity.lore,
        `Your values: ${deity.judgmentCriteria}`,
        `${player.name}, a ${player.class || "adventurer"} who follows you, kneels at a shrine and asks you for ${askText}.`,
        `Their faith in you stands at ${faith}. Anyone above ${FAVOR_FAITH_THRESHOLD} may ask; the higher it goes, the more devoted they have shown themselves to be.`,
        dominantTrait ? `Their dominant personality trait is "${dominantTrait}".` : "",
        traitSummary ? `Their personality profile (from tallied choices): ${traitSummary}.` : "",
        recentEvents.length ? `Recent events in their life: ${recentEvents.join(" | ")}` : "They have no notable recent history.",
        knownFacts.length ? `Other things known about their story: ${knownFacts.join(" | ")}` : "",
        typeof buildDeityLensLine === "function" ? buildDeityLensLine(deity) : "",
        `Granting costs you divine power, about ${normCost} for the norm of ${FAVOR_NORMAL_AMOUNT} ${unit}, scaling with the amount. You hold ${getDivinePower(deity.id)}, so you can pay for at most ${maxAmount}. Divine power is precious: spend it only on requests you judge worthy.`,
        "Decide, in your own voice and by your own values, whether this request is worthy. Refuse frivolous, self-serving or unfitting requests, and any that do not suit who you are. If you grant it, choose the amount: " + FAVOR_NORMAL_AMOUNT + " is the norm; give fewer if you are grudging or lukewarm, and up to " + Math.min(FAVOR_MAX_AMOUNT, maxAmount) + " only if they have truly earned it.",
        "Return ONLY valid JSON, no markdown fences, no commentary, in exactly this shape:",
        "{\"grant\":true or false,\"amount\":a whole number from 1 to " + Math.min(FAVOR_MAX_AMOUNT, maxAmount) + ",\"verdict\":\"1 to 3 sentences, in your voice as the deity, speaking directly to the mortal\",\"surge\":\"only if you grant it: 2 to 3 sentences in second person, no quotation marks, describing how your power rushes through the mortal's body in a way that fits your nature (a surge of energy, tingling skin), including a brief moment where your will takes hold of their body before it fades and returns their faculties to them\",\"fade\":\"only if you grant it: 1 to 2 sentences in second person, no quotation marks, describing the power leaving their body when the gift is spent, in a way that fits your nature, leaving them feeling weak and bereft and wondering whether they always felt this helpless\"}"
    ].filter(Boolean).join("\n");
}

function parseFavorJudgmentPayload(rawText) {
    const parsed = typeof tryParseConversationJSON === "function" ? tryParseConversationJSON(rawText) : null;
    if (!parsed || typeof parsed !== "object") return null;
    const verdict = typeof parsed.verdict === "string" ? parsed.verdict.trim() : "";
    if (!verdict) return null;
    const amount = Math.round(Number(parsed.amount));
    const surge = typeof parsed.surge === "string" ? parsed.surge.trim() : "";
    const fade = typeof parsed.fade === "string" ? parsed.fade.trim() : "";
    return { grant: parsed.grant === true, amount: isFinite(amount) ? amount : FAVOR_NORMAL_AMOUNT, verdict: verdict, surge: surge, fade: fade };
}

// option: { kind: "stat", statKey, def } or { kind: "power", def }
async function requestFavor(option) {
    if (!shrineServiceExecution || shrineServiceExecution.spec.action !== "favor") return requestShrineService("favor", option);
    const serviceContext = shrineServiceExecution;
    const serviceNarration = function (message) { return shrineServiceNarration(message, serviceContext); };
    const player = G.player;
    const room = G.activeRoom;
    if (!player || !room || !option || !option.def) return;
    const block = getFavorRequestBlockReason(room) || getFavorOptionBlockReason(player, option);
    if (block) { serviceNarration(block); return; }
    const deity = getDeityArchetype(player.deity);
    const label = option.kind === "stat" ? `a blessing of ${option.def.label}` : option.def.name;

    // Asking is a prayer: it costs what any prayer costs, whatever the answer.
    favorRequestPending = true;
    ensureEntityStamina(player);
    const serviceStaminaBefore = player.stamina;
    player.stamina = Math.max(0, player.stamina - PRAYER_STAMINA_COST);
    serviceContext.staminaSpent = serviceStaminaBefore - player.stamina;
    shrineServiceStart(serviceContext);
    advanceStoryTurn(PRAYER_TURNS);
    if (!shrineServiceCurrent(serviceContext)) return shrineServiceInterrupted(serviceContext);
    room.lastFavorTurn = getCurrentStoryTurn();
    adjustDivinePower(player.deity, DIVINE_PRAYER_GAIN);
    rememberStoryEvent("faith", `${player.name} asked ${deity.name} for ${label}.`, 4, { tags: ["faith", "prayer", "favor"] });
    renderStats();
    if (!shrineServiceCapture(serviceContext)) renderFavorMenu();
    serviceNarration(`You kneel and ask ${deity.name} for ${label}...`);

    if (!shrineServiceBeforeAnswer(serviceContext)) return { status: "interrupted" };
    const costDef = option.kind === "stat" ? { cost: FAVOR_STAT_COST } : option.def;
    const maxAmount = option.kind === "stat"
        ? getMaxAffordableFavorAmount({ cost: FAVOR_STAT_COST }, getDivinePower(player.deity))
        : getMaxAffordableFavorAmount(option.def, getDivinePower(player.deity));
    let judgment = null;
    try {
        if (aiAvailable()) {
            const instruction = buildFavorJudgmentInstruction(deity, player, option, maxAmount, costDef.fixedAmount ? costDef.cost : getFavorCost(costDef, FAVOR_NORMAL_AMOUNT));
            const jsonPrefix = "{\"grant\":";
            const result = await callAI({ instruction: instruction, startWith: jsonPrefix, endButtons: "none" });
            const continuation = typeof result === "string" ? result : (result && result.text ? result.text : "");
            const rawText = String(continuation || "").trim().startsWith("{")
                ? String(continuation || "").trim()
                : `${jsonPrefix}${String(continuation || "").trim()}`;
            judgment = parseFavorJudgmentPayload(rawText);
        }
    } catch (e) {
        console.warn("Favor judgment failed:", e);
    }
    if (!shrineServiceAnswerCurrent(serviceContext)) return shrineServiceInterrupted(serviceContext);
    // Use AI off: the deity's answer is a weighted roll instead of a judgment.
    if (!judgment && !useAIEnabled()) {
        const granted = Math.random() < Math.max(0.05, Math.min(0.95, AI_OFF_FAVOR_GRANT_CHANCE + (typeof getDeityLensChanceShift === "function" ? getDeityLensChanceShift(deity) : 0)));
        judgment = {
            grant: granted,
            amount: FAVOR_NORMAL_AMOUNT,
            verdict: granted
                ? `${deity.name} hears you and answers.`
                : `${deity.name} does not answer this time.`
        };
    }
    // No AI or a malformed answer: do not punish the player for it. The norm is granted.
    if (!judgment) judgment = { grant: true, amount: FAVOR_NORMAL_AMOUNT, verdict: `${deity.name} says nothing, but the gift is given.` };

    shrineServiceRelease(serviceContext);
    shrineServiceRecord(serviceContext, { granted: false, amount: 0, patronPowerSpent: 0 });
    let text = judgment.verdict;
    // Re-read the pool: it can have moved while the answer was coming.
    const affordable = option.kind === "stat"
        ? getMaxAffordableFavorAmount({ cost: FAVOR_STAT_COST }, getDivinePower(player.deity))
        : getMaxAffordableFavorAmount(option.def, getDivinePower(player.deity));
    const amount = option.def.fixedAmount
        ? option.def.fixedAmount
        : Math.max(1, Math.min(FAVOR_MAX_AMOUNT, affordable, judgment.amount));

    if (!judgment.grant) {
        text += " Your request is refused.";
        rememberStoryEvent("faith", `${deity.name} refused ${player.name}'s request for ${label}.`, 4, { tags: ["faith", "favor-refused"] });
    } else if (affordable < 1) {
        text += ` But ${deity.name} has not the strength to give it.`;
    } else {
        const cost = option.kind === "stat" ? getFavorCost({ cost: FAVOR_STAT_COST }, amount) : getFavorCost(option.def, amount);
        adjustDivinePower(player.deity, -cost);
        shrineServiceRecord(serviceContext, { granted: true, amount: amount, patronPowerSpent: cost });
        const surgeText = judgment.surge || FAVOR_SURGE_LINES[player.deity] || "";
        if (option.kind === "stat") {
            const turns = amount * FAVOR_STAT_TURNS_PER_UNIT;
            const msg = applyStatusEffect(player, option.def.effect, player.name || "You", { isPlayer: true, durationTurns: turns });
            setStatusFadeText(player, option.def.effect, judgment.fade || FAVOR_FADE_LINES[player.deity]);
            text += ` ${surgeText} ${msg || ""} You feel your ${option.def.label} sharpened (+2) for about ${turns} turns.`;
        } else {
            grantDivineBoon(player, option.def, amount, surgeText, judgment.fade);
            text += ` ${deity.name} grants you ${option.def.name} (${describeFavorAmount(option.def, amount)}). It waits in your Powers menu.`;
        }
        rememberStoryEvent("faith", `${deity.name} granted ${player.name} ${label} (${amount}).`, 6, { tags: ["faith", "favor-granted"] });
    }

    renderStats();
    if (!shrineServiceCapture(serviceContext)) renderFavorMenu();
    serviceNarration(text.replace(/\s+/g, " ").trim());
    saveGameState();
}

function renderFavorMenu() {
    if (shrineServiceCapture(shrineServiceExecution) || shrineSceneBlock()) return;
    const el = document.getElementById("chatOptionsEl");
    const player = G.player;
    if (!el || !player) return;
    el.innerHTML = "";
    const deity = getDeityArchetype(player.deity);
    if (!deity) { renderShrinePrayerMenu(); return; }
    const room = G.activeRoom;
    const baseBlock = getFavorRequestBlockReason(room);
    const favorMenu = beginShrineMenu("shrine-favor", "Ask your patron for a favor — " + PRAYER_STAMINA_COST + " stamina, " + PRAYER_TURNS + " turns, " + PRAYER_COOLDOWN_TURNS + "-turn favor cooldown, whatever the answer. Patron power costs and amounts vary.");

    const statButtons = Object.keys(FAVOR_STAT_DEFS).map(function (statKey) {
        const option = { kind: "stat", statKey: statKey, def: Object.assign({ id: "stat:" + statKey }, FAVOR_STAT_DEFS[statKey]) };
        const block = baseBlock || getFavorOptionBlockReason(player, option);
        return shrineServiceButton(favorMenu, `${option.def.label} (about ${FAVOR_STAT_COST} power)`, "favor", option, {
            disabled: !!block,
            title: block || `+2 ${option.def.label} for a time. A short blessing.`
        });
    });
    appendCombatGroup(el, "Ask for a blessing", statButtons);

    const gifts = (DEITY_FAVOR_DEFS[player.deity] || []).map(function (def) {
        const option = { kind: "power", def: def };
        const block = baseBlock || getFavorOptionBlockReason(player, option);
        return shrineServiceButton(favorMenu, `${def.name} (about ${def.cost} power)`, "favor", option, {
            disabled: !!block,
            title: block || def.power.summary + " A one-time gift, held in your Powers menu."
        });
    });
    if (gifts.length) appendCombatGroup(el, `${deity.name}'s gifts`, gifts);

    appendCombatGroup(el, "", [createSharedChoiceButton(favorMenu, "Back", function () { renderShrinePrayerMenu(); return { status: "needs_input" }; }, { disabled: favorRequestPending, textChoice: { action: "back" } })]);
    publishShrineMenu(favorMenu, el);
}

function renderShrinePrayerMenu() {
    if (shrineCaptureMenu()) return;
    if (shrineSceneBlock()) return;
    const el = document.getElementById("chatOptionsEl");
    if (!el) return;
    el.innerHTML = "";

    const player = G.player;
    ensurePlayerDeityState(player);

    const room = G.activeRoom;
    const dedicatedId = getShrineDeityId(room);
    const block = getPrayerBlockReason(room, room);
    const shrineMenu = beginShrineMenu("shrine-prayer", "Shrine services — " + PRAYER_STAMINA_COST + " stamina, " + PRAYER_TURNS + " turns; first prayer chooses a permanent patron. for prayer/favor; other service costs are listed by show shrine services.");
    const prayButtons = [
        shrineMenuPrayerButton(shrineMenu, getPrayerButtonLabel(dedicatedId, "Pray to "), null, {
            disabled: !!block,
            title: block || `Costs ${PRAYER_STAMINA_COST} stamina and ${PRAYER_TURNS} turns. You cannot pray here again for ${PRAYER_COOLDOWN_TURNS} turns.`
        })
    ];
    const newcomerState = getNewcomerProtectionState(player);
    if (newcomerState !== "used") {
        const blessBlock = newcomerState === "none" && roomHasActiveHostile(room) ? "You cannot ask for a blessing with danger nearby." : "";
        appendCombatGroup(el, "Newcomer's blessing", [
            shrineServiceButton(shrineMenu, newcomerState === "active" ? "You hold a newcomer's blessing" : "Ask for a newcomer's blessing", "blessing", null, {
                disabled: newcomerState === "active" || !!blessBlock,
                title: newcomerState === "active"
                    ? "It will pull you back from death once, to the shrine where you asked."
                    : (blessBlock || "Free, once per character, and you pledge nothing. The next time you would die, you wake at this shrine instead, with your gear.")
            })
        ]);
    }
    appendCombatGroup(el, "Pray", prayButtons);

    const otherButtons = player.knownDeities.filter(id => id !== dedicatedId && getDeityArchetype(id)).map(deityId => {
        const deity = getDeityArchetype(deityId);
        return shrineMenuPrayerButton(shrineMenu,
            `Dedicate the shrine to ${deity.name} and pray` + (!player.deity ? " (pledges you to them for good)" : ""),
            deityId,
            { disabled: !!block, title: block || "The shrine's dedication can only be changed as part of a prayer." }
        );
    });
    if (otherButtons.length) appendCombatGroup(el, "Rededicate", otherButtons);

    if (player.deity) {
        const favorDeity = getDeityArchetype(player.deity);
        const favorBlock = getFavorRequestBlockReason(room);
        appendCombatGroup(el, "Favor", [
            shrineServiceButton(shrineMenu, `Ask ${favorDeity ? favorDeity.name : "your patron"} for a favor...`, "favor", null, {
                disabled: !!favorBlock,
                title: favorBlock || "Pray for a blessing or a one-time gift. Your patron decides whether the request is worthy, and it costs them divine power."
            })
        ]);
    }

    const defileBlock = getDefileBlockReason(room, room);
    appendCombatGroup(el, "Defile", [
        shrineServiceButton(shrineMenu, "Defile the shrine", "defile", null, {
            disabled: !!defileBlock,
            title: defileBlock || `Takes ${DIVINE_DEFILE_LOSS} divine power from the shrine's deity. Can be done once every ${DEFILE_COOLDOWN_TURNS} turns.`
        })
    ]);

    // Clerics can pray here to renew their mana, on a cooldown measured in
    // story turns. A patron deity makes the prayer stronger.
    if (playerUsesMana(player) && getClassPerk(player, "shrineMana", false)) {
        const turn = G.story ? (G.story.turnCounter || 0) : 0;
        const last = typeof player.lastShrinePrayerTurn === "number" ? player.lastShrinePrayerTurn : -Infinity;
        const waitLeft = Math.max(0, SHRINE_MANA_COOLDOWN_TURNS - (turn - last));
        const full = player.mana >= getPlayerManaCeiling(player);
        appendCombatGroup(el, "Devotion", [
            shrineServiceButton(shrineMenu, "Pray for renewal (restore mana)", "renewal", null, {
                disabled: full || waitLeft > 0,
                title: full ? "Your mana is already full."
                    : (waitLeft > 0 ? `The shrine's blessing has not settled yet (${waitLeft} more turn${waitLeft === 1 ? "" : "s"}).` : "Spend a moment in prayer to renew your mana.")
            })
        ]);
    }

    // Untrained in divine faith: a quiet devotion is how you start (slowly).
    if (getClassSkillRank(player, "cleric") < 1) {
        const devotionBlock = getDevotionPracticeBlockReason(G.activeRoom);
        appendCombatGroup(el, "Devotion", [
            shrineServiceButton(shrineMenu, "Kneel in quiet devotion (learn the basics)", "devotion", null, {
                disabled: !!devotionBlock,
                title: devotionBlock || "Nobody has taught you, but practice can start you on the way."
            })
        ]);
    }

    appendCombatGroup(el, "", [shrineMenuLeaveButton(shrineMenu, "Leave")]);
    publishShrineMenu(shrineMenu, el);
}

// Cleric devotion: kneel at a shrine to recover part of the mana pool. Takes
// two story turns and then needs SHRINE_MANA_COOLDOWN_TURNS to pass before it
// works again; having a patron deity restores more.
function prayAtShrineForMana() {
    if (!shrineServiceExecution || shrineServiceExecution.spec.action !== "renewal") return requestShrineService("renewal");
    const serviceContext = shrineServiceExecution;
    const serviceNarration = function (message) { return shrineServiceNarration(message, serviceContext); };
    const player = G.player;
    const room = G.activeRoom;
    if (!player || !room || !isShrineRoom(room)) return;
    if (!playerUsesMana(player) || !getClassPerk(player, "shrineMana", false)) return;

    const turn = G.story ? (G.story.turnCounter || 0) : 0;
    const last = typeof player.lastShrinePrayerTurn === "number" ? player.lastShrinePrayerTurn : -Infinity;
    if (player.mana >= getPlayerManaCeiling(player) || turn - last < SHRINE_MANA_COOLDOWN_TURNS) return;

    shrineServiceStart(serviceContext);
    advanceStoryTurn(2);
    if (!shrineServiceCurrent(serviceContext)) return shrineServiceInterrupted(serviceContext);
    const pathDef = getFaithPathDef(player);
    let ratio = (player.deity ? SHRINE_MANA_RESTORE_PATRON : SHRINE_MANA_RESTORE_NO_PATRON) + getEquippedAffinityTotal(player, "shrineMana") +
        (pathDef ? pathDef.shrineRatioBonus : 0);
    if (pathDef && pathDef.shrineVariance) ratio *= 0.5 + Math.random();
    ratio = Math.max(0.1, Math.min(1, ratio));
    const serviceHpBefore = player.hp;
    let bloodLine = "";
    if (pathDef && pathDef.shrineHpCost > 0 && typeof player.hp === "number") {
        player.hp = Math.max(1, player.hp - pathDef.shrineHpCost);
        bloodLine = ` It costs you ${pathDef.shrineHpCost} HP.`;
    }
    const gained = restorePlayerMana(player, Math.max(1, Math.ceil(player.manaMax * ratio)));
    shrineServiceRecord(serviceContext, { manaRestored: gained, hpCost: Math.max(0, serviceHpBefore - player.hp) });
    player.lastShrinePrayerTurn = G.story ? (G.story.turnCounter || 0) : 0;
    const prayerXPLines = [];
    gainClassSkillXP("cleric", 2, prayerXPLines);

    shrineServiceRecord(serviceContext, { clericXPAwarded: 2, clericRank: getClassSkillRank(player, "cleric") });
    renderStats();
    renderShrinePrayerMenu();
    serviceNarration((pathDef
        ? `${pathDef.prayerLine} You regain ${gained} mana.${bloodLine}`
        : (player.deity
            ? `You pray and feel your patron's presence gather in you. You regain ${gained} mana.`
            : `You pray quietly, and a calm settles over you. You regain ${gained} mana.`)) + (prayerXPLines.length ? " " + prayerXPLines.join(" ") : ""));
    saveGameState();
}

function closeShrinePrayerMenu() {
    returnToRoomView();
    saveGameState();
}

// ── ROOM OBJECT PANEL ────────────────────────────────────────────

function isRoomObjectInteractive(item) {
    // Bodies (searchable) and loose dropped items (takeable) are both interactive.
    // Room items are only ever one of those two kinds, so any item here qualifies.
    return !!item;
}

function selectRoomObject(item, narrationText = null) {
    if (!item) return;
    if (isSlimeRemains(item)) refreshSlimeRemainsDescription(item);

    // Loose items open a centered item card (examine text plus Take / Leave)
    // instead of swapping the bottom bar. Bodies keep the action-bar flow
    // (Search / Try to wake / Finish off / loot).
    if (item.objectType !== "body") {
        openItemModal(item);
        return;
    }

    G.activeNPC = null;
    G.activeObject = item;
    G.activeNPCMode = "object";

    const placeholderEl = document.getElementById("npcPlaceholderEl");
    const detailEl = document.getElementById("npcDetailEl");
    if (placeholderEl) placeholderEl.style.display = "none";
    if (detailEl) detailEl.classList.add("active");

    document.getElementById("npcDetailNameEl").textContent = getEntityName(item);
    renderNPCPortrait(null);
    document.getElementById("npcDetailBehaviorEl").textContent = item.description || "";
    document.getElementById("npcMoodEl").textContent =
        item.bodyState === "corpse" ? "dead" : item.bodyState || "object";
    document.getElementById("npcRoleEl").textContent = item.objectType === "body" ? "Body" : "Object";
    document.getElementById("npcFavorEl").textContent = item.objectType === "body"
        ? (item.bodyLooted ? "Searched" : "Unsearched")
        : "Loose item";

    clearChatLog();
    setExitGridVisible(false);
    renderRoomObjectActionMenu(item);
    if (narrationText) setNarration(narrationText);
    saveGameState();
}

