function getHerbKey(item) {
    if (!item) return null;
    if (item.herbKey && HEALING_HERBS[item.herbKey]) return item.herbKey;
    if (/^healing-herb/.test(String(item.id || ""))) return "greenwort";
    return null;
}

function isHerbItem(item) {
    return !!getHerbKey(item);
}

function createHerbItem(id) {
    const def = HEALING_HERBS[id];
    if (!def) return null;
    return cloneLootTemplate({ id: id, name: def.name, value: def.value, type: ["misc", "herb"], herbKey: id, description: def.description });
}

// Applies an herb to an entity and returns the narration line.
function applyHerbEffect(entity, item, options) {
    const key = getHerbKey(item);
    const def = key ? HEALING_HERBS[key] : null;
    if (!entity || !def) return null;
    const bits = [];
    if (def.stopBleed && typeof getTotalBleed === "function" && getTotalBleed(entity) > 0) {
        clearAllBleeding(entity);
        bits.push("the bleeding stops");
    }
    if (def.heal && typeof entity.hp === "number") {
        const before = entity.hp;
        entity.hp = Math.min(entity.hpMax || before, before + def.heal);
        if (entity.hp > before) bits.push(`you recover ${entity.hp - before} HP`);
    }
    if (def.stamina) {
        ensureEntityStamina(entity);
        const beforeSt = entity.stamina;
        restoreEntityStamina(entity, def.stamina);
        if (entity.stamina > beforeSt) bits.push("your strength returns");
    }
    if (entity.poisoned && (def.curePoison || def.easePoison)) {
        if (def.curePoison) { entity.poisoned = null; bits.push("the poison is purged from your blood"); }
        else {
            entity.poisoned.rounds -= def.easePoison;
            if (entity.poisoned.rounds <= 0) { entity.poisoned = null; bits.push("the poison fades"); }
            else bits.push("the poison eases");
        }
    }
    if (hasOpenWound(entity) && (key === "bloodmoss" || key === "greenwort" || key === "silverroot" || def.dressesWound)) {
        markWoundDressed(entity);
        if (key !== "bloodmoss" && !def.dressOnly) markWoundCleaned(entity);
        if (def.heal && entity.hpMax) healPlayerLimbs(entity, def.heal / entity.hpMax);
        bits.push(key === "bloodmoss" || def.dressOnly ? "the wound is dressed" : "the wound is dressed and clean");
    }
    const text = bits.length ? bits.join(", ") : "you feel no different";
    return `You ${def.verb ? def.verb.toLowerCase() : "chew"} the ${def.name.toLowerCase()}: ${text}.`;
}

function eatInventoryHerb(stackKey) {
    const entries = buildPlayerInventoryEntries(G.player);
    const entry = entries.find(function (c) { return c.key === stackKey; });
    if (!entry || !isHerbItem(entry.item)) return null;
    const consumed = takeInventoryEntryAmount(G.player, stackKey, 1);
    if (!consumed) return null;
    return applyHerbEffect(G.player, consumed, { isPlayer: true });
}

// Eating an herb mid-fight costs a turn, like drinking a potion.
function eatHerbInCombat(npc, stackKey) {
    if (!npc || npc.unconscious || npc.isUnconsciousBody || npc.hidden || npc.isHidden) return;
    const line = eatInventoryHerb(stackKey);
    if (!line) return;
    const lines = [line];
    if (resolveNPCCounter(npc, lines, { playerPassed: true })) return;
    if (npc.hp <= 0 || npc.unconscious || npc.isHidden || G.activeNPC !== npc) return;
    renderStats();
    renderCombatActionMenu(npc);
    renderCombatNarrationLines(lines);
    rememberStoryEvent("combat", `${G.player.name} ate a healing herb mid-fight with ${npc.name || "the creature"}.`, 3);
    saveGameState();
}

// ── ALCHEMY TABLE ───────────────────────────────────────────────────────
// A fixture with id "alchemy-table" (tag "alchemy"; it stands in the quiet-arts
// houses and hideouts, see the room templates in cyoaftw-world-data.js). Work at
// it from the fixture card.
//   PREP  cut, mince or mash a plant into a prepared form (diced, minced, pulp).
//         1 turn, no roll, no stamina. Prepared plants are items of their own,
//         written "greenwort:mince" in recipes.
//   MIX   build a queue of steps, then Start. Each step is an INGREDIENT (any
//         plant in any form, or any consumable: a drink, a liquid, a potion) or an
//         ACTION (boil, stir, simmer, extract). The whole process is narrated, and
//         what comes out is DESIGNED from the whole process (the AI when it is on,
//         else a seeded roll weighted by the plants, how they were prepared, the
//         actions and whether any heat was used). The design is stored once per
//         process (player.alchemy.mixLog) so the same process always gives the same
//         result. The result is not announced: it fills the EXTRACTION BOWL on the
//         table as a liquid of some look and smell, and the player has to try it.
//   BOWL  Like a cauldron: drink some, dip something in it, or collect some in an
//         empty vial (kept on a rack at the table). It holds a few doses and goes
//         flat after a day. Drinking or an obvious dip reveals what it was and adds
//         the process to the table's list of recipes; a poor batch (failed roll) is
//         a dud that does nothing and reveals nothing.
//   RECIPES  Salves, tonics and a few potions are known recipes: click one and it
//         is made at once (any prepared form that is missing is prepped from the raw
//         plant for a turn each). A queue that matches a recipe you have not learned
//         learns it on a hit.
//   POISONS  Poisons and antitoxin (rogues, Journeyman subterfuge) can only be
//         BREWED at an alchemy table (no brewing on the road until there is a
//         portable lab); coating a weapon with a finished poison works anywhere.
// State: player.alchemy = { seed, known{recipeId:true}, mixLog{sig:design} }
// design = { kind, magnitude, status, name, vial, smell, narration, doses, steps, tested }.
// Bowl: fixture.bowl = { sig, kind, magnitude, status, vial, smell, name, doses, botched, madeTurn }.
const ALCHEMY_STAMINA = 2;
