// ── EXAMINING EQUIPMENT ──────────────────────────────────────────
// "Examine" on an equipped item or a carried item in the Equipment panel opens
// the item card with its description (AI examine text, cached on the item),
// its real numbers, and how it stacks up against what you wear in the same
// slot, so better and worse gear can be told apart. Weapons also show your own
// skill with that weapon type (combatSkills.weapons) and what it is worth. Hidden
// enchantments stay hidden until revealed (askAboutTradeItem).
let equipmentExamineItem = null;

function signedNumber(value) {
    const rounded = Math.round(value * 10) / 10;
    return (rounded > 0 ? "+" : "") + rounded;
}

// The numbers a weapon actually brings to combat (mirrors getEntityWeaponProfile),
// plus the selected character's proficiency bonus with that weapon type.
function getWeaponExamineProfile(item, entity = G.player) {
    const type = String(item.weaponType || getWeaponTypeFromName(String(item.name || "").toLowerCase(), "generic")).toLowerCase();
    const broken = item.broken === true;
    let die = typeof item.damage === "number" ? Math.max(2, item.damage) : getWeaponDamageByName(getItemName(item));
    let hit = 0;
    let dmg = 0;
    if (broken) {
        die = 2; hit = -2;
    } else {
        if (type === "dagger") hit += 1;
        if (type === "sword" || type === "spear" || type === "polearm") hit += 1;
        if (type === "axe" || type === "mace" || type === "flail") dmg += 1;
        if (typeof item.quality === "number") hit += Math.max(-1, Math.min(1, item.quality));
        if (item.edgeHits > 0) {
            dmg += item.edgeBonus || 0;
            hit += item.edgeHitBonus || 0;
        }
        if (typeof item.enchantDamageBonus === "number") dmg += item.enchantDamageBonus;
        if (item.elementalDamage && typeof item.elementalDamage.amount === "number") dmg += item.elementalDamage.amount;
        if (item.buff && item.buff.kind === "weapon") dmg += item.buff.bonus || 0;
    }
    const skillHit = getWeaponProficiencyHitBonus(entity, type);
    return { type: type, die: die, hit: hit, dmg: dmg, skillHit: skillHit, avg: (die + 1) / 2 + dmg, broken: broken };
}

function toRomanNumeral(n) {
    const map = [[1000, "m"], [900, "cm"], [500, "d"], [400, "cd"], [100, "c"], [90, "xc"], [50, "l"], [40, "xl"], [10, "x"], [9, "ix"], [5, "v"], [4, "iv"], [1, "i"]];
    let out = "";
    let v = Math.max(1, Math.floor(n));
    map.forEach(function (p) { while (v >= p[0]) { out += p[1]; v -= p[0]; } });
    return out;
}

// Novice, Practised, Skilled, Expert by hit bonus 0-3; from +4 it is Master (i),
// Master (ii), Master (iii)... one numeral per extra point, with no end.
function getWeaponProficiencyRankName(practice, bonus) {
    if (!(practice > 0)) return "Untrained";
    const names = ["Novice", "Practised", "Skilled", "Expert"];
    if (bonus < names.length) return names[Math.max(0, bonus)];
    return "Master (" + toRomanNumeral(bonus - names.length + 1) + ")";
}

function getWeaponSkillSummary(type) {
    const weapons = G.player && G.player.combatSkills && G.player.combatSkills.weapons;
    const practice = (weapons && weapons[type]) || 0;
    const bonus = getWeaponProficiencyHitBonus(G.player, type);
    const rank = getWeaponProficiencyRankName(practice, bonus);
    const kind = type === "generic" ? "general weapons" : type + " weapons";
    let text = rank + " with " + kind + " (" + practice + " practice, " + signedNumber(bonus) + " to hit)";
    text += "; next +1 at " + getProficiencyNextThreshold(bonus, WEAPON_PROFICIENCY_HIT_DIVISOR, WEAPON_PROFICIENCY_HIT_SCALE) + " practice";
    return text;
}

// Comparable numbers for any item. Weapons: average damage and total to-hit
// (including your own skill with that weapon type).
function getItemExamineStats(item, entity = G.player) {
    const stats = { damage: 0, hit: 0, armor: 0, charisma: 0, pouch: 0, isWeapon: false };
    if (!item) return stats;
    if (getItemEquipSlot(item) === "weapon") {
        const weapon = getWeaponExamineProfile(item, entity);
        stats.isWeapon = true;
        stats.damage = weapon.avg;
        stats.hit = weapon.hit + weapon.skillHit;
        return stats;
    }
    stats.armor = getItemArmorValue(item);
    stats.charisma = getEffectiveItemCharisma(item);
    stats.pouch = typeof item.pouchSlots === "number" ? item.pouchSlots : 0;
    return stats;
}

function getExamineScore(stats) {
    return stats.damage + stats.hit + stats.armor + stats.charisma + stats.pouch * 0.5;
}

function buildEquipmentExamineLines(item, slot) {
    const lines = [];
    if (item.physicalDefinition && typeof calculateWorldObjectPhysics === "function") {
        const physical = calculateWorldObjectPhysics(item.physicalDefinition);
        if (physical) lines.push("Material: " + physical.material + ". Empty weight: " + physical.dryMassKg + " kg. Dimensions: " + physical.dimensionsCm.join(" × ") + " cm.");
    }
    if (slot) lines.push("Slot: " + getEquipmentSlotMeta(slot).label);
    lines.push("Size when carried: " + getItemUnitSize(item) + " units. Equipped items use no storage space.");
    if (item.qualityName) lines.push("Quality: " + item.qualityName);

    if (slot === "weapon") {
        const weapon = getWeaponExamineProfile(item);
        lines.push("Type: " + (weapon.type === "generic" ? "weapon" : weapon.type));
        lines.push("Damage: d" + weapon.die + (weapon.dmg ? " " + signedNumber(weapon.dmg) : "") + " (average " + signedNumber(weapon.avg).replace("+", "") + ")");
        lines.push("To hit: " + signedNumber(weapon.hit) + " from the weapon, " + signedNumber(weapon.skillHit) + " from your skill");
        lines.push("Your skill: " + getWeaponSkillSummary(weapon.type));
        if (weapon.broken) lines.push("Broken: it barely works until it is mended.");
        if (item.edgeHits > 0) lines.push("Honed: bonus applies for " + item.edgeHits + " more landed hit" + (item.edgeHits === 1 ? "" : "s") + ".");
    } else {
        const armor = getItemArmorValue(item);
        if (armor > 0 || (item.type && [].concat(item.type).indexOf("armor") >= 0)) lines.push("Armor: " + armor);
        if (typeof describeResistances === "function" && describeResistances(item)) lines.push("Resists: " + describeResistances(item));
        if (typeof getArmourTreatmentSlots === "function" && getArmourTreatmentSlots(item) > 0) lines.push("Treatment slots: " + ((item.treatments || 0)) + "/" + getArmourTreatmentSlots(item) + " used");
        const charisma = getEffectiveItemCharisma(item);
        if (charisma !== 0 || (item.type && [].concat(item.type).indexOf("clothes") >= 0)) lines.push("Charisma while worn: " + signedNumber(charisma));
        if (typeof item.pouchSlots === "number") lines.push("Pouch slots: " + item.pouchSlots);
    }

    const durLine = getDurabilityExamineLine(item, "item");
    if (durLine) lines.push(durLine);
    if (typeof item.grime === "number" && getItemGrimeLabel(item) !== "clean") lines.push("Cleanliness: " + getItemGrimeLabel(item));
    const value = typeof getItemValue === "function" ? getItemValue(item) : 0;
    if (value > 0) lines.push("Worth about " + value + "g");
    if (item.hiddenTrait && item.hiddenTraitRevealed) {
        lines.push("Enchantment: " + item.hiddenTrait.label + " (" + item.hiddenTrait.summary + ")");
    }
    if (item.relicPower && RELIC_POWERS[item.relicPower]) {
        lines.push("Relic power: " + RELIC_POWERS[item.relicPower].name + " - " + relicPowerDesc(item.relicPower, item.relicMaxStacks));
    }
    return lines;
}

function describeExamineDeltas(candidate, current) {
    const a = getItemExamineStats(candidate);
    const b = getItemExamineStats(current);
    const parts = [];
    const add = (label, delta) => { if (Math.abs(delta) >= 0.05) parts.push(signedNumber(delta) + " " + label); };
    add("average damage", a.damage - b.damage);
    add("to hit", a.hit - b.hit);
    add("armor", a.armor - b.armor);
    add("Charisma", a.charisma - b.charisma);
    add("pouch slots", a.pouch - b.pouch);
    const total = getExamineScore(a) - getExamineScore(b);
    const verdict = total > 0.25 ? "better overall" : total < -0.25 ? "worse overall" : "about the same overall";
    return { text: parts.length ? parts.join(", ") + " (" + verdict + ")" : "no real difference", total: total };
}

// The pack item that beats the worn `item` for `slot` by the biggest margin
// (see describeExamineDeltas), or null. Used for the "better in your pack"
// line and the Swap recommended button.
function findBetterPackItem(item, slot) {
    if (!slot || !G.player) return null;
    const pack = Array.isArray(G.player.inventory) ? G.player.inventory : [];
    let best = null;
    let bestTotal = item ? 0.25 : -Infinity;
    pack.forEach(candidate => {
        if (!candidate || candidate === item || getItemEquipSlot(candidate) !== slot) return;
        const total = describeExamineDeltas(candidate, item).total;
        if (total > bestTotal) { best = candidate; bestTotal = total; }
    });
    return best;
}

function buildEquipmentCompareLines(item, slot, equipped) {
    const lines = [];
    if (!slot) return lines;
    const label = getEquipmentSlotMeta(slot).label.toLowerCase();
    const worn = G.player && G.player.equipped ? G.player.equipped[slot] : null;

    if (!equipped) {
        if (!worn || Array.isArray(worn)) {
            lines.push("Nothing is equipped on your " + label + " right now.");
        } else if (worn !== item) {
            lines.push("Compared with your " + getItemName(worn) + ": " + describeExamineDeltas(item, worn).text + ".");
        }
        return lines;
    }

    // Examining something you are wearing: point out a better one in the pack.
    const best = findBetterPackItem(item, slot);
    if (best) lines.push("Your pack holds something better for this slot: " + getItemName(best) + " (" + describeExamineDeltas(best, item).text + ").");
    return lines;
}

function closeEquipmentExamine() {
    equipmentExamineItem = null;
    closeItemModal();
    refreshRoomViewAfterClose();
}

function openEquipmentExamine(item, options) {
    const opts = options || {};
    const modal = document.getElementById("itemModal");
    if (!modal || !item) return;
    clearItemModalContents();

    const titleEl = document.getElementById("itemModalTitle");
    const descEl = document.getElementById("itemModalDesc");
    const statsEl = document.getElementById("itemModalStats");
    const actionsEl = document.getElementById("itemModalActions");

    const name = getItemName(item);
    titleEl.textContent = name.charAt(0).toUpperCase() + name.slice(1);
    descEl.textContent = item.examineText || item.description || ("You look over " + withIndefiniteArticle(name) + ".");

    const slot = opts.slot || getItemEquipSlot(item);
    const lines = buildEquipmentExamineLines(item, slot).concat(buildItemEffectLines(item)).concat(buildEquipmentCompareLines(item, slot, !!opts.equipped));
    statsEl.innerHTML = "";
    lines.forEach(line => {
        const row = document.createElement("div");
        row.textContent = line;
        statsEl.appendChild(row);
    });
    statsEl.style.display = lines.length ? "block" : "none";

    actionsEl.innerHTML = "";

    // Worn gear recommends a better carried piece. A carried piece can also
    // be equipped directly, including when its destination slot is empty.
    if (slot && slot !== "coinPouch") {
        const worn = G.player && G.player.equipped && G.player.equipped[slot];
        const better = opts.equipped ? findBetterPackItem(item, slot)
            : ((G.player.inventory || []).includes(item) ? item : null);
        if (better) {
            const swapBtn = document.createElement("button");
            swapBtn.type = "button";
            swapBtn.textContent = opts.equipped ? "Swap recommended" : "Swap";
            swapBtn.title = "Equip " + getItemName(better) + (worn ? " in place of " + getItemName(worn) : " to your empty " + getEquipmentSlotMeta(slot).label.toLowerCase() + " slot") + ".";
            swapBtn.onclick = () => {
                if (!(G.player.inventory || []).includes(better)) return;
                const betterName = getItemName(better);
                const slotLabel = getEquipmentSlotMeta(slot).label.toLowerCase();
                if (!equipInventoryEntry(getInventoryEntryKey(better))) return;
                closeEquipmentExamine();
                refreshInventoryUi(worn ? "You swap " + getItemName(worn) + " for " + betterName + " on your " + slotLabel + "."
                    : "You equip " + betterName + " to your " + slotLabel + ".");
            };
            actionsEl.appendChild(swapBtn);
        }
    }

    const leaveBtn = document.createElement("button");
    leaveBtn.type = "button";
    leaveBtn.className = "primary";
    leaveBtn.textContent = "Close";
    leaveBtn.onclick = () => closeEquipmentExamine();
    actionsEl.appendChild(leaveBtn);

    const closeBtn = document.getElementById("itemModalClose");
    if (closeBtn) closeBtn.onclick = () => closeEquipmentExamine();
    modal.onclick = (e) => { if (e.target === modal) closeEquipmentExamine(); };

    // Not G.activeItemModal: that one's Leave re-renders the room narration.
    equipmentExamineItem = item;
    modal.classList.add("active");
    leaveBtn.focus();

    if (!item.examineText) {
        generateItemExamineText(item).then(text => {
            if (equipmentExamineItem === item && text) descEl.textContent = text;
            saveGameState();
        });
    }
}

document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && equipmentExamineItem) closeEquipmentExamine();
});

function renderEquipmentSlot(slot) {
    const slotEl = document.getElementById(`eq-slot-${slot}`);
    if (!slotEl) return;

    // Show Hands as soon as gloves are available, even before first equipping.
    if (slot === "hands") {
        const wornHands = G.player && G.player.equipped ? G.player.equipped.hands : null;
        const carriedHands = (G.player.inventory || []).some(function (candidate) { return getItemEquipSlot(candidate) === "hands"; });
        slotEl.style.display = ((wornHands && !Array.isArray(wornHands)) || carriedHands) ? "" : "none";
    }

    slotEl.innerHTML = "";

    const meta = getEquipmentSlotMeta(slot);
    const labelEl = document.createElement("b");
    labelEl.textContent = `${meta.icon} ${meta.label}`;
    slotEl.appendChild(labelEl);

    const valueEl = document.createElement("div");
    valueEl.className = "equipment-row-title";

    if (slot === "coinPouch") {
        const coins = getCoinValue(G.player);
        valueEl.textContent = `${coins} coin${coins === 1 ? "" : "s"}`;
        valueEl.classList.toggle("equipment-empty", coins <= 0);
        slotEl.appendChild(valueEl);

        if (coins > 0) {
            const actionsEl = document.createElement("div");
            actionsEl.className = "equipment-row-actions";

            const qtyWrap = document.createElement("label");
            qtyWrap.className = "equipment-qty-wrap";
            qtyWrap.textContent = "Drop";
            const qtyInput = createEquipmentQuantityInput(coins, 1);
            qtyWrap.appendChild(qtyInput);
            actionsEl.appendChild(qtyWrap);

            actionsEl.appendChild(createEquipmentActionButton("Drop", () => {
                const amount = readEquipmentQuantityInput(qtyInput, coins);
                adjustCoins(G.player, -amount);
                if (!dropItemIntoCurrentRoom(createDroppedCoinsItem(amount))) {
                    adjustCoins(G.player, amount);
                    return;
                }
                refreshInventoryUi(`You drop ${amount} coin${amount === 1 ? "" : "s"} to the ground.`);
            }));

            slotEl.appendChild(actionsEl);
        }

        return;
    }

    const item = G.player.equipped[slot];
    const wornCharisma = item ? getEffectiveItemCharisma(item) : 0;
    const grimeNote = item && getItemGrimeCharismaPenalty(item) !== 0
        ? ` [${getItemGrimeLabel(item)}]`
        : "";
    valueEl.textContent = item
        ? `${getItemName(item)}${wornCharisma !== 0 ? ` (${wornCharisma > 0 ? "+" : ""}${wornCharisma} CHA)` : ""}${grimeNote}`
        : "(empty)";
    if (!item) valueEl.classList.add("equipment-empty");
    slotEl.appendChild(valueEl);

    if (!item) {
        const best = findBetterPackItem(null, slot);
        const actions = document.createElement("div");
        actions.className = "equipment-row-actions";
        if (best) {
            const recommendation = document.createElement("div");
            recommendation.className = "equipment-row-subtitle";
            recommendation.textContent = "Best in pack: " + getItemName(best);
            slotEl.appendChild(recommendation);
        }
        actions.appendChild(createEquipmentActionButton("Swap", () => {
            if (G.player.equipped[slot] || !(G.player.inventory || []).includes(best)) return;
            if (!equipInventoryEntry(getInventoryEntryKey(best))) return;
            refreshInventoryUi("You equip " + getItemName(best) + " to your " + meta.label.toLowerCase() + ".");
        }, { disabled: !best, title: best ? "Equip " + getItemName(best) + " to this empty slot." : "No carried item fits this slot." }));
        slotEl.appendChild(actions);
        return;
    }

    const actionsEl = document.createElement("div");
    actionsEl.className = "equipment-row-actions";

    const extraActionsEl = document.createElement("div");
    actionsEl.appendChild(createEquipmentActionButton("Examine", () => openEquipmentExamine(item, { slot: slot, equipped: true })));

    if (isCarryContainerItem(item)) {
        extraActionsEl.appendChild(createEquipmentActionButton("Contents", function () { openContainerCard(item, ""); }));
        extraActionsEl.appendChild(createEquipmentActionButton("Search", () => searchOwnContainer(item), { title: "Costs 1 stamina, 1 turn." }));
    }
    if (slot !== "weapon") getOwnItemFireSpellButtons(item).forEach(function (b) { extraActionsEl.appendChild(b); });

    actionsEl.appendChild(createEquipmentActionButton("Remove", () => {
        const removed = moveEquippedItemToInventory(slot);
        if (!removed) return;
        refreshInventoryUi(`You remove ${getItemName(removed)} and stow it in your pack.`);
    }));

    actionsEl.appendChild(createEquipmentActionButton("Drop", () => {
        const itemName = getItemName(item);
        const didDrop = dropEquippedItemToRoom(slot);
        if (!didDrop) return;
        refreshInventoryUi(`You drop ${itemName}.`);
    }));

    appendEquipmentItemActions(slotEl, actionsEl, extraActionsEl, getItemName(item));
}

function renderEquipmentInventoryEntry(entry, inventoryEl) {
    const rowEl = document.createElement("div");
    rowEl.className = "equipment-row";

    const headerEl = document.createElement("div");
    headerEl.className = "equipment-row-header";

    const titleWrapEl = document.createElement("div");
    const titleEl = document.createElement("div");
    titleEl.className = "equipment-row-title";
    titleEl.textContent = formatInventoryItemLabel(entry.item, entry.totalQuantity);
    titleWrapEl.appendChild(titleEl);

    const slot = getItemEquipSlot(entry.item);
    const wearablePack = entry.item.container && entry.item.container.wearable === "back" && !entry.item.ruined && !entry.item.unusable;
    const isPotion = isPotionItem(entry.item);
    const isAlcohol = isAlcoholItem(entry.item);
    const isHerb = isHerbItem(entry.item);
    const isDeityTome = isDeityTomeItem(entry.item);
    const isGenericLore = isGenericLoreItem(entry.item);
    const isSpellScroll = isSpellScrollItem(entry.item);
    const isSpellbook = isSpellbookItem(entry.item);
    const isPrimer = isClassPrimerItem(entry.item);
    const subtitleEl = document.createElement("div");
    subtitleEl.className = "equipment-row-subtitle";
    const baseSubtitle = slot ? `Can equip to ${getEquipmentSlotMeta(slot).label}` : (wearablePack ? "Can equip to Back" : ((isPotion || isAlcohol) ? "Drinkable"
        : (isHerb ? "Edible herb"
        : (isSpellScroll ? `Spell scroll - ${entry.item.copyProgress || 0}% copied`
        : (isSpellbook ? `Spellbook - ${(Array.isArray(entry.item.spells) ? entry.item.spells.length : 0)} spell${(Array.isArray(entry.item.spells) && entry.item.spells.length === 1) ? "" : "s"}`
        : ((isDeityTome || isGenericLore) ? "Readable" : getInventoryUseSubtitle(entry.item)))))));
    const affinityNote = isClassGearItem(entry.item)
        ? ` - ${describeItemAffinity(entry.item)}${itemAffinityActive(entry.item, G.player) ? "" : " (needs training)"}`
        : "";
    // A REVEALED hidden trait (see askAboutTradeItem) sticks with the item
    // permanently, so it's worth surfacing here too, not just in the
    // one-time reveal message. Stays hidden if never asked about.
    subtitleEl.textContent = (entry.item.hiddenTrait && entry.item.hiddenTraitRevealed)
        ? `${baseSubtitle}${affinityNote} - ${entry.item.hiddenTrait.label} (${entry.item.hiddenTrait.summary})`
        : baseSubtitle + affinityNote;
    titleWrapEl.appendChild(subtitleEl);
    const size = getItemUnitSize(entry.item);
    const stowedText = "Size: " + size + " unit" + (size === 1 ? "" : "s") + " each" +
        (entry.totalQuantity > 1 ? " (" + (size * entry.totalQuantity) + " total)" : "") +
        (isTieSpotId(entry.item.stowed) ? " · Tied on" : "");
    if (stowedText) {
        const stowedEl = document.createElement("div");
        stowedEl.className = "equipment-row-subtitle";
        stowedEl.textContent = stowedText;
        titleWrapEl.appendChild(stowedEl);
    }

    headerEl.appendChild(titleWrapEl);
    rowEl.appendChild(headerEl);

    const actionsEl = document.createElement("div");
    actionsEl.className = "equipment-row-actions";

    if (entry.storageLabel) {
        const location = document.createElement("div");
        location.className = "equipment-row-subtitle inventory-item-location";
        location.textContent = "Stored in: " + entry.storageLabel;
        actionsEl.appendChild(location);
    }

    const primaryActionsEl = document.createElement("div");
    primaryActionsEl.className = "equipment-row-actions";
    primaryActionsEl.appendChild(createEquipmentActionButton("Examine", () => openEquipmentExamine(entry.item, { slot: slot, equipped: false })));
    if (slot) {
        actionsEl.appendChild(createEquipmentActionButton("Equip", () => {
            const itemName = getItemName(entry.item);
            const destination = getEquipmentSlotMeta(slot).label.toLowerCase();
            if (!equipInventoryEntry(entry.key)) return;
            refreshInventoryUi(`You equip ${itemName} to your ${destination}.`);
        }, { disabled: getInventoryEntryMaxEquipAmount(entry) <= 0 }));
    } else {
        const equip = createEquipmentActionButton("Equip", function () {
            if (!wearablePack || G.player.rucksack || (G.player.inventory || []).indexOf(entry.item) < 0) return;
            refreshInventoryUi(wearRucksack(entry.item));
        }, { disabled: !wearablePack || !!G.player.rucksack });
        equip.title = wearablePack ? (G.player.rucksack ? "Remove your current pack first." : "Wear as your pack.") : "This item cannot be equipped.";
        actionsEl.appendChild(equip);
    }

    if (isPotion || isAlcohol) {
        // Only the mana potion can be wasted (no mana pool to restore);
        // alcohol is always drinkable.
        const wastedMana = isPotion && entry.item.statusKey === "potionMana" && !playerUsesMana(G.player);
        const drinkBtn = createEquipmentActionButton("Drink", () => {
            // Mid-fight, drinking costs a turn like any other combat action
            // (see drinkPotionInCombat) - close the panel so the resulting
            // combat narration/menu is visible right away. Outside combat
            // it's still a free action.
            if (G.activeNPCMode === "combat" && G.activeNPC) {
                drinkPotionInCombat(G.activeNPC, entry.key);
                closeEquipmentManager();
                return;
            }
            const line = drinkInventoryEntry(entry.key);
            refreshInventoryUi(line || `You drink ${getItemName(entry.item)}.`);
        }, { disabled: wastedMana });
        if (wastedMana) drinkBtn.title = "You have no mana to restore.";
        actionsEl.appendChild(drinkBtn);
    }

    const supplyUse = getSupplyUse(entry.item);
    if (supplyUse) {
        const inFight = G.activeNPCMode === "combat" && !!G.activeNPC;
        const supplyBtn = createEquipmentActionButton(supplyUse.verb, () => {
            const line = useSupplyEntry(entry.key);
            refreshInventoryUi(line || `You ${supplyUse.verb.toLowerCase()} ${getItemName(entry.item)}.`);
        }, { disabled: inFight });
        if (inFight) supplyBtn.title = "Not in the middle of a fight.";
        actionsEl.appendChild(supplyBtn);
    }

    if (getItemLiquid(entry.item) || isPotionItem(entry.item)) {
        actionsEl.appendChild(createEquipmentActionButton("Pour out", materialPourCallback(entry), { disabled: !!materialBlock("pour", null), title: materialBlock("pour", null) }));
    }

    if (isHerb) {
        actionsEl.appendChild(createEquipmentActionButton((HEALING_HERBS[getHerbKey(entry.item)] && HEALING_HERBS[getHerbKey(entry.item)].verb) || "Eat", () => {
            if (G.activeNPCMode === "combat" && G.activeNPC) {
                eatHerbInCombat(G.activeNPC, entry.key);
                closeEquipmentManager();
                return;
            }
            const line = eatInventoryHerb(entry.key);
            refreshInventoryUi(line || `You eat ${getItemName(entry.item)}.`);
        }));
    }

    appendReadableInventoryActions(entry, actionsEl);
    if (isSpellbook) {
        getCastableSpellIds(G.player).filter(function (id) { return (entry.item.spells || []).indexOf(id) >= 0 && WIZARD_SPELLS[id].travel; }).forEach(function (spellId) {
            const sp = WIZARD_SPELLS[spellId];
            const cost = getEffectiveSpellManaCost(G.player, sp);
            const cb = createEquipmentActionButton("Cast " + sp.name + " (" + cost + " mana)", () => { refreshInventoryUi(castTravelSpell(spellId)); }, { disabled: G.player.mana < cost || G.activeNPCMode === "combat" });
            cb.title = sp.summary;
            actionsEl.appendChild(cb);
        });
    }

    if (isCarryContainerItem(entry.item)) {
        actionsEl.appendChild(createEquipmentActionButton("Contents", function () { openContainerCard(entry.item, ""); }));
        actionsEl.appendChild(createEquipmentActionButton("Search", () => searchOwnContainer(entry.item), { title: "Costs 1 stamina, 1 turn." }));
    }
    getOwnItemFireSpellButtons(entry.item).forEach(function (b) { actionsEl.appendChild(b); });
    if (isEntryTied(entry.key)) {
        actionsEl.appendChild(createEquipmentActionButton("Untie", () => { refreshInventoryUi(untieItem(entry.key)); }));
    }
    if (canTieItemSize(entry.item)) {
        const untiedLeft = (G.player.inventory || []).some(it => it && getInventoryEntryKey(it) === entry.key && !isTieSpotId(it.stowed));
        [["belt", "Tie to belt loop"], ["rucksack", "Tie to pack strap"]].forEach(function (pair) {
            if (!getPlayerTieSpots(G.player).some(t => t.kind === pair[0])) return;
            const free = getFreeTieSpot(pair[0]);
            const tieBtn = createEquipmentActionButton(pair[1], () => { refreshInventoryUi(tieItemOn(entry.key, pair[0])); }, { disabled: !free || !untiedLeft });
            tieBtn.title = free ? "Frees pack space, but it costs flexibility (1 point per 2 tied items)." : "Every spot is already in use.";
            actionsEl.appendChild(tieBtn);
        });
    }

    appendEquipmentMoveControl(entry, actionsEl);

    const dropQuantity = entry.totalQuantity;
    let qtyInput = null;
    if (dropQuantity > 1) {
        const qtyWrap = document.createElement("label");
        qtyWrap.className = "equipment-qty-wrap";
        qtyWrap.textContent = "Drop";
        qtyInput = createEquipmentQuantityInput(dropQuantity, 1);
        qtyWrap.appendChild(qtyInput);
        primaryActionsEl.appendChild(qtyWrap);
    }

    primaryActionsEl.appendChild(createEquipmentActionButton("Drop", () => {
        const amount = qtyInput ? readEquipmentQuantityInput(qtyInput, dropQuantity) : 1;
        const dropped = dropInventoryEntryToRoom(entry.key, amount);
        if (!dropped) return;
        refreshInventoryUi(`You drop ${formatInventoryItemLabel(entry.item, amount)}.`);
    }));

    appendEquipmentItemActions(rowEl, primaryActionsEl, actionsEl, getItemName(entry.item), headerEl);
    inventoryEl.appendChild(rowEl);
}

let _equipmentMoreSequence = 0;
let _equipmentOpenMore = null;

// Extra item controls expand below their own row, so selects and long spell
// actions stay usable without covering another item. Only one is open at once.
function appendEquipmentItemActions(parent, primary, extra, itemName, primaryParent) {
    if (!extra.children.length) {
        (primaryParent || parent).appendChild(primary);
        return;
    }
    const id = "equipment-more-" + (++_equipmentMoreSequence);
    extra.id = id;
    extra.className = "equipment-row-actions equipment-more-actions";
    extra.hidden = true;
    extra.style.display = "none";
    extra.setAttribute("role", "group");
    extra.setAttribute("aria-label", "More actions for " + itemName);
    const close = function (restoreFocus) {
        extra.hidden = true;
        extra.style.display = "none";
        more.setAttribute("aria-expanded", "false");
        if (_equipmentOpenMore && _equipmentOpenMore.panel === extra) _equipmentOpenMore = null;
        if (restoreFocus) more.focus();
    };
    const more = createEquipmentActionButton("\u2026", function () {
        if (!extra.hidden) { close(false); return; }
        if (_equipmentOpenMore) _equipmentOpenMore.close(false);
        extra.hidden = false;
        extra.style.display = "";
        more.setAttribute("aria-expanded", "true");
        _equipmentOpenMore = { panel: extra, close: close };
    });
    more.className = "equipment-action-btn equipment-more-toggle";
    more.title = "More actions for " + itemName;
    more.setAttribute("aria-label", more.title);
    more.setAttribute("aria-expanded", "false");
    more.setAttribute("aria-controls", id);
    const escape = function (event) {
        if (event.key !== "Escape") return;
        event.preventDefault();
        event.stopPropagation();
        close(true);
    };
    more.onkeydown = escape;
    extra.onkeydown = escape;
    primary.appendChild(more);
    (primaryParent || parent).appendChild(primary);
    parent.appendChild(extra);
}

// A worn pack can also be carried, with its storage and contents intact.
function removeWornRucksack() {
    const player = G.player;
    const item = player && player.rucksack;
    if (!item) return;
    player.rucksack = null;
    delete item.stowed;
    player.inventory = Array.isArray(player.inventory) ? player.inventory : [];
    player.inventory.push(item);
    restowPlayerPack(player);
    refreshInventoryUi("You remove " + getItemName(item) + " and carry it.");
}


// ── CHARACTER SHEET (Stats button) ───────────────────────────────
// Read-only overlay built on demand (no markup in the HTML shell besides the
// button). Shows who you are, your five stats (base vs effective, with the
// combat bonus and stat XP), armour per hit location, weapon and weapon
// skills, worn gear effects, active status effects, faith and condition.
// Unrevealed hidden item enchantments are deliberately NOT counted here.
const CHARACTER_SHEET_STATS = [
    { key: "physicalProwess", label: "Physical Prowess" },
    { key: "flexibility", label: "Flexibility" },
    { key: "willpower", label: "Willpower" },
    { key: "endurance", label: "Endurance" },
    { key: "charisma", label: "Charisma" }
];

function getRevealedCarriedStatBonus(entity, statKey) {
    if (!entity) return 0;
    const items = [];
    if (Array.isArray(entity.inventory)) items.push.apply(items, entity.inventory);
    if (entity.equipped && typeof entity.equipped === "object") {
        Object.keys(entity.equipped).forEach(slot => {
            const it = entity.equipped[slot];
            if (it && !Array.isArray(it)) items.push(it);
        });
    }
    // Same split as getCarriedStatBonus (revealed traits only): trinkets cap
    // among themselves, boss relics sit on top, so the sheet matches the real
    // bonus. Unrevealed hidden enchantments are deliberately NOT counted here.
    let relicTotal = 0;
    let trinketTotal = 0;
    items.forEach((item) => {
        if (item && item.hiddenTrait && item.hiddenTraitRevealed && item.hiddenTrait.effectType === "stat" && item.hiddenTrait.statKey === statKey) {
            const add = item.hiddenTrait.effectValue || 0;
            if (item.bossRelic === true) relicTotal += add;
            else trinketTotal = Math.min(trinketTotal + add, HIDDEN_ITEM_TRAIT_STAT_CAP);
        }
    });
    return relicTotal + trinketTotal;
}

function getCharacterSheetStatBreakdown(p, statKey) {
    const base = typeof p.stats[statKey] === "number" ? p.stats[statKey] : 3;
    const status = getStatusStatModifier(p, statKey);
    const gear = getRevealedCarriedStatBonus(p, statKey);
    const worn = statKey === "charisma" ? getWornCharismaBonus(p) : 0;
    const hygiene = statKey === "charisma" ? getHygieneCharismaPenalty(p) : 0;
    const tied = getTiedGearPenalty(p, statKey);
    const effective = Math.max(1, base + status + gear + worn + hygiene + tied);
    return { base: base, status: status, gear: gear, worn: worn, hygiene: hygiene, tied: tied, effective: effective, bonus: getStatBonusFromValue(effective) };
}

function sheetEl(tag, text, css) {
    const el = document.createElement(tag);
    if (text !== undefined && text !== null) el.textContent = text;
    if (css) el.style.cssText = css;
    return el;
}

function sheetSection(parent, title) {
    const box = sheetEl("div", null, "margin-top:14px;");
    box.appendChild(sheetEl("div", title, "color:#fff; font-weight:bold; border-bottom:1px solid #333; padding-bottom:4px; margin-bottom:6px;"));
    parent.appendChild(box);
    return box;
}

function sheetRow(parent, label, value, valueCss) {
    const row = sheetEl("div", null, "display:flex; justify-content:space-between; gap:12px; padding:2px 0; color:#bbb; font-size:0.95em;");
    row.appendChild(sheetEl("span", label));
    row.appendChild(sheetEl("span", value, "text-align:right; color:#ddd;" + (valueCss || "")));
    parent.appendChild(row);
    return row;
}

function sheetNote(parent, text) {
    parent.appendChild(sheetEl("div", text, "color:#888; font-size:0.85em; padding:2px 0;"));
}

function buildCharacterSheetContent(root) {
    const p = G.player;
    ensurePlayerEquipmentState(p);
    root.innerHTML = "";
    // Top-right close (X) that stays pinned while the sheet scrolls, so you
    // never have to scroll to the bottom Close button. The zero-height sticky
    // wrapper keeps it from pushing the title down.
    const closeWrap = sheetEl("div", null, "position:sticky; top:0; height:0; z-index:2; text-align:right; overflow:visible;");
    const closeX = sheetEl("button", "×", "width:30px; height:30px; padding:0; font-size:20px; line-height:1; cursor:pointer; background:#2a2a2a; color:#ddd; border:1px solid #555; border-radius:6px;");
    closeX.type = "button";
    closeX.title = "Close (Esc)";
    closeX.setAttribute("aria-label", "Close");
    closeX.onclick = () => closeCharacterSheet();
    closeWrap.appendChild(closeX);
    root.appendChild(closeWrap);
    root.appendChild(sheetEl("h3", p.name + " — " + p.class, "color:#fff; margin:0 0 4px 0; padding-right:36px; padding-left:36px; text-align:center;"));

    // Identity
    const who = sheetSection(root, "Character");
    if (p.gender) sheetRow(who, "Gender", String(p.gender));
    const look = typeof getPlayerAppearanceText === "function" ? getPlayerAppearanceText() : "";
    if (look) sheetRow(who, "Appearance", look);
    const traits = getPlayerTraitCounts();
    const traitKeys = Object.keys(traits).filter(k => typeof traits[k] === "number" && traits[k] > 0)
        .sort((a, b) => traits[b] - traits[a]);
    if (traitKeys.length) {
        sheetRow(who, "Personality", traitKeys.map(k => k + " " + traits[k]).join(", "));
        const dominant = getPlayerDominantTrait();
        if (dominant) sheetRow(who, "Defining trait", dominant);
    }
    if (typeof getHygieneLabel === "function") sheetRow(who, "Hygiene", getHygieneLabel(p));
    if (getHighestPortalTier() > 0) sheetRow(who, "Town portals taken", getHighestPortalTier() + " (this town: " + getPortalTownLabel(getPortalTier()) + ", foes x" + getPortalMobFactor().toFixed(2) + "; next new town costs " + getTownPortalCost() + " gold)");

    // Background (from character creation; absent on older saves)
    const backstory = getPlayerBackstory();
    if (backstory) {
        const past = sheetSection(root, "Background");
        sheetRow(past, "Past", backstory.label || backstory.archetype);
        sheetNote(past, backstory.text);
        if (backstory.goal) sheetRow(past, "Aim", backstory.goal);
        if (backstory.guide && backstory.guide.name) {
            sheetRow(past, "Guide", backstory.guide.name + (backstory.guide.relation ? " (" + backstory.guide.relation + ")" : ""));
            if (typeof window.getGuidePlanText === "function" && backstory.guide.state === "oriented") sheetRow(past, "Next step", window.getGuidePlanText(backstory));
        }
    }

    // Likes & dislikes (optional, from character creation)
    const prefs = getPlayerPreferences();
    if (prefs.likes.length || prefs.dislikes.length) {
        const tastes = sheetSection(root, "Likes & Dislikes");
        if (prefs.likes.length) sheetRow(tastes, "Likes", prefs.likes.map(function (x) { return x.label; }).join(", "));
        if (prefs.dislikes.length) sheetRow(tastes, "Dislikes", prefs.dislikes.map(function (x) { return x.label; }).join(", "));
    }

    // Condition
    const cond = sheetSection(root, "Condition");
    sheetRow(cond, "Health", p.hp + " / " + p.hpMax);
    const staminaMax = typeof p.staminaMax === "number" ? p.staminaMax : PLAYER_STAMINA_MAX;
    const stamina = typeof p.stamina === "number" ? p.stamina : staminaMax;
    sheetRow(cond, "Stamina", stamina + " / " + staminaMax);
    if (playerUsesMana(p)) sheetRow(cond, "Mana", p.mana + " / " + p.manaMax + (getPlayerManaReserved(p) > 0 ? " (" + getPlayerManaReserved(p) + " held by enchantments)" : ""));
    if (playerIsSpellcaster(p)) {
        const knownSpells = getCastableSpellIds(p);
        sheetRow(cond, "Spells", knownSpells.length
            ? knownSpells.map(id => `${WIZARD_SPELLS[id].name} (${WIZARD_SPELLS[id].manaCost})`).join(", ")
            : (getPlayerSpellbooks(p).length ? "None copied yet" : "No spellbook"));
    }
    CLASS_KEYS.forEach(function (ck) {
        const bs = describeBranchSummary(p, ck);
        if (bs.length) sheetRow(cond, CLASS_KEY_TO_NAME[ck] + " branches", bs.join("; "));
    });
    sheetRow(cond, "Coins", getCoinValue(p) + "g");
    const bleed = typeof getTotalBleed === "function" ? getTotalBleed(p) : 0;
    if (bleed > 0) sheetRow(cond, "Bleeding", "Yes (" + bleed + ")", "color:#c66;");
    if (p.carrying) sheetRow(cond, "Hauling", getBodyDisplayName(p.carrying) + " (carried)");

    // Stats
    const stats = sheetSection(root, "Stats");
    const xp = (p.combatSkills && p.combatSkills.statXP) || {};
    CHARACTER_SHEET_STATS.forEach(def => {
        const b = getCharacterSheetStatBreakdown(p, def.key);
        const parts = [];
        if (b.status) parts.push(signedNumber(b.status) + " status");
        if (b.worn) parts.push(signedNumber(b.worn) + " worn");
        if (b.hygiene) parts.push(signedNumber(b.hygiene) + " hygiene");
        if (b.gear) parts.push(signedNumber(b.gear) + " gear");
        if (b.tied) parts.push(signedNumber(b.tied) + " tied-on gear");
        let text = String(b.effective);
        if (b.effective !== b.base) text += " (base " + b.base + ")";
        text += "  ·  " + signedNumber(b.bonus) + " to rolls";
        const row = sheetRow(stats, def.label, text, b.effective < b.base ? "color:#c88;" : (b.effective > b.base ? "color:#8c8;" : ""));
        if (parts.length) sheetNote(stats, "   " + parts.join(", "));
        const need = getStatLevelXPThreshold(b.base);
        const have = xp[def.key] || 0;
        if (have > 0) sheetNote(stats, "   Training: " + have + " / " + need + " XP toward " + (b.base + 1));
    });
    sheetNote(stats, "Roll bonus = floor((stat - 3) / 2), added to d20 checks.");

    // Armour
    const armour = sheetSection(root, "Defence");
    sheetRow(armour, "Armour class (torso)", String(getEntityArmorClass(p, "torso")));
    [["head", "Head"], ["torso", "Torso"], ["arms", "Arms"], ["legs", "Legs"]].forEach(pair => {
        let text = "AC " + getEntityArmorClass(p, pair[0]);
        if (typeof getTargetDamageReduction === "function") {
            const dr = getTargetDamageReduction(p, pair[0], "physical");
            if (typeof dr === "number" && dr > 0) text += ", " + dr + " damage reduction";
        }
        sheetRow(armour, pair[1], text);
    });
    sheetRow(armour, "Armour worn", String(getEquippedArmorTotal(p)));
    const dodge = getEquipmentDodgeBonus(p);
    if (dodge) sheetRow(armour, "Dodge from gear", signedNumber(dodge));

    // Weapon and skills
    const weapon = sheetSection(root, "Weapon");
    const wp = getEntityWeaponProfile(p);
    sheetRow(weapon, "Wielding", wp.name + (wp.broken ? " (broken)" : ""));
    sheetRow(weapon, "Type", wp.type === "generic" ? "weapon" : wp.type);
    sheetRow(weapon, "Damage", "d" + wp.damageDie + (wp.damageBonus ? " " + signedNumber(wp.damageBonus) : ""));
    const skillHit = getWeaponProficiencyHitBonus(p, wp.type);
    sheetRow(weapon, "To hit", signedNumber((p.attackBonus || 0) + wp.hitBonus + skillHit) + " (class " + signedNumber(p.attackBonus || 0) + ", weapon " + signedNumber(wp.hitBonus) + ", skill " + signedNumber(skillHit) + ")");
    sheetRow(weapon, "Skill", getWeaponSkillSummary(wp.type));
    const skills = p.combatSkills || {};
    const weaponSkills = skills.weapons ? Object.keys(skills.weapons).filter(k => skills.weapons[k] > 0) : [];
    if (weaponSkills.length) {
        sheetRow(weapon, "Practised with", weaponSkills.map(k => k + " " + skills.weapons[k]).join(", "));
    }
    const actionSkills = skills.actions ? Object.keys(skills.actions).filter(k => skills.actions[k] > 0) : [];
    if (actionSkills.length) {
        sheetRow(weapon, "Combat moves", actionSkills.map(k => k + " " + skills.actions[k]).join(", "));
    }

    // Gear
    const gear = sheetSection(root, "Worn gear");
    let anyGear = false;
    getPlayerEquipmentSlots().forEach(slot => {
        const item = p.equipped[slot];
        if (!item || Array.isArray(item)) return;
        anyGear = true;
        const bits = [];
        const arm = getItemArmorValue(item);
        const cha = getEffectiveItemCharisma(item);
        if (getItemEquipSlot(item) === "weapon") bits.push("d" + (typeof item.damage === "number" ? item.damage : 4));
        if (arm) bits.push("armour " + arm);
        if (cha) bits.push("CHA " + signedNumber(cha));
        if (typeof item.pouchSlots === "number") bits.push(item.pouchSlots + " pouch slots");
        if (isClassGearItem(item)) bits.push(describeItemAffinity(item) + (itemAffinityActive(item, p) ? "" : " - needs training"));
        if (typeof getItemGrimeLabel === "function" && typeof item.grime === "number" && getItemGrimeLabel(item) !== "clean") bits.push(getItemGrimeLabel(item));
        sheetRow(gear, getEquipmentSlotMeta(slot).label, getItemName(item) + (bits.length ? " (" + bits.join(", ") + ")" : ""));
    });
    if (!anyGear) sheetNote(gear, "Nothing equipped.");

    // Class training
    ensureClassSkillState(p);
    const training = sheetSection(root, "Class training");
    CLASS_KEYS.forEach(function (key) {
        const e = p.classSkills[key];
        const need = getClassSkillXPNeeded(p, key);
        const isPrimary = getPlayerClassKey(p) === key;
        sheetRow(training, CLASS_KEY_TO_NAME[key] + " (" + CLASS_SKILL_LABELS[key] + ")",
            getClassRankName(e.rank) + (isPrimary ? " - your class" : "") + (need ? ", " + Math.floor(e.xp) + "/" + need + " XP" : ""));
    });
    const sheetWeapon = getEntityWeaponProfile(p);
    const offClass = getOffClassWeaponPenalty(p, sheetWeapon.type);
    if (offClass.offClass && (offClass.hit || offClass.damage)) {
        sheetNote(training, "Unfamiliar weapon: -" + offClass.hit + " to hit, -" + offClass.damage + " damage until you practise with it.");
    }
    const faithPath = getPlayerFaithPathKey(p);
    if (faithPath) {
        sheetRow(training, "Faith path", FAITH_PATHS[faithPath].label + " (" + DEITY_ARCHETYPES[p.deity].name + ", " + DEITY_ARCHETYPES[p.deity].alignment + ")");
    }
    if (p.deity && getPlayerDeityPowers(p).length) {
        getPlayerDeityPowers(p).forEach(function (power) {
            const block = getDeityPowerBlockReason(p, power);
            sheetRow(training, "Power: " + power.name, block ? block : "available (" + getDeityPowerManaCost(p, power) + " mana)");
        });
    }
    if (p.knownTeachers) {
        Object.keys(p.knownTeachers).forEach(function (key) {
            const kt = p.knownTeachers[key];
            if (kt && CLASS_SKILL_LABELS[key]) sheetRow(training, "Teacher: " + CLASS_SKILL_LABELS[key], kt.role + ", " + kt.place);
        });
    }
    sheetNote(training, "Find a trainer (Arcanist, Priest, Guard, Scout...) to learn another class, or ask around to be pointed to one. Primers and practice can start Arcane and Divine too. Higher ranks cost far more and need practice between lessons.");

    // Techniques the player devised (see SYNERGIES)
    const synState = ensureSynergyState(p);
    if (synState && synState.notebook.length) {
        const tech = sheetSection(root, "Techniques");
        synState.notebook.forEach(function (t) {
            sheetRow(tech, getSynergyLabel(t), (synState.repertoire.indexOf(t.id) >= 0 ? "memorised - " : "notebook only - ") + describeSynergyTechnique(t));
        });
        sheetNote(tech, "Memorised: " + synState.repertoire.length + "/" + getSynergySlots(p) + ". Combine skills at a training ground, workshop, lab bench or shrine (the Experiment button beside the exits).");
    }

    // Status effects
    const fx = sheetSection(root, "Status effects");
    const effects = getActiveStatusEffects(p);
    if (!effects.length) {
        sheetNote(fx, "None.");
    } else {
        const now = getStatusClock();
        effects.forEach(effect => {
            const def = STATUS_EFFECT_DEFINITIONS[effect.key] || {};
            const mods = [];
            if (def.statMods) Object.keys(def.statMods).forEach(k => mods.push(signedNumber(def.statMods[k]) + " " + k));
            if (def.combatMods) Object.keys(def.combatMods).forEach(k => mods.push(signedNumber(def.combatMods[k]) + " " + k));
            if (def.hpMaxDelta) mods.push(signedNumber(def.hpMaxDelta) + " max HP");
            const left = typeof effect.expiresAtTurn === "number" ? Math.max(0, effect.expiresAtTurn - now) : null;
            sheetRow(fx, effect.label || def.label || effect.key, (mods.length ? mods.join(", ") + "; " : "") + (left !== null ? left + " turns left" : ""));
        });
    }

    // Faith
    ensurePlayerFaithState(p);
    if (p.deity && getDeityArchetype(p.deity)) {
        const faith = sheetSection(root, "Faith");
        sheetRow(faith, "Patron", getDeityArchetype(p.deity).name);
        if (p.faith) sheetRow(faith, "Standing", String(p.faith.score));
    }

    const close = sheetEl("button", "Close", "margin-top:16px; width:100%;");
    close.type = "button";
    close.onclick = () => closeCharacterSheet();
    root.appendChild(close);
}

function isCharacterSheetOpen() {
    const el = document.getElementById("characterSheet");
    return !!(el && el.style.display !== "none");
}

function renderCharacterSheet() {
    const el = document.getElementById("characterSheet");
    if (!el || !G || !G.player) return;
    buildCharacterSheetContent(document.getElementById("characterSheetBody"));
}

function toggleCharacterSheet() {
    if (isCharacterSheetOpen()) { closeCharacterSheet(); return; }
    if (!G || !G.player) return;
    let el = document.getElementById("characterSheet");
    if (!el) {
        el = sheetEl("div", null, "position:fixed; inset:0; background:rgba(0,0,0,0.55); z-index:100; display:none; align-items:center; justify-content:center;");
        el.id = "characterSheet";
        const card = sheetEl("div", null, "background:#1e1e1e; border:1px solid #444; border-radius:10px; padding:20px; width:min(92vw, 520px); max-height:85vh; overflow-y:auto;");
        card.id = "characterSheetBody";
        el.appendChild(card);
        el.onclick = (e) => { if (e.target === el) closeCharacterSheet(); };
        document.body.appendChild(el);
    }
    el.style.display = "flex";
    renderCharacterSheet();
}

function closeCharacterSheet() {
    const el = document.getElementById("characterSheet");
    if (el) el.style.display = "none";
    refreshRoomViewAfterClose();
}

document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && isCharacterSheetOpen() && !equipmentExamineItem) closeCharacterSheet();
});

function toggleEquipment() {
    const el = document.getElementById("equipmentManager");
    if (!el) return;
    el.classList.toggle("active");
    renderEquipment();
    if (!el.classList.contains("active")) refreshRoomViewAfterClose();
}

// ── MAP ───────────────────────────────────────────────────────────
// 🗺 Map button (under Equipment): a scrollable popup that draws the rooms the
// player has visited on the current map plane, north up, joined by the paths
// between them. Rooms are flagged `room.mapSeen` in renderRoom (saved with the
// room, so old saves fill in as the player walks). Unvisited rooms next to a
// visited one show as dashed "?" cells; their type is never revealed. The map
// follows ordinary exits only; stairs, lifts and portal exits (a door into a
// building) are shown as marks on the room that has them, so each building,
// floor or level is its own map. Display only: nothing here changes the world.
const MAP_CELL_SPAN = 2; // grid tracks per room: one room cell + one link cell
const MAP_MAX_ROOMS = 1500;

function getMapRoomMarks(room) {
    const marks = [];
    if (!room) return marks;
    const btype = String(room.buildingType || "");
    const fixtures = Array.isArray(room.structural) ? room.structural : [];
    function hasFixture(re) {
        return fixtures.some(function (f) { return f && !f.concealed && re.test(String(f.id || "")); });
    }
    if (typeof ZONE_BOSS_ROOMS !== "undefined" && ZONE_BOSS_ROOMS[room.zone] && room.type === ZONE_BOSS_ROOMS[room.zone]) {
        marks.push({ key: "boss", icon: "💀", label: "Boss room" });
    }
    if (typeof isShrineRoom === "function" && isShrineRoom(room)) {
        marks.push({ key: "shrine", icon: "⛩️", label: "Shrine" });
    }
    if (/^tavern/i.test(btype) ? !!room.isEntrance : hasFixture(/^bar/)) {
        marks.push({ key: "bar", icon: "🍺", label: "Tavern / bar" });
    }
    if (/^inn/i.test(btype) ? !!room.isEntrance : (!btype && hasFixture(/^(bed|bunk)/))) {
        marks.push({ key: "inn", icon: "🛏️", label: "Inn / beds" });
    }
    if (/^smithy/i.test(btype) ? !!room.isEntrance : hasFixture(/^anvil/)) {
        marks.push({ key: "forge", icon: "🔨", label: "Smithy / forge" });
    }
    if (/^guildhall/i.test(btype) && room.isEntrance) {
        marks.push({ key: "guild", icon: "⚔️", label: "Guildhall" });
    }
    if (/^town hall/i.test(btype) && room.isEntrance) {
        marks.push({ key: "hall", icon: "🏛️", label: "Town Hall" });
    }
    if (room.exits && room.exits.D) marks.push({ key: "down", icon: "⬇️", label: "Way down" });
    if (room.exits && room.exits.U) marks.push({ key: "up", icon: "⬆️", label: "Way up" });
    if (room.portalExits) {
        const pk = Object.keys(room.portalExits).filter(function (d) { return room.portalExits[d] && !isVerticalDirection(d); });
        if (pk.length) marks.push({ key: "portal", icon: "🚪", label: "Door to another part of the map" });
    }
    return marks;
}

// Visited rooms connected to `start` through ordinary exits, plus the
// unvisited neighbours beside them. Returns { rooms: [{room, x, y}], ghosts: [{x, y}], links: [...] }.
function collectMapRooms(start) {
    const rooms = [];
    const ghosts = {};
    const links = [];
    const seen = {};
    const queue = [start];
    seen[start.coords] = true;
    const dirs = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"];
    while (queue.length && rooms.length < MAP_MAX_ROOMS) {
        const room = queue.shift();
        const p = parseCoords(room.coords);
        if (!p) continue;
        rooms.push({ room: room, x: p.x, y: p.y });
        dirs.forEach(function (dir) {
            const target = room.exits ? room.exits[dir] : null;
            if (!target || isPortalExit(room, dir)) return;
            const tp = parseCoords(target);
            if (!tp || tp.key !== getAdjacentCoords(room.coords, dir)) return;
            const other = G.roomMap[tp.key];
            const state = (typeof isExitCollapsed === "function" && isExitCollapsed(room, dir)) ? "rubble"
                : (typeof isExitLocked === "function" && isExitLocked(room, dir)) ? "locked" : "open";
            if (other && other.mapSeen) {
                links.push({ x: p.x, y: p.y, dir: dir, state: state });
                if (!seen[tp.key]) { seen[tp.key] = true; queue.push(other); }
            } else if (!ghosts[tp.key]) {
                ghosts[tp.key] = { x: tp.x, y: tp.y };
                links.push({ x: p.x, y: p.y, dir: dir, state: state });
            } else {
                links.push({ x: p.x, y: p.y, dir: dir, state: state });
            }
        });
    }
    return { rooms: rooms, ghosts: Object.keys(ghosts).map(function (k) { return ghosts[k]; }).filter(function (g) {
        return !seen[g.x + "," + g.y];
    }), links: links };
}

function renderMap() {
    const hereEl = document.getElementById("mapHere");
    const gridEl = document.getElementById("mapGrid");
    const detailEl = document.getElementById("mapDetail");
    const legendEl = document.getElementById("mapLegend");
    if (!hereEl || !gridEl) return;
    gridEl.innerHTML = "";
    if (detailEl) detailEl.textContent = "Tap a room to see its name.";
    const current = G && G.activeRoom ? G.activeRoom : null;
    if (!current || !current.coords) {
        hereEl.textContent = "No map yet.";
        return;
    }
    current.mapSeen = true;
    hereEl.textContent = "You are in: " + getRoomHeaderLabel(current);
    const data = collectMapRooms(current);
    let minX = Infinity, maxY = -Infinity;
    data.rooms.forEach(function (e) { if (e.x < minX) minX = e.x; if (e.y > maxY) maxY = e.y; });
    data.ghosts.forEach(function (g) { if (g.x < minX) minX = g.x; if (g.y > maxY) maxY = g.y; });
    function colOf(x) { return (x - minX) * MAP_CELL_SPAN + 1; }  // CSS grid lines start at 1
    function rowOf(y) { return (maxY - y) * MAP_CELL_SPAN + 1; }  // north (higher y) is up
    let maxCol = 1, maxRow = 1;
    function place(el, col, row) {
        el.style.gridColumn = String(col);
        el.style.gridRow = String(row);
        if (col > maxCol) maxCol = col;
        if (row > maxRow) maxRow = row;
        gridEl.appendChild(el);
    }

    const usedMarks = {};
    let hereCell = null;
    data.rooms.forEach(function (e) {
        const room = e.room;
        const marks = getMapRoomMarks(room);
        const cell = document.createElement("div");
        cell.className = "map-room";
        const isHere = room === current;
        if (isHere) { cell.className += " here"; hereCell = cell; }
        if (marks.length) cell.className += marks.some(function (m) { return m.key === "boss"; }) ? " boss" : " special";
        const shown = marks.slice(0, 2);
        cell.textContent = shown.length ? shown[0].icon : (isHere ? "●" : "·");
        if (shown.length > 1) {
            const extra = document.createElement("span");
            extra.className = "map-extra";
            extra.textContent = shown[1].icon;
            cell.appendChild(extra);
        }
        marks.forEach(function (m) { usedMarks[m.key] = m; });
        const label = getRoomHeaderLabel(room) + (isHere ? " (you are here)" : "")
            + (marks.length ? " — " + marks.map(function (m) { return m.label; }).join(", ") : "");
        cell.title = label;
        cell.addEventListener("click", function () { if (detailEl) detailEl.textContent = label; });
        place(cell, colOf(e.x), rowOf(e.y));
    });
    data.ghosts.forEach(function (g) {
        const cell = document.createElement("div");
        cell.className = "map-room unseen";
        cell.textContent = "?";
        cell.title = "Unexplored";
        place(cell, colOf(g.x), rowOf(g.y));
    });
    // Each path is listed from both ends; draw it once, keeping a lock/rubble state if either end has one.
    const linkCells = {};
    data.links.forEach(function (l) {
        const o = dirToOffset(l.dir);
        const key = (colOf(l.x) + o.x) + "," + (rowOf(l.y) - o.y);
        const prev = linkCells[key];
        if (!prev || (prev.state === "open" && l.state !== "open")) linkCells[key] = l;
    });
    Object.keys(linkCells).forEach(function (key) {
        const l = linkCells[key];
        const off = dirToOffset(l.dir);
        const el = document.createElement("div");
        const cls = l.state === "locked" ? " locked" : (l.state === "rubble" ? " rubble" : "");
        const col = colOf(l.x) + off.x;  // link tracks sit between the two room tracks
        const row = rowOf(l.y) - off.y;
        if (off.x && off.y) {
            // diagonal: a glyph in the corner track; NE/SW are "/" and NW/SE are "\"
            el.className = "map-link d" + cls;
            el.textContent = (off.x * off.y > 0) ? "╱" : "╲";
        } else if (off.x) {
            el.className = "map-link h" + cls;
        } else {
            el.className = "map-link v" + cls;
        }
        place(el, col, row);
    });
    // Track sizes: room tracks 44px, link tracks 14px (odd lines are rooms).
    let cols = "", rows = "";
    for (let c = 1; c <= maxCol; c++) cols += (c % 2 === 1 ? "44px " : "14px ");
    for (let r = 1; r <= maxRow; r++) rows += (r % 2 === 1 ? "44px " : "14px ");
    gridEl.style.gridTemplateColumns = cols;
    gridEl.style.gridTemplateRows = rows;

    if (legendEl) {
        const order = ["boss", "shrine", "bar", "inn", "forge", "guild", "hall", "down", "up", "portal"];
        let html = '<span>● you</span><span>? unexplored</span><span style="color:#c9a227">━ locked</span>';
        order.forEach(function (k) {
            if (usedMarks[k]) html += "<span>" + usedMarks[k].icon + " " + usedMarks[k].label + "</span>";
        });
        legendEl.innerHTML = html;
    }
    if (hereCell && hereCell.scrollIntoView) {
        // Centre the player's room in the scroll area (after layout).
        setTimeout(function () {
            try { hereCell.scrollIntoView({ block: "center", inline: "center" }); } catch (e) { /* ignore */ }
        }, 0);
    }
}

function toggleMap() {
    const el = document.getElementById("mapManager");
    if (!el) return;
    el.classList.toggle("active");
    if (el.classList.contains("active")) renderMap();
    else refreshRoomViewAfterClose();
}

// Used after a combat-turn action taken from inside the inventory panel
// (currently just drinking a potion mid-fight - see drinkPotionInCombat)
// so the player is dropped straight back into the combat log/menu that
// action just updated, instead of staring at the inventory overlay.
function closeEquipmentManager() {
    const equipmentManager = document.getElementById("equipmentManager");
    if (equipmentManager) equipmentManager.classList.remove("active");
    refreshRoomViewAfterClose();
}

// "Other Worn Items": anything in G.player.equipped that has no fixed box in
// the equipment panel's markup (the Amulet/neck slot used by class gear, plus
// any slot a future item type introduces). Without this, such items showed on
// the character sheet but could not be examined, removed or dropped. Each one
// gets a slot box built on the fly and rendered by the same renderEquipmentSlot
// (Examine / Remove / Drop) as the fixed slots. The section is created on first
// use and hidden while nothing is worn in it, so the panel markup stays thin.
function renderOtherWornItems() {
    const inventoryEl = document.getElementById("equipmentInventory");
    if (!inventoryEl || !inventoryEl.parentNode) return;

    let section = document.getElementById("equipmentOtherWorn");
    if (!section) {
        section = document.createElement("div");
        section.id = "equipmentOtherWorn";
        const title = document.createElement("div");
        title.className = "equipment-section-title";
        title.textContent = "Other Worn Items";
        section.appendChild(title);
        const slotsEl = document.createElement("div");
        slotsEl.id = "equipmentOtherSlots";
        section.appendChild(slotsEl);
        // Sits just above the "Carried Items" heading.
        const carriedTitle = inventoryEl.previousElementSibling;
        inventoryEl.parentNode.insertBefore(section, carriedTitle || inventoryEl);
    }

    const slotsEl = document.getElementById("equipmentOtherSlots");
    slotsEl.innerHTML = "";

    const equipped = G.player && G.player.equipped ? G.player.equipped : {};
    const keys = Object.keys(equipped).filter(slot => {
        const worn = equipped[slot];
        if (!worn || Array.isArray(worn) || slot === "coinPouch") return false;
        const fixedEl = document.getElementById(`eq-slot-${slot}`);
        return !(fixedEl && fixedEl.parentNode && fixedEl.parentNode.id === "equipmentSlots");
    });

    keys.forEach(slot => {
        const box = document.createElement("div");
        box.className = "eq-slot";
        box.id = `eq-slot-${slot}`;
        slotsEl.appendChild(box);
        renderEquipmentSlot(slot);
    });

    section.style.display = keys.length ? "" : "none";
}

function getPlayerCarryContainers(player) {
    const items = [player && player.rucksack];
    const eq = player && player.equipped || {};
    Object.keys(eq).forEach(function (slot) { items.push(eq[slot]); });
    items.push.apply(items, player && player.inventory || []);
    return items.filter(function (item, i) { return item && items.indexOf(item) === i && isCarryContainerItem(item); });
}

// One group per actual container, including empty worn storage and containers
// inside other carried containers. Contents remain in the existing flat model.
function buildEquipmentInventoryGroups(player) {
    const containers = getPlayerCarryContainers(player);
    const byItem = new Map();
    const byPlace = new Map();
    const groups = [];
    const worn = player && player.equipped || {};
    containers.forEach(function (item) {
        const garment = getGarmentPlaces(item);
        const slot = Object.keys(worn).find(function (key) { return worn[key] === item; });
        const label = item === player.rucksack ? "Back" : (slot ? getEquipmentSlotMeta(slot).label : "Carried container");
        const group = { item: item, label: getItemName(item) + " · " + label, storage: garment.storage, ties: garment.ties, entries: [], used: 0, tied: 0 };
        group.capacity = garment.storage.reduce(function (sum, place) { return sum + place.cap; }, 0);
        groups.push(group);
        byItem.set(item, group);
        garment.storage.concat(garment.ties).forEach(function (place) { byPlace.set(place.id, group); });
    });
    if (!worn.hand) {
        const hand = { label: "Free hand", storage: [{ id: "hand", cap: 1 }], ties: [], entries: [], used: 0, tied: 0, capacity: 1 };
        groups.push(hand);
        byPlace.set("hand", hand);
    }
    const overflow = { label: "No room · Overflow", storage: [], ties: [], entries: [], used: 0, tied: 0, capacity: 0, overflow: true };
    buildPlayerInventoryEntries(player).forEach(function (entry) {
        const container = byItem.get(entry.item);
        if (container) container.ownEntry = entry;
        const group = byPlace.get(entry.item.stowed) || overflow;
        group.entries.push(entry);
        if (isTieSpotId(entry.item.stowed)) group.tied += entry.totalQuantity;
        else group.used += getItemUnitSize(entry.item) * entry.totalQuantity;
    });
    if (overflow.entries.length) groups.push(overflow);
    groups.forEach(function (group) {
        group.parent = group.item ? byPlace.get(group.item.stowed) : null;
        if (group.item && !group.parent && (player.inventory || []).indexOf(group.item) >= 0) group.parent = overflow;
    });
    return { groups: groups, byItem: byItem };
}

function describeEquipmentStorageCapacity(view) {
    const groups = view.groups.filter(function (group) { return !group.overflow; });
    const used = groups.reduce(function (sum, group) { return sum + group.used; }, 0);
    const capacity = groups.reduce(function (sum, group) { return sum + group.capacity; }, 0);
    const sack = view.byItem.get(G.player.rucksack);
    const bits = [];
    if (sack) bits.push("Rucksack: " + sack.used + "/" + sack.capacity + " units");
    bits.push("Combined storage: " + used + "/" + capacity + " units");
    const tied = groups.reduce(function (sum, group) { return sum + group.tied; }, 0);
    if (tied) bits.push(tied + " tied on");
    const overflow = view.groups.find(function (group) { return group.overflow; });
    if (overflow) bits.push(overflow.entries.reduce(function (sum, entry) { return sum + entry.totalQuantity; }, 0) + " with no room");
    return bits.join(" · ");
}

function appendEquipmentMoveControl(entry, actionsEl) {
    const player = G.player;
    const destinations = getPlayerCarryContainers(player).filter(function (container) {
        if (carryContainerHoldsItem(entry.item, container, player)) return false;
        if (getContainerContents(container).indexOf(entry.item) >= 0) return false;
        return !!getContainerFreePlace(container, { ...entry.item, quantity: 1 }, getContainerContents(container));
    });
    if (!destinations.length) return;
    const select = document.createElement("select");
    select.className = "equipment-action-btn equipment-move-select";
    select.setAttribute("aria-label", "Move " + getItemName(entry.item) + " to another container");
    const prompt = document.createElement("option");
    prompt.value = "";
    prompt.textContent = entry.totalQuantity > 1 ? "Move one to…" : "Move to…";
    select.appendChild(prompt);
    destinations.forEach(function (container, index) {
        const option = document.createElement("option");
        option.value = String(index);
        option.textContent = getItemName(container);
        select.appendChild(option);
    });
    select.onchange = function () {
        if (select.value === "") return;
        const container = destinations[Number(select.value)];
        if (container) refreshInventoryUi(storeInCarryContainer(container, entry.key));
    };
    actionsEl.appendChild(select);
}

function appendWornContainerActions(item, parent) {
    const equipped = G.player && G.player.equipped || {};
    const slot = Object.keys(equipped).find(function (key) { return equipped[key] === item; });
    if (!slot || slot === "coinPouch") return;
    const name = getItemName(item);
    const actions = document.createElement("div");
    actions.className = "equipment-row-actions";
    const extra = document.createElement("div");
    actions.appendChild(createEquipmentActionButton("Examine", () => openEquipmentExamine(item, { slot: slot, equipped: true })));
    extra.appendChild(createEquipmentActionButton("Contents", function () { openContainerCard(item, ""); }));
    extra.appendChild(createEquipmentActionButton("Search", () => searchOwnContainer(item), { title: "Costs 1 stamina, 1 turn." }));
    getOwnItemFireSpellButtons(item).forEach(function (button) { extra.appendChild(button); });
    actions.appendChild(createEquipmentActionButton("Remove", () => {
        const removed = moveEquippedItemToInventory(slot);
        if (removed) refreshInventoryUi("You remove " + name + " and stow it in your pack.");
    }));
    actions.appendChild(createEquipmentActionButton("Drop", () => {
        if (dropEquippedItemToRoom(slot)) refreshInventoryUi("You drop " + name + ".");
    }, { disabled: !G.activeRoom }));
    appendEquipmentItemActions(parent, actions, extra, name);
}

function renderEquipmentInventoryGroups(view, inventoryEl) {
    const rendered = new Set();
    function renderGroup(group, parent) {
        if (rendered.has(group)) return;
        rendered.add(group);
        const section = document.createElement("section");
        section.className = "equipment-container";
        const heading = document.createElement("div");
        heading.className = "equipment-container-title";
        heading.textContent = group.label + (group.overflow ? "" : " — " + group.used + "/" + group.capacity + " units");
        section.appendChild(heading);
        if (group.ties.length) {
            const ties = document.createElement("div");
            ties.className = "equipment-row-subtitle";
            ties.textContent = "Tied on: " + group.tied + "/" + group.ties.length + " · uses no storage units";
            section.appendChild(ties);
        }
        if (group.ownEntry) renderEquipmentInventoryEntry(group.ownEntry, section);
        else if (group.item && group.item !== G.player.rucksack) appendWornContainerActions(group.item, section);
        if (group.item === G.player.rucksack) appendRucksackInventoryActions(group.item, section);
        if (!group.entries.length) {
            const empty = document.createElement("div");
            empty.className = "equipment-empty";
            empty.textContent = "Empty";
            section.appendChild(empty);
        }
        group.entries.slice().sort(compareInventoryDisplayEntries).forEach(function (entry) {
            const child = view.byItem.get(entry.item);
            if (child) {
                if (child !== group && !rendered.has(child)) renderGroup(child, section);
            } else renderEquipmentInventoryEntry(entry, section);
        });
        parent.appendChild(section);
    }
    view.groups.filter(function (group) { return !group.parent; }).forEach(function (group) { renderGroup(group, inventoryEl); });
    // Defensive fallback for malformed legacy stowage cycles: keep every group
    // visible and actionable rather than recursing forever or hiding items.
    view.groups.forEach(function (group) { if (!rendered.has(group)) renderGroup(group, inventoryEl); });
}

let _inventoryDisplayPreferences = null;
const INVENTORY_DISPLAY_PREF_KEY = "cyoaftw.inventoryDisplay";

function getInventoryDisplayPreferences() {
    if (_inventoryDisplayPreferences) return _inventoryDisplayPreferences;
    const prefs = { view: "compact", sort: "name" };
    try {
        const saved = JSON.parse(localStorage.getItem(INVENTORY_DISPLAY_PREF_KEY) || "null");
        if (saved && (saved.view === "compact" || saved.view === "expanded")) prefs.view = saved.view;
        if (saved && (saved.sort === "name" || saved.sort === "value")) prefs.sort = saved.sort;
    } catch (e) { /* Storage may be unavailable; the view still works. */ }
    _inventoryDisplayPreferences = prefs;
    return prefs;
}

function setInventoryDisplayPreference(key, value) {
    if (key === "view" ? value !== "compact" && value !== "expanded" : key !== "sort" || value !== "name" && value !== "value") return;
    getInventoryDisplayPreferences()[key] = value;
    try { localStorage.setItem(INVENTORY_DISPLAY_PREF_KEY, JSON.stringify(_inventoryDisplayPreferences)); } catch (e) {}
    renderEquipment();
    const select = document.getElementById(key === "view" ? "inventoryViewSelect" : "inventorySortSelect");
    if (select) select.focus();
}

function compareInventoryDisplayEntries(a, b) {
    if (getInventoryDisplayPreferences().sort === "value") {
        const valueDifference = getItemUnitValue(b.item) - getItemUnitValue(a.item);
        if (valueDifference) return valueDifference;
    }
    return getItemName(a.item).localeCompare(getItemName(b.item)) || String(a.key || "").localeCompare(String(b.key || ""));
}

function appendInventoryDisplayToolbar(parent) {
    const prefs = getInventoryDisplayPreferences();
    const toolbar = document.createElement("div");
    toolbar.className = "inventory-display-toolbar";
    const addSelect = function (key, title, choices) {
        const label = document.createElement("label");
        label.textContent = title + " ";
        const select = document.createElement("select");
        select.id = key === "view" ? "inventoryViewSelect" : "inventorySortSelect";
        select.className = "equipment-action-btn";
        select.setAttribute("aria-label", title + " inventory");
        choices.forEach(function (choice) {
            const option = document.createElement("option");
            option.value = choice[0];
            option.textContent = choice[1];
            select.appendChild(option);
        });
        select.value = prefs[key];
        if (key === "sort") select.title = "Name: A to Z. Value: highest value per item first.";
        select.onchange = function () { setInventoryDisplayPreference(key, select.value); };
        label.appendChild(select);
        toolbar.appendChild(label);
    };
    addSelect("view", "View", [["compact", "Compact"], ["expanded", "Expanded"]]);
    addSelect("sort", "Sort", [["name", "Name (A–Z)"], ["value", "Value (high first)"]]);
    parent.appendChild(toolbar);
}

function appendRucksackInventoryActions(item, parent, primaryParent) {
    const actions = document.createElement("div");
    actions.className = "equipment-row-actions";
    actions.appendChild(createEquipmentActionButton("Examine", function () { openEquipmentExamine(item, { equipped: true }); }));
    actions.appendChild(createEquipmentActionButton("Remove", removeWornRucksack));
    actions.appendChild(createEquipmentActionButton("Drop", function () { refreshInventoryUi(dropRucksack()); }, { disabled: !G.activeRoom }));
    const extra = document.createElement("div");
    extra.appendChild(createEquipmentActionButton("Contents", function () { openContainerCard(item, ""); }));
    extra.appendChild(createEquipmentActionButton("Search", function () { searchOwnContainer(item); }, { title: "Costs 1 stamina, 1 turn." }));
    getOwnItemFireSpellButtons(item).forEach(function (button) { extra.appendChild(button); });
    appendEquipmentItemActions(parent, actions, extra, getItemName(item), primaryParent);
}

function renderCompactEquipmentInventory(view, parent) {
    const entries = [];
    view.groups.forEach(function (group) {
        group.entries.forEach(function (entry) {
            entries.push(Object.assign({}, entry, { storageLabel: group.item ? getItemName(group.item) : group.label }));
        });
    });
    // The worn backpack has no fixed equipment slot box; keep it actionable.
    if (G.player.rucksack) entries.push({ item: G.player.rucksack, wornPack: true, key: "worn-pack" });
    entries.sort(compareInventoryDisplayEntries).forEach(function (entry) {
        if (!entry.wornPack) { renderEquipmentInventoryEntry(entry, parent); return; }
        const row = document.createElement("div");
        row.className = "equipment-row";
        const header = document.createElement("div");
        header.className = "equipment-row-header";
        const title = document.createElement("div");
        title.className = "equipment-row-title";
        title.textContent = getItemName(entry.item) + " (worn)";
        header.appendChild(title);
        row.appendChild(header);
        appendRucksackInventoryActions(entry.item, row, header);
        parent.appendChild(row);
    });
    if (!entries.length) {
        const empty = document.createElement("div");
        empty.className = "equipment-empty";
        empty.textContent = "Nothing carried";
        parent.appendChild(empty);
    }
}


function renderEquipment() {
    ensurePlayerEquipmentState(G.player);
    renderOtherWornItems();
    getPlayerEquipmentSlots().forEach(renderEquipmentSlot);
    const inventoryEl = document.getElementById("equipmentInventory");
    if (!inventoryEl) return;
    restowPlayerPack(G.player);
    inventoryEl.classList.remove("empty");
    inventoryEl.innerHTML = "";
    const compact = getInventoryDisplayPreferences().view === "compact";
    inventoryEl.classList.toggle("inventory-compact", compact);
    appendInventoryDisplayToolbar(inventoryEl);
    const view = buildEquipmentInventoryGroups(G.player);
    const capacity = document.createElement("div");
    capacity.className = "equipment-capacity-summary";
    capacity.textContent = describeEquipmentStorageCapacity(view);
    inventoryEl.appendChild(capacity);
    const note = document.createElement("div");
    note.className = "equipment-row-subtitle";
    note.textContent = "Equipped items use no storage space. Combined storage includes nested containers.";
    inventoryEl.appendChild(note);
    if (compact) renderCompactEquipmentInventory(view, inventoryEl);
    else renderEquipmentInventoryGroups(view, inventoryEl);
    if (!compact && !view.groups.length) {
        const empty = document.createElement("div");
        empty.className = "equipment-empty";
        empty.textContent = "Nothing carried · No storage available";
        inventoryEl.appendChild(empty);
    }
}


// ── SPINNER ──────────────────────────────────────────────────────

function wait(ms) {
    return new Promise(resolve => setTimeout(resolve, Math.max(0, ms || 0)));
}

function waitForNextPaint() {
    return new Promise(resolve => {
        requestAnimationFrame(() => requestAnimationFrame(resolve));
    });
}

function countNPCsInRoomMap(roomMap) {
    return Object.values(roomMap || {}).reduce((total, room) => {
        return total + (Array.isArray(room && room.creatures) ? room.creatures.length : 0);
    }, 0);
}

function setLoadingProgress(progress) {
    const barEl = document.getElementById("loadingProgressBar");
    if (!barEl) return;

    const clamped = Math.max(0, Math.min(100, Number(progress) || 0));
    barEl.style.width = `${clamped}%`;
}

function appendLoadingHistory(message) {
    const historyEl = document.getElementById("loadingStepHistory");
    if (!historyEl || !message) return;

    const entryEl = document.createElement("div");
    entryEl.className = "loading-step-entry";
    entryEl.textContent = message;
    historyEl.appendChild(entryEl);

    while (historyEl.children.length > 4) {
        historyEl.removeChild(historyEl.firstChild);
    }
}

function updateLoadingStatus(message, progress, addHistory = false) {
    const logEl = document.getElementById("loadingLog");
    if (logEl) logEl.textContent = message || "Loading...";
    if (typeof progress === "number") setLoadingProgress(progress);
    if (addHistory) appendLoadingHistory(message);
}

async function performLoadingStep(message, progress, action, minDurationMs = 240) {
    updateLoadingStatus(message, progress, true);
    await waitForNextPaint();

    const result = typeof action === "function" ? await action() : null;
    await wait(minDurationMs);
    return result;
}

function showSpinner(msg, title) {
    const titleEl = document.getElementById("loadingTitle");
    const historyEl = document.getElementById("loadingStepHistory");

    if (titleEl) titleEl.textContent = title || "Preparing Adventure";
    if (historyEl) historyEl.innerHTML = "";
    setLoadingProgress(0);
    updateLoadingStatus(msg || "Loading...", 0, false);
    document.getElementById("loadingSpinner").classList.add("active");
}

function hideSpinner() {
    setLoadingProgress(0);
    document.getElementById("loadingSpinner").classList.remove("active");
}
// Initialize debug mode
setupRelationshipDebug();

// Expose setup/character-creation functions on window so inline onclick
// handlers in the HTML shell can find them (Perchance's script loader does
// not put top-level declarations on window automatically).
window.setupGoTo = setupGoTo;
window.randomizeName = randomizeName;
window.changeStat = changeStat;
window.selectPersonality = selectPersonality;
window.beginAdventure = beginAdventure;
window.startNewAdventureFromPrompt = startNewAdventureFromPrompt;
window.resumeSavedGame = resumeSavedGame;
window.getTemperamentInflection = getTemperamentInflection;

// Expose SFW room-object + narration helpers the NSFW body-action hooks call
// via window.* (the unconscious-body Kiss/Position/Oral/Penetrate/Spit groups
// in nsfw/cyoaftw-nsfw-system.js, and describeUnconsciousBodyExamine). These
// are typeof-guarded on the NSFW side, so exposing them is a no-op when the
// NSFW files aren't loaded. Same Perchance-loader caveat as above applies.
window.getEntityName = getEntityName;
window.describeCombatWounds = describeCombatWounds;
window.setNarration = setNarration;
window.saveGameState = saveGameState;
window.rememberStoryEvent = rememberStoryEvent;
// The NSFW system's free-use tick deposits seed in rooms; it needs the
// same add-liquid funnel everything else uses (fixtures, overflow, evaporation).
window.addRoomLiquid = addRoomLiquid;
window.createCombatButton = createCombatButton;
window.appendCombatGroup = appendCombatGroup;
window.renderRoomObjectActionMenu = renderRoomObjectActionMenu;
window.renderCaptorMenu = renderCaptorMenu;
window.isHeldCaptive = isHeldCaptive;
window.unbindCaptive = unbindCaptive;
window.examineRoomObject = examineRoomObject;

// Expose stat/read helpers that the script-src data files (cyoaftw-npc-data.js,
// nsfw/cyoaftw-nsfw-system.js) reference with typeof guards. Without these
// the guards silently take their fallback branches: charisma never scaled
// attraction/lust, temperament never modified NSFW impacts, the catalogue's
// playerTraits/tradeAvailable conditions were always empty. Same
// Perchance-loader caveat as the blocks above.
window.getSetupStat = getSetupStat;
window.getPlayerAppearanceText = getPlayerAppearanceText;
window.getPlayerAppearance = getPlayerAppearance;
window.getPlayerHygienePenalty = getPlayerHygienePenalty;
window.getPlayerPresentationScore = getPlayerPresentationScore;
window.getPlayerTraitCounts = getPlayerTraitCounts;
window.getPlayerDominantTrait = getPlayerDominantTrait;
window.getPlayerTraitValue = getPlayerTraitValue;
window.getTemperamentModifier = getTemperamentModifier;
window.shouldShowPostReplyTradeAction = shouldShowPostReplyTradeAction;

// Grime: the intimacy system adds post-act grime through this wrapper so the
// constants stay engine-side (see the GRIME/HYGIENE block). options.highTier
// marks the messy acts (ejaculation/watersports/anal) - the NSFW side decides
// which acts qualify, since act data lives there. typeof-guarded no-op on the
// NSFW side when absent.
window.addIntimacyActGrime = function(entity, options) {
    const highTier = !!(options && options.highTier);
    addEntityGrime(entity, highTier ? GRIME_INTIMACY_AMOUNT_HIGH : GRIME_INTIMACY_AMOUNT);
};

// The intimacy system stamps smell notes with the story turn (see
// addSmellMark/getActiveSmellNotes in nsfw/intimacy-system.js); the context
// builder and detail panel use this to read them.
window.getCurrentStoryTurn = getCurrentStoryTurn;
